/// ```php
/// $tags = \is_array($tags) ? new \Sharp\Set<string>($tags) : $tags;
/// $states = \is_array($states) ? new \Sharp\Set<Lib.Calc>($states) : $states;
/// \Sharp\Internal\addKey($tags, $name);
/// \Sharp\Internal\removeKey($tags, \Lib\Calc::upper($name));
/// \Sharp\Internal\addKey($states, $status);
/// \Sharp\Internal\removeKey($states, \Lib\Calc::Closed);
/// \Sharp\Internal\clear($tags);
/// return \Sharp\Internal\containsKey($tags, $name);
/// ```
///
/// A `Set`'s members are the standard library's, spec section 12, each the engine function of the set's table, which
/// takes the `Set` by reference where it changes it. Each element goes in as itself.
#[test]
fn set_methods_run_on_the_set() {
    assert_eq!(
        body_in(
            "bool run(Set<string> tags, Set<Calc> states, Calc status, string name)",
            "        tags.add(name);\n        tags.remove(Calc.upper(name));\n        states.add(status);\n        states.remove(Calc.Closed);\n        tags.clear();\n        return tags.contains(name);\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; enum Calc: string { case Active = 'a'; case Closed = 'c'; public static function upper(string $text): string { return strtoupper($text); } }"
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "tags"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "tags"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Set"
                      ARG_LIST
                        VAR
                          ZVAL "tags"
                    ZVAL "string"
                  VAR
                    ZVAL "tags"
              ASSIGN
                VAR
                  ZVAL "states"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "states"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Set"
                      ARG_LIST
                        VAR
                          ZVAL "states"
                    ZVAL "Lib.Calc"
                  VAR
                    ZVAL "states"
              CALL
                ZVAL "Sharp\\Internal\\addKey"
                ARG_LIST
                  VAR
                    ZVAL "tags"
                  VAR
                    ZVAL "name"
              CALL
                ZVAL "Sharp\\Internal\\removeKey"
                ARG_LIST
                  VAR
                    ZVAL "tags"
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "upper"
                    ARG_LIST
                      VAR
                        ZVAL "name"
              CALL
                ZVAL "Sharp\\Internal\\addKey"
                ARG_LIST
                  VAR
                    ZVAL "states"
                  VAR
                    ZVAL "status"
              CALL
                ZVAL "Sharp\\Internal\\removeKey"
                ARG_LIST
                  VAR
                    ZVAL "states"
                  CLASS_CONST
                    ZVAL "Lib\\Calc"
                    ZVAL "Closed"
              CALL
                ZVAL "Sharp\\Internal\\clear"
                ARG_LIST
                  VAR
                    ZVAL "tags"
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\containsKey"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    VAR
                      ZVAL "name"
        "#}
    );
}

/// ```php
/// $tags = \is_array($tags) ? new \Sharp\Set<string>($tags) : $tags;
/// $prices = …;
/// $count = \Sharp\Internal\size($tags);
/// $kept = \Sharp\Internal\filterElements($tags, $keep);
/// $priced = \Sharp\Internal\filterEntries($prices, $positive);
/// \Sharp\Internal\any($tags, $keep);
/// return \Sharp\Internal\keys($tags);
/// ```
///
/// A `Set`'s and a `Map`'s members inline to the call their standard library body makes, spec section 12: the engine
/// function a `List` shares, or the one of a table. A `Set`'s `filter` and a `Map`'s keep the type arguments of the
/// one they filter, and a `Set`'s `toList()` is its table's keys.
#[test]
fn set_and_map_methods_are_the_collection_methods_of_their_names() {
    assert_eq!(
        body_in(
            "List<string> run(Set<string> tags, Function<bool(string)> keep, Map<string, int> prices, Function<bool(int)> positive)",
            "        const count = tags.count();\n        const kept = tags.filter(keep);\n        const priced = prices.filter(positive);\n        tags.any(keep);\n        return tags.toList();\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "tags"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "tags"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Set"
                      ARG_LIST
                        VAR
                          ZVAL "tags"
                    ZVAL "string"
                  VAR
                    ZVAL "tags"
              ASSIGN
                VAR
                  ZVAL "prices"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "prices"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @7-7
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#1"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#2"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#1"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#2"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "prices"
                                  VAR
                                    ZVAL "prices"
                    ZVAL "string, int"
                  VAR
                    ZVAL "prices"
              ASSIGN
                VAR
                  ZVAL "count"
                CALL
                  ZVAL "Sharp\\Internal\\size"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
              ASSIGN
                VAR
                  ZVAL "kept"
                CALL
                  ZVAL "Sharp\\Internal\\filterElements"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    VAR
                      ZVAL "keep"
              ASSIGN
                VAR
                  ZVAL "priced"
                CALL
                  ZVAL "Sharp\\Internal\\filterEntries"
                  ARG_LIST
                    VAR
                      ZVAL "prices"
                    VAR
                      ZVAL "positive"
              CALL
                ZVAL "Sharp\\Internal\\any"
                ARG_LIST
                  VAR
                    ZVAL "tags"
                  VAR
                    ZVAL "keep"
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\keys"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
        "#}
    );
}

/// ```php
/// return \count($this->lines) + \Sharp\Internal\size($counts);
/// ```
///
/// A `List`'s `count()` is PHP's `count` on the array, and a `Map`'s is the engine's `size` of its table, since PHP's
/// built-ins take a `Map` as the PHP array it crosses into.
#[test]
fn a_list_counts_with_php_count_and_a_map_with_its_size() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public List<int> lines { get; private set; } = [];\n\n    public int run(Map<string, int> counts)\n    {\n        return this.lines.count() + counts.count();\n    }\n}\n",
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "counts"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "counts"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @7-7
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#1"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#2"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#1"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#2"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "counts"
                                  VAR
                                    ZVAL "counts"
                    ZVAL "string, int"
                  VAR
                    ZVAL "counts"
              RETURN
                BINARY_OP [1]
                  CALL
                    ZVAL "count"
                    ARG_LIST
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "lines"
                  CALL
                    ZVAL "Sharp\\Internal\\size"
                    ARG_LIST
                      VAR
                        ZVAL "counts"
        "#}
    );
}

/// ```php
/// $found = \Sharp\Internal\get($sizes, $extra);
/// $unique = \Sharp\Internal\toSet($sizes, 'int');
/// $copy = $sizes;
/// ```
///
/// Spec section 12: `getOrNull(i)` is the safe read, which gives null past either end, `toSet()` is the `Set` of the
/// elements, each once, with the type argument the call gives, and `toList()` is the list itself, which PHP copies on
/// a write.
#[test]
fn get_or_null_to_set_and_to_list_lower_to_php_on_the_array() {
    assert_eq!(
        body_in(
            "void run(List<int> sizes, int extra)",
            "        let found = sizes.getOrNull(extra);\n        let unique = sizes.toSet();\n        let copy = sizes.toList();\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "found"
                CALL
                  ZVAL "Sharp\\Internal\\get"
                  ARG_LIST
                    VAR
                      ZVAL "sizes"
                    VAR
                      ZVAL "extra"
              ASSIGN
                VAR
                  ZVAL "unique"
                CALL
                  ZVAL "Sharp\\Internal\\toSet"
                  ARG_LIST
                    VAR
                      ZVAL "sizes"
                    ZVAL "int"
              ASSIGN
                VAR
                  ZVAL "copy"
                VAR
                  ZVAL "sizes"
        "#}
    );
}

/// ```php
/// $held = \Sharp\Internal\contains($tags, $tag);
/// $at = \Sharp\Internal\indexOf($tags, 'vip');
/// $next = \Sharp\Internal\indexOf($tags, $tag);
/// $found = (($maybe === null) ? null : \Sharp\Internal\contains($maybe, $tag)) ?? false;
/// return $held && $at !== $next && $found && \Sharp\Internal\contains($ratios, $ratio);
/// ```
///
/// Spec section 12's `contains` and `indexOf` are the engine functions of their names, which compare each element by
/// section 19's `==`. `indexOf` gives null where no element is equal. A null-safe search tests its receiver first.
#[test]
fn a_list_search_is_the_engine_function_of_its_name() {
    assert_eq!(
        body_in(
            "bool run(List<string> tags, string tag, List<float> ratios, float ratio, List<string>? maybe)",
            "        const held = tags.contains(tag);\n        const at = tags.indexOf(\"vip\");\n        const next = tags.indexOf(tag);\n        const found = maybe?.contains(tag) ?? false;\n        return held && at != next && found && ratios.contains(ratio);\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "held"
                CALL
                  ZVAL "Sharp\\Internal\\contains"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    VAR
                      ZVAL "tag"
              ASSIGN
                VAR
                  ZVAL "at"
                CALL
                  ZVAL "Sharp\\Internal\\indexOf"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    ZVAL "vip"
              ASSIGN
                VAR
                  ZVAL "next"
                CALL
                  ZVAL "Sharp\\Internal\\indexOf"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    VAR
                      ZVAL "tag"
              ASSIGN
                VAR
                  ZVAL "found"
                COALESCE
                  CONDITIONAL [1]
                    BINARY_OP [16]
                      VAR
                        ZVAL "maybe"
                      ZVAL null
                    ZVAL null
                    CALL
                      ZVAL "Sharp\\Internal\\contains"
                      ARG_LIST
                        VAR
                          ZVAL "maybe"
                        VAR
                          ZVAL "tag"
                  ZVAL false
              RETURN
                AND
                  AND
                    AND
                      VAR
                        ZVAL "held"
                      BINARY_OP [17]
                        VAR
                          ZVAL "at"
                        VAR
                          ZVAL "next"
                    VAR
                      ZVAL "found"
                  CALL
                    ZVAL "Sharp\\Internal\\contains"
                    ARG_LIST
                      VAR
                        ZVAL "ratios"
                      VAR
                        ZVAL "ratio"
        "#}
    );
}

/// ```php
/// $x = 1;
/// return \Sharp\Internal\contains($this->bump($xs), $this->n)
///     && \Sharp\Internal\indexOf(\App\Tenant\Report::pick($xs, $x = 2), $x) === 0
///     && [${'receiver#1'} = $this->bumped(), \Sharp\Internal\remove(${'receiver#1'}->items, $this->n)][1];
///
/// return \Sharp\Internal\containsKey($this->bumped()->counts, $this->n)
///     && [${'receiver#1'} = $this->bumped(), \Sharp\Internal\removeKey(${'receiver#1'}->counts, $this->n)][1];
/// ```
///
/// A search runs its receiver before its value, as the call runs it: the engine function takes the list first, so
/// `this.bump(xs)` changes `this.n` before `contains` reads it, `Report.pick(xs, x = 2)` assigns `x` before `indexOf`
/// reads it, and `this.bumped()`, held once for the place `remove` changes, changes `this.n` before `remove` reads it.
/// A `Map`'s `has` and `remove` take the `Map` first the same way.
#[test]
fn a_search_runs_its_receiver_before_its_value() {
    assert_eq!(
        Lowered::new(
            "namespace App.Tenant;\n\nclass Report\n{\n    private int n = 1;\n\n    public List<int> items { get; set; } = [];\n\n    public List<int> bump(List<int> xs)\n    {\n        this.n = this.n + 1;\n        return xs;\n    }\n\n    public Report bumped()\n    {\n        this.n = this.n + 1;\n        return this;\n    }\n\n    public static List<int> pick(List<int> xs, int ignored) => xs;\n\n    public bool run(List<int> xs)\n    {\n        let x = 1;\n        return this.bump(xs).contains(this.n) && Report.pick(xs, x = 2).indexOf(x) == 0 && this.bumped().items.remove(this.n);\n    }\n}\n"
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "x"
                ZVAL 1
              RETURN
                AND
                  AND
                    CALL
                      ZVAL "Sharp\\Internal\\contains"
                      ARG_LIST
                        METHOD_CALL
                          VAR
                            ZVAL "this"
                          ZVAL "bump"
                          ARG_LIST
                            VAR
                              ZVAL "xs"
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "n"
                    BINARY_OP [16]
                      CALL
                        ZVAL "Sharp\\Internal\\indexOf"
                        ARG_LIST
                          STATIC_CALL
                            ZVAL "App\\Tenant\\Report"
                            ZVAL "pick"
                            ARG_LIST
                              VAR
                                ZVAL "xs"
                              ASSIGN
                                VAR
                                  ZVAL "x"
                                ZVAL 2
                          VAR
                            ZVAL "x"
                      ZVAL 0
                  DIM
                    ARRAY [3]
                      ARRAY_ELEM
                        ASSIGN
                          VAR
                            ZVAL "receiver#1"
                          METHOD_CALL
                            VAR
                              ZVAL "this"
                            ZVAL "bumped"
                            ARG_LIST
                        null
                      ARRAY_ELEM
                        CALL
                          ZVAL "Sharp\\Internal\\remove"
                          ARG_LIST
                            PROP
                              VAR
                                ZVAL "receiver#1"
                              ZVAL "items"
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "n"
                        null
                    ZVAL 1
        "#}
    );
    assert_eq!(
        Lowered::new(
            "namespace App.Tenant;\n\nclass Report\n{\n    private int n = 1;\n\n    public Map<int, int> counts { get; set; } = [:];\n\n    public Report bumped()\n    {\n        this.n = this.n + 1;\n        return this;\n    }\n\n    public bool run()\n    {\n        return this.bumped().counts.has(this.n) && this.bumped().counts.remove(this.n);\n    }\n}\n"
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                AND
                  CALL
                    ZVAL "Sharp\\Internal\\containsKey"
                    ARG_LIST
                      PROP
                        METHOD_CALL
                          VAR
                            ZVAL "this"
                          ZVAL "bumped"
                          ARG_LIST
                        ZVAL "counts"
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "n"
                  DIM
                    ARRAY [3]
                      ARRAY_ELEM
                        ASSIGN
                          VAR
                            ZVAL "receiver#1"
                          METHOD_CALL
                            VAR
                              ZVAL "this"
                            ZVAL "bumped"
                            ARG_LIST
                        null
                      ARRAY_ELEM
                        CALL
                          ZVAL "Sharp\\Internal\\removeKey"
                          ARG_LIST
                            PROP
                              VAR
                                ZVAL "receiver#1"
                              ZVAL "counts"
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "n"
                        null
                    ZVAL 1
        "#}
    );
}

/// ```php
/// $last = @\array_last(\Sharp\Internal\nonEmpty($sizes));
/// return $last + @\array_last(\Sharp\Internal\nonEmpty($this->make()));
/// ```
///
/// `last()` is the last element, and throws `OutOfRangeException` on an empty list, as Kotlin's `last()` throws.
/// `Sharp\Internal\nonEmpty` throws on an empty list rather than `\array_last` giving null, which a `List<int?>` may
/// hold last, and the receiver runs once. Its result is no generic call's to check: the list's elements are checked.
#[test]
fn last_is_the_last_element_and_throws_on_an_empty_list() {
    assert_eq!(
        Lowered::new(
            "namespace App.Tenant;\n\nclass Report\n{\n    public List<int> make() => [1];\n\n    public int run(List<int> sizes)\n    {\n        const last = sizes.last();\n        return last + this.make().last();\n    }\n}\n"
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "last"
                SILENCE
                  CALL
                    ZVAL "array_last"
                    ARG_LIST
                      CALL
                        ZVAL "Sharp\\Internal\\nonEmpty"
                        ARG_LIST
                          VAR
                            ZVAL "sizes"
              RETURN
                BINARY_OP [1]
                  VAR
                    ZVAL "last"
                  SILENCE
                    CALL
                      ZVAL "array_last"
                      ARG_LIST
                        CALL
                          ZVAL "Sharp\\Internal\\nonEmpty"
                          ARG_LIST
                            METHOD_CALL
                              VAR
                                ZVAL "this"
                              ZVAL "make"
                              ARG_LIST
        "#}
    );
}

/// ```php
/// $stock = \is_array($stock) ? new \Sharp\Set<string>($stock) : $stock;
/// $held = $listed ? $names : $stock;
/// return (\is_array($held) ? \Sharp\Internal\contains($held, 'tea') : \Sharp\Internal\containsKey($held, 'tea'))
///     && (\is_array($held) ? \count($held) : \Sharp\Internal\size($held)) > 0;
/// ```
///
/// A member a `List` shares with a `Map` or a `Set` runs on a value that may be either, spec section 12: the `List`'s
/// member when the value is an array, and the other collection's member otherwise, each as its own call runs it.
#[test]
fn a_shared_list_method_on_a_value_that_may_be_another_collection_tests_for_the_list() {
    assert_eq!(
        Lowered::new(
            "namespace App.Tenant;\n\nclass Report\n{\n    public bool run(bool listed, List<string> names, Set<string> stock)\n    {\n        let held = listed ? names : stock;\n        return held.contains(\"tea\") && held.count() > 0;\n    }\n}\n"
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "stock"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Set"
                      ARG_LIST
                        VAR
                          ZVAL "stock"
                    ZVAL "string"
                  VAR
                    ZVAL "stock"
              ASSIGN
                VAR
                  ZVAL "held"
                CONDITIONAL
                  VAR
                    ZVAL "listed"
                  VAR
                    ZVAL "names"
                  VAR
                    ZVAL "stock"
              RETURN
                AND
                  CONDITIONAL [1]
                    CALL
                      ZVAL "is_array"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                    CALL
                      ZVAL "Sharp\\Internal\\contains"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                        ZVAL "tea"
                    CALL
                      ZVAL "Sharp\\Internal\\containsKey"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                        ZVAL "tea"
                  GREATER
                    CONDITIONAL [1]
                      CALL
                        ZVAL "is_array"
                        ARG_LIST
                          VAR
                            ZVAL "held"
                      CALL
                        ZVAL "count"
                        ARG_LIST
                          VAR
                            ZVAL "held"
                      CALL
                        ZVAL "Sharp\\Internal\\size"
                        ARG_LIST
                          VAR
                            ZVAL "held"
                    ZVAL 0
        "#}
    );
    // A receiver that runs something runs once, before an argument that runs something:
    // `[$receiver#1 = $this->listed() ? $this->names : $this->stock, [$argument#2 = $this->wanted(), …][1]][1]`.
    let run = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    private List<string> names = [];\n\n    private Set<string> stock = [];\n\n    public bool listed() => true;\n\n    public string wanted() => \"tea\";\n\n    public bool run() => (this.listed() ? this.names : this.stock).contains(this.wanted());\n}\n",
    )
    .body_of("run");
    let (receiver, argument) = (run.find(r##"ZVAL "receiver#1""##), run.find(r##"ZVAL "argument#2""##));
    assert!(receiver.is_some() && receiver < argument, "{run}");
    assert_eq!(run.matches(r#"ZVAL "listed""#).count(), 1, "{run}");
    // A change passes the place, the local, to both, and a named argument goes by its name to both, which then run as
    // static calls with the type arguments of their own kind.
    let body = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public bool run(bool listed, List<string> names, Set<string> stock)\n    {\n        let held = listed ? names : stock;\n        held.add(\"tea\");\n        return held.contains(value: \"tea\");\n    }\n}\n",
    )
    .body();
    let changes = &body[body.find("  CONDITIONAL [1]").expect("the change")..];
    assert_eq!(
        format!("STMT_LIST\n{changes}"),
        indoc! {r#"
            STMT_LIST
              CONDITIONAL [1]
                CALL
                  ZVAL "is_array"
                  ARG_LIST
                    VAR
                      ZVAL "held"
                CALL
                  ZVAL "Sharp\\Internal\\add"
                  ARG_LIST
                    VAR
                      ZVAL "held"
                    ZVAL "tea"
                CALL
                  ZVAL "Sharp\\Internal\\addKey"
                  ARG_LIST
                    VAR
                      ZVAL "held"
                    ZVAL "tea"
              RETURN
                CONDITIONAL [1]
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                  STATIC_CALL
                    ZVAL "Sharp\\ListMembers"
                    ZVAL "contains"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                      NAMED_ARG
                        ZVAL "value"
                        ZVAL "tea"
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "string"
                  STATIC_CALL
                    ZVAL "Sharp\\SetMembers"
                    ZVAL "contains"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                      NAMED_ARG
                        ZVAL "value"
                        ZVAL "tea"
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "string"
        "#}
    );
    assert_eq!(run.matches(r#"ZVAL "wanted""#).count(), 1, "{run}");
}

/// ```php
/// $counts = new \Sharp\Map<string, int>();
/// \Sharp\Internal\removeKey($counts, $key);
/// ```
///
/// Spec section 12: the empty literal `[:]` a `Map` local holds leaves it a `Map`, so `remove` is the `Map`'s member,
/// though an empty array the checker cannot place resolves to the `List`'s.
#[test]
fn an_empty_map_local_runs_the_maps_remove() {
    assert_eq!(
        body_in("void run(string key)", "        Map<string, int> counts = [:];\n        counts.remove(key);\n", &[]),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "counts"
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "Sharp\\Map"
                    ARG_LIST
                  ZVAL "string, int"
              CALL
                ZVAL "Sharp\\Internal\\removeKey"
                ARG_LIST
                  VAR
                    ZVAL "counts"
                  VAR
                    ZVAL "key"
        "#}
    );
}

/// ```php
/// return \is_array($held) ? \count($held)
///     : ($held instanceof \Sharp\Map ? \Sharp\Internal\size($held)
///         : ($held instanceof \Sharp\Set ? \Sharp\Internal\size($held) : $held->count()));
/// ```
///
/// Spec section 12: a member of a value that may be any collection or an object tests the kind the value holds, a
/// `List` as an array and a `Map` and a `Set` as the object each runs as, and runs that kind's member, or the object's
/// own method by an ordinary method call.
#[test]
fn a_member_of_a_value_that_may_be_any_collection_or_an_object_tests_each_kind() {
    let body = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public int count() => 7;\n\n    public int run(int pick, List<int> items, Map<string, int> counts, Set<int> tags)\n    {\n        let held = pick == 0 ? items : (pick == 1 ? counts : (pick == 2 ? tags : this));\n        return held.count();\n    }\n}\n",
    )
    .body_of("run");
    let returned = &body[body.find("  RETURN").expect("the return")..];

    assert_eq!(
        format!("STMT_LIST\n{returned}"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL [1]
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                  CALL
                    ZVAL "count"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                  CONDITIONAL [1]
                    INSTANCEOF
                      VAR
                        ZVAL "held"
                      ZVAL "Sharp\\Map"
                    CALL
                      ZVAL "Sharp\\Internal\\size"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                    CONDITIONAL [1]
                      INSTANCEOF
                        VAR
                          ZVAL "held"
                        ZVAL "Sharp\\Set"
                      CALL
                        ZVAL "Sharp\\Internal\\size"
                        ARG_LIST
                          VAR
                            ZVAL "held"
                      METHOD_CALL
                        VAR
                          ZVAL "held"
                        ZVAL "count"
                        ARG_LIST
        "#}
    );

    // The object's own method takes the arguments as the members do, a named one by its name.
    let body = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public bool contains(int value) => value == 7;\n\n    public bool run(bool boxed, Set<int> tags, int wanted)\n    {\n        let held = boxed ? this : tags;\n        return held.contains(value: wanted);\n    }\n}\n",
    )
    .body_of("run");
    let own = &body[body.find("METHOD_CALL").expect("the object's own method")..];

    assert_eq!(own.matches("NAMED_ARG").count(), 1, "{body}");
    assert!(own.contains(r#"ZVAL "value""#) && own.contains(r#"ZVAL "wanted""#), "{body}");
}

/// ```php
/// return [$argument#1 = fn ($value) => 1, \is_array($held) ? \Sharp\Internal\associateBy($held, $argument#1, 'int, int')
///     : \Sharp\Internal\associateBy($held, $argument#1, 'int, string')][1];
/// ```
///
/// Spec section 12: each kind's member a value that may be a `List` or a `Map` runs makes the `Map` its own call on that
/// kind makes, of the type arguments the checker inferred for it, not of the union of both.
#[test]
fn a_member_of_each_kind_makes_the_map_of_its_own_type() {
    let body = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public Any run(bool listed, List<int> items, Map<string, string> names)\n    {\n        let held = listed ? items : names;\n        return held.associateBy(value => 1);\n    }\n}\n",
    )
    .body_of("run");

    assert_eq!(body.matches(r#"ZVAL "Sharp\\Internal\\associateBy""#).count(), 2, "{body}");
    assert_eq!(body.matches(r#"ZVAL "int, int""#).count(), 1, "{body}");
    assert_eq!(body.matches(r#"ZVAL "int, string""#).count(), 1, "{body}");
}

/// Spec section 12: a null-safe member of a value that may be a `List`, a `Set` or null skips the null as the chain's
/// test, and runs the member of the kind the value holds.
#[test]
fn a_null_safe_member_of_a_value_that_may_be_either_collection_tests_null_then_each_kind() {
    let body = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public int? run(bool listed, bool missing, List<int> items, Set<int> tags)\n    {\n        let held = missing ? null : (listed ? items : tags);\n        return held?.count();\n    }\n}\n",
    )
    .body_of("run");
    let returned = &body[body.find("  RETURN").expect("the return")..];

    assert_eq!(
        format!("STMT_LIST\n{returned}"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "held"
                    ZVAL null
                  ZVAL null
                  CONDITIONAL [1]
                    CALL
                      ZVAL "is_array"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                    CALL
                      ZVAL "count"
                      ARG_LIST
                        VAR
                          ZVAL "held"
                    CALL
                      ZVAL "Sharp\\Internal\\size"
                      ARG_LIST
                        VAR
                          ZVAL "held"
        "#}
    );
}

/// ```php
/// return @\max(\Sharp\Internal\nonEmpty($sizes)) + @\max(\Sharp\Internal\nonEmpty($this->make()));
/// ```
///
/// A `List<int>`'s `max()` and `min()` are its largest and smallest element, PHP's `\max` and `\min` on the array,
/// and throw `OutOfRangeException` on an empty list, as `last()` does, where PHP's throw a `ValueError`:
/// `Sharp\Internal\nonEmpty` gives the list it takes, and throws on an empty one. The receiver runs once.
#[test]
fn max_and_min_are_the_largest_and_smallest_element_and_throw_on_an_empty_list() {
    for method in ["max", "min"] {
        assert_eq!(
            Lowered::new(&format!(
                "namespace App.Tenant;\n\nclass Report\n{{\n    public List<int> make() => [1];\n\n    public int run(List<int> sizes) => sizes.{method}() + this.make().{method}();\n}}\n"
            ))
            .body(),
            format!(
                indoc! {r#"
                    STMT_LIST
                      RETURN
                        BINARY_OP [1]
                          SILENCE
                            CALL
                              ZVAL "{method}"
                              ARG_LIST
                                CALL
                                  ZVAL "Sharp\\Internal\\nonEmpty"
                                  ARG_LIST
                                    VAR
                                      ZVAL "sizes"
                          SILENCE
                            CALL
                              ZVAL "{method}"
                              ARG_LIST
                                CALL
                                  ZVAL "Sharp\\Internal\\nonEmpty"
                                  ARG_LIST
                                    METHOD_CALL
                                      VAR
                                        ZVAL "this"
                                      ZVAL "make"
                                      ARG_LIST
                "#},
                method = method
            ),
            "{method}"
        );
    }
}

/// ```php
/// \Sharp\Internal\insert($tags, 0, 'a');
/// $removed = \Sharp\Internal\remove($tags, 'a');
/// \Sharp\Internal\clear($tags);
/// return $removed && \Sharp\Internal\remove($prices, $price);
/// ```
///
/// Spec section 12's changes to a `List` write it back where it lives: each is the engine function of its name, which
/// takes the list by reference. `remove(value)` removes the first element `==` the value, by spec section 19's `==`
/// of the element type, as `Money`'s `operator ==`, renumbers the list and gives whether it removed one.
#[test]
fn list_insert_remove_and_clear_change_the_list_where_it_lives() {
    assert_eq!(
        ledger_body(
            "bool run(List<string> tags, List<Money> prices, Money price)",
            "        tags.insert(0, \"a\");\n        const removed = tags.remove(\"a\");\n        tags.clear();\n        return removed && prices.remove(price);\n"
        ),
        indoc! {r#"
            STMT_LIST
              CALL
                ZVAL "Sharp\\Internal\\insert"
                ARG_LIST
                  VAR
                    ZVAL "tags"
                  ZVAL 0
                  ZVAL "a"
              ASSIGN
                VAR
                  ZVAL "removed"
                CALL
                  ZVAL "Sharp\\Internal\\remove"
                  ARG_LIST
                    VAR
                      ZVAL "tags"
                    ZVAL "a"
              CALL
                ZVAL "Sharp\\Internal\\clear"
                ARG_LIST
                  VAR
                    ZVAL "tags"
              RETURN
                AND
                  VAR
                    ZVAL "removed"
                  CALL
                    ZVAL "Sharp\\Internal\\remove"
                    ARG_LIST
                      VAR
                        ZVAL "prices"
                      VAR
                        ZVAL "price"
        "#}
    );
}

