/// ```php
/// (\array_key_exists(0, $rows) ? (($rows[0] === null) ? null : \Sharp\Internal\add($rows[0], 5)) : throw …);
/// (\array_key_exists(1, $maybe) ? (($maybe[1] === null) ? null : \Sharp\Internal\insert($maybe[1], 0, 6)) : throw …);
/// [${'receiver#1'} = $this->held, ${'kept#2'} = ${'receiver#1'}, (\array_key_exists(0, ${'receiver#1'}) ? … : throw …),
///     ${'receiver#1'} === ${'kept#2'} || ($this->held = ${'receiver#1'})][2];
/// ((${'nullsafe#1'} = $maybe[0]) === null) ? null : \Sharp\Internal\entries(${'nullsafe#1'}, 'int, int');
/// (\array_key_exists(2, $maybe) ? (($maybe[2] === null) ? null : \Sharp\Internal\clear($maybe[2])) : throw …);
/// return ((${'nullsafe#1'} = $maybe[3]) === null) ? null : \Sharp\Internal\contains(${'nullsafe#1'}, 4);
/// ```
///
/// Spec section 12 makes a `List` index a place, so a change after `?.` on one runs on the index itself, as a change
/// without `?.` does, and reaches the element the list stores, here a local's, a parameter's and a hooked property's,
/// which PHP gives no reference to, so the change runs on its value and its `set` stores it back once it changed. A
/// missing index throws, so `?.` skips only a null element. A read after `?.` tests the element it holds first.
#[test]
fn a_null_safe_change_through_a_list_index_runs_on_the_index() {
    assert_eq!(
        child_body(
            "bool? run(List<List<int>?> rows, List<List<int>?> maybe)",
            "        rows[0]?.add(5);\n        maybe[1]?.insert(0, 6);\n        this.held[0]?.add(7);\n        maybe[0]?.entries();\n        maybe[2]?.clear();\n        return maybe[3]?.contains(4);\n",
            "<?php namespace App\\Tenant; class Base { /** @var list<list<int>|null> */ public array $held = [[1]] { set { $this->held = $value; } } }"
        ),
        indoc! {r#"
            STMT_LIST
              CONDITIONAL [1]
                CALL
                  ZVAL "array_key_exists"
                  ARG_LIST
                    ZVAL 0
                    VAR
                      ZVAL "rows"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    DIM
                      VAR
                        ZVAL "rows"
                      ZVAL 0
                    ZVAL null
                  ZVAL null
                  CALL
                    ZVAL "Sharp\\Internal\\add"
                    ARG_LIST
                      DIM
                        VAR
                          ZVAL "rows"
                        ZVAL 0
                      ZVAL 5
                THROW
                  NEW
                    ZVAL "OutOfRangeException"
                    ARG_LIST
                      BINARY_OP [8]
                        ZVAL "Undefined array key "
                        ZVAL 0
              CONDITIONAL [1]
                CALL
                  ZVAL "array_key_exists"
                  ARG_LIST
                    ZVAL 1
                    VAR
                      ZVAL "maybe"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    DIM
                      VAR
                        ZVAL "maybe"
                      ZVAL 1
                    ZVAL null
                  ZVAL null
                  CALL
                    ZVAL "Sharp\\Internal\\insert"
                    ARG_LIST
                      DIM
                        VAR
                          ZVAL "maybe"
                        ZVAL 1
                      ZVAL 0
                      ZVAL 6
                THROW
                  NEW
                    ZVAL "OutOfRangeException"
                    ARG_LIST
                      BINARY_OP [8]
                        ZVAL "Undefined array key "
                        ZVAL 1
              DIM
                ARRAY [3]
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "receiver#1"
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "held"
                    null
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "kept#2"
                      VAR
                        ZVAL "receiver#1"
                    null
                  ARRAY_ELEM
                    CONDITIONAL [1]
                      CALL
                        ZVAL "array_key_exists"
                        ARG_LIST
                          ZVAL 0
                          VAR
                            ZVAL "receiver#1"
                      CONDITIONAL [1]
                        BINARY_OP [16]
                          DIM
                            VAR
                              ZVAL "receiver#1"
                            ZVAL 0
                          ZVAL null
                        ZVAL null
                        CALL
                          ZVAL "Sharp\\Internal\\add"
                          ARG_LIST
                            DIM
                              VAR
                                ZVAL "receiver#1"
                              ZVAL 0
                            ZVAL 7
                      THROW
                        NEW
                          ZVAL "OutOfRangeException"
                          ARG_LIST
                            BINARY_OP [8]
                              ZVAL "Undefined array key "
                              ZVAL 0
                    null
                  ARRAY_ELEM
                    OR
                      BINARY_OP [16]
                        VAR
                          ZVAL "receiver#1"
                        VAR
                          ZVAL "kept#2"
                      ASSIGN
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "held"
                        VAR
                          ZVAL "receiver#1"
                    null
                ZVAL 2
              CONDITIONAL [1]
                BINARY_OP [16]
                  ASSIGN
                    VAR
                      ZVAL "nullsafe#1"
                    DIM
                      VAR
                        ZVAL "maybe"
                      ZVAL 0
                  ZVAL null
                ZVAL null
                CALL
                  ZVAL "Sharp\\Internal\\entries"
                  ARG_LIST
                    VAR
                      ZVAL "nullsafe#1"
                    ZVAL "int, int"
              CONDITIONAL [1]
                CALL
                  ZVAL "array_key_exists"
                  ARG_LIST
                    ZVAL 2
                    VAR
                      ZVAL "maybe"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    DIM
                      VAR
                        ZVAL "maybe"
                      ZVAL 2
                    ZVAL null
                  ZVAL null
                  CALL
                    ZVAL "Sharp\\Internal\\clear"
                    ARG_LIST
                      DIM
                        VAR
                          ZVAL "maybe"
                        ZVAL 2
                THROW
                  NEW
                    ZVAL "OutOfRangeException"
                    ARG_LIST
                      BINARY_OP [8]
                        ZVAL "Undefined array key "
                        ZVAL 2
              RETURN
                CONDITIONAL [1]
                  BINARY_OP [16]
                    ASSIGN
                      VAR
                        ZVAL "nullsafe#1"
                      DIM
                        VAR
                          ZVAL "maybe"
                        ZVAL 3
                    ZVAL null
                  ZVAL null
                  CALL
                    ZVAL "Sharp\\Internal\\contains"
                    ARG_LIST
                      VAR
                        ZVAL "nullsafe#1"
                      ZVAL 4
        "#}
    );
}

/// ```php
/// ((${'nullsafe#1'} = $other) === null) ? null : \Sharp\Internal\add(${'nullsafe#1'}->grid, [1]);
/// return ($rows === null) ? null : \count(\Sharp\Internal\removeLast($rows));
/// ```
///
/// A change after `?.` reaches the place below it as a change without `?.` does: `other?.grid.add([1])` adds to the
/// property of the object `other` holds, and `rows?.removeLast().count()` counts what `removeLast` removed. Each
/// skips the rest of its chain where the value before `?.` is null, one test around the whole chain.
#[test]
fn a_change_after_a_null_safe_link_reaches_the_place_below_it() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    private List<List<int>> grid = [];\n\n    public int? run(Report? other, List<List<int>>? rows)\n    {\n        other?.grid.add([1]);\n        return rows?.removeLast().count();\n    }\n}\n",
    );

    assert_eq!(
        lowered.body_of("run"),
        indoc! {r#"
            STMT_LIST
              CONDITIONAL [1]
                BINARY_OP [16]
                  ASSIGN
                    VAR
                      ZVAL "nullsafe#1"
                    VAR
                      ZVAL "other"
                  ZVAL null
                ZVAL null
                CALL
                  ZVAL "Sharp\\Internal\\add"
                  ARG_LIST
                    PROP
                      VAR
                        ZVAL "nullsafe#1"
                      ZVAL "grid"
                    ARRAY [3]
                      ARRAY_ELEM
                        ZVAL 1
                        null
              RETURN
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "rows"
                    ZVAL null
                  ZVAL null
                  CALL
                    ZVAL "count"
                    ARG_LIST
                      CALL
                        ZVAL "Sharp\\Internal\\removeLast"
                        ARG_LIST
                          VAR
                            ZVAL "rows"
        "#}
    );
}

/// ```php
/// [$receiver#1 = $this->sizes, $kept#2 = $receiver#1, $receiver#1['a'] = $extra,
///     $receiver#1 === $kept#2 || ($this->sizes = $receiver#1)][2];
/// [$receiver#1 = $this->sizes, $kept#2 = $receiver#1, $receiver#1['b'] ??= 2, …][2];
/// [$receiver#1 = $this->me(), $receiver#2 = $receiver#1->sizes, $kept#3 = $receiver#2, $receiver#2['c'] ??= 3,
///     $receiver#2 === $kept#3 || ($receiver#1->sizes = $receiver#2)][3];
/// ```
///
/// PHP gives no reference to a hooked property, so a write into the `Map` one holds writes a hidden copy of it, which
/// its `set` hook then stores once the write changed it, as a member that changes the property does. A `??=` writes
/// only for a missing key, and an object that runs something is held once. A property without hooks keeps PHP's
/// write, as `literals_are_short_arrays_and_an_index_is_a_dim` shows.
#[test]
fn a_write_into_a_map_a_hooked_property_holds_stores_it_through_the_property() {
    assert_eq!(
        child_body(
            "void run(int extra)",
            "        this.sizes[\"a\"] = extra;\n        this.sizes[\"b\"] ??= 2;\n        this.me().sizes[\"c\"] ??= 3;\n    }\n\n    private Report me()\n    {\n        return this;\n",
            "<?php namespace App\\Tenant; class Base { /** @var array<string, int> */ public array $sizes = ['a' => 0] { set { $this->sizes = $value; } } }"
        ),
        indoc! {r#"
            STMT_LIST
              DIM
                ARRAY [3]
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "receiver#1"
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "sizes"
                    null
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "kept#2"
                      VAR
                        ZVAL "receiver#1"
                    null
                  ARRAY_ELEM
                    ASSIGN
                      DIM
                        VAR
                          ZVAL "receiver#1"
                        ZVAL "a"
                      VAR
                        ZVAL "extra"
                    null
                  ARRAY_ELEM
                    OR
                      BINARY_OP [16]
                        VAR
                          ZVAL "receiver#1"
                        VAR
                          ZVAL "kept#2"
                      ASSIGN
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "sizes"
                        VAR
                          ZVAL "receiver#1"
                    null
                ZVAL 2
              DIM
                ARRAY [3]
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "receiver#1"
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "sizes"
                    null
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "kept#2"
                      VAR
                        ZVAL "receiver#1"
                    null
                  ARRAY_ELEM
                    ASSIGN_COALESCE
                      DIM
                        VAR
                          ZVAL "receiver#1"
                        ZVAL "b"
                      ZVAL 2
                    null
                  ARRAY_ELEM
                    OR
                      BINARY_OP [16]
                        VAR
                          ZVAL "receiver#1"
                        VAR
                          ZVAL "kept#2"
                      ASSIGN
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "sizes"
                        VAR
                          ZVAL "receiver#1"
                    null
                ZVAL 2
              DIM
                ARRAY [3]
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "receiver#1"
                      METHOD_CALL
                        VAR
                          ZVAL "this"
                        ZVAL "me"
                        ARG_LIST
                    null
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "receiver#2"
                      PROP
                        VAR
                          ZVAL "receiver#1"
                        ZVAL "sizes"
                    null
                  ARRAY_ELEM
                    ASSIGN
                      VAR
                        ZVAL "kept#3"
                      VAR
                        ZVAL "receiver#2"
                    null
                  ARRAY_ELEM
                    ASSIGN_COALESCE
                      DIM
                        VAR
                          ZVAL "receiver#2"
                        ZVAL "c"
                      ZVAL 3
                    null
                  ARRAY_ELEM
                    OR
                      BINARY_OP [16]
                        VAR
                          ZVAL "receiver#2"
                        VAR
                          ZVAL "kept#3"
                      ASSIGN
                        PROP
                          VAR
                            ZVAL "receiver#1"
                          ZVAL "sizes"
                        VAR
                          ZVAL "receiver#2"
                    null
                ZVAL 3
        "#}
    );
}

/// ```php
/// \Sharp\Internal\set($sizes, 0, $extra);
/// (\array_key_exists($extra, $grid) ? \Sharp\Internal\set($grid[$extra], 1, 2)
///     : throw new \OutOfRangeException('Undefined array key ' . $extra));
/// ```
///
/// Spec section 12: `x[i] = v` on a `List` replaces the element at `i`, and throws `OutOfRangeException` past the end,
/// where PHP's write would append or leave a gap. So it is the standard library's `set` member, whose inline form
/// calls the engine's `set`, which takes the list's place by reference: a local, or an element of another `List` that
/// exists, since PHP's write to a missing one would add it.
#[test]
fn a_list_index_write_replaces_the_element_through_set() {
    assert_eq!(
        body_in(
            "void run(List<int> sizes, List<List<int>> grid, int extra)",
            "        sizes[0] = extra;\n        grid[extra][1] = 2;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              CALL
                ZVAL "Sharp\\Internal\\set"
                ARG_LIST
                  VAR
                    ZVAL "sizes"
                  ZVAL 0
                  VAR
                    ZVAL "extra"
              CONDITIONAL [1]
                CALL
                  ZVAL "array_key_exists"
                  ARG_LIST
                    VAR
                      ZVAL "extra"
                    VAR
                      ZVAL "grid"
                CALL
                  ZVAL "Sharp\\Internal\\set"
                  ARG_LIST
                    DIM
                      VAR
                        ZVAL "grid"
                      VAR
                        ZVAL "extra"
                    ZVAL 1
                    ZVAL 2
                THROW
                  NEW
                    ZVAL "OutOfRangeException"
                    ARG_LIST
                      BINARY_OP [8]
                        ZVAL "Undefined array key "
                        VAR
                          ZVAL "extra"
        "#}
    );
}

/// The index write runs the standard library's `set` member, as every member of a `List` runs its library member, so
/// the unit names that member's form among the forms it inlines, and a change to the form reaches the write.
#[test]
fn a_list_index_write_runs_the_standard_library_s_set_member() {
    let code = "namespace App.Tenant;\n\nclass Report\n{\n    public void run(List<int> sizes)\n    {\n        sizes[0] = 1;\n    }\n}\n";
    let lowered = Lowered::new(code);
    let inlined: Vec<String> = lowered
        .unit()
        .expect("the source lowers")
        .inlined()
        .iter()
        .map(|read| String::from_utf8_lossy(&read.name).into_owned())
        .collect();

    assert_eq!(inlined, ["sharp\\listmembers::set"]);
}

/// ```php
/// \Sharp\Internal\set($sizes, ${'index#1'} = $this->at(), $sizes[${'index#1'}] + $extra);
/// \Sharp\Internal\set($sizes, 0, $sizes[0] + 1);
/// \Sharp\Internal\set($names, 0, $names[0] . "s");
/// return \Sharp\Internal\set($sizes, 1, $sizes[1] - 1);
/// ```
///
/// `list[i] op= v`, `++list[i]` and `--list[i]` write what the operator gives on the element, through `set`, and `+=`
/// on a `List<string>` element joins the strings, spec section 24. An index that runs something runs once, in a hidden
/// variable. `list[i]++` and `list[i]--` give the element before the write, which `set` gives, as Kotlin's does.
#[test]
fn a_compound_write_or_a_step_on_a_list_index_sets_what_the_operator_gives() {
    assert_eq!(
        body_in(
            "int run(List<int> sizes, int extra, List<string> names)",
            "        sizes[this.at()] += extra;\n        ++sizes[0];\n        names[0] += \"s\";\n        return sizes[1]--;\n    }\n\n    private int at()\n    {\n        return 0;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              CALL
                ZVAL "Sharp\\Internal\\set"
                ARG_LIST
                  VAR
                    ZVAL "sizes"
                  ASSIGN
                    VAR
                      ZVAL "index#1"
                    METHOD_CALL
                      VAR
                        ZVAL "this"
                      ZVAL "at"
                      ARG_LIST
                  BINARY_OP [1]
                    DIM
                      VAR
                        ZVAL "sizes"
                      VAR
                        ZVAL "index#1"
                    VAR
                      ZVAL "extra"
              CALL
                ZVAL "Sharp\\Internal\\set"
                ARG_LIST
                  VAR
                    ZVAL "sizes"
                  ZVAL 0
                  BINARY_OP [1]
                    DIM
                      VAR
                        ZVAL "sizes"
                      ZVAL 0
                    ZVAL 1
              CALL
                ZVAL "Sharp\\Internal\\set"
                ARG_LIST
                  VAR
                    ZVAL "names"
                  ZVAL 0
                  BINARY_OP [8]
                    DIM
                      VAR
                        ZVAL "names"
                      ZVAL 0
                    ZVAL "s"
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\set"
                  ARG_LIST
                    VAR
                      ZVAL "sizes"
                    ZVAL 1
                    BINARY_OP [2]
                      DIM
                        VAR
                          ZVAL "sizes"
                        ZVAL 1
                      ZVAL 1
        "#}
    );
}

/// ```php
/// return \Sharp\Internal\set($sizes, 0, ${'stored#1'} = $extra) ? ${'stored#1'} : ${'stored#1'};
/// ```
///
/// `set` gives the element it replaced, as Kotlin's does, so a write whose value code reads gives the value it stores
/// from a hidden variable, as PHP has no expression that runs one and gives another. A write that is a statement of its
/// own gives nothing anyone reads, so it is the call alone.
#[test]
fn a_list_index_write_whose_value_is_read_gives_the_value_it_stores() {
    assert_eq!(
        body_in("int run(List<int> sizes, int extra)", "        return sizes[0] = extra;\n", &[]),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL [1]
                  CALL
                    ZVAL "Sharp\\Internal\\set"
                    ARG_LIST
                      VAR
                        ZVAL "sizes"
                      ZVAL 0
                      ASSIGN
                        VAR
                          ZVAL "stored#1"
                        VAR
                          ZVAL "extra"
                  VAR
                    ZVAL "stored#1"
                  VAR
                    ZVAL "stored#1"
        "#}
    );
}

/// ```php
/// \Sharp\ListMembers::set($sizes, $this->at(), $extra);
/// ```
///
/// An index write lowers its index and its value before it runs `set`, so it copies only a form that reads its slots
/// in order before it calls anything. A `set` whose form calls first is a call of the library's member.
#[test]
fn a_list_index_write_calls_a_set_whose_form_calls_before_it_reads_every_slot() {
    let (path, members) = common::effect_classes::LIST_MEMBERS;
    let calls_first =
        members.replace("Internal.set(list, index, value)", "Internal.set(list, global.intval(index), value)");
    let forms: InlineForms = common::checked(path, &calls_first, &[], inline_forms)
        .expect("the library file is checked")
        .into_iter()
        .collect();
    let code = method_with(
        "void run(List<int> sizes, int extra)",
        "        sizes[this.at()] = extra;\n    }\n\n    private int at()\n    {\n        return 0;\n",
    );
    let lowered = Lowered(common::checked_inlining(&common::sharp_files::type_file(&code), &code, &[], &forms, lower));

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              STATIC_CALL
                ZVAL "Sharp\\ListMembers"
                ZVAL "set"
                ARG_LIST
                  VAR
                    ZVAL "sizes"
                  METHOD_CALL
                    VAR
                      ZVAL "this"
                    ZVAL "at"
                    ARG_LIST
                  VAR
                    ZVAL "extra"
        "#}
    );
}

/// ```php
