///     ${'receiver#1'} === ${'kept#2'} || ($this->held = ${'receiver#1'})][2];
/// [${'receiver#1'} = $this->me(), ${'receiver#2'} = ${'receiver#1'}->held, ${'kept#3'} = ${'receiver#2'},
///     \Sharp\Internal\set(${'receiver#2'}, 0, ${'receiver#2'}[0] * 2),
///     ${'receiver#2'} === ${'kept#3'} || (${'receiver#1'}->held = ${'receiver#2'})][3];
