/// ```php
/// $prefix = "v";
/// $check = function (\Sharp\Set|array $tags) use ($prefix) { $tags = \is_array($tags) ? new \Sharp\Set<string>($tags) : $tags; return \Sharp\Internal\containsKey($tags, $prefix); };
/// $size = function (\Sharp\Set|array $tags) { $tags = \is_array($tags) ? new \Sharp\Set<string>($tags) : $tags; return \count($tags); };
/// return $check(new \Sharp\Set<string>(['a'])) ? $size(new \Sharp\Set<string>(['b'])) : 0;
/// ```
///
/// A list literal passed to a lambda's `Set` parameter is a `Set`, and plain PHP may pass a PHP array, so a lambda
/// makes each `Set` parameter a `Set` object first, as a method does. PHP's `fn` has no statements before its
/// expression, so a lambda with an expression body and a `Set` parameter is a `CLOSURE` whose `use` list captures what
/// the binder says it captures.
#[test]
fn a_lambda_with_a_set_parameter_is_a_closure_that_makes_it_a_set_first() {
    assert_eq!(
        body_in(
            "int run()",
            "        const prefix = \"v\";\n        const check = (Set<string> tags) => tags.contains(prefix);\n        const size = (Set<string> tags) => {\n            return tags.count();\n        };\n        return check([\"a\"]) ? size([\"b\"]) : 0;\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "prefix"
                ZVAL "v"
              ASSIGN
                VAR
                  ZVAL "check"
                CLOSURE "" @10-10
                  PARAM_LIST
                    PARAM
                      TYPE_UNION
                        ZVAL "Sharp\\Set"
                        TYPE [7]
                      ZVAL "tags"
                      null
                      null
                      null
                      null
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Set<string>"
                  CLOSURE_USES
                    ZVAL "prefix"
                  STMT_LIST
                    ASSIGN
                      VAR
                        ZVAL "tags"
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            VAR
                              ZVAL "tags"
                        SHARP_TYPE_ARGS
                          NEW
                            ZVAL "Sharp\\Set"
                            ARG_LIST
                              VAR
                                ZVAL "tags"
                          ZVAL "string"
                        VAR
                          ZVAL "tags"
                    RETURN
                      CALL
                        ZVAL "Sharp\\Internal\\containsKey"
                        ARG_LIST
                          VAR
                            ZVAL "tags"
                          VAR
                            ZVAL "prefix"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<bool(Set<string>)>"
                  null
              ASSIGN
                VAR
                  ZVAL "size"
                CLOSURE "" @11-13
                  PARAM_LIST
                    PARAM
                      TYPE_UNION
                        ZVAL "Sharp\\Set"
                        TYPE [7]
                      ZVAL "tags"
                      null
                      null
                      null
                      null
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Set<string>"
                  null
                  STMT_LIST
                    ASSIGN
                      VAR
                        ZVAL "tags"
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            VAR
                              ZVAL "tags"
                        SHARP_TYPE_ARGS
                          NEW
                            ZVAL "Sharp\\Set"
                            ARG_LIST
                              VAR
                                ZVAL "tags"
                          ZVAL "string"
                        VAR
                          ZVAL "tags"
                    RETURN
                      CALL
                        ZVAL "Sharp\\Internal\\size"
                        ARG_LIST
                          VAR
                            ZVAL "tags"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int(Set<string>)>"
                  null
              RETURN
                CONDITIONAL
                  CALL
                    VAR
                      ZVAL "check"
                    ARG_LIST
                      SHARP_TYPE_ARGS
                        NEW
                          ZVAL "Sharp\\Set"
                          ARG_LIST
                            ARRAY [3]
                              ARRAY_ELEM
                                ZVAL "a"
                                null
                        ZVAL "string"
                  CALL
                    VAR
                      ZVAL "size"
                    ARG_LIST
                      SHARP_TYPE_ARGS
                        NEW
                          ZVAL "Sharp\\Set"
                          ARG_LIST
                            ARRAY [3]
                              ARRAY_ELEM
                                ZVAL "b"
                                null
                        ZVAL "string"
                  ZVAL 0
        "#}
    );
}

/// `App\Tenant\Order`, a plain PHP class whose rows a lazy chain reads.
const ORDER: (&str, &str) = (
    "src/App/Tenant/Order.php",
    "<?php\n\nnamespace App\\Tenant;\n\nfinal class Order\n{\n    public function __construct(public bool $paid, public string $number)\n    {\n    }\n}\n",
);

/// ```php
/// return \Sharp\Sequence::from($orders)->filter(fn ($o) => $o->paid)->map(fn ($o) => $o->number)->take(100)->toList();
/// ```
///
/// A call of a lazy operation of `Iterable<T>`, spec section 12, runs the method `Sharp\Internal\IterableMethods`
/// declares on the engine's `Sharp\Sequence`. A chain reads its receiver through one `\Sharp\Sequence::from`, and each
/// later operation calls the `Sequence` the one before it gave.
#[test]
fn a_lazy_chain_is_one_sequence_from_its_receiver_and_each_operation_on_it() {
    assert_eq!(
        body_in(
            "List<string> run(Iterable<Order> orders)",
            "        return orders.filter(o => o.paid).map(o => o.number).take(100).toList();\n",
            &[ORDER]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                METHOD_CALL
                  METHOD_CALL
                    METHOD_CALL
                      METHOD_CALL
                        STATIC_CALL
                          ZVAL "Sharp\\Sequence"
                          ZVAL "from"
                          ARG_LIST
                            VAR
                              ZVAL "orders"
                        ZVAL "filter"
                        ARG_LIST
                          ARROW_FUNC "" @9-9
                            PARAM_LIST
                              PARAM
                                null
                                ZVAL "o"
                                null
                                null
                                null
                                null
                            null
                            PROP
                              VAR
                                ZVAL "o"
                              ZVAL "paid"
                            SHARP_TYPE_ARGS
                              null
                              ZVAL "Function<bool(App.Tenant.Order)>"
                            null
                      ZVAL "map"
                      ARG_LIST
                        ARROW_FUNC "" @9-9
                          PARAM_LIST
                            PARAM
                              null
                              ZVAL "o"
                              null
                              null
                              null
                              null
                          null
                          PROP
                            VAR
                              ZVAL "o"
                            ZVAL "number"
                          SHARP_TYPE_ARGS
                            null
                            ZVAL "Function<string(App.Tenant.Order)>"
                          null
                    ZVAL "take"
                    ARG_LIST
                      ZVAL 100
                  ZVAL "toList"
                  ARG_LIST
        "#}
    );
}

/// ```php
/// $held = $sizes;
/// $held = $sizes;
/// $small = \Sharp\Sequence::from($held)->filter(fn ($n) => $n < 10);
/// return \Sharp\Sequence::from($small)->take(2)->toList();
/// ```
///
/// A `List` held as an `Iterable<T>` has the lazy operations, whatever was assigned to its place last, so its call
/// reads it through `from` too. A local that holds a chain's `Sequence` is read through `from` again, which gives that
/// `Sequence` back.
#[test]
fn a_list_held_as_an_iterable_and_a_local_holding_a_chain_are_read_through_from() {
    assert_eq!(
        body_in(
            "List<int> run(List<int> sizes)",
            "        Iterable<int> held = sizes;\n        held = sizes;\n        Iterable<int> small = held.filter(n => n < 10);\n        return small.take(2).toList();\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "held"
                VAR
                  ZVAL "sizes"
              ASSIGN
                VAR
                  ZVAL "held"
                VAR
                  ZVAL "sizes"
              ASSIGN
                VAR
                  ZVAL "small"
                METHOD_CALL
                  STATIC_CALL
                    ZVAL "Sharp\\Sequence"
                    ZVAL "from"
                    ARG_LIST
                      VAR
                        ZVAL "held"
                  ZVAL "filter"
                  ARG_LIST
                    ARROW_FUNC "" @11-11
                      PARAM_LIST
                        PARAM
                          null
                          ZVAL "n"
                          null
                          null
                          null
                          null
                      null
                      BINARY_OP [20]
                        VAR
                          ZVAL "n"
                        ZVAL 10
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "Function<bool(int)>"
                      null
              RETURN
                METHOD_CALL
                  METHOD_CALL
                    STATIC_CALL
                      ZVAL "Sharp\\Sequence"
                      ZVAL "from"
                      ARG_LIST
                        VAR
                          ZVAL "small"
                    ZVAL "take"
                    ARG_LIST
                      ZVAL 2
                  ZVAL "toList"
                  ARG_LIST
        "#}
    );
}

/// Spec section 14.3: the value of a lazy operation of an `Iterable<T>` is a closure over the collection that runs the
/// operation on its `\Sharp\Sequence::from`, and a null-safe one is that closure where the collection is not null.
#[test]
fn a_lazy_operation_value_is_a_closure_over_the_sequence_of_its_collection() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public Iterable<int> kept(Iterable<int> sizes)\n    {\n        const keep = sizes.filter;\n        return keep((int n) => n > 1);\n    }\n\n    public bool maybe(Iterable<int>? sizes)\n    {\n        const keep = sizes?.filter;\n        return keep == null;\n    }\n}\n",
    );

    assert_eq!(
        lowered.body_of("kept"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "keep"
                CALL
                  CLOSURE "" @7-7
                    PARAM_LIST
                      PARAM
                        null
                        ZVAL "receiver"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        CLOSURE "" @7-7
                          PARAM_LIST
                            PARAM
                              ZVAL "Closure"
                              ZVAL "predicate"
                              null
                              null
                              null
                              null
                          CLOSURE_USES
                            ZVAL "receiver"
                          STMT_LIST
                            RETURN
                              METHOD_CALL
                                STATIC_CALL
                                  ZVAL "Sharp\\Sequence"
                                  ZVAL "from"
                                  ARG_LIST
                                    VAR
                                      ZVAL "receiver"
                                ZVAL "filter"
                                ARG_LIST
                                  VAR
                                    ZVAL "predicate"
                          null
                          null
                    null
                    null
                  ARG_LIST
                    VAR
                      ZVAL "sizes"
              RETURN
                CALL
                  VAR
                    ZVAL "keep"
                  ARG_LIST
                    ARROW_FUNC "" @8-8
                      PARAM_LIST
                        PARAM
                          ZVAL [1] "int"
                          ZVAL "n"
                          null
                          null
                          null
                          null
                      null
                      GREATER
                        VAR
                          ZVAL "n"
                        ZVAL 1
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "Function<bool(int)>"
                      null
        "#}
    );
    assert_eq!(
        lowered.body_of("maybe"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "keep"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "sizes"
                    ZVAL null
                  ZVAL null
                  CALL
                    CLOSURE "" @13-13
                      PARAM_LIST
                        PARAM
                          null
                          ZVAL "receiver"
                          null
                          null
                          null
                          null
                      null
                      STMT_LIST
                        RETURN
                          CLOSURE "" @13-13
                            PARAM_LIST
                              PARAM
                                ZVAL "Closure"
                                ZVAL "predicate"
                                null
                                null
                                null
                                null
                            CLOSURE_USES
                              ZVAL "receiver"
                            STMT_LIST
                              RETURN
                                METHOD_CALL
                                  STATIC_CALL
                                    ZVAL "Sharp\\Sequence"
                                    ZVAL "from"
                                    ARG_LIST
                                      VAR
                                        ZVAL "receiver"
                                  ZVAL "filter"
                                  ARG_LIST
                                    VAR
                                      ZVAL "predicate"
                            null
                            null
                      null
                      null
                    ARG_LIST
                      VAR
                        ZVAL "sizes"
              RETURN
                BINARY_OP [16]
                  VAR
                    ZVAL "keep"
                  ZVAL null
        "#}
    );
}

/// ```php
/// return ($maybe === null ? null : \Sharp\Sequence::from($maybe)->filter(fn ($o) => $o->paid));
/// ```
///
/// PHP's `?->` cannot read a receiver through `from`, so a null-safe lazy operation is the conditional a null-safe
/// property call is, over the `Sequence` call. php-src writes each `null` as a `CONST`, which compiles to the same
/// value as the `ZVAL` the bridge writes.
#[test]
fn a_null_safe_lazy_operation_is_a_conditional_over_the_sequence_call() {
    assert_eq!(
        body_in(
            "Iterable<Order>? run(Iterable<Order>? maybe)",
            "        return maybe?.filter(o => o.paid);\n",
            &[ORDER]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "maybe"
                    ZVAL null
                  ZVAL null
                  METHOD_CALL
                    STATIC_CALL
                      ZVAL "Sharp\\Sequence"
                      ZVAL "from"
                      ARG_LIST
                        VAR
                          ZVAL "maybe"
                    ZVAL "filter"
                    ARG_LIST
                      ARROW_FUNC "" @9-9
                        PARAM_LIST
                          PARAM
                            null
                            ZVAL "o"
                            null
                            null
                            null
                            null
                        null
                        PROP
                          VAR
                            ZVAL "o"
                          ZVAL "paid"
                        SHARP_TYPE_ARGS
                          null
                          ZVAL "Function<bool(App.Tenant.Order)>"
                        null
        "#}
    );
}

/// ```php
/// public function many(\Sharp\Set|array ...$groups): int
/// {
///     $groups = \array_map(fn ($collection#1) => \is_array($collection#1) ? new \Sharp\Set<string>($collection#1) : $collection#1, $groups);
///     return \count($groups);
/// }
/// public static function op_Addition(\App\Tenant\Order $order, \Sharp\Set|array $tags): \App\Tenant\Order
/// {
///     $tags = \is_array($tags) ? new \Sharp\Set<string>($tags) : $tags;
///     return $order;
/// }
/// ```
///
/// A variadic `Set` parameter takes a list or a `Set` for each of its elements, so each list becomes a `Set`, under
/// its position or its name, and a null element of a nullable one stays null. An operator is a method, and makes each
/// `Set` parameter a `Set` first too.

#[test]
fn a_variadic_or_operator_set_parameter_becomes_a_set_before_the_body_runs() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Order\n{\n    public int many(Set<string> ...groups) => groups.count();\n\n    public static readonly Order operator +(Order order, Set<string> tags) => order;\n\n    public int maybe(Set<string>? ...groups) => groups.count();\n}\n",
    );
    let body = |name: &str| lowered.render(lowered.child(lowered.method_named(name), 2));

    assert_eq!(
        body("many"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "groups"
                CALL
                  ZVAL "array_map"
                  ARG_LIST
                    ARROW_FUNC "" @5-5
                      PARAM_LIST
                        PARAM
                          null
                          ZVAL "collection#1"
                          null
                          null
                          null
                          null
                      null
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            VAR
                              ZVAL "collection#1"
                        SHARP_TYPE_ARGS
                          NEW
                            ZVAL "Sharp\\Set"
                            ARG_LIST
                              VAR
                                ZVAL "collection#1"
                          ZVAL "string"
                        VAR
                          ZVAL "collection#1"
                      null
                      null
                    VAR
                      ZVAL "groups"
              RETURN
                CALL
                  ZVAL "count"
                  ARG_LIST
                    VAR
                      ZVAL "groups"
        "#}
    );
    assert_eq!(
        body("op_Addition"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "tags"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "tags"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Set"
                      ARG_LIST
                        VAR
                          ZVAL "tags"
                    ZVAL "string"
                  VAR
                    ZVAL "tags"
              RETURN
                VAR
                  ZVAL "order"
        "#}
    );
    assert_eq!(
        body("maybe"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "groups"
                CALL
                  ZVAL "array_map"
                  ARG_LIST
                    ARROW_FUNC "" @9-9
                      PARAM_LIST
                        PARAM
                          null
                          ZVAL "collection#1"
                          null
                          null
                          null
                          null
                      null
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            VAR
                              ZVAL "collection#1"
                        SHARP_TYPE_ARGS
                          NEW
                            ZVAL "Sharp\\Set"
                            ARG_LIST
                              VAR
                                ZVAL "collection#1"
                          ZVAL "string"
                        VAR
                          ZVAL "collection#1"
                      null
                      null
                    VAR
                      ZVAL "groups"
              RETURN
                CALL
                  ZVAL "count"
                  ARG_LIST
                    VAR
                      ZVAL "groups"
        "#}
    );
}

/// ```php
/// public array $tags = [] { set { $this->tags = []; \Sharp\Internal\add($this->tags, "x"); } }
/// ```
///
/// `field = []` leaves the property a `List<string>`, so the checker checks `field.add` as `List.add`, and the add
/// lowers as that call, which a hook passes its own backing store by reference.
#[test]
fn an_emptied_list_field_takes_add_as_the_list_method() {
    let lowered = Lowered::new(
        "class Product\n{\n    public List<string> tags { get; set { field = []; field.add(\"x\"); } } = [];\n}\n",
    );

    assert_eq!(
        property_groups(&lowered),
        [indoc! {r#"
            PROP_GROUP [1]
              SHARP_TYPE_ARGS
                TYPE [7]
                ZVAL "List<string>"
              PROP_DECL
                PROP_ELEM
                  ZVAL "tags"
                  ARRAY [3]
                  null
                  STMT_LIST
                    PROPERTY_HOOK "set" @3-3
                      null
                      null
                      STMT_LIST
                        ASSIGN
                          PROP
                            VAR
                              ZVAL "this"
                            ZVAL "tags"
                          ARRAY [3]
                        CALL
                          ZVAL "Sharp\\Internal\\add"
                          ARG_LIST
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "tags"
                            ZVAL "x"
                      null
                      null
              null
        "#}]
    );
}

/// ```php
/// $standings = [$status];
/// $standings = [];
/// \Sharp\Internal\add($standings, $status);
/// ```
///
/// `standings = []` leaves the local a `List<Calc>`, whose `add` takes an element, so a case goes in as the case.
#[test]
fn a_backed_enum_value_goes_into_an_emptied_list_add_as_its_case() {
    assert_eq!(
        body_in(
            "void run(Calc status)",
            "        List<Calc> standings = [status];\n        standings = [];\n        standings.add(status);\n",
            &[("src/Lib/Calc.php", "<?php namespace Lib; enum Calc: string { case Active = 'a'; case Closed = 'c'; }")]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "standings"
                ARRAY [3]
                  ARRAY_ELEM
                    VAR
                      ZVAL "status"
                    null
              ASSIGN
                VAR
                  ZVAL "standings"
                ARRAY [3]
              CALL
                ZVAL "Sharp\\Internal\\add"
                ARG_LIST
                  VAR
                    ZVAL "standings"
                  VAR
                    ZVAL "status"
        "#}
    );
}

/// `sizes = []` leaves the parameter a `List<int>`, whose indexes come from `entries()`, so `[k, v]` is refused before
/// the lowering reads a key type.
#[test]
fn an_emptied_list_loop_by_key_and_value_is_refused_before_lowering() {
    let lowered = Lowered::with(
        &method_with(
            "int run(int extra, List<int> sizes)",
            "        sizes = [];\n        for (const [index, size] of sizes) {\n            extra += index + size;\n        }\n        return extra;\n",
        ),
        &[],
    );

    assert_eq!(
        lowered.diagnostics(),
        ["10:37 compile error: `for (const [k, v] of x)` reads the keys of a `Map`, and this is a `List`."]
    );
    assert_eq!(lowered.nodes().len(), 0);
}

/// ```php
/// public function apply(\Closure $step, ?\Closure $other = null): \Closure { return $step; }
/// ```
///
/// A function type runs as PHP's `\Closure`, so its type is the full name `Closure` with `ZEND_NAME_FQ`, which is 0.
/// `step` states its effect, since a function parameter whose type states none is never returned (spec section 29).
#[test]
fn a_function_type_is_the_closure_class() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public Function<int(string, int) uses Http> apply(Function<int(string, int) uses Http> step, Function<void()>? other = null) { return step; }\n}\n",
    );
    let method = lowered.nodes().iter().position(|node| node.kind == sharp_kind::SHARP_AST_METHOD).expect("a method");

    assert_eq!(
        lowered.render(lowered.child(method as u32, 0)),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL "Closure"
                ZVAL "step"
                null
                null
                null
                null
              PARAM
                ZVAL [256] "Closure"
                ZVAL "other"
                ZVAL null
                null
                null
                null
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(method as u32, 3)),
        indoc! {r#"
            SHARP_TYPE_ARGS
              ZVAL "Closure"
              ZVAL "Function<Function<int(string, int) uses Sharp.Net.Http>(Function<int(string, int) uses Sharp.Net.Http>, Function<void()>?)>"
        "#}
    );
}

/// `App\Shop\Cart` and `App\Shop\Charge`, the parameter and return types of the function types below.
const SHOP: (&str, &str) =
    ("src/App/Shop/Shop.php", "<?php namespace App\\Shop; final class Cart {} final class Charge {}");
/// The type and the declaration of the one property `code` declares, rendered, after the checker accepts `code`.
fn lowered_field(code: &str) -> (String, String) {
    let lowered = Lowered::with(code, &[SHOP]);
    assert_eq!(lowered.diagnostics(), Vec::<String>::new(), "the source lowers");
    let group =
        lowered.nodes().iter().position(|node| node.kind == sharp_kind::SHARP_AST_PROP_GROUP).expect("a property");

    (lowered.render(lowered.child(group as u32, 0)), lowered.render(lowered.child(group as u32, 1)))
}

/// ```php
/// private \Closure $charge;
/// ```
///
/// A function type's effects are the checker's alone, so a function type with effects runs as PHP's `\Closure`.
#[test]
fn a_function_type_with_effects_is_the_closure_class() {
    let (hint, declaration) = lowered_field(
        "namespace App.Shop;\n\nclass Checkout\n{\n    Function<Charge(Cart) uses Http> charge;\n\n    public Checkout(Function<Charge(Cart) uses Http> charge)\n    {\n        this.charge = charge;\n    }\n}\n",
    );

    assert_eq!(hint, "ZVAL \"Closure\"\n");
    assert_eq!(declaration, "PROP_DECL\n  PROP_ELEM\n    ZVAL \"charge\"\n    null\n    null\n    null\n");
}

/// ```php
/// private ?\Closure $fallback = null;
/// ```
///
/// `[256]` is `ZEND_TYPE_NULLABLE`.
#[test]
fn a_nullable_function_type_with_effects_is_the_nullable_closure_class() {
    let (hint, declaration) = lowered_field(
        "namespace App.Shop;\n\nclass Checkout\n{\n    Function<Charge(Cart) uses Http>? fallback = null;\n\n    public Function<Charge(Cart) uses Http>? current() => this.fallback;\n}\n",
    );

    assert_eq!(hint, "ZVAL [256] \"Closure\"\n");
    assert_eq!(declaration, "PROP_DECL\n  PROP_ELEM\n    ZVAL \"fallback\"\n    ZVAL null\n    null\n    null\n");
}

/// ```php
/// private \Sharp\Map $handlers;
/// ```
///
/// A `Map` is its class, whatever its value type, under the type text a write from plain PHP is checked against, whose
/// function type lists its effects by their full names, sorted.
#[test]
fn a_map_of_function_types_with_two_effects_is_the_map_class() {
    let (hint, declaration) = lowered_field(
        "namespace App.Shop;\n\nclass Checkout\n{\n    Map<string, Function<Charge(Cart) uses Mail, Http>> handlers;\n\n    public Checkout(Map<string, Function<Charge(Cart) uses Mail, Http>> handlers)\n    {\n        this.handlers = handlers;\n    }\n}\n",
    );

    assert_eq!(
        hint,
        indoc! {r#"
            SHARP_TYPE_ARGS
              ZVAL "Sharp\\Map"
              ZVAL "Map<string, Function<App.Shop.Charge(App.Shop.Cart) uses Sharp.Net.Http, Sharp.Net.Mail>>"
        "#}
    );
    assert_eq!(declaration, "PROP_DECL\n  PROP_ELEM\n    ZVAL \"handlers\"\n    null\n    null\n    null\n");
}

/// ```php
/// private \Closure $apply;
/// ```
#[test]
fn a_function_type_taking_a_function_type_with_effects_is_the_closure_class() {
    let (hint, declaration) = lowered_field(
        "namespace App.Shop;\n\nclass Checkout\n{\n    Function<int(Function<int(int) uses Http>) uses Mail> apply;\n\n    public Checkout(Function<int(Function<int(int) uses Http>) uses Mail> apply)\n    {\n        this.apply = apply;\n    }\n}\n",
    );

    assert_eq!(hint, "ZVAL \"Closure\"\n");
    assert_eq!(declaration, "PROP_DECL\n  PROP_ELEM\n    ZVAL \"apply\"\n    null\n    null\n    null\n");
}

/// ```php
/// /** @template TItem of \Lib\DatabaseEntity */
/// class PaginatedList
/// {
///     /** @var list<TItem> */
///     private array $rows;
///
///     public function __construct(array $rows)
///     {
///         $this->rows = $rows;
///     }
///
///     public function first(): \Lib\DatabaseEntity { return $this->rows[0]; }
///
///     public function find(int $id): ?\Lib\DatabaseEntity { return null; }
/// }
/// ```
///
/// PHP types are erased, so a type parameter is the type of its bound, its list lowers to nothing, and a `List` of it
/// is still `array`, as the PHP twin a developer writes with `@template` declares it. A call or a write from plain PHP
/// checks each element of `rows` against the object's own type argument, `List<$0>`. The class's last member is the
/// `SHARP_TYPE_ARGS` that declares its hidden type-argument slot, whose text is its bounds.
#[test]
fn a_type_parameter_is_its_bound_and_its_list_lowers_to_nothing() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.DatabaseEntity;

        public class PaginatedList<TItem : DatabaseEntity>
        {
            private List<TItem> rows;

            public PaginatedList(List<TItem> rows)
            {
                this.rows = rows;
            }

            public TItem first() => this.rows[0];

            public TItem? find(int id) { return null; }
        }
    "},
        &[("src/Lib/DatabaseEntity.php", "<?php namespace Lib; abstract class DatabaseEntity {}")],
    );
    let tree = lowered.tree();

    assert_eq!(
        lowered.render(lowered.child(lowered.root(), 2)),
        indoc! {r#"
            CLASS "PaginatedList" @5-17
              null
              null
              STMT_LIST
                PROP_GROUP [32772]
                  SHARP_TYPE_ARGS
                    TYPE [7]
                    ZVAL "List<$0>"
                  PROP_DECL
                    PROP_ELEM
                      ZVAL "rows"
                      null
                      null
                      null
                  null
                METHOD [1] "__construct" @9-12
                  PARAM_LIST
                    PARAM
                      TYPE [7]
                      ZVAL "rows"
                      null
                      null
                      null
                      null
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "List<$0>"
                  null
                  STMT_LIST
                    ASSIGN
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "rows"
                      VAR
                        ZVAL "rows"
                  null
                  null
                METHOD [1] "first" @14-14
                  PARAM_LIST
                  null
                  STMT_LIST
                    RETURN
                      DIM
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "rows"
                        ZVAL 0
                  SHARP_TYPE_ARGS
                    ZVAL "Lib\\DatabaseEntity"
                    ZVAL "Function<$0()>"
                  null
                METHOD [1] "find" @16-16
                  PARAM_LIST
                    PARAM
                      ZVAL [1] "int"
                      ZVAL "id"
                      null
                      null
                      null
                      null
                  null
                  STMT_LIST
                    RETURN
                      ZVAL null
                  SHARP_TYPE_ARGS
                    ZVAL [256] "Lib\\DatabaseEntity"
                    ZVAL "Function<$0?(int)>"
                  null
                SHARP_CLASS_METADATA
                  null
                  ZVAL "Lib.DatabaseEntity"
                  null
              null
              null
        "#}
    );
    assert!(!tree.contains("TItem"), "{tree}");
}

/// ```php
/// /** @template T */
/// public function first(array $items) { return $items[0]; }
/// /** @template T */
/// public function maybe() { return null; }
/// /** @template T */
/// public function pick(mixed $a) { return $a; }
/// ```
///
/// A type parameter without a bound is `mixed`. PHP refuses `?mixed` and `mixed` in a union, and `mixed` already holds
/// null and every other type, so `T?` and a union that holds `T` are `mixed` too. A result of `mixed` declares no PHP
/// type, so a plain PHP method without one fits it.
#[test]
fn a_type_parameter_without_a_bound_is_mixed_alone_nullable_or_in_a_union() {
    let lowered = Lowered::new(indoc! {"
        class Report
        {
            public T first<T>(List<T> items) => items[0];

            public T? maybe<T>() { return null; }

            public T|int pick<T>(T a) { return a; }
        }
    "});
    let members = lowered.child(lowered.child(lowered.root(), 1), 2);
    // The PHP return type is the first child of the `SHARP_TYPE_ARGS` that holds the method's function type.
    let signature = |index: u32| {
        let method = lowered.child(members, index);

        format!(
            "{}{}",
            lowered.render(lowered.child(method, 0)),
            lowered.render(lowered.child(lowered.child(method, 3), 0))
        )
    };

    assert_eq!(
        signature(0),
        indoc! {r#"
            PARAM_LIST
              PARAM
                TYPE [7]
                ZVAL "items"
                null
                null
                null
                null
              SHARP_TYPE_ARGS
                ZVAL "Any?"
                null
            null
        "#}
    );
    assert_eq!(
        signature(1),
        indoc! {r#"
            PARAM_LIST
              SHARP_TYPE_ARGS
                ZVAL "Any?"
                null
            null
        "#}
    );
    assert_eq!(
        signature(2),
        indoc! {r##"
            PARAM_LIST
              PARAM
                ZVAL [1] "mixed"
                ZVAL "a"
                null
                null
                null
                null
              SHARP_TYPE_ARGS
                ZVAL "Any?"
                null
            null
        "##}
    );
}

/// ```php
/// /** @template T of object */
/// public function keep(object $value): object { return $value; }
/// ```
///
/// A type parameter bounded by `Object` is PHP's `object`, and a call from plain PHP gives it `Object`.
#[test]
fn a_type_parameter_bounded_by_object_is_php_object() {
    let lowered = Lowered::new(indoc! {"
        class Report
        {
            public T keep<T : Object>(T value) => value;
        }
    "});
    let method = lowered.child(lowered.child(lowered.child(lowered.root(), 1), 2), 0);

    assert_eq!(
        format!("{}{}", lowered.render(lowered.child(method, 0)), lowered.render(lowered.child(method, 3))),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL [1] "object"
                ZVAL "value"
                null
                null
                null
                null
              SHARP_TYPE_ARGS
                ZVAL "Object"
                null
            SHARP_TYPE_ARGS
              ZVAL [1] "object"
              ZVAL "Function<#0(#0)>"
        "#}
    );
}

/// ```php
/// /** @template TItem of \Lib\DatabaseEntity&\Lib\Shareable */
/// public function share(\Lib\DatabaseEntity&\Lib\Shareable $item): (\Lib\DatabaseEntity&\Lib\Shareable)|null
/// ```
///
/// A type parameter bound by several classes is their `TYPE_INTERSECTION`, as php-src's `intersection_type` rule
/// builds `A&B`. PHP refuses `?` before an intersection, so a nullable one is the DNF type `(A&B)|null`: a
/// `TYPE_UNION` of the intersection and `null`.
#[test]
fn a_type_parameter_bound_by_several_classes_is_their_intersection() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.DatabaseEntity;
        import Lib.Shareable;

        class Report<TItem : DatabaseEntity & Shareable>
        {
            public TItem? share(TItem item) { return null; }
        }
    "},
        &[(
            "src/Lib/DatabaseEntity.php",
            "<?php namespace Lib; abstract class DatabaseEntity {} interface Shareable {}",
        )],
    );
    let method = lowered.child(lowered.child(lowered.child(lowered.root(), 2), 2), 0);

    assert_eq!(
        lowered.render(lowered.child(method, 0)),
        indoc! {r#"
            PARAM_LIST
              PARAM
                TYPE_INTERSECTION
                  ZVAL "Lib\\DatabaseEntity"
                  ZVAL "Lib\\Shareable"
                ZVAL "item"
                null
                null
                null
                null
              SHARP_TYPE_ARGS
                null
                ZVAL "$0"
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(method, 3)),
        indoc! {r#"
            SHARP_TYPE_ARGS
              TYPE_UNION
                TYPE_INTERSECTION
                  ZVAL "Lib\\DatabaseEntity"
                  ZVAL "Lib\\Shareable"
                ZVAL [1] "null"
              ZVAL "Function<$0?($0)>"
        "#}
    );
}

/// ```php
/// /** @template TItem of \Lib\Order */
/// public function keep(\Lib\Order $order, ?\Lib\Order $other): string { return 'kept'; }
/// /** @template TShared of \Lib\Order&\Lib\Shareable */
/// public function share(\Lib\Order $order, string $type): string { return 'shared'; }
/// ```
///
/// PHP refuses a union that names a type twice, or names an intersection beside one of its classes. So members that
/// erase to one type appear once, and a member another member already holds is left out: `TItem|Order` is `Order`,
/// `(TShared|Order)` is `Order`, and `Class<Order>|string` is `string`.
#[test]
fn union_members_that_erase_to_one_type_appear_once() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.Order;
        import Lib.Shareable;

        class Report<TItem : Order>
        {
            public string keep(TItem|Order order, (Order|TItem)? other) { return \"kept\"; }

            public string share<TShared : Order & Shareable>(TShared|Order order, Class<Order>|string type)
            {
                return \"shared\";
            }
        }
    "},
        &[("src/Lib/Order.php", "<?php namespace Lib; class Order {} interface Shareable {}")],
    );
    let members = lowered.child(lowered.child(lowered.root(), 2), 2);
    let parameter_types = |index: u32| {
        let parameters = lowered.child(lowered.child(members, index), 0);

        format!(
            "{}{}",
            lowered.render(lowered.child(lowered.child(parameters, 0), 0)),
            lowered.render(lowered.child(lowered.child(parameters, 1), 0))
        )
    };

    assert_eq!(
        parameter_types(0),
        indoc! {r#"
            ZVAL "Lib\\Order"
            ZVAL [256] "Lib\\Order"
        "#}
    );
    assert_eq!(
        parameter_types(1),
        indoc! {r#"
            ZVAL "Lib\\Order"
            ZVAL [1] "string"
        "#}
    );
}

/// ```php
/// /** @var array<string, class-string<\Lib\Element>> */
/// private \Sharp\Map $elements = new \Sharp\Map();
///
/// /** @param class-string<\Lib\Model> $type */
/// public function load(string $type, ?string $other = null): ?string { return $type; }
///
/// /** @param \Lib\PaginatedList<\Lib\Order> $rows */
/// public function page(\Lib\PaginatedList $rows): ?\Lib\PaginatedList { return $rows; }
/// ```
///
/// A generic class type is its class by its full name. Plain PHP receives a class value as its class-name string,
/// spec section 25, so `Class<T>` is `string`, and a `Map` of class values is still its class.
#[test]
fn a_generic_class_type_is_its_class_and_a_class_value_type_is_string() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.Element;
        import Lib.Model;
        import Lib.Order;
        import Lib.PaginatedList;

        class Report
        {
            private Map<string, Class<Element>> elements = [:];

            public Class<Model>? load(Class<Model> type, Class<Model>? other = null) { return other; }

            public PaginatedList<Order>? page(PaginatedList<Order> rows) { return this.elements.count() > 0 ? rows : null; }
        }
    "},
        &[(
            "src/Lib/Model.php",
            "<?php namespace Lib; class Element {} class Model {} class Order {} /** @template T */ class PaginatedList {}",
        )],
    );
    let members = lowered.child(lowered.child(lowered.root(), 2), 2);
    let load = lowered.child(members, 1);
    let page = lowered.child(members, 2);

    assert_eq!(
        lowered.render(lowered.child(lowered.child(members, 0), 0)),
        indoc! {r#"
            SHARP_TYPE_ARGS
              ZVAL "Sharp\\Map"
              ZVAL "Map<string, Class<Lib.Element>>"
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(load, 0)),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL [1] "string"
                ZVAL "type"
                null
                null
                null
                null
              PARAM
                ZVAL [257] "string"
                ZVAL "other"
                ZVAL null
                null
                null
                null
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(load, 3)),
        indoc! {r#"
            SHARP_TYPE_ARGS
              ZVAL [257] "string"
              ZVAL "Function<Class<Lib.Model>?(Class<Lib.Model>, Class<Lib.Model>?)>"
        "#}
    );
    assert_eq!(
        format!("{}{}", lowered.render(lowered.child(page, 0)), lowered.render(lowered.child(page, 3))),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL "Lib\\PaginatedList"
                ZVAL "rows"
                null
                null
                null
                null
            SHARP_TYPE_ARGS
              ZVAL [256] "Lib\\PaginatedList"
              ZVAL "Function<Lib.PaginatedList<Lib.Order>?(Lib.PaginatedList<Lib.Order>)>"
        "#}
    );
}

/// ```php
/// $numbers = [1, $extra];
/// $named = new \Sharp\Map<int|string, int>(['a', 1, 2, $numbers[0]]);
/// $empty = new \Sharp\Map<string, int>();
/// $named['b'] = $numbers[0];
/// $this->sizes['a'] = ($this->sizes['a'] ?? 0) + 1;
/// return $numbers[1];
/// ```
///
/// A list literal is an `ARRAY` with `ZEND_ARRAY_SYNTAX_SHORT`, which is 3, of `ARRAY_ELEM`s. A map literal is a new
/// `Map` of each key followed by its value. An index is a `DIM` of the value and the key, read or written as its place
/// in the tree decides.

#[test]
fn literals_are_short_arrays_and_an_index_is_a_dim() {
    assert_eq!(
        child_body(
            RUN,
            "        List<int> numbers = [1, extra];\n        const named = [\"a\": 1, 2: numbers[0]];\n        const Map<string, int> empty = [:];\n        named[\"b\"] = numbers[0];\n        this.sizes[\"a\"] = (this.sizes[\"a\"] ?? 0) + 1;\n        return numbers[1];\n",
            "<?php namespace App\\Tenant; class Base { /** @var array<string, int> */ public array $sizes = ['a' => 0]; }"
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "numbers"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL 1
                    null
                  ARRAY_ELEM
                    VAR
                      ZVAL "extra"
                    null
              ASSIGN
                VAR
                  ZVAL "named"
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "Sharp\\Map"
                    ARG_LIST
                      ARRAY [3]
                        ARRAY_ELEM
                          ZVAL "a"
                          null
                        ARRAY_ELEM
                          ZVAL 1
                          null
                        ARRAY_ELEM
                          ZVAL 2
                          null
                        ARRAY_ELEM
                          DIM
                            VAR
                              ZVAL "numbers"
                            ZVAL 0
                          null
                  ZVAL "int|string, int"
              ASSIGN
                VAR
                  ZVAL "empty"
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "Sharp\\Map"
                    ARG_LIST
                  ZVAL "string, int"
              ASSIGN
                DIM
                  VAR
                    ZVAL "named"
                  ZVAL "b"
                DIM
                  VAR
                    ZVAL "numbers"
                  ZVAL 0
              ASSIGN
                DIM
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "sizes"
                  ZVAL "a"
                BINARY_OP [1]
                  COALESCE
                    DIM
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "sizes"
                      ZVAL "a"
                    ZVAL 0
                  ZVAL 1
              RETURN
                DIM
                  VAR
                    ZVAL "numbers"
                  ZVAL 1
        "#}
    );
}

/// ```php
/// public function run(mixed $value, mixed $maybe) { $held = $maybe; return $value; }
/// ```
///
/// `Any` and `Any?` are both PHP's `mixed`, which already holds null and refuses `?`, so neither carries
/// `ZEND_TYPE_NULLABLE`. `[1]` is `ZEND_NAME_NOT_FQ`. An `Any` refuses null, spec section 24, so the parameter list
/// ends with the type texts a call from plain PHP is checked against, as for a generic class. A result of `mixed`
/// declares no PHP type, so a plain PHP method without one fits it, and it can hold a `Map` or a `Set`, so `[1]`,
/// `ZEND_SHARP_RESULT_CROSSES`, gives plain PHP the PHP array of one, spec section 12.
#[test]
fn any_and_nullable_any_are_mixed() {
    let lowered = Lowered::new(
        "class Report\n{\n    public Any run(Any value, Any? maybe)\n    {\n        Any? held = maybe;\n        return value;\n    }\n}\n",
    );
    let method = lowered.nodes().iter().position(|node| node.kind == sharp_kind::SHARP_AST_METHOD).expect("a method");

    assert_eq!(
        lowered.render(lowered.child(method as u32, 0)),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL [1] "mixed"
                ZVAL "value"
                null
                null
                null
                null
              PARAM
                ZVAL [1] "mixed"
                ZVAL "maybe"
                null
                null
                null
                null
              SHARP_TYPE_ARGS
                null
                ZVAL "Any, Any?"
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(method as u32, 3)),
        indoc! {r#"
            SHARP_TYPE_ARGS [1]
              null
              ZVAL "Function<Any(Any, Any?)>"
        "#}
    );
    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "held"
                VAR
                  ZVAL "maybe"
              RETURN
                VAR
                  ZVAL "value"
        "#}
    );
}

/// ```php
/// public function run(int $extra): never
/// {
///     throw new \App\Tenant\Failure();
/// }
/// ```
///
/// Spec section 7: a `never` method is PHP's `never`, so PHP throws `TypeError` if it returns.
#[test]
fn a_never_method_is_php_never() {
    let lowered = Lowered::with(
        &method_with("never run(int extra)", "        throw new Failure();\n"),
        &[("src/App/Tenant/Failure.php", "<?php namespace App\\Tenant; final class Failure extends \\Exception {}")],
    );

    assert_eq!(member_in(&[lowered], "Report", &[0, 3]), "ZVAL [1] \"never\"\n");
}

/// Spec section 9: a parameter's default is any expression. One PHP takes as a constant expression stays as written,
/// and any other runs in a static closure the default calls, which the engine runs each time a call leaves the
/// argument out. PHP reads a property in a constant expression only of an enum case, so a property read runs in the
/// closure too.
///
/// ```php
/// public function run(int $at = (static function () { return \Words::distance("a", "b"); })(), int $step = 1 + 2): int
/// public function size(int $size = (static function () { return (new \Report())->count; })()): int
/// ```
#[test]
fn a_parameter_default_that_is_no_constant_expression_runs_in_a_static_closure() {
    let lowered = [Lowered::with(
        "class Report\n{\n    public int count { get; } = 7;\n\n    public int run(int at = Words.distance(\"a\", \"b\"), int step = 1 + 2)\n    {\n        return at + step;\n    }\n\n    public int size(int size = new Report().count) => size;\n}\n",
        &[WORDS],
    )];
    assert_eq!(
        member_in(&lowered, "Report", &[2, 0, 0, 2]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @10-10
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    PROP
                      NEW
                        ZVAL "Report"
                        ARG_LIST
                      ZVAL "count"
                null
                null
              ARG_LIST
        "#}
    );

    assert_eq!(
        member_in(&lowered, "Report", &[1, 0, 0, 2]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @5-5
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    STATIC_CALL
                      ZVAL "Words"
                      ZVAL "distance"
                      ARG_LIST
                        ZVAL "a"
                        ZVAL "b"
                null
                null
              ARG_LIST
        "#}
    );
    assert_eq!(member_in(&lowered, "Report", &[1, 0, 1, 2]), "BINARY_OP [1]\n  ZVAL 1\n  ZVAL 2\n");
}

/// Spec section 2: a constant's value is built from constants. One PHP takes as a constant expression stays as written,
/// and a template, which PHP builds while the code runs, runs in the static closure a computed parameter default runs
/// in, which the engine runs when it first reads the constant.
///
/// ```php
/// public const int GRACE = \Report::DAYS > 7 ? 3 : 1;
/// public const string LABEL = (static function () { return "Trial: {\Report::DAYS} days"; })();
/// ```
#[test]
fn a_constant_value_that_is_no_constant_expression_runs_in_a_static_closure() {
    let lowered = [Lowered::new(
        "class Report\n{\n    public const int DAYS = 14;\n    public const int GRACE = Report.DAYS > 7 ? 3 : 1;\n    public const string LABEL = `Trial: ${Report.DAYS} days`;\n}\n",
    )];

    assert_eq!(
        member_in(&lowered, "Report", &[1, 0, 0, 1]),
        indoc! {r#"
            CONDITIONAL
              GREATER
                CLASS_CONST
                  ZVAL "Report"
                  ZVAL "DAYS"
                ZVAL 7
              ZVAL 3
              ZVAL 1
        "#}
    );
    assert_eq!(
        member_in(&lowered, "Report", &[2, 0, 0, 1]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @5-5
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    ENCAPS_LIST
                      ZVAL "Trial: "
                      CLASS_CONST
                        ZVAL "Report"
                        ZVAL "DAYS"
                      ZVAL " days"
                null
                null
              ARG_LIST
        "#}
    );
}

