/// ```php
/// $page = new \Lib\PaginatedList($rows);
/// $payload = \Lib\Json::decode($body);
/// $found = $this->repository?->find($id);
/// $type = \Lib\PaginatedList::class;
/// ```
///
/// A plain PHP class's `@template` type arguments are erased, so those of its `new` and its `typeof` lower to nothing.
/// A call of its generic method, static or null-safe, carries them, since a PHP# method that overrides or implements it
/// reads them.
#[test]
fn type_arguments_of_a_plain_php_new_lower_to_nothing_and_of_a_call_to_its_type_arguments() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.Json;
        import Lib.Order;
        import Lib.PaginatedList;
        import Lib.Repository;
        import Lib.WebhookPayload;

        class Report
        {
            private Repository? repository = null;

            public void run(List<Order> rows, string body, int id)
            {
                const page = new PaginatedList<Order>(rows);
                const payload = Json.decode<WebhookPayload>(body);
                const found = this.repository?.find<Order>(id);
                const type = typeof(PaginatedList<Order>);
            }
        }
    "},
        &[(
            "src/Lib/Json.php",
            "<?php namespace Lib; class Order {} class WebhookPayload {} /** @template T */ class PaginatedList { /** @param list<T> $rows */ public function __construct(array $rows) {} } final class Json { /** @template T @return T */ public static function decode(string $body): mixed { return null; } } interface Repository { /** @template T @return T|null */ public function find(int $id): mixed; }",
        )],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "page"
                NEW
                  ZVAL "Lib\\PaginatedList"
                  ARG_LIST
                    VAR
                      ZVAL "rows"
              ASSIGN
                VAR
                  ZVAL "payload"
                STATIC_CALL
                  ZVAL "Lib\\Json"
                  ZVAL "decode"
                  ARG_LIST
                    VAR
                      ZVAL "body"
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Lib.WebhookPayload"
              ASSIGN
                VAR
                  ZVAL "found"
                NULLSAFE_METHOD_CALL
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "repository"
                  ZVAL "find"
                  ARG_LIST
                    VAR
                      ZVAL "id"
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Lib.Order"
              ASSIGN
                VAR
                  ZVAL "type"
                CLASS_NAME
                  ZVAL "Lib\\PaginatedList"
        "#}
    );
}

/// A class-like's metadata holds, first, the type arguments its header gives each generic parent and interface, as a
/// type text list of those classes sorted by their text, each of its own type parameters written as `$` and its index.
/// Its second text is its bounds, an interface's as a class's, so the engine knows how many type arguments each takes
/// and which class a type argument may name. Its third is the variance of its type parameters, `+` for `out`, `-` for
/// `in` and `=` for neither, when one of them has `out` or `in`, which the engine reads where it checks a value against
/// a generic type.
#[test]
fn a_class_like_metadata_holds_its_header_type_arguments_its_bounds_and_its_variance() {
    let files = lowered_each(
        &[
            ("src/App/Query.sharp", "namespace App;\n\npublic interface Query<TItem : DatabaseEntity>\n{\n}\n"),
            ("src/App/Base.sharp", "namespace App;\n\npublic class Base<T>\n{\n}\n"),
            ("src/App/Sub.sharp", "namespace App;\n\npublic class Sub<T> : Base<List<T>>, Query<Order>\n{\n}\n"),
            ("src/App/OrderPage.sharp", "namespace App;\n\npublic class OrderPage : Base<Order>\n{\n}\n"),
            ("src/App/Feed.sharp", "namespace App;\n\npublic interface Feed<out TItem, in TKey, TValue>\n{\n}\n"),
        ],
        &[(
            "src/App/Entities.php",
            "<?php namespace App; abstract class DatabaseEntity {} final class Order extends DatabaseEntity {}",
        )],
    );
    let metadata = |lowered: &Lowered| {
        let members = lowered.child(lowered.child(lowered.root(), 2), 2);

        lowered.render(lowered.child(members, lowered.nodes()[members as usize].child_count - 1))
    };

    assert_eq!(
        files.iter().map(metadata).collect::<Vec<_>>(),
        [
            indoc! {r#"
                SHARP_CLASS_METADATA
                  null
                  ZVAL "App.DatabaseEntity"
                  null
            "#},
            indoc! {r#"
                SHARP_CLASS_METADATA
                  null
                  ZVAL "Any?"
                  null
            "#},
            indoc! {r#"
                SHARP_CLASS_METADATA
                  ZVAL "App.Base<List<$0>>, App.Query<App.Order>"
                  ZVAL "Any?"
                  null
            "#},
            indoc! {r#"
                SHARP_CLASS_METADATA
                  ZVAL "App.Base<App.Order>"
                  null
                  null
            "#},
            indoc! {r#"
                SHARP_CLASS_METADATA
                  null
                  ZVAL "Any?, Any?, Any?"
                  ZVAL "+-="
            "#},
        ]
    );
}

/// A bound that names a type parameter of its own class writes it as `Any?`: the bounds are the type arguments of an
/// object plain PHP creates, which has no type argument to give it, and a text that names one would be open.
#[test]
fn a_bound_writes_a_type_parameter_of_its_own_class_as_any() {
    let comparable = ("src/Demo/Comparable.sharp", "namespace Demo;\n\npublic interface Comparable<T>\n{\n}\n");
    let bounds = |declaration: &str| {
        let lowered = Lowered::with(&format!("namespace Demo;\n\n{declaration}"), &[comparable]);
        let members = lowered.child(lowered.child(lowered.root(), 2), 2);
        let metadata = lowered.child(members, lowered.nodes()[members as usize].child_count - 1);

        lowered.render(lowered.child(metadata, 1))
    };

    assert_eq!(
        [
            bounds("public class Sorted<TItem : Comparable<TItem>>\n{\n}\n"),
            bounds("public class Ranked<TKey, TItem : Comparable<TKey>>\n{\n}\n"),
        ],
        ["ZVAL \"Demo.Comparable<Any?>\"\n", "ZVAL \"Any?, Demo.Comparable<Any?>\"\n"]
    );
}

/// A call of a generic method carries the type arguments the checker found, written or inferred, as the last child of
/// its argument list: a `SHARP_TYPE_ARGS` without a `new`. A type parameter of the class the call is in is `$` and its
/// index, and one of the method the call is in is `#` and its index, which the engine reads from the method's own
/// call. A lambda writes them the same way, and the engine reads them from the method's call the lambda captured them
/// from: a lambda whose body, or a lambda in it, names a `#` is a `CLOSURE` whose `use` list ends with the method's
/// hidden local, by value. A method whose call needs its type arguments, or whose parameter names a PHP# class with type
/// arguments, a class value of one or of a type that is no class, or a type parameter, ends its parameter list with its metadata: a `SHARP_TYPE_ARGS` of the bounds of its
/// own type parameters and a type text list with each parameter's type, `Any?` for one the engine never checks. Plain
/// PHP's generics are erased, so a parameter of a plain PHP class with type arguments is never checked, and a call from
/// plain PHP gives a method's own type parameters none, so a parameter of one is never checked either.
#[test]
fn a_generic_call_carries_its_type_arguments_and_a_generic_method_its_metadata() {
    let entities = (
        "src/App/Entities.php",
        "<?php namespace App; abstract class DatabaseEntity {} final class Order extends DatabaseEntity {}",
    );
    let holder = (
        "src/App/Holder.php",
        "<?php namespace App; /** @template T */ final class Holder { /** @return T */ public function get(): mixed { return null; } }",
    );
    let r#box = ("src/App/Box.sharp", "namespace App;\n\npublic class Box<TValue>\n{\n    public Box() { }\n}\n");
    let pair =
        ("src/App/Pair.sharp", "namespace App;\n\npublic class Pair<TFirst, TSecond>\n{\n    public Pair() { }\n}\n");
    let paginated = (
        "src/App/PaginatedList.sharp",
        indoc! {"
        namespace App;

        public class PaginatedList<TItem : DatabaseEntity>
        {
            public PaginatedList() { }

            public Pair<TItem, TOther> pairWith<TOther>() => new Pair<TItem, TOther>();

            public Pair<TItem, TOther> again<TOther>() => this.pairWith<TOther>();

            public int checks<TOther>(Box<TOther> box, Box<TItem> own, Pair<Box<TOther>, Order> nested) => 1;
        }
    "},
    );
    let list = Lowered::with(paginated.1, &[entities, r#box, pair]);
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Repository
        {
            public static List<T> repeat<T>(T value, int times) => [value];

            public List<Order> run(Order order) => Repository.repeat<Order>(order, 3);

            public List<Order> inferred(Order order) => Repository.repeat(order, 2);

            public List<T> forward<T : DatabaseEntity>(T item) => Repository.repeat<T>(item, 1);

            public Box<T> box<T : DatabaseEntity>() => new Box<T>();

            public Function<Box<T>()> later<T>() => () => new Box<T>();

            public Function<Function<List<T>()>()> nested<T>(T item) => () => () => Repository.repeat<T>(item, 1);

            public void show(PaginatedList<Order> page, int count) { }

            public void keep(Holder<Order> holder) { }

            public List<Any?> unbound() => Repository.repeat(new Holder<Any?>().get(), 4);

            public void kinds(Class<PaginatedList<Order>> pages, Class<PaginatedList> any, Class<Order> order, Class<Holder<Order>> holders) { }

            public void types(Class<int|string> either, Class<int> number, Class<Any> anything) { }
        }
    "},
        &[entities, holder, r#box, pair, paginated],
    );

    let call = |count: u32, type_arguments: &str| {
        format!(
            indoc! {r#"
                STMT_LIST
                  RETURN
                    STATIC_CALL
                      ZVAL "App\\Repository"
                      ZVAL "repeat"
                      ARG_LIST
                        VAR
                          ZVAL "{}"
                        ZVAL {}
                        SHARP_TYPE_ARGS
                          null
                          ZVAL "{}"
            "#},
            if count == 1 { "item" } else { "order" },
            count,
            type_arguments,
        )
    };
    // Spec section 22: a call that gives a generic method its type arguments checks the result against the type they
    // give, and one that gives its own method's type parameter leaves the check to the call of that method.
    let checked = |count: u32| {
        format!(
            indoc! {r#"
                STMT_LIST
                  RETURN
                    VERIFY_TYPE_ARGS
                      STATIC_CALL
                        ZVAL "App\\Repository"
                        ZVAL "repeat"
                        ARG_LIST
                          VAR
                            ZVAL "order"
                          ZVAL {}
                          SHARP_TYPE_ARGS
                            null
                            ZVAL "App.Order"
                      ZVAL "List<Any?>, List<App.Order>"
                      ZVAL "App.Repository.repeat()"
            "#},
            count,
        )
    };
    assert_eq!(lowered.body(), checked(3));
    assert_eq!(lowered.body_of("inferred"), checked(2));
    // `new Holder()` binds no `T`, so `get()` gives a type argument nothing chose, which the engine takes as `Any?`.
    assert_eq!(
        lowered.body_of("unbound"),
        indoc! {r#"
            STMT_LIST
              RETURN
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL "App\\Repository"
                    ZVAL "repeat"
                    ARG_LIST
                      METHOD_CALL
                        NEW
                          ZVAL "App\\Holder"
                          ARG_LIST
                        ZVAL "get"
                        ARG_LIST
                      ZVAL 4
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "Any?"
                  ZVAL "List<Any?>"
                  ZVAL "App.Repository.repeat()"
        "#}
    );
    assert_eq!(lowered.body_of("forward"), call(1, "#0"));
    assert_eq!(
        lowered.body_of("box"),
        indoc! {r##"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "App\\Box"
                    ARG_LIST
                  ZVAL "#0"
        "##}
    );
    assert_eq!(
        lowered.body_of("later"),
        indoc! {r##"
            STMT_LIST
              RETURN
                CLOSURE "" @15-15
                  PARAM_LIST
                  CLOSURE_USES
                    ZVAL "\0<sharp>\0types"
                  STMT_LIST
                    RETURN
                      SHARP_TYPE_ARGS
                        NEW
                          ZVAL "App\\Box"
                          ARG_LIST
                        ZVAL "#0"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<App.Box<#0>()>"
                  null
        "##}
    );
    assert_eq!(
        lowered.body_of("nested"),
        indoc! {r##"
            STMT_LIST
              RETURN
                CLOSURE "" @17-17
                  PARAM_LIST
                  CLOSURE_USES
                    ZVAL "item"
                    ZVAL "\0<sharp>\0types"
                  STMT_LIST
                    RETURN
                      CLOSURE "" @17-17
                        PARAM_LIST
                        CLOSURE_USES
                          ZVAL "item"
                          ZVAL "\0<sharp>\0types"
                        STMT_LIST
                          RETURN
                            STATIC_CALL
                              ZVAL "App\\Repository"
                              ZVAL "repeat"
                              ARG_LIST
                                VAR
                                  ZVAL "item"
                                ZVAL 1
                                SHARP_TYPE_ARGS
                                  null
                                  ZVAL "#0"
                        SHARP_TYPE_ARGS [1]
                          null
                          ZVAL "Function<List<#0>()>"
                        null
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<Function<List<#0>()>()>"
                  null
        "##}
    );
    assert_eq!(
        list.body_of("pairWith"),
        indoc! {r##"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "App\\Pair"
                    ARG_LIST
                  ZVAL "$0, #0"
        "##}
    );
    assert_eq!(
        list.body_of("again"),
        indoc! {r##"
            STMT_LIST
              RETURN
                METHOD_CALL
                  VAR
                    ZVAL "this"
                  ZVAL "pairWith"
                  ARG_LIST
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "#0"
        "##}
    );

    let metadata = |bounds: &str, parameters: &str| format!("  SHARP_TYPE_ARGS\n    {bounds}\n    {parameters}\n");
    // A call from plain PHP gives a method's own type parameter no type argument, so a parameter of one has no check.
    assert!(
        lowered.parameters_of("repeat").ends_with(&metadata(r#"ZVAL "Any?""#, "null")),
        "{}",
        lowered.parameters_of("repeat")
    );
    assert!(lowered.parameters_of("forward").ends_with(&metadata(r#"ZVAL "App.DatabaseEntity""#, "null")));
    // A class all of whose type arguments are the method's own takes any object of it, and one that holds such a class
    // as its type argument checks the class.
    assert!(
        list.parameters_of("checks")
            .ends_with(&metadata(r#"ZVAL "Any?""#, r##"ZVAL "Any?, App.Box<$0>, App.Pair<App.Box<#0>, App.Order>""##)),
        "{}",
        list.parameters_of("checks")
    );
    assert!(
        lowered.parameters_of("show").ends_with(&metadata("null", r#"ZVAL "App.PaginatedList<App.Order>, Any?""#)),
        "{}",
        lowered.parameters_of("show")
    );
    // PHP's `string` type checks no class value, so one of a PHP# class with type arguments is checked as its object is.
    assert!(
        lowered
            .parameters_of("kinds")
            .ends_with(&metadata("null", r#"ZVAL "Class<App.PaginatedList<App.Order>>, Any?, Any?, Any?""#)),
        "{}",
        lowered.parameters_of("kinds")
    );
    // A class value of a type that is no class is only the text `typeof` gives that type, which PHP's `string` type
    // doesn't check.
    assert!(
        lowered.parameters_of("types").ends_with(&metadata("null", r#"ZVAL "Class<int|string>, Class<int>, Any?""#)),
        "{}",
        lowered.parameters_of("types")
    );
    assert_eq!(list.parameters_of("pairWith"), format!("PARAM_LIST\n{}", metadata(r#"ZVAL "Any?""#, "null")));
    assert!(!lowered.parameters_of("run").contains("SHARP_TYPE_ARGS"));
    assert!(!list.parameters_of("__construct").contains("SHARP_TYPE_ARGS"));
    assert!(!lowered.parameters_of("keep").contains("SHARP_TYPE_ARGS"), "{}", lowered.parameters_of("keep"));
}

/// A value that enters PHP# from plain PHP is checked, as a parameter checks an argument from plain PHP: a call the
/// checker resolved to plain PHP checks its result in a `VERIFY_TYPE_ARGS` that names the call, wherever the value goes,
/// whether a typed local, a `let`, an argument, a return or a property write takes it. A property has its PHP# type
/// around its PHP type, which PHP's typed property check reads on each write plain PHP makes, and a write from PHP#
/// skips. A PHP# call's return, a call of a function a property holds and a type with nothing to check need none.
#[test]
fn a_value_from_plain_php_is_checked_where_it_enters_php_sharp() {
    let r#box = ("src/App/Box.sharp", "namespace App;\n\npublic class Box<TValue>\n{\n    public Box() { }\n}\n");
    let order = (
        "src/App/Order.sharp",
        "namespace App;\n\npublic class Order\n{\n    private static Box<Order>? latest = null;\n\n    public static Box<Order> make() => new Box<Order>();\n}\n",
    );
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        import Lib;
        import Lib.Pager;

        public class Shelf<TItem>
        {
            public Box<Order>? auto { get; set; } = null;

            public Box<TItem>? own { get; set; } = null;

            public Box<Order>? logged
            {
                get => field;
                set { field = value; }
            } = null;

            protected Box<Order>? inherited = null;

            private Box<Order>? hidden = null;

            public Box<Order>? fixed { get; private set; } = null;

            public Box<Order>? created
            {
                get => field;
                init { field = value; }
            }

            public int count { get; set; } = 0;

            private Function<Box<Order>()> maker = () => new Box<Order>();

            public Shelf(public Box<Order>? promoted { get; set; }, public Box<Order>? frozen { get; }) { }

            public void run()
            {
                Box<Order> box = Pager.orders();
                box = Pager.orders();
                let untyped = Pager.orders();
                this.keep(Pager.orders());
                this.auto = Pager.orders();
                Box<Order> made = Order.make();
                Box<Order> held = this.maker();
                int count = Pager.count();
            }

            public Box<Order> give()
            {
                return Pager.orders();
            }

            public Box<Order> listed()
            {
                return Lib.orders();
            }

            public void keep(Box<Order> box) { }
        }
        "},
        &[
            r#box,
            order,
            (
                "src/Lib/Pager.php",
                "<?php\n\nnamespace Lib;\n\nuse App\\Box;\n\nfinal class Pager\n{\n    /** @return Box<\\App\\Order> */\n    public static function orders(): Box\n    {\n        return new Box();\n    }\n\n    public static function count(): int\n    {\n        return 1;\n    }\n}\n",
            ),
            (
                "src/Lib/orders.php",
                "<?php\n\n/** @return \\App\\Box<\\App\\Order> */\nfunction orders(): \\App\\Box\n{\n    return new \\App\\Box();\n}\n",
            ),
        ],
    );

    // `Pager.orders()`, checked, at the depth `depth`.
    let orders = |depth: usize| {
        let lines = [
            "VERIFY_TYPE_ARGS",
            "  STATIC_CALL",
            r#"    ZVAL "Lib\\Pager""#,
            r#"    ZVAL "orders""#,
            "    ARG_LIST",
            r#"  ZVAL "App.Box<App.Order>""#,
            r#"  ZVAL "Lib\\Pager::orders()""#,
        ];

        lines.map(|line| format!("{}{line}\n", "  ".repeat(depth))).concat()
    };
    let assign = |variable: &str| format!("  ASSIGN\n    VAR\n      ZVAL \"{variable}\"\n{}", orders(2));
    let unchecked = indoc! {r#"
          ASSIGN
            VAR
              ZVAL "made"
            STATIC_CALL
              ZVAL "App\\Order"
              ZVAL "make"
              ARG_LIST
          ASSIGN
            VAR
              ZVAL "held"
            CALL
              PROP
                VAR
                  ZVAL "this"
                ZVAL "maker"
              ARG_LIST
          ASSIGN
            VAR
              ZVAL "count"
            STATIC_CALL
              ZVAL "Lib\\Pager"
              ZVAL "count"
              ARG_LIST
    "#};
    assert_eq!(
        lowered.body(),
        [
            "STMT_LIST\n".to_owned(),
            assign("box"),
            assign("box"),
            assign("untyped"),
            format!("  METHOD_CALL\n    VAR\n      ZVAL \"this\"\n    ZVAL \"keep\"\n    ARG_LIST\n{}", orders(3)),
            format!("  ASSIGN\n    PROP\n      VAR\n        ZVAL \"this\"\n      ZVAL \"auto\"\n{}", orders(2)),
            unchecked.lines().flat_map(|line| ["  ", line, "\n"]).collect(),
        ]
        .concat()
    );
    assert_eq!(lowered.body_of("give"), format!("STMT_LIST\n  RETURN\n{}", orders(2)));
    // A plain PHP function's result names the function.
    assert_eq!(
        lowered.body_of("listed"),
        indoc! {r#"
            STMT_LIST
              RETURN
                VERIFY_TYPE_ARGS
                  CALL
                    ZVAL "orders"
                    ARG_LIST
                  ZVAL "App.Box<App.Order>"
                  ZVAL "orders()"
        "#}
    );

    let tree = lowered.tree();
    // A property's PHP# type stands around its PHP type, whatever the property's visibility and accessors, with a type
    // parameter of its class as `$0`, and a promoted one's around its parameter's.
    let typed = |property: &str, text: &str| {
        format!(
            "SHARP_TYPE_ARGS\n          ZVAL [256] \"App\\\\Box\"\n          ZVAL \"{text}\"\n        PROP_DECL\n          PROP_ELEM\n            ZVAL \"{property}\"\n"
        )
    };
    for (property, text) in [
        ("auto", "App.Box<App.Order>?"),
        ("own", "App.Box<$0>?"),
        ("logged", "App.Box<App.Order>?"),
        ("inherited", "App.Box<App.Order>?"),
        ("hidden", "App.Box<App.Order>?"),
        ("fixed", "App.Box<App.Order>?"),
        ("created", "App.Box<App.Order>?"),
    ] {
        assert!(tree.contains(&typed(property, text)), "{property}: {tree}");
    }
    let static_tree = Lowered::with(order.1, &[r#box]).tree();
    assert!(static_tree.contains(&typed("latest", "App.Box<App.Order>?")), "latest: {static_tree}");
    for parameter in ["promoted", "frozen"] {
        let typed = format!(
            "SHARP_TYPE_ARGS\n              ZVAL [256] \"App\\\\Box\"\n              ZVAL \"App.Box<App.Order>?\"\n            ZVAL \"{parameter}\"\n"
        );
        assert!(tree.contains(&typed), "{parameter}: {tree}");
    }
    // Each of the seven properties of `Shelf` above, and no other: a method's result type holds its function type
    // instead.
    assert_eq!(
        tree.matches("SHARP_TYPE_ARGS\n          ZVAL [256] \"App\\\\Box\"\n          ZVAL \"App.").count(),
        7,
        "{tree}"
    );
    // PHP's typed property check runs the check, so a property takes no `set` hook for it: only a written `set` or
    // `init` body is a hook.
    assert!(!tree.contains("VERIFY_TYPE_ARGS ["), "{tree}");
    assert_eq!(tree.matches("PROPERTY_HOOK \"set\"").count(), 2, "{tree}");
    assert_eq!(tree.matches("PROPERTY_HOOK \"get\"").count(), 2, "{tree}");
}

/// A collection the project's plain PHP returns is checked element by element where it enters PHP#, since its type is
/// a docblock nothing checks. A collection PHP's internal functions return, which the standard library alone calls, is
/// not: the engine guarantees their types. Neither is one whose elements take any value, nor one PHP# can't write, such
/// as `array<array-key, int>`.
#[test]
fn a_collection_the_project_returns_from_plain_php_is_checked_element_by_element() {
    let body = Lowered(common::checked(
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Report.sharp",
        "namespace Sharp;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public int run()\n    {\n        let ints = Calc.ints();\n        let keyed = Calc.keyed();\n        let untyped = Calc.untyped();\n        let anything = Calc.anything();\n        let letters = global.str_split(\"ab\");\n        return 1;\n    }\n}\n",
        &[(
            "src/Lib/Calc.php",
            "<?php namespace Lib; final class Calc { /** @return list<int> */ public static function ints(): array { return []; } /** @return array<array-key, int> */ public static function keyed(): array { return []; } public static function untyped(): array { return []; } /** @return list<mixed> */ public static function anything(): array { return []; } }",
        )],
        lower,
    ))
    .body();

    assert_eq!(body.matches("VERIFY_TYPE_ARGS").count(), 1, "{body}");
    assert!(body.contains("ZVAL \"List<int>\"\n      ZVAL \"Lib\\\\Calc::ints()\""), "{body}");
}

/// Every function a call from plain PHP reaches checks a parameter that names a PHP# class with type arguments, as a
/// method does: an event's constructor, a named constructor, an operator and a lambda, with a block body or an
/// expression body. Each one's parameter list ends with the metadata that holds the parameter's type text.
#[test]
fn every_function_plain_php_calls_checks_its_parameters_type_arguments() {
    let library = [
        ("src/App/Order.sharp", "namespace App;\n\npublic class Order\n{\n}\n"),
        (
            "src/App/PaginatedList.sharp",
            "namespace App;\n\npublic class PaginatedList<TItem>\n{\n    public PaginatedList() { }\n}\n",
        ),
    ];
    let event = Lowered::with("namespace App;\n\npublic event Paged(PaginatedList<Order> page);\n", &library);
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Shelf
        {
            public Shelf(public int count { get; }) { }

            public Shelf.of(PaginatedList<Order> page) : this(1) { }

            public static Shelf operator +(Shelf shelf, PaginatedList<Order> page) => new Shelf(shelf.count);

            public Function<int(PaginatedList<Order>)> counted() => (PaginatedList<Order> page) => 1;

            public Function<void(PaginatedList<Order>)> kept()
            {
                let seen = 0;
                return (PaginatedList<Order> page) => {
                    seen += 1;
                };
            }
        }
    "},
        &library,
    );
    let metadata = |checks: &str| format!("  SHARP_TYPE_ARGS\n    null\n    ZVAL \"{checks}\"\n");

    assert!(event.parameters_of("__construct").ends_with(&metadata("App.PaginatedList<App.Order>")));
    assert!(lowered.parameters_of("of").ends_with(&metadata("App.PaginatedList<App.Order>")));
    assert!(lowered.parameters_of("op_Addition").ends_with(&metadata("Any?, App.PaginatedList<App.Order>")));
    assert_eq!(
        lowered.body_of("counted"),
        indoc! {r#"
            STMT_LIST
              RETURN
                ARROW_FUNC "" @11-11
                  PARAM_LIST
                    PARAM
                      ZVAL "App\\PaginatedList"
                      ZVAL "page"
                      null
                      null
                      null
                      null
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "App.PaginatedList<App.Order>"
                  null
                  ZVAL 1
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int(App.PaginatedList<App.Order>)>"
                  null
        "#}
    );
    assert_eq!(
        lowered.body_of("kept"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "seen"
                ZVAL 0
              RETURN
                CLOSURE "" @16-18
                  PARAM_LIST
                    PARAM
                      ZVAL "App\\PaginatedList"
                      ZVAL "page"
                      null
                      null
                      null
                      null
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "App.PaginatedList<App.Order>"
                  CLOSURE_USES
                    ZVAL [1] "seen"
                  STMT_LIST
                    ASSIGN_OP [1]
                      VAR
                        ZVAL "seen"
                      ZVAL 1
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<void(App.PaginatedList<App.Order>)>"
                  null
        "#}
    );
}

/// A type argument a plain PHP value fixes as a refinement PHP# writes as a wider type carries that type's text:
/// `list<int>` is `List<int>`, `array{a: int}` is `Map<string, int>`, `non-empty-string` is `string`, `positive-int` is
/// `int` and `class-string` is `Class<Object>`. A list or map literal carries its collection's text, as `[1, 2]` does
/// `List<int>`, and keeps a `Set` in it a `Set`. A written type argument carries its own text.
#[test]
fn a_type_argument_a_plain_php_refinement_fixes_carries_its_php_sharp_text() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        import Lib.Pager;

        public class Registry
        {
            public static T keep<T>(T value) => value;

            public void run(Set<string> tags)
            {
                Registry.keep(Pager.list());
                Registry.keep(Pager.text());
                Registry.keep(Pager.count());
                Registry.keep(Pager.class());
                Registry.keep<Map<string, int>>(Pager.shape());
                Registry.keep<int|string>(Pager.key());
                Registry.keep(Pager.shape());
                Registry.keep([1, 2]);
                Registry.keep([\"k\": [1]]);
                Registry.keep([tags]);
            }
        }
        "},
        &[(
            "src/Lib/Pager.php",
            "<?php\n\nnamespace Lib;\n\nfinal class Pager\n{\n    /** @return list<int> */\n    public static function list(): array\n    {\n        return [1];\n    }\n\n    /** @return non-empty-string */\n    public static function text(): string\n    {\n        return 'a';\n    }\n\n    /** @return positive-int */\n    public static function count(): int\n    {\n        return 1;\n    }\n\n    /** @return class-string */\n    public static function class(): string\n    {\n        return self::class;\n    }\n\n    /** @return array{a: int} */\n    public static function shape(): array\n    {\n        return ['a' => 1];\n    }\n\n    /** @return array-key */\n    public static function key(): int|string\n    {\n        return 1;\n    }\n}\n",
        )],
    );

    let body = lowered.body();
    assert_eq!(body.matches("SHARP_TYPE_ARGS").count(), 12, "{body}");
    assert_eq!(body.matches("VERIFY_TYPE_ARGS").count(), 11, "{body}");
    for (text, calls) in [
        // Two type arguments, and the check of the list `Pager.list()` returns.
        ("List<int>", 3),
        // A type argument, and the check of the result of the call that gives it, spec section 22, which reads a
        // collection alone and names the type argument. The `Set` the parameter `tags` makes takes `string` too.
        ("string", 3),
        ("int", 2),
        ("Class<Object>", 2),
        ("Map<string, int>", 2),
        ("Map<Any?, Any?>, Map<string, int>", 2),
        ("int|string", 2),
        // The `Map` the literal makes, with its own type, since its place names the method's type parameter.
        ("string, List<int>", 1),
        ("Map<string, List<int>>", 1),
        ("List<Set<string>>", 1),
        ("List<Any?>, List<Set<string>>", 1),
    ] {
        assert_eq!(body.matches(&format!("ZVAL \"{text}\"\n")).count(), calls, "{text}: {body}");
    }
}

/// A value of a type parameter is a value of its bound, so a generic method called on it carries its type arguments as
/// a call on the bound does, and checks the result against the type they give, spec section 22.
#[test]
fn a_generic_call_on_a_value_of_a_type_parameter_carries_its_type_arguments() {
    let lowered = Lowered::with(
        "namespace App;\n\npublic class Store\n{\n    public Box<Order> stock<TShelf : Shelf>(TShelf shelf) => shelf.make<Order>();\n}\n",
        &[
            (
                "src/App/Entities.php",
                "<?php namespace App; abstract class DatabaseEntity {} final class Order extends DatabaseEntity {}",
            ),
            ("src/App/Box.sharp", "namespace App;\n\npublic class Box<TValue>\n{\n    public Box() { }\n}\n"),
            (
                "src/App/Shelf.sharp",
                "namespace App;\n\npublic class Shelf\n{\n    public Shelf() { }\n\n    public Box<T> make<T>() => new Box<T>();\n}\n",
            ),
        ],
    );

    assert_eq!(
        lowered.body_of("stock"),
        indoc! {r#"
            STMT_LIST
              RETURN
                VERIFY_TYPE_ARGS
                  METHOD_CALL
                    VAR
                      ZVAL "shelf"
                    ZVAL "make"
                    ARG_LIST
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "App.Order"
                  ZVAL "App.Box<App.Order>"
                  ZVAL "App.Shelf.make()"
        "#}
    );
}

/// A test of a class with type arguments or of a type parameter, in `is`, `as` and a `match` arm, and `typeof` of a type
/// parameter, read the type arguments while the code runs: a `SHARP_IS_TYPE` of the value and the type text, and a
/// `SHARP_TYPE_OF` of the type text, written as `new` writes its type arguments. None runs as `instanceof` a class named
/// for a type parameter, which no value is.
#[test]
fn a_test_and_typeof_of_a_type_with_type_arguments_read_them_while_the_code_runs() {
    let entities = (
        "src/App/Entities.php",
        "<?php namespace App; abstract class DatabaseEntity {} final class Order extends DatabaseEntity {}",
    );
    let r#box = (
        "src/App/Box.sharp",
        "namespace App;\n\npublic class Box<TValue>\n{\n    public Box() { }\n\n    public bool holds(Any value) => value is TValue;\n}\n",
    );
    let generic = Lowered::with(r#box.1, &[entities]);
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Shelf
        {
            public bool boxed(Any value) => value is Box<Order>;

            public bool kept<T>(Any value) => value is T;

            public T? cast<T>(Any value) => value as T;

            public int arm<T>(Any value) => match (value) { T => 1, default => 0 };

            public Class<T> kind<T>() => typeof(T);
        }
    "},
        &[entities, r#box],
    );

    let test = |text: &str| {
        format!("STMT_LIST\n  RETURN\n    SHARP_IS_TYPE\n      VAR\n        ZVAL \"value\"\n      ZVAL \"{text}\"\n")
    };

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    assert_eq!(generic.body_of("holds"), test("$0"));
    assert_eq!(lowered.body_of("boxed"), test("App.Box<App.Order>"));
    assert_eq!(lowered.body_of("kept"), test("#0"));
    assert_eq!(
        lowered.body_of("cast"),
        "STMT_LIST\n  RETURN\n    CONDITIONAL\n      SHARP_IS_TYPE\n        VAR\n          ZVAL \"value\"\n        ZVAL \"#0\"\n      VAR\n        ZVAL \"value\"\n      ZVAL null\n"
    );
    assert_eq!(
        lowered.body_of("arm"),
        "STMT_LIST\n  RETURN\n    MATCH\n      ZVAL true\n      MATCH_ARM_LIST\n        MATCH_ARM\n          EXPR_LIST\n            SHARP_IS_TYPE\n              VAR\n                ZVAL \"value\"\n              ZVAL \"#0\"\n          ZVAL 1\n        MATCH_ARM\n          null\n          ZVAL 0\n"
    );
    assert_eq!(lowered.body_of("kind"), "STMT_LIST\n  RETURN\n    SHARP_TYPE_OF\n      ZVAL \"#0\"\n");
}

/// `typeof` of a type that is no class is a `SHARP_TYPE_OF` of its type text, as `typeof(T)` is when `T` runs as that
/// type, so the engine gives its class value. A nullable or union type is one type, spelled whole. `typeof(Self)` is
/// PHP's `static::class`, and a static call through it is PHP's `static::method()`.
#[test]
fn typeof_of_a_type_that_is_no_class_spells_its_type() {
    let lowered = Lowered::new(indoc! {"
        namespace App;

        public class Order
        {
            public static string defaultTag() => \"div\";

            public static Any whole() => typeof(int);

            public static Any nullable() => typeof(int?);

            public static Any either() => typeof(string|int);

            public static Any held() => typeof((Order|int)?);

            public static Any orders() => typeof(List<Order>);

            public static Any counts() => typeof(Map<string, int>);

            public static Any numbers() => typeof(Set<int>);

            public static Any own() => typeof(Self);

            public static string tag() => typeof(Self).defaultTag();
        }
    "});
    let type_of = |text: &str| format!("STMT_LIST\n  RETURN\n    SHARP_TYPE_OF\n      ZVAL \"{text}\"\n");

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    assert_eq!(lowered.body_of("whole"), type_of("int"));
    assert_eq!(lowered.body_of("nullable"), type_of("int?"));
    assert_eq!(lowered.body_of("either"), type_of("int|string"));
    assert_eq!(lowered.body_of("held"), type_of("(App.Order|int)?"));
    assert_eq!(lowered.body_of("orders"), type_of("List<App.Order>"));
    assert_eq!(lowered.body_of("counts"), type_of("Map<string, int>"));
    assert_eq!(lowered.body_of("numbers"), type_of("Set<int>"));
    assert_eq!(lowered.body_of("own"), "STMT_LIST\n  RETURN\n    CLASS_NAME\n      ZVAL [1] \"static\"\n");
    assert_eq!(
        lowered.body_of("tag"),
        "STMT_LIST\n  RETURN\n    STATIC_CALL\n      ZVAL [1] \"static\"\n      ZVAL \"defaultTag\"\n      ARG_LIST\n"
    );
}

/// `new TItem(…)` is a `NEW` that names no class under the `SHARP_TYPE_ARGS` of `TItem`'s text, so the engine creates
/// the type argument with its own type arguments. A static member of `TItem` is read on the class `SHARP_TYPE_OF`
/// gives, as PHP's `$class::member` reads one, and a static method of it is never inlined, since the type argument may
/// declare its own.
#[test]
fn new_and_a_static_member_of_a_type_parameter_read_its_class_while_the_code_runs() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Builder<TItem : Maker>
        {
            public Builder() { }

            public TItem create() => new TItem(TItem.LIMIT);

            public int made<TOther : Maker>() => TOther.make();

            public void counted()
            {
                TItem.count = 2;
            }
        }
    "},
        &[(
            "src/App/Maker.sharp",
            "namespace App;\n\npublic abstract class Maker\n{\n    public const int LIMIT = 3;\n\n    public static int count { get; set; } = 0;\n\n    public required Maker(public int size { get; }) { }\n\n    public static int make() => 1;\n}\n",
        )],
    );

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    assert_eq!(
        lowered.body_of("create"),
        "STMT_LIST\n  RETURN\n    SHARP_TYPE_ARGS\n      NEW\n        null\n        ARG_LIST\n          CLASS_CONST\n            SHARP_TYPE_OF\n              ZVAL \"$0\"\n            ZVAL \"LIMIT\"\n      ZVAL \"$0\"\n"
    );
    assert_eq!(
        lowered.body_of("made"),
        "STMT_LIST\n  RETURN\n    STATIC_CALL\n      SHARP_TYPE_OF\n        ZVAL \"#0\"\n      ZVAL \"make\"\n      ARG_LIST\n"
    );
    assert_eq!(
        lowered.body_of("counted"),
        "STMT_LIST\n  ASSIGN\n    STATIC_PROP\n      SHARP_TYPE_OF\n        ZVAL \"$0\"\n      ZVAL \"count\"\n    ZVAL 2\n"
    );
}

/// A list's generic member such as `map` runs as the engine function it inlines to, which takes no type arguments, as a
/// call of any built-in function does.
#[test]
fn a_generic_member_call_on_a_list_carries_no_type_arguments() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Prices
        {
            public static List<string> labels(List<int> prices) => prices.map(price => (string) price);
        }
    "},
        &[],
    );

    // A call with type arguments is a `SHARP_TYPE_ARGS` around the call. The lambda's own holds its function type.
    assert!(
        lowered
            .body_of("labels")
            .starts_with("STMT_LIST\n  RETURN\n    CALL\n      ZVAL \"Sharp\\\\Internal\\\\map\"\n"),
        "{}",
        lowered.body_of("labels")
    );
}

/// A PHP# generic class ends with its metadata, a `SHARP_TYPE_ARGS` without a `new` whose second text is its bounds:
/// the type text of each type parameter's bound, `Any?` for one without a bound. It declares its hidden type-argument
/// slot from it. A class without type parameters, whose header gives no type arguments, has no metadata. `new` of the
/// class is a `SHARP_TYPE_ARGS` over the `NEW`, whose text is the type arguments the checker found, each in its full
/// dotted name. `new Self` gives the new object `this`'s type arguments, so its text is null. A type argument
/// that names a type parameter of the class writes it as `$` and its index, and the engine gives it `this`'s type
/// argument at that index. One that names a method's own type parameter writes it as `#` and its index, and the engine
/// gives it the method's own type argument at that index.
#[test]
fn new_of_a_generic_php_sharp_class_carries_its_type_arguments() {
    let files = lowered_each(
        &[
            (
                "src/App/PaginatedList.sharp",
                indoc! {"
                namespace App;

                public class PaginatedList<TItem : DatabaseEntity, TKey>
                {
                    public required PaginatedList(private List<TItem> rows)
                    {
                    }

                    public PaginatedList<TItem, TKey> copy() => new Self(this.rows);

                    public PaginatedList<TItem, List<TKey>?> nested() => new PaginatedList<TItem, List<TKey>?>(this.rows);
                }
            "},
            ),
            (
                "src/App/Report.sharp",
                indoc! {"
                namespace App;

                public class Report
                {
                    public PaginatedList<Order, int> run(List<Order> rows) => new PaginatedList<Order, int>(rows);

                    public PaginatedList<TItem, int> open<TItem : DatabaseEntity>(List<TItem> rows) => new PaginatedList<TItem, int>(rows);
                }
            "},
            ),
        ],
        &[(
            "src/App/Entities.php",
            "<?php namespace App; abstract class DatabaseEntity {} final class Order extends DatabaseEntity {}",
        )],
    );
    let list = class_in(&files, "PaginatedList").0;
    let lowered = class_in(&files, "Report").0;
    let last_member = |lowered: &Lowered| {
        let members = lowered.child(lowered.child(lowered.root(), 2), 2);

        lowered.child(members, lowered.nodes()[members as usize].child_count - 1)
    };

    assert_eq!(
        list.render(last_member(list)),
        indoc! {r#"
            SHARP_CLASS_METADATA
              null
              ZVAL "App.DatabaseEntity, Any?"
              null
        "#}
    );
    assert_eq!(lowered.nodes()[last_member(lowered) as usize].kind, sharp_kind::SHARP_AST_METHOD);
    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "App\\PaginatedList"
                    ARG_LIST
                      VAR
                        ZVAL "rows"
                  ZVAL "App.Order, int"
        "#}
    );
    assert_eq!(
        list.body_of("copy"),
        indoc! {r#"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL [1] "static"
                    ARG_LIST
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "rows"
                  null
        "#}
    );
    assert_eq!(
        list.body_of("nested"),
        indoc! {r#"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "App\\PaginatedList"
                    ARG_LIST
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "rows"
                  ZVAL "$0, List<$1>?"
        "#}
    );
    assert_eq!(
        lowered.body_of("open"),
        indoc! {r##"
            STMT_LIST
              RETURN
                SHARP_TYPE_ARGS
                  NEW
                    ZVAL "App\\PaginatedList"
                    ARG_LIST
                      VAR
                        ZVAL "rows"
                  ZVAL "#0, int"
        "##}
    );
}

/// PHP has no class visibility, so a `public` class is the same class.
#[test]
fn a_public_class_is_a_class() {
    let public = Lowered::new("namespace App.Tenant;\n\npublic class Report\n{\n}\n");
    let internal = Lowered::new("namespace App.Tenant;\n\nclass Report\n{\n}\n");

    assert_eq!(public.tree(), internal.tree());
}

/// PHP has no enum visibility, so a `public` enum is the same enum.
#[test]
fn a_public_enum_is_an_enum() {
    let public = Lowered::new("namespace App.Tenant;\n\npublic enum Suit\n{\n    case Hearts;\n}\n");
    let internal = Lowered::new("namespace App.Tenant;\n\nenum Suit\n{\n    case Hearts;\n}\n");

    assert_eq!(public.tree(), internal.tree());
}

/// ```php
/// public function keep(object $first, ?object $source = null): object { return $first; }
/// ```
///
/// `Object` is PHP's `object`, a built-in type, so its type is the name `object` with `ZEND_NAME_NOT_FQ`, which is 1,
/// as php-src's grammar builds it, and `[257]` adds `ZEND_TYPE_NULLABLE`. The result carries the method's function type,
/// as a method's does when a function type can say its whole type.
#[test]
fn an_object_type_is_the_object_name() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public Object keep(Object first, Object? source = null) { return first; }\n}\n",
    );
    let method = lowered.nodes().iter().position(|node| node.kind == sharp_kind::SHARP_AST_METHOD).expect("a method");

    assert_eq!(
        lowered.render(lowered.child(method as u32, 0)),
        indoc! {r#"
            PARAM_LIST
              PARAM
                ZVAL [1] "object"
                ZVAL "first"
                null
                null
                null
                null
              PARAM
                ZVAL [257] "object"
                ZVAL "source"
                ZVAL null
                null
                null
                null
        "#}
    );
    assert_eq!(
        lowered.render(lowered.child(method as u32, 3)),
        indoc! {r#"
            SHARP_TYPE_ARGS
              ZVAL [1] "object"
              ZVAL "Function<Object(Object, Object?)>"
        "#}
    );
}

/// ```php
/// abstract class Shape { abstract public function area(): float; }
/// final class Unit { }
/// interface Measured { public function label(int $digits): string; }
/// ```
///
/// `[64]` is `ZEND_ACC_EXPLICIT_ABSTRACT_CLASS` on the class and `ZEND_ACC_ABSTRACT` on the method, `[32]`
/// `ZEND_ACC_FINAL`, `[1]` `ZEND_ACC_INTERFACE` on the interface, and an interface method is `ZEND_ACC_PUBLIC`, `[1]`,
/// as php-src's grammar writes it. An abstract method has no statement list. `[2]` on an interface method's result is
/// `ZEND_SHARP_RESULT_CALLER_CHECKED`.
#[test]
fn abstract_and_final_classes_and_interfaces_are_class_declarations_with_their_flags() {
    let tree = |declaration: &str| Lowered::new(&format!("namespace App.Tenant;\n\n{declaration}")).tree();

    assert_eq!(
        tree("abstract class Shape\n{\n    public abstract float area();\n}\n"),
        file_tree(
            "App\\Tenant",
            indoc! {r#"
              CLASS [64] "Shape" @3-6
                null
                null
                STMT_LIST
                  METHOD [65] "area" @5-5
                    PARAM_LIST
                    null
                    null
                    SHARP_TYPE_ARGS
                      ZVAL [1] "float"
                      ZVAL "float"
                    null
                null
                null
        "#}
        )
    );
    assert_eq!(
        tree("final class Unit\n{\n}\n"),
        file_tree(
            "App\\Tenant",
            indoc! {r#"
              CLASS [32] "Unit" @3-5
                null
                null
                STMT_LIST
                null
                null
        "#}
        )
    );
    assert_eq!(
        tree("interface Measured\n{\n    string label(int digits);\n}\n"),
        file_tree(
            "App\\Tenant",
            indoc! {r#"
              CLASS [1] "Measured" @3-6
                null
                null
                STMT_LIST
                  METHOD [1] "label" @5-5
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "int"
                        ZVAL "digits"
                        null
                        null
                        null
                        null
                    null
                    null
                    SHARP_TYPE_ARGS [2]
                      ZVAL [1] "string"
                      ZVAL "string"
                    null
                null
                null
        "#}
        )
    );
}

/// ```php
/// final class Text
/// {
///     public static function slug(string $title): string { return \Sharp\Internal\Text\Text\slug($title); }
/// }
/// ```
///
/// A static class is a final class, `[32]` `ZEND_ACC_FINAL`. An `extern` method is its `public static` method, `[17]`,
/// whose body returns the call of its native function: `Sharp\Internal`, then the class's full name after `Sharp\`,
/// then the method's name, with `ZEND_NAME_FQ`, which is 0.
#[test]
fn a_static_class_is_a_final_class_whose_extern_method_calls_its_native_function() {
    let lowered = Lowered::named(
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Text/Text.sharp",
        "namespace Sharp.Text;\n\npublic static class Text\n{\n    public static extern string slug(string title);\n}\n",
    );

    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              NAMESPACE
                ZVAL "Sharp\\Text"
                null
              CLASS [32] "Text" @3-6
                null
                null
                STMT_LIST
                  METHOD [17] "slug" @5-5
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "string"
                        ZVAL "title"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        CALL
                          ZVAL "Sharp\\Internal\\Text\\Text\\slug"
                          ARG_LIST
                            VAR
                              ZVAL "title"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "string"
                    null
                null
                null
        "#}
    );
}

/// ```php
/// final class Slug
/// {
///     public const SEPARATOR = '-';
///     public static function reset(): void { \Sharp\Internal\Slug\reset(); }
///     public static function of(string $title, string ...$words): string { return \Sharp\Internal\Slug\of($title, ...$words); }
/// }
/// ```
///
/// A `void` method calls its native function without `return`, and a variadic parameter forwards as a spread.
#[test]
fn an_extern_void_method_calls_without_return_and_forwards_a_variadic_parameter_as_a_spread() {
    let lowered = Lowered::named(
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Slug.sharp",
        "namespace Sharp;\n\npublic static class Slug\n{\n    public const string SEPARATOR = \"-\";\n\n    public static extern void reset();\n\n    public static extern string of(string title, string ...words);\n}\n",
    );
    let bodies: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_METHOD)
        .map(|(index, _)| lowered.render(lowered.child(index as u32, 2)))
        .collect();

    assert_eq!(
        bodies,
        [
            indoc! {r#"
                STMT_LIST
                  CALL
                    ZVAL "Sharp\\Internal\\Slug\\reset"
                    ARG_LIST
            "#},
            indoc! {r#"
                STMT_LIST
                  RETURN
                    CALL
                      ZVAL "Sharp\\Internal\\Slug\\of"
                      ARG_LIST
                        VAR
                          ZVAL "title"
                        UNPACK
                          VAR
                            ZVAL "words"
            "#},
        ]
    );
}

/// The checker refuses an `extern` method in a project file, so `check` refuses the file and nothing lowers it. `Text\Text`
/// would otherwise reach `Sharp\Text\Text`'s native body.
#[test]
fn an_extern_method_outside_the_library_is_refused_before_lowering() {
    for namespace in ["App", "Text"] {
        let lowered = Lowered::named(
            "src/Text.sharp",
            &format!(
                "namespace {namespace};\n\npublic static class Text\n{{\n    public static extern string slug(string title);\n}}\n"
            ),
        );

        assert_eq!(
            lowered.diagnostics(),
            ["5:33 compile error: Only the standard library declares native bodies: give `slug` a body."],
            "{namespace}"
        );
        assert!(lowered.nodes().is_empty(), "{namespace}");
    }
}

/// ```php
/// interface Linkable extends \Lib\Named { }
/// class Page extends \Lib\Entity implements \App\Tenant\Linkable { }
/// ```
///
/// A class's header name that the checker found to be a class is its `extends` name, and the rest are its
/// `implements` name list, each with `ZEND_NAME_FQ`, which is 0. An interface's header holds only interfaces, as PHP's
/// `extends` list does.
#[test]
fn a_header_is_the_parent_class_and_the_interface_name_list() {
    let entity = ("src/Lib/Entity.php", "<?php namespace Lib; interface Named {} class Entity {}");
    let linkable = (
        "src/App/Tenant/Linkable.sharp",
        "namespace App.Tenant;\n\nimport Lib.Named;\n\ninterface Linkable : Named\n{\n}\n",
    );
    let interface = Lowered::with(linkable.1, &[entity]);
    let class = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Entity;\n\nclass Page : Entity, Linkable\n{\n}\n",
        &[entity, linkable],
    );
    let file = |declaration: &str| file_tree("App\\Tenant", declaration);

    assert_eq!(
        interface.tree(),
        file(indoc! {r#"
              CLASS [1] "Linkable" @5-7
                null
                NAME_LIST
                  ZVAL "Lib\\Named"
                STMT_LIST
                null
                null
        "#})
    );
    assert_eq!(
        class.tree(),
        file(indoc! {r#"
              CLASS "Page" @5-7
                ZVAL "Lib\\Entity"
                NAME_LIST
                  ZVAL "App\\Tenant\\Linkable"
                STMT_LIST
                null
                null
        "#})
    );
}

/// A call from plain PHP gives a method's own type parameters no type arguments, spec section 11, so a parameter whose
/// type is one of them, alone or nullable, checks the type parameter's bound: `boxed<TBox : Box<Order>>(TBox box)`
/// checks `App.Box<App.Order>`, and `add<TSub : TItem>(TSub item)` the class's `$0`. A static method reads the class's
/// type parameters as its own leading ones, `#0`, in its bounds as in its checks. A bound PHP's own type checks, as a
/// plain class, needs none, and so does a type parameter nested in a type, as `Box<TOther>`, which takes any type
/// argument.
#[test]
fn a_parameter_of_a_methods_own_type_parameter_checks_its_bound_from_plain_php() {
    let lowered = Lowered::with(
        "namespace App;\n\npublic class Rack<TItem>\n{\n    public string add<TSub : TItem>(TSub item) => \"added\";\n\n    public string boxed<TBox : Box<Order>>(TBox box) => \"boxed\";\n\n    public string maybe<TBox : Box<Order>>(TBox? box) => \"maybe\";\n\n    public string plain<TOrder : Order>(TOrder order) => \"plain\";\n\n    public string nested<TOther : Order>(Box<TOther> box) => \"nested\";\n\n    public static string put<TSub : TItem>(TSub item) => \"put\";\n\n    public static string held<TBox : Box<TItem>>(TBox box) => \"held\";\n}\n",
        &[
            ("src/App/Order.sharp", "namespace App;\n\npublic class Order\n{\n}\n"),
            ("src/App/Box.sharp", "namespace App;\n\npublic class Box<T>\n{\n}\n"),
        ],
    );
    let metadata = |bounds: &str, parameters: &str| format!("  SHARP_TYPE_ARGS\n    {bounds}\n    {parameters}\n");

    for (method, bounds, parameters) in [
        ("put", r##"ZVAL "Any?, #0""##, r##"ZVAL "#0""##),
        ("held", r##"ZVAL "Any?, App.Box<#0>""##, r##"ZVAL "App.Box<#0>""##),
        ("add", r#"ZVAL "$0""#, r#"ZVAL "$0""#),
        ("boxed", r#"ZVAL "App.Box<App.Order>""#, r#"ZVAL "App.Box<App.Order>""#),
        ("maybe", r#"ZVAL "App.Box<App.Order>""#, r#"ZVAL "App.Box<App.Order>?""#),
        ("plain", r#"ZVAL "App.Order""#, "null"),
        ("nested", r#"ZVAL "App.Order""#, "null"),
    ] {
        assert!(
            lowered.parameters_of(method).ends_with(&metadata(bounds, parameters)),
            "{method}: {}",
            lowered.parameters_of(method)
        );
    }
}

/// ```php
/// public function seed(object $owner): bool { return $owner instanceof \Lib\HasLabel; }
/// ```
///
/// Spec section 22: a plain PHP trait is a type, and no PHP value is `instanceof` a trait. So a trait type is PHP's
/// `object`, and its PHP# type text, as #102 writes it, makes a call from plain PHP check the argument, a `List` of it
/// checks each element, and `is` reads it while the code runs, as the engine's test finds a trait any class up the
/// chain uses. A method's type parameter bounded by the trait checks a call from plain PHP against its bound, and in an
/// intersection bound, `Greeter & HasLabel`, PHP's type is the class beside the trait.
#[test]
fn a_trait_type_is_object_and_its_test_reads_the_trait() {
    let lowered = Lowered::with(
        "namespace App;\n\nimport Lib.HasLabel;\n\npublic class Seeder\n{\n    public bool seed(HasLabel owner, List<HasLabel> owners, Any other) => other is HasLabel;\n}\n",
        &[(
            "src/Lib/HasLabel.php",
            "<?php namespace Lib; trait HasLabel { public function label(): string { return 'label'; } }",
        )],
    );

    assert_eq!(
        lowered.declared("seed"),
        indoc! {r#"
            METHOD [1] "seed" @7-7
              PARAM_LIST
                PARAM
                  ZVAL [1] "object"
                  ZVAL "owner"
                  null
                  null
                  null
                  null
                PARAM
                  TYPE [7]
                  ZVAL "owners"
                  null
                  null
                  null
                  null
                PARAM
                  ZVAL [1] "mixed"
                  ZVAL "other"
                  null
                  null
                  null
                  null
                SHARP_TYPE_ARGS
                  null
                  ZVAL "Lib.HasLabel, List<Lib.HasLabel>, Any"
              null
              STMT_LIST
                RETURN
                  SHARP_IS_TYPE
                    VAR
                      ZVAL "other"
                    ZVAL "Lib.HasLabel"
              SHARP_TYPE_ARGS
                ZVAL [1] "bool"
                ZVAL "Function<bool(Lib.HasLabel, List<Lib.HasLabel>, Any)>"
              null
        "#}
    );

    // A method's type parameter bounded by the trait checks its bound, and the trait leaves an intersection to the
    // classes beside it. A call of the PHP# interface's member checks its result, spec section 22.
    let lowered = Lowered::with(
        "namespace App;\n\nimport Lib.HasLabel;\n\npublic class Seeder\n{\n    public string bound<T : HasLabel>(T owner) => owner.label();\n\n    public string both<T : Greeter & HasLabel>(T owner) => owner.hi() + owner.label();\n}\n",
        &[
            (
                "src/Lib/HasLabel.php",
                "<?php namespace Lib; trait HasLabel { public function label(): string { return 'label'; } }",
            ),
            ("src/App/Greeter.sharp", "namespace App;\n\npublic interface Greeter\n{\n    string hi();\n}\n"),
        ],
    );

    assert_eq!(
        [lowered.declared("bound"), lowered.declared("both")].concat(),
        indoc! {r#"
            METHOD [1] "bound" @7-7
              PARAM_LIST
                PARAM
                  ZVAL [1] "object"
                  ZVAL "owner"
                  null
                  null
                  null
                  null
                SHARP_TYPE_ARGS
                  ZVAL "Lib.HasLabel"
                  ZVAL "Lib.HasLabel"
              null
              STMT_LIST
                RETURN
                  METHOD_CALL
                    VAR
                      ZVAL "owner"
                    ZVAL "label"
                    ARG_LIST
              SHARP_TYPE_ARGS
                ZVAL [1] "string"
                ZVAL "string"
              null
            METHOD [1] "both" @9-9
              PARAM_LIST
                PARAM
                  ZVAL "App\\Greeter"
                  ZVAL "owner"
                  null
                  null
                  null
                  null
                SHARP_TYPE_ARGS
                  ZVAL "App.Greeter & Lib.HasLabel"
                  ZVAL "App.Greeter & Lib.HasLabel"
              null
              STMT_LIST
                RETURN
                  BINARY_OP [8]
                    VERIFY_TYPE_ARGS
                      METHOD_CALL
                        VAR
                          ZVAL "owner"
                        ZVAL "hi"
                        ARG_LIST
                      ZVAL "string"
                      ZVAL "App.Greeter.hi()"
                    METHOD_CALL
                      VAR
                        ZVAL "owner"
                      ZVAL "label"
                      ARG_LIST
              SHARP_TYPE_ARGS
                ZVAL [1] "string"
                ZVAL "string"
              null
        "#}
    );
}

/// ```php
/// class Both implements \App\Described, \App\Told
/// {
///     use \App\Described\Defaults, \App\Told\Defaults {
///         \App\Described\Defaults::describe as protected `describe@App\Described`;
///         \App\Told\Defaults::describe as protected `describe@App\Told`;
///     }
///     public function describe(): string
///     {
///         return $this->{'describe@App\Described'}() . $this->{'describe@App\Told'}();
///     }
/// }
/// ```
///
/// Spec section 22: `super<Described>.describe()` runs `Described`'s default body through a protected alias of the
/// trait's method, `[2]` `ZEND_ACC_PROTECTED`, that the `use` of each class that uses the trait declares, so a
/// subclass calls it too. Its name joins the method and the interface with `@`, which no PHP# member name holds, so it
/// can't clash with one.
#[test]
fn super_of_an_interface_calls_a_protected_alias_of_its_default_body() {
    let lowered = Lowered::with(
        "namespace App;\n\npublic class Both : Described, Told\n{\n    public override string describe() => super<Described>.describe() + super<Told>.describe();\n}\n",
        &[
            (
                "src/App/Described.sharp",
                "namespace App;\n\npublic interface Described\n{\n    string describe() => \"described\";\n}\n",
            ),
            (
                "src/App/Told.sharp",
                "namespace App;\n\npublic interface Told\n{\n    string describe() => \"told\";\n}\n",
            ),
        ],
    );
    let class = lowered
        .nodes()
        .iter()
        .position(|node| node.kind == sharp_kind::SHARP_AST_CLASS && lowered.text(node.text) == "Both")
        .expect("the source declares `Both`");

    assert_eq!(
        lowered.render(lowered.child(class as u32, 2)),
        indoc! {r#"
            STMT_LIST
              USE_TRAIT
                NAME_LIST
                  ZVAL "App\\Described\\Defaults"
                  ZVAL "App\\Told\\Defaults"
                TRAIT_ADAPTATIONS
                  TRAIT_ALIAS [2]
                    METHOD_REFERENCE
                      ZVAL "App\\Described\\Defaults"
                      ZVAL "describe"
                    ZVAL "describe@App\\Described"
                  TRAIT_ALIAS [2]
                    METHOD_REFERENCE
                      ZVAL "App\\Told\\Defaults"
                      ZVAL "describe"
                    ZVAL "describe@App\\Told"
              METHOD [1] "describe" @5-5
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    BINARY_OP [8]
                      METHOD_CALL
                        VAR
                          ZVAL "this"
                        ZVAL "describe@App\\Described"
                        ARG_LIST
                      METHOD_CALL
                        VAR
                          ZVAL "this"
                        ZVAL "describe@App\\Told"
                        ARG_LIST
                SHARP_TYPE_ARGS
                  ZVAL [1] "string"
                  ZVAL "Function<string()>"
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
        "#}
    );
}

/// ```php
/// namespace App;
/// interface HasDesign {
///     public string $designColumn { get; }
///     public function designKey(): string;
///     public function title(): string;
/// }
/// trait HasDesign\Defaults {
///     public function designKey(): string { return $this->designColumn; }
/// }
/// interface Labeled { public function label(): string; }
/// trait Labeled\Defaults { public function label(): string { return 'labeled'; } }
/// abstract class Page extends \Lib\Model { use \Lib\HasSlug, \App\HasDesign\Defaults; }
/// class Child extends \App\Page { }
/// enum Shade implements \App\Labeled { use \App\Labeled\Defaults; case Light; }
/// final class Painted implements \App\Labeled { use \App\Labeled\Defaults; public function __construct(…) {} }
/// ```
///
/// Spec section 22: a PHP# interface with default bodies is a PHP interface whose methods are all abstract, `[1]`
/// `ZEND_ACC_INTERFACE`, then the trait `[2]` `ZEND_ACC_TRAIT` named `HasDesign\Defaults`, which the engine declares in
/// the file's namespace and which holds each default body as a public method. A class's header traits and the traits of
/// the default bodies of the interfaces it implements first are one `use`, its first member, and a subclass of a class
/// that already uses them uses none. The `use` gives each default body the protected alias `super<Labeled>` calls,
/// `[2]` `ZEND_ACC_PROTECTED`. An enum, an event, a struct and the class of an enum with a case that carries data use
/// them too. The interface's method marks its result `[2]` `ZEND_SHARP_RESULT_CALLER_CHECKED`, and the default body
/// marks none.
#[test]
fn a_header_trait_and_the_traits_of_default_bodies_are_one_use_after_the_interface_and_its_trait() {
    let files = [
        (
            "src/App/HasDesign.sharp",
            "namespace App;\n\npublic interface HasDesign\n{\n    string designColumn { get; }\n    string designKey() => this.designColumn;\n    string title();\n}\n",
        ),
        (
            "src/App/Labeled.sharp",
            "namespace App;\n\npublic interface Labeled\n{\n    string label() => \"labeled\";\n}\n",
        ),
        (
            "src/App/Page.sharp",
            "namespace App;\n\nimport Lib.HasSlug;\nimport Lib.Model;\n\npublic abstract class Page : Model, HasSlug, HasDesign\n{\n}\n",
        ),
        ("src/App/Child.sharp", "namespace App;\n\npublic abstract class Child : Page\n{\n}\n"),
        ("src/App/Shade.sharp", "namespace App;\n\npublic enum Shade : Labeled\n{\n    case Light;\n}\n"),
        ("src/App/Painted.sharp", "namespace App;\n\npublic event Painted(int id) : Labeled;\n"),
    ];
    let lowered = lowered_each(
        &files,
        &[(
            "src/Lib/Model.php",
            "<?php namespace Lib; abstract class Model {} trait HasSlug { public function slug(): string { return 'slug'; } }",
        )],
    );
    let tree = |name: &str| class_in(&lowered, name).0.tree();
    let file = |declaration: &str| file_tree("App", declaration);

    assert_eq!(
        tree("HasDesign"),
        file(indoc! {r#"
              CLASS [1] "HasDesign" @3-8
                null
                null
                STMT_LIST
                  PROP_GROUP [1]
                    ZVAL [1] "string"
                    PROP_DECL
                      PROP_ELEM
                        ZVAL "designColumn"
                        null
                        null
                        STMT_LIST
                          PROPERTY_HOOK "get" @5-5
                            null
                            null
                            null
                            null
                            null
                    null
                  METHOD [1] "designKey" @6-6
                    PARAM_LIST
                    null
                    null
                    SHARP_TYPE_ARGS [2]
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                  METHOD [1] "title" @7-7
                    PARAM_LIST
                    null
                    null
                    SHARP_TYPE_ARGS [2]
                      ZVAL [1] "string"
                      ZVAL "string"
                    null
                null
                null
              CLASS [2] "HasDesign\\Defaults" @3-8
                null
                null
                STMT_LIST
                  METHOD [1] "designKey" @6-6
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "designColumn"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                null
                null
        "#})
    );
    assert_eq!(
        tree("Labeled"),
        file(indoc! {r#"
              CLASS [1] "Labeled" @3-6
                null
                null
                STMT_LIST
                  METHOD [1] "label" @5-5
                    PARAM_LIST
                    null
                    null
                    SHARP_TYPE_ARGS [2]
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                null
                null
              CLASS [2] "Labeled\\Defaults" @3-6
                null
                null
                STMT_LIST
                  METHOD [1] "label" @5-5
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ZVAL "labeled"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                null
                null
        "#})
    );
    assert_eq!(
        tree("Page"),
        file(indoc! {r#"
              CLASS [64] "Page" @6-8
                ZVAL "Lib\\Model"
                NAME_LIST
                  ZVAL "App\\HasDesign"
                STMT_LIST
                  USE_TRAIT
                    NAME_LIST
                      ZVAL "Lib\\HasSlug"
                      ZVAL "App\\HasDesign\\Defaults"
                    TRAIT_ADAPTATIONS
                      TRAIT_ALIAS [2]
                        METHOD_REFERENCE
                          ZVAL "App\\HasDesign\\Defaults"
                          ZVAL "designKey"
                        ZVAL "designKey@App\\HasDesign"
                null
                null
        "#})
    );
    assert_eq!(
        tree("Child"),
        file(indoc! {r#"
              CLASS [64] "Child" @3-5
                ZVAL "App\\Page"
                null
                STMT_LIST
                null
                null
        "#})
    );
    assert_eq!(
        tree("Shade"),
        file(indoc! {r#"
              CLASS [268435488] "Shade" @3-6
                null
                NAME_LIST
                  ZVAL "App\\Labeled"
                STMT_LIST
                  USE_TRAIT
                    NAME_LIST
                      ZVAL "App\\Labeled\\Defaults"
                    TRAIT_ADAPTATIONS
                      TRAIT_ALIAS [2]
                        METHOD_REFERENCE
                          ZVAL "App\\Labeled\\Defaults"
                          ZVAL "label"
                        ZVAL "label@App\\Labeled"
                  ENUM_CASE
                    ZVAL "Light"
                    null
                    null
                    null
                null
                null
        "#})
    );
    assert_eq!(
        tree("Painted"),
        file(indoc! {r#"
              CLASS [32] "Painted" @3-3
                null
                NAME_LIST
                  ZVAL "App\\Labeled"
                STMT_LIST
                  USE_TRAIT
                    NAME_LIST
                      ZVAL "App\\Labeled\\Defaults"
                    TRAIT_ADAPTATIONS
                      TRAIT_ALIAS [2]
                        METHOD_REFERENCE
                          ZVAL "App\\Labeled\\Defaults"
                          ZVAL "label"
                        ZVAL "label@App\\Labeled"
                  METHOD [1] "__construct" @3-3
                    PARAM_LIST
                      PARAM [129]
                        ZVAL [1] "int"
                        ZVAL "id"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                    null
                    null
                null
                null
        "#})
    );

    // A struct and an enum with a case that carries data, whose class runs each case's class's methods, start with
    // the same `use`.
    for (name, code) in [
        ("Badge", "namespace App;\n\npublic struct Badge : Labeled\n{\n}\n"),
        ("Mark", "namespace App;\n\npublic enum Mark : Labeled\n{\n    case Plain;\n    case Tagged(string tag);\n}\n"),
    ] {
        let lowered = Lowered::with(code, &[files[1]]);
        let class = lowered
            .nodes()
            .iter()
            .position(|node| node.kind == sharp_kind::SHARP_AST_CLASS && lowered.text(node.text) == name)
            .expect("the source declares the class");

        assert_eq!(
            lowered.render(lowered.child(lowered.child(class as u32, 2), 0)),
            indoc! {r#"
                USE_TRAIT
                  NAME_LIST
                    ZVAL "App\\Labeled\\Defaults"
                  TRAIT_ADAPTATIONS
                    TRAIT_ALIAS [2]
                      METHOD_REFERENCE
                        ZVAL "App\\Labeled\\Defaults"
                        ZVAL "label"
                      ZVAL "label@App\\Labeled"
            "#},
            "{name}"
        );
    }

    // A struct's header trait is its `use`, never an interface.
    let lowered = Lowered::with(
        "namespace App;\n\nimport Lib.HasLabel;\n\npublic struct Seal : HasLabel\n{\n    public Seal(public int at { get; }) { }\n}\n",
        &[(
            "src/Lib/HasLabel.php",
            "<?php namespace Lib; trait HasLabel { public function label(): string { return 'label'; } }",
        )],
    );
    let seal = lowered
        .nodes()
        .iter()
        .position(|node| node.kind == sharp_kind::SHARP_AST_CLASS && lowered.text(node.text) == "Seal")
        .expect("the source declares the struct") as u32;

    assert_eq!(
        [lowered.render(lowered.child(seal, 1)), lowered.render(lowered.child(lowered.child(seal, 2), 0))].concat(),
        indoc! {r#"
            NAME_LIST
              ZVAL "Sharp\\Struct"
            USE_TRAIT
              NAME_LIST
                ZVAL "Lib\\HasLabel"
              null
        "#}
    );
}

/// ```php
/// class Fancy implements \App\ShowsMore {
///     use \App\Shows\Defaults, \App\ShowsMore\Defaults {
///         \App\ShowsMore\Defaults::label insteadof \App\Shows\Defaults;
///         \App\Shows\Defaults::label as protected `label@App\Shows`;
///         \App\ShowsMore\Defaults::label as protected `label@App\ShowsMore`;
///     }
/// }
/// ```
///
/// Spec section 22: a sub-interface's default body replaces its parent's, so the class's `use` takes it `insteadof`
/// the parent's, which `super<Shows>` still reaches through its alias.
#[test]
fn a_sub_interfaces_default_body_runs_instead_of_its_parents() {
    let files = lowered_each(
        &[
            (
                "src/App/Shows.sharp",
                "namespace App;\n\npublic interface Shows\n{\n    string label() => \"shows\";\n\n    string tag => \"s\";\n}\n",
            ),
            (
                "src/App/ShowsMore.sharp",
                "namespace App;\n\npublic interface ShowsMore : Shows\n{\n    override string label() => \"more\";\n\n    override string tag => \"m\";\n}\n",
            ),
            ("src/App/Fancy.sharp", "namespace App;\n\npublic class Fancy : ShowsMore\n{\n}\n"),
        ],
        &[],
    );
    let member = |name: &str, path: &[u32]| member_in(&files, name, path);

    // The trait's body has no parent, so only the interface's signature carries `#[\Override]`.
    assert_eq!(
        [member("ShowsMore", &[0, 4]), member("ShowsMore\\Defaults", &[0, 4])].concat(),
        indoc! {r#"
            ATTRIBUTE_LIST
              ATTRIBUTE_GROUP
                ATTRIBUTE
                  ZVAL "Override"
                  null
            null
        "#}
    );
    // A computed property's body of the sub-interface replaces its parent's too.
    assert_eq!(
        member("Fancy", &[1, 1, 0]),
        indoc! {r#"
            PROP_ELEM
              ZVAL "tag"
              null
              null
              STMT_LIST
                PROPERTY_HOOK "get" @4-4
                  null
                  null
                  PROPERTY_HOOK_SHORT_BODY
                    METHOD_CALL
                      VAR
                        ZVAL "this"
                      ZVAL "tag@App\\ShowsMore"
                      ARG_LIST
                  null
                  null
        "#}
    );
    assert_eq!(
        member("Fancy", &[0]),
        indoc! {r#"
            USE_TRAIT
              NAME_LIST
                ZVAL "App\\Shows\\Defaults"
                ZVAL "App\\ShowsMore\\Defaults"
              TRAIT_ADAPTATIONS
                TRAIT_PRECEDENCE
                  METHOD_REFERENCE
                    ZVAL "App\\ShowsMore\\Defaults"
                    ZVAL "label"
                  NAME_LIST
                    ZVAL "App\\Shows\\Defaults"
                TRAIT_ALIAS [2]
                  METHOD_REFERENCE
                    ZVAL "App\\Shows\\Defaults"
                    ZVAL "label"
                  ZVAL "label@App\\Shows"
                TRAIT_ALIAS [2]
                  METHOD_REFERENCE
                    ZVAL "App\\ShowsMore\\Defaults"
                    ZVAL "label"
                  ZVAL "label@App\\ShowsMore"
        "#}
    );
}

/// Lowers, in PHP:
///
/// ```php
/// interface Tagged { public mixed $tag { get; } }
/// trait Tagged\Defaults { protected function `tag@App\Tagged`(): string { return 'tagged'; } }
/// final class Note implements \App\Tagged {
///     use \App\Tagged\Defaults;
///     public mixed $tag { get => $this->{'tag@App\Tagged'}(); }
/// }
/// final class Own implements \App\Tagged { use \App\Tagged\Defaults; public string $tag { get => 'own'; } }
/// final class Kept implements \App\Tagged { use \App\Tagged\Defaults; public string $tag = 'kept'; }
/// interface Keyed { public function key(): mixed; }
/// trait Keyed\Defaults { /* header App.Keyed<$0> */ public function holds(mixed $value): bool { … } }
/// ```
///
/// Spec section 22: an interface's computed property is `[1]` `ZEND_ACC_PUBLIC` `mixed` with an abstract `get` in the
/// interface, and its default body is the trait's `[2]` `ZEND_ACC_PROTECTED` method, which keeps the type. Each class
/// that gets the body declares the `mixed` property, running that method, after its `use`, and a class that overrides
/// it, computed or stored, declares its own with its type, as a `get` hook narrows a `mixed` one. A generic interface's
/// trait names the interface with its type parameters
/// as its header, so the engine counts a default body's `$0` among the interface's type arguments.
#[test]
fn an_interface_computed_property_runs_its_default_body_through_a_protected_method_of_the_trait() {
    let files = lowered_each(
        &[
            (
                "src/App/Tagged.sharp",
                "namespace App;\n\npublic interface Tagged\n{\n    string tag => \"tagged\";\n}\n",
            ),
            ("src/App/Note.sharp", "namespace App;\n\npublic class Note : Tagged\n{\n}\n"),
            (
                "src/App/Own.sharp",
                "namespace App;\n\npublic class Own : Tagged\n{\n    public override string tag => \"own\";\n}\n",
            ),
            (
                "src/App/Kept.sharp",
                "namespace App;\n\npublic class Kept : Tagged\n{\n    public override string tag { get; set; } = \"kept\";\n}\n",
            ),
            (
                "src/App/Keyed.sharp",
                "namespace App;\n\npublic interface Keyed<TKey>\n{\n    TKey key();\n\n    bool holds(Any value) => value is TKey;\n}\n",
            ),
        ],
        &[],
    );
    let member = |name: &str, path: &[u32]| member_in(&files, name, path);

    assert_eq!(
        [
            member("Tagged", &[]),
            member("Tagged\\Defaults", &[]),
            member("Note", &[]),
            member("Own", &[1]),
            member("Kept", &[1]),
            member("Keyed\\Defaults", &[1]),
        ]
        .concat(),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [1]
                ZVAL [1] "mixed"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "tag"
                    null
                    null
                    STMT_LIST
                      PROPERTY_HOOK "get" @5-5
                        null
                        null
                        null
                        null
                        null
                null
            STMT_LIST
              METHOD [2] "tag@App\\Tagged" @5-5
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    ZVAL "tagged"
                ZVAL [1] "string"
                null
            STMT_LIST
              USE_TRAIT
                NAME_LIST
                  ZVAL "App\\Tagged\\Defaults"
                null
              PROP_GROUP [1]
                ZVAL [1] "mixed"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "tag"
                    null
                    null
                    STMT_LIST
                      PROPERTY_HOOK "get" @4-4
                        null
                        null
                        PROPERTY_HOOK_SHORT_BODY
                          METHOD_CALL
                            VAR
                              ZVAL "this"
                            ZVAL "tag@App\\Tagged"
                            ARG_LIST
                        null
                        null
                null
            PROP_GROUP [1]
              ZVAL [1] "string"
              PROP_DECL
                PROP_ELEM
                  ZVAL "tag"
                  null
                  null
                  STMT_LIST
                    PROPERTY_HOOK "get" @5-5
                      null
                      null
                      PROPERTY_HOOK_SHORT_BODY
                        ZVAL "own"
                      null
                      null
              ATTRIBUTE_LIST
                ATTRIBUTE_GROUP
                  ATTRIBUTE
                    ZVAL "Override"
                    null
            PROP_GROUP [1]
              ZVAL [1] "string"
              PROP_DECL
                PROP_ELEM
                  ZVAL "tag"
                  ZVAL "kept"
                  null
                  null
              ATTRIBUTE_LIST
                ATTRIBUTE_GROUP
                  ATTRIBUTE
                    ZVAL "Override"
                    null
            SHARP_CLASS_METADATA
              ZVAL "App.Keyed<$0>"
              null
              null
        "#}
    );
}

/// Spec section 15: an `on` clause adds nothing to its class, because `mago compile` lists each listener in
/// `.sharp/listeners.php`, so a listener lowers to its method alone.
#[test]
fn a_listener_lowers_to_its_method_alone() {
    let library = [
        ("src/App/OrderEvent.sharp", "namespace App;\n\npublic interface OrderEvent\n{\n    int orderId { get; }\n}\n"),
        ("src/App/OrderPaid.sharp", "namespace App;\n\npublic event OrderPaid(int orderId) : OrderEvent;\n"),
    ];
    let code = "namespace App;\n\npublic class Notices\n{\n    public void send(OrderEvent e) on OrderPaid { }\n\n    public void refresh() on OrderPaid, OrderEvent => this.send(new OrderPaid(1));\n}\n";

    assert_eq!(
        Lowered::with(code, &library).tree(),
        Lowered::with(&code.replace(" on OrderPaid, OrderEvent", "").replace(" on OrderPaid", ""), &library).tree()
    );
}

/// ```php
/// /** @extends \Lib\PaginatedList<\Lib\Order> */
/// class OrderPage extends \Lib\PaginatedList { }
/// ```
///
/// A header entry with type arguments is its class, as the same entry without them. The class's metadata keeps the
/// type arguments, as a type text list of each class its header gives some.
#[test]
fn a_header_entry_with_type_arguments_is_its_class() {
    let source = |header: &str| {
        format!(
            "namespace App.Tenant;\n\nimport Lib.Order;\nimport Lib.PaginatedList;\n\npublic class OrderPage : {header}\n{{\n}}\n"
        )
    };
    let generic = Lowered::with(
        &source("PaginatedList<Order>"),
        &[(
            "src/Lib/PaginatedList.php",
            "<?php namespace Lib; class Order {} /** @template T */ class PaginatedList {}",
        )],
    );
    let plain = Lowered::with(
        &source("PaginatedList"),
        &[("src/Lib/PaginatedList.php", "<?php namespace Lib; class Order {} class PaginatedList {}")],
    );

    let parent = |lowered: &Lowered| lowered.render(lowered.child(lowered.child(lowered.root(), 2), 0));
    let members = |lowered: &Lowered| lowered.render(lowered.child(lowered.child(lowered.root(), 2), 2));

    assert_eq!(parent(&generic), parent(&plain));
    assert_eq!(parent(&generic), "ZVAL \"Lib\\\\PaginatedList\"\n");
    assert_eq!(
        members(&generic),
        indoc! {r#"
            STMT_LIST
              SHARP_CLASS_METADATA
                ZVAL "Lib.PaginatedList<Lib.Order>"
                null
                null
        "#}
    );
    assert_eq!(members(&plain), "STMT_LIST\n");
}

/// An event's header keeps its type arguments as a class's does, after its constructor, so the engine knows
/// `Moved` is a `Holder<int>`.
#[test]
fn an_event_header_entry_with_type_arguments_keeps_them() {
    let lowered = Lowered::with(
        "namespace App;\n\npublic event Moved(int item) : Holder<int>;\n",
        &[(
            "app/Holder.sharp",
            "namespace App;\n\npublic interface Holder<TItem>\n{\n    public TItem item { get; }\n}\n",
        )],
    );
    let members = lowered.child(lowered.child(lowered.root(), 2), 2);

    assert_eq!(
        lowered.render(lowered.child(members, 1)),
        indoc! {r#"
            SHARP_CLASS_METADATA
              ZVAL "App.Holder<int>"
              null
              null
        "#}
    );
}

/// ```php
/// interface OrderEvent
/// {
///     public int $orderId { get; }
/// }
/// final class OrderPaid implements \App\OrderEvent
/// {
///     public function __construct(public readonly int $orderId, public readonly int $amount = 0) {}
/// }
/// class Order
/// {
///     public function pay(int $orderId): \App\OrderPaid { return new \App\OrderPaid($orderId); }
/// }
/// ```
///
/// ```php
/// abstract class CheckoutState
/// {
///     public function label(): string { return 'checkout'; }
///     public static function op_Equality(mixed $a, mixed $b): bool
///     {
///         if ($a instanceof \App\CheckoutState\Open && $b instanceof \App\CheckoutState\Open) { return true; }
///         if ($a instanceof \App\CheckoutState\Paying && $b instanceof \App\CheckoutState\Paying) { return $a->gateway === $b->gateway; }
///         return $a === $b;
///     }
/// }
/// final class CheckoutState\Open extends \App\CheckoutState implements \Sharp\Struct
/// {
///     private static $instance;
///     private function __construct() {}
///     public static function instance(): self { return self::$instance ??= new self(); }
/// }
/// final class CheckoutState\Paying extends \App\CheckoutState implements \Sharp\Struct
/// {
///     public function __construct(public readonly string $gateway) {}
/// }
/// class Shop
/// {
///     public function open(): \App\CheckoutState { return \App\CheckoutState\Open::instance(); }
///     public function pay(): \App\CheckoutState { return new \App\CheckoutState\Paying(gateway: 'stripe'); }
///     public function same(\App\CheckoutState $a, \App\CheckoutState $b): bool { return \App\CheckoutState::op_Equality($a, $b); }
/// }
/// ```
///
/// Spec section 20: an enum with a case that carries data is an abstract class, `[64]`
/// `ZEND_ACC_EXPLICIT_ABSTRACT_CLASS`, and each case a final subclass named in the enum's namespace. A plain case is the
/// one object its class's `instance()` gives, and `CheckoutState.Paying(…)` creates its case. An enum compares by value,
/// sections 19 and 20, so `==` runs the enum's `op_Equality`, which compares two of the same case field by field and
/// anything else as identical, as a struct's does. A plain case is a case with no fields, so the copy `unserialize`
/// makes of it is equal to it. Each case implements `\Sharp\Struct`, so a `Map` or a `Set` hashes it by its fields, as
/// it hashes a struct.
#[test]
fn an_enum_with_data_is_an_abstract_class_and_each_case_a_final_subclass() {
    let checkout_state = (
        "src/App/CheckoutState.sharp",
        "namespace App;\n\npublic enum CheckoutState\n{\n    case Open;\n    case Paying(string gateway);\n\n    public string label() => \"checkout\";\n}\n",
    );
    let lowered = Lowered::new(checkout_state.1);
    let shop = Lowered::with(
        "namespace App;\n\npublic class Shop\n{\n    public CheckoutState open() => CheckoutState.Open;\n    public CheckoutState pay() => CheckoutState.Paying(gateway: \"stripe\");\n    public bool same(CheckoutState a, CheckoutState b) => a == b;\n}\n",
        &[checkout_state],
    );

    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              NAMESPACE
                ZVAL "App"
                null
              CLASS [64] "CheckoutState" @3-9
                null
                null
                STMT_LIST
                  METHOD [1] "label" @8-8
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ZVAL "checkout"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                  METHOD [17] "op_Equality" @3-3
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "mixed"
                        ZVAL "a"
                        null
                        null
                        null
                        null
                      PARAM
                        ZVAL [1] "mixed"
                        ZVAL "b"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      IF
                        IF_ELEM
                          AND
                            INSTANCEOF
                              VAR
                                ZVAL "a"
                              ZVAL "App\\CheckoutState\\Open"
                            INSTANCEOF
                              VAR
                                ZVAL "b"
                              ZVAL "App\\CheckoutState\\Open"
                          STMT_LIST
                            RETURN
                              ZVAL true
                      IF
                        IF_ELEM
                          AND
                            INSTANCEOF
                              VAR
                                ZVAL "a"
                              ZVAL "App\\CheckoutState\\Paying"
                            INSTANCEOF
                              VAR
                                ZVAL "b"
                              ZVAL "App\\CheckoutState\\Paying"
                          STMT_LIST
                            RETURN
                              BINARY_OP [16]
                                PROP
                                  VAR
                                    ZVAL "a"
                                  ZVAL "gateway"
                                PROP
                                  VAR
                                    ZVAL "b"
                                  ZVAL "gateway"
                      RETURN
                        BINARY_OP [16]
                          VAR
                            ZVAL "a"
                          VAR
                            ZVAL "b"
                    ZVAL [1] "bool"
                    null
                null
                null
              CLASS [32] "CheckoutState\\Open" @5-5
                ZVAL "App\\CheckoutState"
                NAME_LIST
                  ZVAL "Sharp\\Struct"
                STMT_LIST
                  PROP_GROUP [20]
                    null
                    PROP_DECL
                      PROP_ELEM
                        ZVAL "instance"
                        null
                        null
                        null
                    null
                  METHOD [4] "__construct" @5-5
                    PARAM_LIST
                    null
                    STMT_LIST
                    null
                    null
                  METHOD [17] "instance" @5-5
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ASSIGN_COALESCE
                          STATIC_PROP
                            ZVAL [1] "self"
                            ZVAL "instance"
                          NEW
                            ZVAL [1] "self"
                            ARG_LIST
                    ZVAL [1] "self"
                    null
                null
                null
              CLASS [32] "CheckoutState\\Paying" @6-6
                ZVAL "App\\CheckoutState"
                NAME_LIST
                  ZVAL "Sharp\\Struct"
                STMT_LIST
                  METHOD [1] "__construct" @6-6
                    PARAM_LIST
                      PARAM [129]
                        ZVAL [1] "string"
                        ZVAL "gateway"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                    null
                    null
                null
                null
        "#}
    );
    assert_eq!(
        shop.tree(),
        file_tree(
            "App",
            indoc! {r#"
              CLASS "Shop" @3-8
                null
                null
                STMT_LIST
                  METHOD [1] "open" @5-5
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        STATIC_CALL
                          ZVAL "App\\CheckoutState\\Open"
                          ZVAL "instance"
                          ARG_LIST
                    SHARP_TYPE_ARGS
                      ZVAL "App\\CheckoutState"
                      ZVAL "Function<App.CheckoutState()>"
                    null
                  METHOD [1] "pay" @6-6
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        NEW
                          ZVAL "App\\CheckoutState\\Paying"
                          ARG_LIST
                            NAMED_ARG
                              ZVAL "gateway"
                              ZVAL "stripe"
                    SHARP_TYPE_ARGS
                      ZVAL "App\\CheckoutState"
                      ZVAL "Function<App.CheckoutState()>"
                    null
                  METHOD [1] "same" @7-7
                    PARAM_LIST
                      PARAM
                        ZVAL "App\\CheckoutState"
                        ZVAL "a"
                        null
                        null
                        null
                        null
                      PARAM
                        ZVAL "App\\CheckoutState"
                        ZVAL "b"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        STATIC_CALL
                          ZVAL "App\\CheckoutState"
                          ZVAL "op_Equality"
                          ARG_LIST
                            VAR
                              ZVAL "a"
                            VAR
                              ZVAL "b"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "bool"
                      ZVAL "Function<bool(App.CheckoutState, App.CheckoutState)>"
                    null
                null
                null
        "#}
        )
    );
}

/// Spec section 15: an event is a final class, `[32]` `ZEND_ACC_FINAL`, whose constructor promotes each parameter to a
/// public get-only property, `[129]` `ZEND_ACC_PUBLIC | ZEND_ACC_READONLY`, and its header is the `implements` name
/// list. An interface's get-only property, written bare, is a public property, `[1]`, with an abstract `get` hook.
#[test]
fn an_event_is_a_final_class_and_an_interface_property_has_an_abstract_get_hook() {
    let files = lowered_each(
        &[
            (
                "src/App/OrderEvent.sharp",
                "namespace App;\n\npublic interface OrderEvent\n{\n    int orderId { get; }\n}\n",
            ),
            (
                "src/App/OrderPaid.sharp",
                "namespace App;\n\npublic event OrderPaid(int orderId, int amount = 0) : OrderEvent;\n",
            ),
            (
                "src/App/Order.sharp",
                "namespace App;\n\npublic class Order\n{\n    public OrderPaid pay(int orderId) => new OrderPaid(orderId);\n}\n",
            ),
        ],
        &[],
    );
    let tree = |name: &str| class_in(&files, name).0.tree();

    assert_eq!(
        tree("OrderEvent"),
        file_tree(
            "App",
            indoc! {r#"
              CLASS [1] "OrderEvent" @3-6
                null
                null
                STMT_LIST
                  PROP_GROUP [1]
                    ZVAL [1] "int"
                    PROP_DECL
                      PROP_ELEM
                        ZVAL "orderId"
                        null
                        null
                        STMT_LIST
                          PROPERTY_HOOK "get" @5-5
                            null
                            null
                            null
                            null
                            null
                    null
                null
                null
        "#}
        )
    );
    assert_eq!(
        tree("OrderPaid"),
        file_tree(
            "App",
            indoc! {r#"
              CLASS [32] "OrderPaid" @3-3
                null
                NAME_LIST
                  ZVAL "App\\OrderEvent"
                STMT_LIST
                  METHOD [1] "__construct" @3-3
                    PARAM_LIST
                      PARAM [129]
                        ZVAL [1] "int"
                        ZVAL "orderId"
                        null
                        null
                        null
                        null
                      PARAM [129]
                        ZVAL [1] "int"
                        ZVAL "amount"
                        ZVAL 0
                        null
                        null
                        null
                    null
                    STMT_LIST
                    null
                    null
                null
                null
        "#}
        )
    );
    assert_eq!(
        tree("Order"),
        file_tree(
            "App",
            indoc! {r#"
              CLASS "Order" @3-6
                null
                null
                STMT_LIST
                  METHOD [1] "pay" @5-5
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "int"
                        ZVAL "orderId"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        NEW
                          ZVAL "App\\OrderPaid"
                          ARG_LIST
                            VAR
                              ZVAL "orderId"
                    SHARP_TYPE_ARGS
                      ZVAL "App\\OrderPaid"
                      ZVAL "Function<App.OrderPaid(int)>"
                    null
                null
                null
        "#}
        )
    );
}

/// ```php
/// \Sharp\Internal\emit(new \App\OrderPaid(1));
/// \Sharp\Internal\emit($paid);
/// ```
///
/// Spec section 15: `emit` raises the event its expression gives, through the one function the engine adds, which runs
/// every listener of the event before it returns.
#[test]
fn emit_is_a_call_of_the_engine_emit() {
    let lowered = Lowered::with(
        "namespace App;\n\npublic class Order\n{\n    public void run(OrderPaid paid)\n    {\n        emit new OrderPaid(1);\n        emit paid;\n    }\n}\n",
        &[("src/OrderPaid.sharp", "namespace App;\n\npublic event OrderPaid(int orderId);\n")],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              CALL
                ZVAL "Sharp\\Internal\\emit"
                ARG_LIST
                  NEW
                    ZVAL "App\\OrderPaid"
                    ARG_LIST
                      ZVAL 1
              CALL
                ZVAL "Sharp\\Internal\\emit"
                ARG_LIST
                  VAR
                    ZVAL "paid"
        "#}
    );
}

/// ```php
/// public function size(): int { return 1; }
/// #[\Override] public function name(): string { return 'thumbnail'; }
/// ```
///
/// `virtual` lowers to nothing, because PHP methods are open to overriding, and `override` lowers to `#[\Override]`,
/// so PHP checks at link time that a parent method exists. Its attribute group follows the method's own.
#[test]
fn virtual_lowers_to_nothing_and_override_to_the_override_attribute() {
    let lowered = Lowered::with(
        "class Thumbnail : Image\n{\n    public virtual int size()\n    {\n        return 1;\n    }\n\n    [Deprecated]\n    public override string name()\n    {\n        return \"thumbnail\";\n    }\n}\n",
        &[("src/Image.php", "<?php class Image { public function name(): string { return 'image'; } }")],
    );

    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              CLASS "Thumbnail" @1-13
                ZVAL "Image"
                null
                STMT_LIST
                  METHOD [1] "size" @3-6
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ZVAL 1
                    SHARP_TYPE_ARGS
                      ZVAL [1] "int"
                      ZVAL "Function<int()>"
                    null
                  METHOD [1] "name" @9-12
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ZVAL "thumbnail"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    ATTRIBUTE_LIST
                      ATTRIBUTE_GROUP
                        ATTRIBUTE
                          ZVAL "Deprecated"
                          null
                      ATTRIBUTE_GROUP
                        ATTRIBUTE
                          ZVAL "Override"
                          null
                null
                null
        "#}
    );
}

/// ```php
/// #[\Override] final public function name(): string { return 'thumbnail'; }
/// ```
///
/// `final override` stops an override chain, spec section 22, so it lowers to PHP's `final`, and the engine refuses a
/// plain PHP subclass that replaces the method too.
#[test]
fn final_override_lowers_to_a_final_method_with_the_override_attribute() {
    let lowered = Lowered::with(
        "class Thumbnail : Image\n{\n    public final override string name()\n    {\n        return \"thumbnail\";\n    }\n}\n",
        &[("src/Image.php", "<?php class Image { public function name(): string { return 'image'; } }")],
    );

    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              CLASS "Thumbnail" @1-7
                ZVAL "Image"
                null
                STMT_LIST
                  METHOD [33] "name" @3-6
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        ZVAL "thumbnail"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    ATTRIBUTE_LIST
                      ATTRIBUTE_GROUP
                        ATTRIBUTE
                          ZVAL "Override"
                          null
                null
                null
        "#}
    );
}

/// ```php
/// #[\Override] protected $table = 'orders';
/// #[\Override] public bool $timestamps = false;
/// ```
///
/// An override is a property with `#[\Override]`, and an auto-property lowers as a field does, so PHP checks at link
/// time that the parent has the property. PHP refuses a type on a property whose parent's has none, so an override of
/// a property with no type has none either, as decision 028 writes. An override of a typed property keeps its type.
#[test]
fn an_override_of_a_property_with_no_type_has_no_type() {
    let lowered = Lowered::with(
        "class Order : Model\n{\n    protected override string table { get; set; } = \"orders\";\n    public override bool timestamps { get; set; } = false;\n}\n",
        &[("src/Model.php", "<?php class Model { protected $table = ''; public bool $timestamps = true; }")],
    );
    let class = lowered.child(lowered.root(), 1);

    assert_eq!(
        lowered.render(lowered.child(class, 2)),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [2]
                null
                PROP_DECL
                  PROP_ELEM
                    ZVAL "table"
                    ZVAL "orders"
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
              PROP_GROUP [1]
                ZVAL [1] "bool"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "timestamps"
                    ZVAL false
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
        "#}
    );
}

/// ```php
/// #[\Override] protected null|string $table = 'orders';   // with the type text "string"
/// #[\Override] public int|float $level = 3;           // with the type text "int"
/// ```
///
/// An override that narrows a typed plain PHP property, spec section 6.1, runs with the parent's PHP type, which PHP
/// keeps through every override as the class links, and the engine checks its own type on each write.
#[test]
fn an_override_that_narrows_a_typed_property_runs_with_the_parent_type_and_checks_its_own() {
    let lowered = Lowered::with(
        "class Order : Model\n{\n    protected override string table { get; set; } = \"orders\";\n    public override int level { get; set; } = 3;\n}\n",
        &[("src/Model.php", "<?php class Model { protected ?string $table = null; public int|float $level = 0; }")],
    );
    let class = lowered.child(lowered.root(), 1);

    assert_eq!(
        lowered.render(lowered.child(class, 2)),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [2]
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    ZVAL [1] "null"
                    ZVAL [1] "string"
                  ZVAL "string"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "table"
                    ZVAL "orders"
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
              PROP_GROUP [1]
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    ZVAL [1] "int"
                    ZVAL [1] "float"
                  ZVAL "int"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "level"
                    ZVAL 3
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
        "#}
    );
}

/// Spec section 6.1: an override that narrows a typed plain PHP property runs with whichever PHP type the parent
/// declares, a single type, `mixed`, `array`, `iterable`, `object`, an enum, a class or an intersection of classes.
#[test]
fn an_override_runs_with_each_php_type_its_plain_php_parent_declares() {
    let model = "<?php enum Level: string { case Low = 'low'; } final class Box implements Countable, ArrayAccess { public function count(): int { return 0; } public function offsetExists(mixed $o): bool { return false; } public function offsetGet(mixed $o): mixed { return null; } public function offsetSet(mixed $o, mixed $v): void {} public function offsetUnset(mixed $o): void {} } class Model { public mixed $anything = null; public ?array $items = null; public ?iterable $each = null; public ?object $owner = null; public ?Level $level = null; public (Countable&ArrayAccess)|null $box = null; }";
    let lowered = Lowered::with(
        "class Order : Model\n{\n    public override string anything { get; set; } = \"\";\n    public override List<int> items { get; set; } = [];\n    public override List<int> each { get; set; } = [];\n    public override Box owner { get; set; } = new Box();\n    public override Level level { get; set; } = Level.Low;\n    public override Box box { get; set; } = new Box();\n}\n",
        &[("src/Model.php", model)],
    );
    let types: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_PROP_GROUP)
        .map(|(group, _)| lowered.render(lowered.child(group as u32, 0)))
        .collect();

    assert_eq!(
        types,
        [
            indoc! {r#"
                SHARP_TYPE_ARGS
                  ZVAL [1] "mixed"
                  ZVAL "string"
            "#},
            indoc! {r#"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    TYPE [7]
                    ZVAL [1] "null"
                  ZVAL "List<int>"
            "#},
            indoc! {r#"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    ZVAL [1] "iterable"
                    ZVAL [1] "null"
                  ZVAL "List<int>"
            "#},
            indoc! {r#"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    ZVAL [1] "null"
                    ZVAL [1] "object"
                  ZVAL "Box"
            "#},
            indoc! {r#"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    ZVAL "Level"
                    ZVAL [1] "null"
                  ZVAL "Level"
            "#},
            indoc! {r#"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    TYPE_INTERSECTION
                      ZVAL "Countable"
                      ZVAL "ArrayAccess"
                    ZVAL [1] "null"
                  ZVAL "Box"
            "#},
        ]
    );
}

/// ```php
/// #[\Override] protected $table = 'orders' { set { $this->table = \Model::clean($value); } }
/// abstract public string $kind { get; }
/// ```
///
/// An override with accessor bodies runs as PHP's hooks over the parent's property, untyped when the parent's is, and
/// an abstract property runs as PHP's, with a hook that has no body and no `readonly`.
#[test]
fn an_override_with_accessor_bodies_and_an_abstract_property_are_their_php_hooks() {
    let lowered = Lowered::with(
        "abstract class Order : Model\n{\n    protected override string table { get; set => field = Model.clean(value); } = \"orders\";\n    public abstract string kind { get; }\n}\n",
        &[(
            "src/Model.php",
            "<?php class Model { protected $table = ''; public static function clean(string $text): string { return trim($text); } }",
        )],
    );
    let class = lowered.child(lowered.root(), 1);

    assert_eq!(
        lowered.render(lowered.child(class, 2)),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [2]
                null
                PROP_DECL
                  PROP_ELEM
                    ZVAL "table"
                    ZVAL "orders"
                    null
                    STMT_LIST
                      PROPERTY_HOOK "set" @3-3
                        null
                        null
                        STMT_LIST
                          ASSIGN
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "table"
                            STATIC_CALL
                              ZVAL "Model"
                              ZVAL "clean"
                              ARG_LIST
                                VAR
                                  ZVAL "value"
                        null
                        null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
              PROP_GROUP [65]
                ZVAL [1] "string"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "kind"
                    null
                    null
                    STMT_LIST
                      PROPERTY_HOOK "get" @4-4
                        null
                        null
                        null
                        null
                        null
                null
        "#}
    );
}

/// ```php
/// class Shop
/// {
///     public const int MAX = 3;
///     public int $views = 0;
///     public int $stock = 0;
///     public protected(set) int $id = 0;
///     public function secret(): int { return 1; }
/// }
/// ```
///
/// PHP has no namespace reach, so spec section 5's `internal` runs as public, and the analyzer checks who reaches it.
/// An `internal` class takes no flag, `internal set` takes no set visibility, and `internal init` takes the
/// `protected(set)` of every `init`, which only constructors run.
#[test]
fn internal_runs_as_public() {
    let lowered = Lowered::with(
        "internal class Shop\n{\n    internal const int MAX = 3;\n    public int views { get; internal set; } = 0;\n    internal int stock { get; set; } = 0;\n    public int id { get; internal init; } = 0;\n\n    internal int secret() => 1;\n}\n",
        &[],
    );
    let class = lowered.child(lowered.root(), 1);

    assert_eq!(
        lowered.render(class),
        indoc! {r#"
            CLASS "Shop" @1-9
              null
              null
              STMT_LIST
                CLASS_CONST_GROUP [1]
                  CLASS_CONST_DECL
                    CONST_ELEM
                      ZVAL "MAX"
                      ZVAL 3
                      null
                  null
                  ZVAL [1] "int"
                PROP_GROUP [1]
                  ZVAL [1] "int"
                  PROP_DECL
                    PROP_ELEM
                      ZVAL "views"
                      ZVAL 0
                      null
                      null
                  null
                PROP_GROUP [1]
                  ZVAL [1] "int"
                  PROP_DECL
                    PROP_ELEM
                      ZVAL "stock"
                      ZVAL 0
                      null
                      null
                  null
                PROP_GROUP [2049]
                  ZVAL [1] "int"
                  PROP_DECL
                    PROP_ELEM
                      ZVAL "id"
                      ZVAL 0
                      null
                      null
                  null
                METHOD [1] "secret" @8-8
                  PARAM_LIST
                  null
                  STMT_LIST
                    RETURN
                      ZVAL 1
                  SHARP_TYPE_ARGS
                    ZVAL [1] "int"
                    ZVAL "Function<int()>"
                  null
              null
              null
        "#}
    );
}

/// ```php
/// private bool ${'doubled#lazy'} = false;
/// public private(set) int $doubled { get { if (!$this->{'doubled#lazy'}) { $this->doubled = 2; $this->{'doubled#lazy'} = true; } return $this->doubled; } }
/// private bool ${'found#lazy'} = false;
/// public private(set) ?int $found { get { … } }
/// public function __clone(): void { $this->{'doubled#lazy'} = false; $this->{'found#lazy'} = false; }
/// ```
///
/// A `lazy` property keeps its first value in its own storage, which only its `get` hook writes, and a hidden flag
/// beside it says whether the body ran, since a kept null can't say so. A copy is a new value, so its `__clone`
/// clears each flag, and its first read computes the value again, spec section 6.5.
#[test]
fn a_lazy_property_keeps_its_first_value_in_its_storage() {
    let lowered = Lowered::with(
        "class Plan\n{\n    public lazy int doubled => 2;\n    public lazy int? found => null;\n}\n",
        &[],
    );
    let class = lowered.child(lowered.root(), 1);

    assert_eq!(
        lowered.render(lowered.child(class, 2)),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [4]
                ZVAL [1] "bool"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "doubled#lazy"
                    ZVAL false
                    null
                    null
                null
              PROP_GROUP [4097]
                ZVAL [1] "int"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "doubled"
                    null
                    null
                    STMT_LIST
                      PROPERTY_HOOK "get" @3-3
                        null
                        null
                        STMT_LIST
                          IF
                            IF_ELEM
                              UNARY_OP [14]
                                PROP
                                  VAR
                                    ZVAL "this"
                                  ZVAL "doubled#lazy"
                              STMT_LIST
                                ASSIGN
                                  PROP
                                    VAR
                                      ZVAL "this"
                                    ZVAL "doubled"
                                  ZVAL 2
                                ASSIGN
                                  PROP
                                    VAR
                                      ZVAL "this"
                                    ZVAL "doubled#lazy"
                                  ZVAL true
                          RETURN
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "doubled"
                        null
                        null
                null
              PROP_GROUP [4]
                ZVAL [1] "bool"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "found#lazy"
                    ZVAL false
                    null
                    null
                null
              PROP_GROUP [4097]
                ZVAL [257] "int"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "found"
                    null
                    null
                    STMT_LIST
                      PROPERTY_HOOK "get" @4-4
                        null
                        null
                        STMT_LIST
                          IF
                            IF_ELEM
                              UNARY_OP [14]
                                PROP
                                  VAR
                                    ZVAL "this"
                                  ZVAL "found#lazy"
                              STMT_LIST
                                ASSIGN
                                  PROP
                                    VAR
                                      ZVAL "this"
                                    ZVAL "found"
                                  ZVAL null
                                ASSIGN
                                  PROP
                                    VAR
                                      ZVAL "this"
                                    ZVAL "found#lazy"
                                  ZVAL true
                          RETURN
                            PROP
                              VAR
                                ZVAL "this"
                              ZVAL "found"
                        null
                        null
                null
              METHOD [1] "__clone" @1-5
                PARAM_LIST
                null
                STMT_LIST
                  ASSIGN
                    PROP
                      VAR
                        ZVAL "this"
                      ZVAL "doubled#lazy"
                    ZVAL false
                  ASSIGN
                    PROP
                      VAR
                        ZVAL "this"
                      ZVAL "found#lazy"
                    ZVAL false
                ZVAL [1] "void"
                null
        "#}
    );
}

/// The members of `RushOrder : Order : Model`, where the PHP# class `Order` overrides `table` with `string?` and
/// `model` is the plain PHP class `Model`.
fn rush_order_members(model: &str) -> String {
    let lowered = Lowered::with(
        "class RushOrder : Order\n{\n    protected override string? table { get; set; } = \"rush_orders\";\n}\n",
        &[
            ("src/Model.php", model),
            (
                "src/Order.sharp",
                "public class Order : Model\n{\n    protected override string? table { get; set; } = \"orders\";\n}\n",
            ),
        ],
    );

    lowered.render(lowered.child(lowered.child(lowered.root(), 1), 2))
}

/// ```php
/// #[\Override] protected $table = 'rush_orders';
/// ```
///
/// `Order::$table` runs untyped, because `Model::$table` has no type, so PHP refuses a type on an override of it too.
/// The root declaration of a property, at the bottom of the chain, decides the type of every override above it
/// (decision 028).
#[test]
fn an_override_of_an_override_of_a_property_with_no_type_has_no_type() {
    assert_eq!(
        rush_order_members("<?php class Model { protected $table = ''; }"),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [2]
                null
                PROP_DECL
                  PROP_ELEM
                    ZVAL "table"
                    ZVAL "rush_orders"
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
        "#}
    );
}

/// ```php
/// #[\Override] protected ?string $table = 'rush_orders';
/// ```
///
/// An override of an override keeps its written type when the root declaration has a type.
#[test]
fn an_override_of_an_override_of_a_typed_property_keeps_its_type() {
    assert_eq!(
        rush_order_members("<?php class Model { protected ?string $table = ''; }"),
        indoc! {r#"
            STMT_LIST
              PROP_GROUP [2]
                ZVAL [257] "string"
                PROP_DECL
                  PROP_ELEM
                    ZVAL "table"
                    ZVAL "rush_orders"
                    null
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Override"
                      null
        "#}
    );
}

/// ```php
/// class Account extends \Lib\Ledger
/// {
///     #[\Override]
///     public function total(string $label, int|float ...$amounts): int|float
///     {
///         return parent::total($label, ...$amounts);
///     }
/// }
/// ```
///
/// The classes slice and the signatures slice lower together: the header marks the class to find its parent in the
/// name list, the variadic union parameter carries `ZEND_PARAM_VARIADIC`, and the spread into `super` is an `UNPACK`
/// argument of the static call on `parent`.
#[test]
fn a_subclass_method_with_a_union_variadic_spreads_it_into_the_parent_method() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Ledger;\n\nclass Account : Ledger\n{\n    public override int|float total(string label, int|float ...amounts)\n    {\n        return super.total(label, ...amounts);\n    }\n}\n",
        &[(
            "src/Lib/Ledger.php",
            "<?php namespace Lib; class Ledger { public function total(string $label, int|float ...$amounts): int|float { return 0; } }",
        )],
    );

    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              NAMESPACE
                ZVAL "App\\Tenant"
                null
              CLASS "Account" @5-11
                ZVAL "Lib\\Ledger"
                null
                STMT_LIST
                  METHOD [1] "total" @7-10
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "string"
                        ZVAL "label"
                        null
                        null
                        null
                        null
                      PARAM [16]
                        TYPE_UNION
                          ZVAL [1] "int"
                          ZVAL [1] "float"
                        ZVAL "amounts"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        STATIC_CALL
                          ZVAL [1] "parent"
                          ZVAL "total"
                          ARG_LIST
                            VAR
                              ZVAL "label"
                            UNPACK
                              VAR
                                ZVAL "amounts"
                    SHARP_TYPE_ARGS
                      TYPE_UNION
                        ZVAL [1] "int"
                        ZVAL [1] "float"
                      ZVAL "float|int"
                    ATTRIBUTE_LIST
                      ATTRIBUTE_GROUP
                        ATTRIBUTE
                          ZVAL "Override"
                          null
                null
                null
        "#}
    );
}

/// ```php
/// return parent::size(2);
/// ```
///
/// `super` is `parent`, a name php-src writes with `ZEND_NAME_NOT_FQ`, which is 1, so the call is a static call that
/// runs on the parent class.
#[test]
fn super_calls_are_static_calls_on_parent() {
    assert_eq!(
        child_body(
            RUN,
            "        return super.size(2);\n",
            "<?php namespace App\\Tenant; class Base { public function size(int $n): int { return $n; } }",
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                STATIC_CALL
                  ZVAL [1] "parent"
                  ZVAL "size"
                  ARG_LIST
                    ZVAL 2
        "#}
    );
}

/// ```php
/// return \Sharp\verify(parent::pick($order), 'App.Order', 'App.Base.pick()');
/// ```
///
/// A generic `super` call carries its type arguments when PHP# declares the method, though the parent between is a plain
/// PHP class that inherits it, and checks the result against the type they give, spec section 22.
#[test]
fn a_generic_super_call_through_a_plain_php_parent_carries_its_type_arguments() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        public class Report : Plain
        {
            public Order run(Order order) => super.pick<Order>(order);
        }
    "},
        &[
            (
                "src/App/Base.sharp",
                "namespace App;\n\npublic class Base\n{\n    public T pick<T>(T item) => item;\n}\n",
            ),
            ("src/App/Plain.php", "<?php namespace App; class Plain extends Base {}"),
            ("src/App/Order.php", "<?php namespace App; final class Order {}"),
        ],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL [1] "parent"
                    ZVAL "pick"
                    ARG_LIST
                      VAR
                        ZVAL "order"
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "App.Order"
                  ZVAL "App.Order"
                  ZVAL "App.Base.pick()"
        "#}
    );
}

/// The body of `run`, which calls `wrapper.wrap(order)` through `Wrapper`, the plain PHP class-like `plain` declares,
/// whose `@template` method `wrap` the PHP# method `wrap` declares again in `SharpWrapper`.
fn a_call_through_plain_php(wrap: &str, plain: &str) -> String {
    let sharp_wrapper = format!(
        "namespace App;\n\npublic class SharpWrapper : Wrapper\n{{\n    {wrap} Box<T> wrap<T>(T item) => new Box<T>();\n}}\n"
    );

    Lowered::with(
        "namespace App;\n\npublic class Report\n{\n    public Box<Order> run(Wrapper wrapper, Order order) => wrapper.wrap(order);\n}\n",
        &[
            ("src/App/SharpWrapper.sharp", &sharp_wrapper),
            ("src/App/Box.sharp", "namespace App;\n\npublic class Box<TValue>\n{\n    public Box() { }\n}\n"),
            ("src/App/Wrapper.php", plain),
            ("src/App/Order.php", "<?php namespace App; final class Order {}"),
        ],
    )
    .body_of("run")
}

/// The call resolves to plain PHP, so its result is checked too.
const CALL_WITH_TYPE_ARGUMENTS: &str = indoc! {r#"
    STMT_LIST
      RETURN
        VERIFY_TYPE_ARGS
          METHOD_CALL
            VAR
              ZVAL "wrapper"
            ZVAL "wrap"
            ARG_LIST
              VAR
                ZVAL "order"
              SHARP_TYPE_ARGS
                null
                ZVAL "App.Order"
          ZVAL "App.Box<App.Order>"
          ZVAL "App\\Wrapper::wrap()"
"#};

/// A generic call through a plain PHP `@template` interface carries the type arguments the checker found, since the
/// PHP# class that implements it reads them.
#[test]
fn a_generic_call_through_a_plain_php_interface_carries_its_type_arguments() {
    assert_eq!(
        a_call_through_plain_php(
            "public",
            "<?php namespace App; interface Wrapper {\n/**\n * @template T\n * @param T $item\n * @return Box<T>\n */\npublic function wrap(mixed $item): Box; }",
        ),
        CALL_WITH_TYPE_ARGUMENTS
    );
}

/// A generic call through a plain PHP parent's `@template` method carries the type arguments the checker found, since
/// the PHP# class that overrides it reads them.
#[test]
fn a_generic_call_through_a_plain_php_parent_carries_its_type_arguments() {
    assert_eq!(
        a_call_through_plain_php(
            "public override",
            "<?php namespace App; class Wrapper {\n/**\n * @template T\n * @param T $item\n * @return Box<T>\n */\npublic function wrap(mixed $item): Box { return new Box(); } }",
        ),
        CALL_WITH_TYPE_ARGUMENTS
    );
}

/// ```php
/// public function __construct(\Lib\Row $row) {}
/// public static function fromSchema(\Lib\Row $row): static { return new static($row); }
/// public static function find(\Lib\Row $row): ?static { return $row->saved ? static::fromSchema($row) : null; }
/// public static function counted(\Lib\Row $row): static|int { return static::fromSchema($row); }
/// ```
///
/// `Self` is `static`. As a return type it is a `TYPE` node with `IS_STATIC`, which is 15, and `Self?` adds
/// `ZEND_TYPE_NULLABLE`, which is 256. As a class it is the name `static` with `ZEND_NAME_NOT_FQ`, which is 1, as
/// php-src's grammar builds `new static` and `static::`. `required` adds no flag, as PHP has no `required`.
#[test]
fn self_is_static_and_required_adds_no_flag() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Row;\n\npublic abstract class DatabaseEntity\n{\n    public required DatabaseEntity(Row row)\n    {\n    }\n\n    public static Self fromSchema(Row row)\n    {\n        return new Self(row);\n    }\n\n    public static Self? find(Row row) => row.saved ? Self.fromSchema(row) : null;\n\n    public static Self|int counted(Row row) => Self.fromSchema(row);\n}\n",
        &[("src/Lib/Row.php", "<?php namespace Lib; final class Row { public bool $saved = true; }")],
    );

    assert_eq!(
        lowered.render(lowered.child(lowered.child(lowered.root(), 2), 2)),
        indoc! {r#"
            STMT_LIST
              METHOD [1] "__construct" @7-9
                PARAM_LIST
                  PARAM
                    ZVAL "Lib\\Row"
                    ZVAL "row"
                    null
                    null
                    null
                    null
                null
                STMT_LIST
                null
                null
              METHOD [17] "fromSchema" @11-14
                PARAM_LIST
                  PARAM
                    ZVAL "Lib\\Row"
                    ZVAL "row"
                    null
                    null
                    null
                    null
                null
                STMT_LIST
                  RETURN
                    NEW
                      ZVAL [1] "static"
                      ARG_LIST
                        VAR
                          ZVAL "row"
                SHARP_TYPE_ARGS
                  TYPE [15]
                  ZVAL "Function<App.Tenant.DatabaseEntity(Lib.Row)>"
                null
              METHOD [17] "find" @16-16
                PARAM_LIST
                  PARAM
                    ZVAL "Lib\\Row"
                    ZVAL "row"
                    null
                    null
                    null
                    null
                null
                STMT_LIST
                  RETURN
                    CONDITIONAL
                      PROP
                        VAR
                          ZVAL "row"
                        ZVAL "saved"
                      STATIC_CALL
                        ZVAL [1] "static"
                        ZVAL "fromSchema"
                        ARG_LIST
                          VAR
                            ZVAL "row"
                      ZVAL null
                SHARP_TYPE_ARGS
                  TYPE [271]
                  ZVAL "Function<App.Tenant.DatabaseEntity?(Lib.Row)>"
                null
              METHOD [17] "counted" @18-18
                PARAM_LIST
                  PARAM
                    ZVAL "Lib\\Row"
                    ZVAL "row"
                    null
                    null
                    null
                    null
                null
                STMT_LIST
                  RETURN
                    STATIC_CALL
                      ZVAL [1] "static"
                      ZVAL "fromSchema"
                      ARG_LIST
                        VAR
                          ZVAL "row"
                SHARP_TYPE_ARGS
                  TYPE_UNION
                    TYPE [15]
                    ZVAL [1] "int"
                  ZVAL "Function<App.Tenant.DatabaseEntity|int(Lib.Row)>"
                null
        "#}
    );
}

/// ```php
/// return static::make(2);
