/// ```php
/// return (function ($receiver) {
///     return function (string $separator) use ($receiver) {
///         return \App\Shared\Text\TextExtensions::slug($receiver, $separator);
///     };
/// })($title);
/// return \capitalize(...);
/// return \Vendor\Pdf\render(...);
/// ```
///
/// Spec section 14.3: an extension method's value is a closure over its receiver that calls the static method it runs
/// as, with the receiver first, and a plain PHP function's value is PHP's first-class callable of it.
#[test]
fn an_extension_method_or_plain_php_function_value_calls_what_it_names() {
    let lowered = Lowered::with(
        "namespace App;\n\nimport App.Shared.Text.TextExtensions;\nimport Vendor.Pdf;\n\nclass Report\n{\n    public Function<string(string)> slugger(string title) => title.slug;\n\n    public Function<string(string)> capitalizer() => Pdf.capitalize;\n\n    public Function<string(string)> renderer() => Pdf.render;\n}\n",
        &[
            (
                "src/App/Shared/Text/TextExtensions.sharp",
                "namespace App.Shared.Text;\n\npublic static class TextExtensions\n{\n    extension(string value)\n    {\n        public string slug(string separator) => value + separator;\n    }\n}\n",
            ),
            (
                "src/Vendor/Pdf/functions.php",
                "<?php\n\nnamespace Vendor\\Pdf;\n\nfunction render(string $html): string\n{\n    return $html;\n}\n",
            ),
            (
                "src/Vendor/Pdf/helpers.php",
                "<?php\n\nfunction capitalize(string $text): string\n{\n    return ucfirst($text);\n}\n",
            ),
            ("src/Vendor/Pdf/Document.php", "<?php namespace Vendor\\Pdf; final class Document {}"),
        ],
    );

    assert_eq!(
        lowered.body_of("slugger"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  CLOSURE "" @8-8
                    PARAM_LIST
                      PARAM
                        null
                        ZVAL "receiver"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        CLOSURE "" @8-8
                          PARAM_LIST
                            PARAM
                              ZVAL [1] "string"
                              ZVAL "separator"
                              null
                              null
                              null
                              null
                          CLOSURE_USES
                            ZVAL "receiver"
                          STMT_LIST
                            RETURN
                              STATIC_CALL
                                ZVAL "App\\Shared\\Text\\TextExtensions"
                                ZVAL "slug"
                                ARG_LIST
                                  VAR
                                    ZVAL "receiver"
                                  VAR
                                    ZVAL "separator"
                          null
                          null
                    null
                    null
                  ARG_LIST
                    VAR
                      ZVAL "title"
        "#}
    );
    assert_eq!(
        lowered.body_of("capitalizer"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  ZVAL "capitalize"
                  CALLABLE_CONVERT
        "#}
    );
    assert_eq!(
        lowered.body_of("renderer"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  ZVAL "Vendor\\Pdf\\render"
                  CALLABLE_CONVERT
        "#}
    );
}

/// ```php
