/// An enum value's method value is the method's first-class callable, as a class value's is, not a read of a property
/// of that name.
#[test]
fn a_method_value_of_an_enum_value_is_a_first_class_callable() {
    let lowered = Lowered::with(
        "namespace App;\n\nclass Report\n{\n    public Function<string()> run(Status status) => status.label;\n}\n",
        &[(
            "src/App/Status.sharp",
            "namespace App;\n\nenum Status\n{\n    case Active;\n\n    public string label() => \"active\";\n}\n",
        )],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                METHOD_CALL
                  VAR
                    ZVAL "status"
                  ZVAL "label"
                  CALLABLE_CONVERT
        "#}
    );
}

/// ```php
/// $type = \Lib\Calc::class;
/// return \Lib\Calc::MAX + $type::MAX + $type::$count + \Lib\Calc::measure($type::defaultTag());
/// ```
///
/// A member read through a class value is the fetch of the member kind on the class the value holds, as `Class.y` is:
/// `typeof(X).y` names the class, and a local holding a class value is the class of the fetch.
#[test]
fn a_member_read_through_a_class_value_is_the_fetch_of_its_kind_on_that_class() {
    assert_eq!(
        body_in(
            RUN,
            "        const type = typeof(Calc);\n        return typeof(Calc).MAX + type.MAX + type.count + Calc.measure(type.defaultTag());\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; abstract class Calc { public const int MAX = 3; public static int $count = 0; public static function defaultTag(): string { return 'div'; } public static function measure(string $text): int { return strlen($text); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "type"
                CLASS_NAME
                  ZVAL "Lib\\Calc"
              RETURN
                BINARY_OP [1]
                  BINARY_OP [1]
                    BINARY_OP [1]
                      CLASS_CONST
                        ZVAL "Lib\\Calc"
                        ZVAL "MAX"
                      CLASS_CONST
                        VAR
                          ZVAL "type"
                        ZVAL "MAX"
                    STATIC_PROP
                      VAR
                        ZVAL "type"
                      ZVAL "count"
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "measure"
                    ARG_LIST
                      STATIC_CALL
                        VAR
                          ZVAL "type"
                        ZVAL "defaultTag"
                        ARG_LIST
        "#}
    );
}

/// ```php
/// $type = \Sharp\Class::of($calc);
/// return \Lib\Calc::measure($type::label());
/// ```
///
/// A class value of an enum, as `Class.of` gives for an enum case, calls the enum's static as a class's is called.
#[test]
fn a_static_call_through_a_class_value_of_an_enum_is_a_static_call_on_it() {
    assert_eq!(
        body_in(
            "int run(Calc calc)",
            "        const type = Class.of(calc);\n        return Calc.measure(type.label());\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; enum Calc { case One; public static function label(): string { return 'calc'; } public static function measure(string $text): int { return strlen($text); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "type"
                STATIC_CALL
                  ZVAL "Sharp\\Class"
                  ZVAL "of"
                  ARG_LIST
                    VAR
                      ZVAL "calc"
              RETURN
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "measure"
                  ARG_LIST
                    STATIC_CALL
                      VAR
                        ZVAL "type"
                      ZVAL "label"
                      ARG_LIST
        "#}
    );
}

/// ```php
/// $type = $extra > 0 ? \Lib\Calc::class : null;
/// $max = ($type === null ? null : $type::MAX);
/// $count = ($type === null ? null : $type::$count);
/// $tag = ($type === null ? null : $type::defaultTag());
/// return ($max ?? 0) + ($count ?? 0) + \Lib\Calc::measure($tag ?? '');
/// ```
///
/// A null-safe read or call through a class value is the conditional a null-safe method value is, which reads the
/// local itself and runs the static fetch or call when it holds a class.
#[test]
fn a_null_safe_member_read_through_a_class_value_is_a_conditional_over_the_static_fetch() {
    assert_eq!(
        body_in(
            RUN,
            "        const type = extra > 0 ? typeof(Calc) : null;\n        const max = type?.MAX;\n        const count = type?.count;\n        const tag = type?.defaultTag();\n        return (max ?? 0) + (count ?? 0) + Calc.measure(tag ?? \"\");\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; abstract class Calc { public const int MAX = 3; public static int $count = 0; public static function defaultTag(): string { return 'div'; } public static function measure(string $text): int { return strlen($text); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "type"
                CONDITIONAL
                  GREATER
                    VAR
                      ZVAL "extra"
                    ZVAL 0
                  CLASS_NAME
                    ZVAL "Lib\\Calc"
                  ZVAL null
              ASSIGN
                VAR
                  ZVAL "max"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "type"
                    ZVAL null
                  ZVAL null
                  CLASS_CONST
                    VAR
                      ZVAL "type"
                    ZVAL "MAX"
              ASSIGN
                VAR
                  ZVAL "count"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "type"
                    ZVAL null
                  ZVAL null
                  STATIC_PROP
                    VAR
                      ZVAL "type"
                    ZVAL "count"
              ASSIGN
                VAR
                  ZVAL "tag"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "type"
                    ZVAL null
                  ZVAL null
                  STATIC_CALL
                    VAR
                      ZVAL "type"
                    ZVAL "defaultTag"
                    ARG_LIST
              RETURN
                BINARY_OP [1]
                  BINARY_OP [1]
                    COALESCE
                      VAR
                        ZVAL "max"
                      ZVAL 0
                    COALESCE
                      VAR
                        ZVAL "count"
                      ZVAL 0
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "measure"
                    ARG_LIST
                      COALESCE
                        VAR
                          ZVAL "tag"
                        ZVAL ""
        "#}
    );
}

/// ```php
/// return new \Sharp\Map<string, int>([...\array_merge([], ...\array_map(null, $defaults->keys(), \iterator_to_array($defaults, false))), 'root', 0, ...…]);
/// ```
///
/// A `Map` literal with a spread is a new `Map` of each key followed by its value, each spread `Map`'s and each
/// entry's in order, so every key stays and a later one wins.
