/// ```php
/// $type = \Lib\Calc::class;
/// $tag = $type::defaultTag(...);
/// return \Lib\Calc::measure($tag());
/// ```
///
/// A static method read through a class value without a call is its first-class callable, as `Class.m` is.
#[test]
fn a_static_method_read_through_a_class_value_is_its_first_class_callable() {
    assert_eq!(
        body_in(
            RUN,
            "        const type = typeof(Calc);\n        const Function<string()> tag = type.defaultTag;\n        return Calc.measure(tag());\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; abstract class Calc { public static function defaultTag(): string { return 'div'; } public static function measure(string $text): int { return strlen($text); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "type"
                CLASS_NAME
                  ZVAL "Lib\\Calc"
              ASSIGN
                VAR
                  ZVAL "tag"
                STATIC_CALL
                  VAR
                    ZVAL "type"
                  ZVAL "defaultTag"
                  CALLABLE_CONVERT
              RETURN
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "measure"
                  ARG_LIST
                    CALL
                      VAR
                        ZVAL "tag"
                      ARG_LIST
        "#}
    );
}

/// A PHP class whose `__get` and `__callStatic` serve undeclared members, with a static property and a static method.
const MAGIC_ORDER: (&str, &str) = (
    "src/Lib/Order.php",
    "<?php namespace Lib; final class Order { public static int $max = 3; public static function twice(int $n): int { return $n * 2; } public function __get(string $name): mixed { return null; } public static function __callStatic(string $name, array $arguments): mixed { return null; } }",
);

/// ```php
/// \Lib\Calc::remember($extra);
/// ```
///
/// A static call only `__callStatic` serves is a static call of its name, as PHP calls a facade's methods.
#[test]
fn a_static_call_only_call_static_serves_is_a_static_call() {
    assert_eq!(
        body_in(
            "void run(int extra)",
            "        Calc.remember(extra);\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; final class Calc { public static function __callStatic(string $name, array $arguments): mixed { return null; } }",
            )],
        ),
        indoc! {r#"
            STMT_LIST
              STATIC_CALL
                ZVAL "Lib\\Calc"
                ZVAL "remember"
                ARG_LIST
                  VAR
                    ZVAL "extra"
        "#}
    );
}

/// ```php
/// \Lib\Order::where($extra);
/// ```
///
/// `Order.where(x)` calls the static method `__callStatic` serves, though `__get` would serve a property read of the
/// same name, as PHP runs `Order::where($x)`. So the call lowers to a static call of its name, and a standard library
/// method whose body is that call gives an inline form.
#[test]
fn a_static_call_beside_a_get_is_the_static_method_call_static_serves() {
    let library = "namespace Sharp;\n\nimport Lib.Order;\n\npublic class Text\n{\n    public static Any? found(int id) => Order.where(id);\n}\n";
    let forms: Vec<String> = common::checked(TEXT.0, library, &[MAGIC_ORDER], inline_forms)
        .expect("the library file is checked")
        .into_iter()
        .map(|(name, _)| String::from_utf8_lossy(&name).into_owned())
        .collect();

    assert_eq!(forms, ["sharp\\text::found"]);
    assert_eq!(
        Lowered::with(
            "namespace App.Tenant;\n\nimport Lib.Order;\n\nclass Report\n{\n    public void run(int extra)\n    {\n        Order.where(extra);\n    }\n}\n",
            &[MAGIC_ORDER],
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              STATIC_CALL
                ZVAL "Lib\\Order"
                ZVAL "where"
                ARG_LIST
                  VAR
                    ZVAL "extra"
        "#}
    );
}

/// `Class.y` reads only a member the class declares. One its `__callStatic` would serve is refused, so the lowering of
/// `Class.y` never meets a magic member.
#[test]
fn a_static_member_only_a_magic_method_serves_is_refused() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Order;\n\nclass Report\n{\n    public void run()\n    {\n        const where = Order.where;\n    }\n}\n",
        &[MAGIC_ORDER],
    );

    assert_eq!(lowered.diagnostics(), ["9:29 compile error: `Order.where` does not exist."]);
}

/// ```php
/// public function run(int $limit = (static function () { return \Lib\Order::$max; })()): int
/// ```
///
/// A parameter default is any expression, spec section 7, so one that reads a static property or takes a static
/// method runs in a static closure, as any default PHP's constant expression cannot hold does.
#[test]
fn a_static_property_or_method_in_a_parameter_default_runs_in_a_static_closure() {
    let property = [Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Order;\n\nclass Report\n{\n    public int run(int limit = Order.max)\n    {\n        return limit;\n    }\n}\n",
        &[MAGIC_ORDER],
    )];
    let method = [Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Order;\n\nclass Report\n{\n    public int run(Function<int(int)> twice = Order.twice)\n    {\n        return twice(1);\n    }\n}\n",
        &[MAGIC_ORDER],
    )];

    assert_eq!(
        member_in(&property, "Report", &[0, 0, 0, 2]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @7-7
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    STATIC_PROP
                      ZVAL "Lib\\Order"
                      ZVAL "max"
                null
                null
              ARG_LIST
        "#}
    );
    assert_eq!(
        member_in(&method, "Report", &[0, 0, 0, 2]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @7-7
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    STATIC_CALL
                      ZVAL "Lib\\Order"
                      ZVAL "twice"
                      CALLABLE_CONVERT
                null
                null
              ARG_LIST
        "#}
    );
}

/// ```php
/// public static function pick(string $table = (static function () { return static::TABLE; })()): string
/// ```
///
/// Spec section 25: `Self.TABLE` in a default reads the class the call ran on, which no constant expression knows, so
/// it runs in a static closure, which the engine binds to that class. `Report.TABLE` stays a constant expression.
#[test]
fn a_self_constant_in_a_parameter_default_runs_in_a_static_closure() {
    let lowered = [Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public const string TABLE = \"reports\";\n\n    public static string pick(string table = Self.TABLE) => table;\n\n    public static string named(string table = Report.TABLE) => table;\n}\n",
    )];

    assert_eq!(
        member_in(&lowered, "Report", &[1, 0, 0, 2]),
        indoc! {r#"
            CALL
              CLOSURE [16] "" @7-7
                PARAM_LIST
                null
                STMT_LIST
                  RETURN
                    CLASS_CONST
                      ZVAL [1] "static"
                      ZVAL "TABLE"
                null
                null
              ARG_LIST
        "#}
    );
    assert_eq!(
        member_in(&lowered, "Report", &[2, 0, 0, 2]),
        indoc! {r#"
            CLASS_CONST
              ZVAL "App\\Tenant\\Report"
              ZVAL "TABLE"
        "#}
    );
}

/// ```php
/// public function sort((\App\Tenant\Shippable&\App\Tenant\Billable)|\App\Tenant\Report $item): void
/// ```
///
/// Spec section 24: `&` binds tighter than `|`, so a union holds the intersection, and parentheses around it change
/// nothing.
#[test]
fn a_union_that_holds_an_intersection_is_a_php_dnf_type() {
    let lowered = [Lowered::with(
        "namespace App.Tenant;\n\nclass Report\n{\n    public void sort(Shippable & Billable | Report item) { }\n\n    public void grouped((Shippable & Billable) | Report item) { }\n}\n",
        &[
            ("src/App/Tenant/Shippable.sharp", "namespace App.Tenant;\n\npublic interface Shippable\n{\n}\n"),
            ("src/App/Tenant/Billable.sharp", "namespace App.Tenant;\n\npublic interface Billable\n{\n}\n"),
        ],
    )];
    let dnf = indoc! {r#"
        TYPE_UNION
          TYPE_INTERSECTION
            ZVAL "App\\Tenant\\Shippable"
            ZVAL "App\\Tenant\\Billable"
          ZVAL "App\\Tenant\\Report"
    "#};

    assert_eq!(member_in(&lowered, "Report", &[0, 0, 0, 0]), dnf);
    assert_eq!(member_in(&lowered, "Report", &[1, 0, 0, 0]), dnf);
}

/// ```php
/// public static function bumper(): \Closure {
///     return (function ($receiver) use (/* the method's type arguments */) {
///         return function () use ($receiver, /* the method's type arguments */) { return $receiver::bump(/* "#0" */); };
///     })(static::class);
/// }
/// ```
///
/// Spec section 11: a static method of a generic class runs with its class's type arguments, so its value keeps them:
/// `Self.bump` those of the call, as `#0`, on the class the code is called on.
#[test]
fn a_static_method_value_of_a_generic_class_keeps_its_type_arguments() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Counter<T>\n{\n    public static int bump() => 1;\n\n    public static Function<int()> bumper() => Self.bump;\n}\n",
    );
    let main = Lowered::with(
        "namespace App.Tenant;\n\nclass Main\n{\n    public static Function<int()> bumper() => Counter<int>.bump;\n\n    public static Function<int()> own() => Self.one;\n\n    public static int one() => 1;\n}\n",
        &[(
            "src/App/Tenant/Counter.sharp",
            "namespace App.Tenant;\n\nclass Counter<T>\n{\n    public static int bump() => 1;\n}\n",
        )],
    );

    // `Counter<int>.bump` keeps `int`, on `Counter::class`.
    assert_eq!(
        main.render(main.child(main.method_named("bumper"), 2)),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  CLOSURE "" @5-5
                    PARAM_LIST
                      PARAM
                        null
                        ZVAL "receiver"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      RETURN
                        CLOSURE "" @5-5
                          PARAM_LIST
                          CLOSURE_USES
                            ZVAL "receiver"
                          STMT_LIST
                            RETURN
                              STATIC_CALL
                                VAR
                                  ZVAL "receiver"
                                ZVAL "bump"
                                ARG_LIST
                                  SHARP_TYPE_ARGS
                                    null
                                    ZVAL "int"
                          null
                          null
                    null
                    null
                  ARG_LIST
                    CLASS_NAME
                      ZVAL "App\\Tenant\\Counter"
        "#}
    );
    // A class that isn't generic keeps PHP's first-class callable.
    assert_eq!(
        main.render(main.child(main.method_named("own"), 2)),
        indoc! {r#"
            STMT_LIST
              RETURN
                STATIC_CALL
                  ZVAL [1] "static"
                  ZVAL "one"
                  CALLABLE_CONVERT
        "#}
    );

    assert_eq!(
        lowered.render(lowered.child(lowered.method_named("bumper"), 2)),
        indoc! {r##"
            STMT_LIST
              RETURN
                CALL
                  CLOSURE "" @7-7
                    PARAM_LIST
                      PARAM
                        null
                        ZVAL "receiver"
                        null
                        null
                        null
                        null
                    CLOSURE_USES
                      ZVAL "\0<sharp>\0types"
                    STMT_LIST
                      RETURN
                        CLOSURE "" @7-7
                          PARAM_LIST
                          CLOSURE_USES
                            ZVAL "receiver"
                            ZVAL "\0<sharp>\0types"
                          STMT_LIST
                            RETURN
                              STATIC_CALL
                                VAR
                                  ZVAL "receiver"
                                ZVAL "bump"
                                ARG_LIST
                                  SHARP_TYPE_ARGS
                                    null
                                    ZVAL "#0"
                          null
                          null
                    null
                    null
                  ARG_LIST
                    CLASS_NAME
                      ZVAL [1] "static"
        "##}
    );
}

