/// ```php
/// $a = "line\n"; $b = 'raw\n'; $c = 1.5; $d = 0x10; $e = 9223372036854775808; $f = true; $g = false; $h = null;
/// ```
///
/// `9223372036854775808` overflows `int`, so PHP reads it as a float.
#[test]
fn literals_are_zvals_of_their_php_value() {
    assert_eq!(
        body(
            "        let a = \"line\\n\";\n        let b = 'raw\\n';\n        let c = 1.5;\n        let d = 0x10;\n        let e = 9223372036854775808;\n        let f = true;\n        let g = false;\n        string? h = null;\n        return 1;\n"
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                ZVAL "line\n"
              ASSIGN
                VAR
                  ZVAL "b"
                ZVAL "raw\\n"
              ASSIGN
                VAR
                  ZVAL "c"
                ZVAL 1.5
              ASSIGN
                VAR
                  ZVAL "d"
                ZVAL 16
              ASSIGN
                VAR
                  ZVAL "e"
                ZVAL 9.223372036854776e18
              ASSIGN
                VAR
                  ZVAL "f"
                ZVAL true
              ASSIGN
                VAR
                  ZVAL "g"
                ZVAL false
              ASSIGN
                VAR
                  ZVAL "h"
                ZVAL null
              RETURN
                ZVAL 1
        "#}
    );
}

/// ```php
/// return $a + $a - \intdiv($a * $a, $a) % $a;
/// ```
///
/// `[1]`, `[2]`, `[3]` and `[5]` are `ZEND_ADD`, `ZEND_SUB`, `ZEND_MUL` and `ZEND_MOD`. `/` on two ints is `\intdiv`.
#[test]
fn arithmetic_operators_are_binary_ops() {
    assert_eq!(
        body("        let a = 1;\n        return a + a - a * a / a % a;\n"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                ZVAL 1
              RETURN
                BINARY_OP [2]
                  BINARY_OP [1]
                    VAR
                      ZVAL "a"
                    VAR
                      ZVAL "a"
                  BINARY_OP [5]
                    CALL
                      ZVAL "intdiv"
                      ARG_LIST
                        BINARY_OP [3]
                          VAR
                            ZVAL "a"
                          VAR
                            ZVAL "a"
                        VAR
                          ZVAL "a"
                    VAR
                      ZVAL "a"
        "#}
    );
}

/// ```php
/// $b = $a === $a; $b = $a !== $a; $b = $calc === $calc; $b = $calc !== $calc; $b = $a < $a; $b = $a <= $a;
/// $b = $a > $a; $b = $a >= $a;
/// ```
///
/// `==` and `!=` compare values strictly, so they are `ZEND_IS_IDENTICAL` and `ZEND_IS_NOT_IDENTICAL`, `[16]` and
/// `[17]`, as `===` and `!==` on a class instance are. `[20]` and `[21]` are `ZEND_IS_SMALLER` and
/// `ZEND_IS_SMALLER_OR_EQUAL`. `>` and `>=` have kinds of their own.
#[test]
fn comparison_operators_are_the_kinds_php_gives_them() {
    let tree = body_in(
        "int run(Calc calc)",
        "        let a = 1;\n        let b = a == a;\n        b = a != a;\n        b = calc === calc;\n        b = calc !== calc;\n        b = a < a;\n        b = a <= a;\n        b = a > a;\n        b = a >= a;\n        return a;\n",
        &[("src/Lib/Calc.php", "<?php namespace Lib; final class Calc {}")],
    );

    assert_eq!(
        assigned_values(&tree),
        [
            "ZVAL 1",
            "BINARY_OP [16]",
            "BINARY_OP [17]",
            "BINARY_OP [16]",
            "BINARY_OP [17]",
            "BINARY_OP [20]",
            "BINARY_OP [21]",
            "GREATER",
            "GREATER_EQUAL",
        ]
    );
}

/// The kind of the value each top-level assignment of a body's tree assigns, in order.
fn assigned_values(tree: &str) -> Vec<&str> {
    let lines: Vec<&str> = tree.lines().collect();

    lines.windows(4).filter(|window| window[0] == "  ASSIGN").map(|window| window[3].trim_start()).collect()
}

/// ```php
/// $a = $extra; $b = $a === null; $b = null !== $a; $b = $a === $a;
/// ```
///
/// `==` and `!=` on a nullable value are lifted: null equals only null, so `0 == null` is false. `[16]` and `[17]` are
/// `ZEND_IS_IDENTICAL` and `ZEND_IS_NOT_IDENTICAL`, which compare `null` that way.
#[test]
fn equality_with_null_is_identity() {
    let tree = body_in(
        "int run(int? extra)",
        "        let a = extra;\n        let b = a == null;\n        b = null != a;\n        b = a == a;\n        return 1;\n",
        &[],
    );

    assert_eq!(assigned_values(&tree), ["VAR", "BINARY_OP [16]", "BINARY_OP [17]", "BINARY_OP [16]"]);
}

/// ```php
/// $b = $text === "01"; $b = $text !== "01"; $b = $total === 1; $b = $status === Status::Open;
/// ```
///
/// Spec section 19: `==` compares values strictly, so `"1" == "01"` and `"1e3" == "1000"` are false, as PHP's `===`
/// makes them. `[16]` and `[17]` are `ZEND_IS_IDENTICAL` and `ZEND_IS_NOT_IDENTICAL`.
#[test]
fn equality_of_strings_ints_and_enums_is_identity() {
    let tree = body_in(
        "int run(string text, int total, Status status)",
        "        let b = text == \"01\";\n        b = text != \"01\";\n        b = total == 1;\n        b = status == Status.Open;\n        return 1;\n",
        &[("src/App/Tenant/Status.php", "<?php namespace App\\Tenant; enum Status { case Open; case Closed; }")],
    );

    assert_eq!(assigned_values(&tree), ["BINARY_OP [16]", "BINARY_OP [17]", "BINARY_OP [16]", "BINARY_OP [16]"]);
}

/// ```php
/// $b = \Sharp\Internal\equals($either, $tags); $b = !\Sharp\Internal\equals($either, 1);
/// return \Sharp\Internal\equals($tuple, 1);
///
/// return \Sharp\Internal\contains($rows, $either);
/// ```
///
/// Spec section 19: a value that may be a collection or another type compares by what it holds, which only the running
/// value tells, so `==` on it runs the engine's `\Sharp\Internal\equals`, and `!=` is its `!`.
#[test]
fn equality_of_a_union_that_holds_a_collection_compares_by_what_it_holds() {
    let body = body_in(
        "bool run(Set<int>|int either, Set<int> tags, int|[int, string] tuple)",
        "        let b = either == tags;\n        b = either != 1;\n        return tuple == 1;\n",
        &[],
    );
    let comparisons = &body[body.find("  ASSIGN\n    VAR\n      ZVAL \"b\"").expect("the comparisons")..];

    assert_eq!(
        format!("STMT_LIST\n{comparisons}"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                CALL
                  ZVAL "Sharp\\Internal\\equals"
                  ARG_LIST
                    VAR
                      ZVAL "either"
                    VAR
                      ZVAL "tags"
              ASSIGN
                VAR
                  ZVAL "b"
                UNARY_OP [14]
                  CALL
                    ZVAL "Sharp\\Internal\\equals"
                    ARG_LIST
                      VAR
                        ZVAL "either"
                      ZVAL 1
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\equals"
                  ARG_LIST
                    VAR
                      ZVAL "tuple"
                    ZVAL 1
        "#}
    );
    // A search is the engine's, which compares each element as `==` does, never with `\in_array`'s `===`.
    let search = body_in(
        "bool run(List<Set<int>|int> rows, Set<int>|int either)",
        "        return rows.contains(either);\n",
        &[],
    );
    assert_eq!(
        format!("STMT_LIST\n{}", &search[search.find("  RETURN").expect("the search")..]),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\contains"
                  ARG_LIST
                    VAR
                      ZVAL "rows"
                    VAR
                      ZVAL "either"
        "#}
    );
}

/// ```php
/// $b = \Sharp\Internal\equals($raw, $counts); $b = !\Sharp\Internal\equals($raw, 1.5); $b = $raw === "pro";
/// return $raw === null;
/// ```
///
/// Spec section 24: an unchecked `Any?` compares by value with whatever it holds, so `==` on it runs the engine's
/// `\Sharp\Internal\equals`, which compares a `Map` by its entries and an `int` with a `float` as two floats, and `!=`
/// is its `!`. A string, a `bool` and `null` equal only the same one, so `===` tests them. The body starts with the
/// statement that makes `counts` a `Map`.
#[test]
fn equality_of_an_unchecked_any_compares_by_value() {
    let body = body_in(
        "bool run(Any? raw, Map<string, int> counts)",
        "        let b = raw == counts;\n        b = raw != 1.5;\n        b = raw == \"pro\";\n        return raw == null;\n",
        &[],
    );
    let comparisons = &body[body.find("  ASSIGN\n    VAR\n      ZVAL \"b\"").expect("the comparisons")..];

    assert_eq!(
        format!("STMT_LIST\n{comparisons}"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                CALL
                  ZVAL "Sharp\\Internal\\equals"
                  ARG_LIST
                    VAR
                      ZVAL "raw"
                    VAR
                      ZVAL "counts"
              ASSIGN
                VAR
                  ZVAL "b"
                UNARY_OP [14]
                  CALL
                    ZVAL "Sharp\\Internal\\equals"
                    ARG_LIST
                      VAR
                        ZVAL "raw"
                      ZVAL 1.5
              ASSIGN
                VAR
                  ZVAL "b"
                BINARY_OP [16]
                  VAR
                    ZVAL "raw"
                  ZVAL "pro"
              RETURN
                BINARY_OP [16]
                  VAR
                    ZVAL "raw"
                  ZVAL null
        "#}
    );
}

/// ```php
/// return [$f(2), $holder->onTotal(2), $count(2), ($steps[0])(2)];
/// ```
///
/// Spec section 24: a function value may hold a plain PHP closure, which returns an `int` where the function type says
/// `float`. So a call of a function value whose result holds a `float` checks its result, as a call into plain PHP
/// does, and the check converts the `int`, whether the value is a local, a property or any other expression, which
/// the check names as the file writes it. A result with no `float` needs no check.
#[test]
fn a_call_of_a_function_value_checks_a_float_result() {
    assert_eq!(
        Lowered::with(
            &method_with(
                "List<Any> run(Function<float(int)> f, Holder holder, Function<int(int)> count, List<Function<float(int)>> steps)",
                "        return [f(2), holder.onTotal(2), count(2), steps[0](2)];\n",
            ),
            &[("src/App/Tenant/Holder.sharp", "namespace App.Tenant;\n\npublic class Holder\n{\n    public Function<List<float>(int)> onTotal { get; } = (int n) => [1.5];\n}\n")],
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                ARRAY [3]
                  ARRAY_ELEM
                    VERIFY_TYPE_ARGS
                      CALL
                        VAR
                          ZVAL "f"
                        ARG_LIST
                          ZVAL 2
                      ZVAL "float"
                      ZVAL "f()"
                    null
                  ARRAY_ELEM
                    VERIFY_TYPE_ARGS
                      CALL
                        PROP
                          VAR
                            ZVAL "holder"
                          ZVAL "onTotal"
                        ARG_LIST
                          ZVAL 2
                      ZVAL "List<float>"
                      ZVAL "onTotal()"
                    null
                  ARRAY_ELEM
                    CALL
                      VAR
                        ZVAL "count"
                      ARG_LIST
                        ZVAL 2
                    null
                  ARRAY_ELEM
                    VERIFY_TYPE_ARGS
                      CALL
                        DIM
                          VAR
                            ZVAL "steps"
                          ZVAL 0
                        ARG_LIST
                          ZVAL 2
                      ZVAL "float"
                      ZVAL "steps[0]()"
                    null
        "#}
    );
}

/// ```php
/// $read = $source->read(); return \Sharp\Internal\map($numbers, $f);
/// ```
///
/// Spec section 24: a plain PHP class may implement a PHP# interface, and the engine runs the function value a
/// collection method takes and keeps what it returns, so a call of either checks a result that holds an `Any` or a
/// `float`. A lambda written in PHP# returns what its type says, so the collection method given one checks nothing,
/// and a PHP# method given a function value checks its own result where it returns.
#[test]
fn an_interface_method_and_a_collection_method_given_a_function_value_check_their_results() {
    let body = Lowered::with(
        &method_with(
            "List<float> run(Source source, List<int> numbers, Function<float(int)> f)",
            "        Any read = source.read();\n        List<float> doubled = numbers.map((int n) => n * 2.0);\n        List<float> applied = Doubler.apply(f);\n        return numbers.map(f);\n",
        ),
        &[
            ("src/App/Tenant/Source.sharp", "namespace App.Tenant;\n\npublic interface Source\n{\n    Any read();\n}\n"),
            (
                "src/App/Tenant/Doubler.sharp",
                "namespace App.Tenant;\n\npublic static class Doubler\n{\n    public static List<float> apply(Function<float(int)> f) => [f(1)];\n}\n",
            ),
        ],
    )
    .body();

    assert!(body.contains("      ZVAL \"Any\"\n      ZVAL \"App.Tenant.Source.read()\"\n"), "{body}");
    assert!(body.contains("      ZVAL \"List<float>\"\n      ZVAL \"map()\"\n"), "{body}");
    assert!(body.contains("ZVAL \"apply\""), "{body}");
    assert_eq!(body.matches("VERIFY_TYPE_ARGS").count(), 2, "{body}");
}

/// Spec section 22: each PHP# call of a PHP# interface's instance member checks its result, so `[2]`,
/// `ZEND_SHARP_RESULT_CALLER_CHECKED`, marks each such member's PHP return type, and the engine links a plain PHP method
/// that declares none under it, a `void` or `never` member's included.
#[test]
fn an_interface_member_marks_its_return_type_as_checked_by_each_call() {
    let lowered = Lowered::with(
        "namespace App;\n\nimport Lib.Relation;\n\npublic interface Taggable\n{\n    Relation relate(string name);\n\n    List<int> ids();\n\n    void touch();\n\n    never fail(string reason);\n}\n",
        &[("src/Lib/Relation.php", "<?php namespace Lib; class Relation {}")],
    );
    let marked = |name: &str| lowered.render(lowered.child(lowered.method_named(name), 3));

    assert_eq!(marked("relate"), "SHARP_TYPE_ARGS [2]\n  ZVAL \"Lib\\\\Relation\"\n  ZVAL \"Lib.Relation\"\n");
    assert_eq!(marked("ids"), "SHARP_TYPE_ARGS [2]\n  TYPE [7]\n  ZVAL \"List<int>\"\n");
    assert_eq!(marked("touch"), "SHARP_TYPE_ARGS [2]\n  ZVAL [1] \"void\"\n  ZVAL \"void\"\n");
    assert_eq!(marked("fail"), "SHARP_TYPE_ARGS [2]\n  ZVAL [1] \"never\"\n  null\n");
}

/// ```php
/// $tags = \Sharp\verify($owner->relate('tags'), 'App.Relation', 'App.Taggable.relate()');
/// ```
///
/// Spec section 22: a plain PHP class implements a PHP# interface's member with a method that may declare no return
/// type, so each PHP# call of the member checks its result, as is a call of its method value, named as PHP# writes the
/// member. The check tests a collection alone, `List<Any?>`, inside a tuple too, and the type argument of a generic
/// interface's member, and a second type in the text names the member's type for the error where the check reads less,
/// a null-safe call's included. A result of any value, a `void` or `never` one and a call of a PHP# class's own method
/// check nothing.
#[test]
fn a_call_of_an_interface_member_checks_its_result() {
    let body = Lowered::with(
        &method_with(
            "void run(Taggable owner, Taggable? maybe, Source<Relation> source, Relation relation)",
            "        Relation tags = owner.relate(\"tags\");\n        List<int> ids = owner.ids();\n        Set<string> names = owner.names();\n        Map<string, int> counts = owner.counts();\n        Iterable<int> stream = owner.stream();\n        [List<int>, string] pair = owner.pair();\n        Relation? maybeTags = maybe?.relate(\"maybe\");\n        Relation read = source.read();\n        Any? raw = owner.raw();\n        owner.touch();\n        Relation again = relation.again();\n        const relate = owner.relate;\n        Relation named = relate(\"named\");\n        owner.fail(\"stopped\");\n",
        ),
        &[
            (
                "src/App/Tenant/Taggable.sharp",
                "namespace App.Tenant;\n\npublic interface Taggable\n{\n    Relation relate(string name);\n\n    List<int> ids();\n\n    Set<string> names();\n\n    Map<string, int> counts();\n\n    Iterable<int> stream();\n\n    [List<int>, string] pair();\n\n    Any? raw();\n\n    void touch();\n\n    never fail(string reason);\n}\n",
            ),
            ("src/App/Tenant/Source.sharp", "namespace App.Tenant;\n\npublic interface Source<T>\n{\n    T read();\n}\n"),
            (
                "src/App/Tenant/Relation.sharp",
                "namespace App.Tenant;\n\npublic class Relation\n{\n    public Relation() { }\n\n    public Relation again() => this;\n}\n",
            ),
        ],
    )
    .body();

    assert!(
        body.contains("      ZVAL \"App.Tenant.Relation\"\n      ZVAL \"App.Tenant.Taggable.relate()\"\n"),
        "{body}"
    );
    assert!(
        body.contains(
            "                    ZVAL \"App.Tenant.Relation\"\n                    ZVAL \"App.Tenant.Taggable.relate()\"\n"
        ),
        "{body}"
    );
    assert!(
        body.contains("      ZVAL \"List<Any?>, List<int>\"\n      ZVAL \"App.Tenant.Taggable.ids()\"\n"),
        "{body}"
    );
    // The typed local makes the `Set` and the `Map` the object after the check, as
    // `a_set_or_a_map_an_interface_member_gives_becomes_the_object` shows.
    assert!(
        body.contains(
            "              ZVAL \"Set<Any?>, Set<string>\"\n              ZVAL \"App.Tenant.Taggable.names()\"\n"
        ),
        "{body}"
    );
    assert!(
        body.contains(
            "              ZVAL \"Map<Any?, Any?>, Map<string, int>\"\n              ZVAL \"App.Tenant.Taggable.counts()\"\n"
        ),
        "{body}"
    );
    assert!(
        body.contains("      ZVAL \"Iterable<Any?>, Iterable<int>\"\n      ZVAL \"App.Tenant.Taggable.stream()\"\n"),
        "{body}"
    );
    assert!(
        body.contains(
            "      ZVAL \"[List<Any?>, string], [List<int>, string]\"\n      ZVAL \"App.Tenant.Taggable.pair()\"\n"
        ),
        "{body}"
    );
    assert!(
        body.contains(
            "ZVAL \"App.Tenant.Relation?, App.Tenant.Relation\"\n      ZVAL \"App.Tenant.Taggable.relate()\"\n"
        ),
        "{body}"
    );
    assert!(body.contains("      ZVAL \"App.Tenant.Relation\"\n      ZVAL \"App.Tenant.Source.read()\"\n"), "{body}");
    assert_eq!(body.matches("VERIFY_TYPE_ARGS").count(), 9, "{body}");
}

/// ```php
/// $names = \is_array($crossing#1 = verify($owner->names(), …)) ? new \Sharp\Set<string>($crossing#1) : $crossing#1;
/// return \Sharp\Internal\containsKey(\is_array($crossing#1 = verify($owner->names(), …)) ? new \Sharp\Set<string>(…) : …, 'b')
///     && \Sharp\Internal\containsKey(… ? new \Sharp\Map<string, int>(…each key as a string…) : …, 'a');
/// ```
///
/// Spec section 22: a plain PHP class may implement a PHP# interface's member, so the `Set` or the `Map` a call of the
/// member gives may be the PHP array it crosses into. A typed local that holds it and a member that reads it make it the
/// object first, as they make what a call of plain PHP gives, so each member runs on the object and a key keeps its type.
/// A PHP# class may implement the member too, so the result plain PHP takes still crosses out as its PHP array.
#[test]
fn a_set_or_a_map_an_interface_member_gives_becomes_the_object() {
    let body = Lowered::with(
        &method_with(
            "bool run(Taggable owner)",
            "        Set<string> names = owner.names();\n        names.add(\"d\");\n        return owner.names().contains(\"b\") && owner.counts().has(\"a\") && Calc.total(owner.counts()) > 0;\n",
        ),
        &[
            (
                "src/App/Tenant/Taggable.sharp",
                "namespace App.Tenant;\n\npublic interface Taggable\n{\n    Set<string> names();\n\n    Map<string, int> counts();\n}\n",
            ),
            (
                "src/Lib/Calc.php",
                "<?php namespace Lib;\nfinal class Calc { /** @param array<string, int> $counts */ public static function total(array $counts): int { return 0; } }",
            ),
        ],
    )
    .body();

    assert_eq!(body.matches("ZVAL \"Sharp\\\\Set\"\n").count(), 2, "{body}");
    assert_eq!(body.matches("ZVAL \"Sharp\\\\Map\"\n").count(), 1, "{body}");
    assert_eq!(body.matches("ZVAL \"string\"\n").count(), 2, "{body}");
    assert!(body.contains("ZVAL \"string, int\"\n"), "{body}");
    assert_eq!(body.matches("ZVAL \"Sharp\\\\Internal\\\\arrayOf\"\n").count(), 1, "{body}");
}

/// ```php
/// $tags = \Sharp\verify($contact->relate('tags'), 'App.Tenant.Relation', 'App.Tenant.Taggable.relate()');
/// ```
///
/// Spec section 22: a call of a plain PHP class's method that declares no return type, under a PHP# interface's member
/// the class implements, is a call of the member: the checker types it by the member, and the call checks its result.
/// A PHP# subclass's call on `this` is one too.
#[test]
fn a_call_of_a_plain_class_method_under_an_interface_member_checks_its_result() {
    let library = [
        (
            "src/App/Tenant/Taggable.sharp",
            "namespace App.Tenant;\n\npublic interface Taggable\n{\n    Relation relate(string name);\n}\n",
        ),
        (
            "src/App/Tenant/Relation.sharp",
            "namespace App.Tenant;\n\npublic class Relation\n{\n    public Relation() { }\n}\n",
        ),
        (
            "src/App/Tenant/Contact.php",
            "<?php namespace App\\Tenant; abstract class Model { public function relate($name) { return new Relation(); } } class Contact extends Model implements Taggable {}",
        ),
    ];
    let body = body_in("Relation run(Contact contact)", "        return contact.relate(\"tags\");\n", &library);
    let subclass = Lowered::with(
        "namespace App.Tenant;\n\npublic class Article : Contact\n{\n    public Article() { }\n\n    public Relation run() => this.relate(\"this\");\n}\n",
        &library,
    )
    .body();

    for body in [body, subclass] {
        assert!(body.contains("ZVAL \"App.Tenant.Relation\"\n      ZVAL \"App.Tenant.Taggable.relate()\"\n"), "{body}");
    }
}

/// ```php
/// $value = \Sharp\verify(Generic::readFrom($source, <int>), 'int', 'App.Tenant.Generic.readFrom()');
/// ```
///
/// Spec section 22: a check in a generic method's body, or in a generic class's static method's, reads the type
/// parameter as any type, `#0`, so the call that gives the type argument checks the result against it, as Java checks
/// an erased generic method's result where its caller gives the type. A call that gives a type parameter of the method
/// it is in leaves the check to the call of that method, and a call of a method whose result names no type parameter
/// the call gives checks nothing.
#[test]
fn a_call_of_a_generic_method_checks_its_result_against_the_type_it_gives() {
    let library = [
        ("src/App/Tenant/Source.sharp", "namespace App.Tenant;\n\npublic interface Source<T>\n{\n    T read();\n}\n"),
        (
            "src/App/Tenant/Generic.sharp",
            "namespace App.Tenant;\n\npublic static class Generic\n{\n    public static T readFrom<T>(Source<T> source) => source.read();\n\n    public static T again<T>(Source<T> source) => Generic.readFrom(source);\n\n    public static int plain(Source<int> source) => 1;\n}\n",
        ),
    ];
    let again = Lowered::with(library[1].1, &[library[0]]).body_of("again");
    let body = body_in(
        "int run(Source<int> source)",
        "        int value = Generic.readFrom(source);\n        int first = Repo<int>.first(source);\n        return Generic.plain(source);\n",
        &[
            library[0],
            library[1],
            (
                "src/App/Tenant/Repo.sharp",
                "namespace App.Tenant;\n\npublic class Repo<T>\n{\n    public Repo() { }\n\n    public static T first(Source<T> source) => source.read();\n}\n",
            ),
        ],
    );
    let repo = Lowered::with(
        "namespace App.Tenant;\n\npublic class Repo<T>\n{\n    public Repo() { }\n\n    public static T first(Source<T> source) => source.read();\n}\n",
        &[library[0]],
    )
    .body_of("first");

    assert!(body.contains("      ZVAL \"int\"\n      ZVAL \"App.Tenant.Generic.readFrom()\"\n"), "{body}");
    assert!(body.contains("      ZVAL \"int\"\n      ZVAL \"App.Tenant.Repo.first()\"\n"), "{body}");
    assert_eq!(body.matches("VERIFY_TYPE_ARGS").count(), 2, "{body}");
    assert!(!again.contains("VERIFY_TYPE_ARGS"), "{again}");
    assert_eq!(
        repo,
        indoc! {r##"
            STMT_LIST
              RETURN
                VERIFY_TYPE_ARGS
                  METHOD_CALL
                    VAR
                      ZVAL "source"
                    ZVAL "read"
                    ARG_LIST
                  ZVAL "#0"
                  ZVAL "App.Tenant.Source.read()"
        "##}
    );
}

/// ```php
/// $total = $maybe === null ? null : $maybe(2); return $totals();
/// ```
///
/// A `?.(…)` call of a function value checks its result as a plain call does, and a `Map` whose values are `float`s
/// is checked too.
#[test]
fn a_null_safe_call_and_a_map_of_floats_check_their_results() {
    assert_eq!(
        body_in(
            "Map<string, float> run(Function<float(int)>? maybe, Function<Map<string, float>()> totals)",
            "        const total = maybe?.(2);\n        return totals();\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "total"
                CONDITIONAL [1]
                  BINARY_OP [16]
                    VAR
                      ZVAL "maybe"
                    ZVAL null
                  ZVAL null
                  VERIFY_TYPE_ARGS
                    CALL
                      VAR
                        ZVAL "maybe"
                      ARG_LIST
                        ZVAL 2
                    ZVAL "float?"
                    ZVAL "maybe()"
              RETURN
                VERIFY_TYPE_ARGS
                  CALL
                    VAR
                      ZVAL "totals"
                    ARG_LIST
                  ZVAL "Map<string, float>"
                  ZVAL "totals()"
        "#}
    );
}

/// ```php
/// $b = \Sharp\Internal\equals($kind, $other); $b = !\Sharp\Internal\equals($kind, $other);
/// return \Sharp\Internal\contains($kinds, $kind);
/// ```
///
/// Spec section 25: `==` compares two class values by their whole type, type arguments included, as C# compares two
/// `Type`s, so `typeof(Box<Order>) == typeof(Box<Invoice>)` is false though both name `App\Box`. The engine's
/// `\Sharp\Internal\equals` compares them, `!=` is its `!`, and the engine's search compares each element as `==` does.
#[test]
fn equality_of_class_values_compares_their_whole_types() {
    assert_eq!(
        body_in(
            "bool run(Class<Order> kind, Class<Order> other, List<Class<Order>> kinds)",
            "        let b = kind == other;\n        b = kind != other;\n        return kinds.contains(kind);\n",
            &[("src/App/Tenant/Order.php", "<?php namespace App\\Tenant; final class Order {}")],
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                CALL
                  ZVAL "Sharp\\Internal\\equals"
                  ARG_LIST
                    VAR
                      ZVAL "kind"
                    VAR
                      ZVAL "other"
              ASSIGN
                VAR
                  ZVAL "b"
                UNARY_OP [14]
                  CALL
                    ZVAL "Sharp\\Internal\\equals"
                    ARG_LIST
                      VAR
                        ZVAL "kind"
                      VAR
                        ZVAL "other"
              RETURN
                CALL
                  ZVAL "Sharp\\Internal\\contains"
                  ARG_LIST
                    VAR
                      ZVAL "kinds"
                    VAR
                      ZVAL "kind"
        "#}
    );
}

/// ```php
/// $b = (float) $count === $ratio; $b = $ratio !== (float) $count;
/// ```
///
/// Spec section 19: numbers compare by value, so `1 == 1.0` is true. A side that may hold an int is cast to float, and
/// the floats compare with `===`. `[5]` is `IS_DOUBLE`.
#[test]
fn equality_of_an_int_and_a_float_compares_them_as_floats() {
    assert_eq!(
        body_in(
            "int run(int count, float ratio)",
            "        let b = count == ratio;\n        b = ratio != count;\n        return 1;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                BINARY_OP [16]
                  CAST [5]
                    VAR
                      ZVAL "count"
                  VAR
                    ZVAL "ratio"
              ASSIGN
                VAR
                  ZVAL "b"
                BINARY_OP [17]
                  VAR
                    ZVAL "ratio"
                  CAST [5]
                    VAR
                      ZVAL "count"
              RETURN
                ZVAL 1
        "#}
    );
}

/// A value pattern compares as `==` does, so an int subject matches the float `1.0` as a float.
#[test]
fn an_int_subject_matches_a_float_pattern_as_a_float() {
    assert_eq!(
        body_in(
            "int run(int count)",
            "        return match (count) {\n            == 1.0 => 1,\n            default => 2,\n        };\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                MATCH
                  ZVAL true
                  MATCH_ARM_LIST
                    MATCH_ARM
                      EXPR_LIST
                        BINARY_OP [16]
                          CAST [5]
                            VAR
                              ZVAL "count"
                          ZVAL 1.0
                      ZVAL 1
                    MATCH_ARM
                      null
                      ZVAL 2
        "#}
    );
}

/// ```php
/// $b = (($operand#1 = $count) === null) === (($operand#2 = $ratio) === null)
///     && ($operand#1 === null || (float) $operand#1 === $operand#2);
/// $b = !((($operand#1 = $count) === null) === (($operand#2 = 1.5) === null)
///     && ($operand#1 === null || (float) $operand#1 === $operand#2));
/// ```
///
/// A nullable side is lifted: null equals only null, and `(float) null` never compares. Each side runs once into a
/// hidden `$operand#N`, so `int? == float` with a null int is false and two nulls are equal.
#[test]
fn equality_of_a_nullable_int_and_a_float_compares_null_before_the_floats() {
    assert_eq!(
        body_in(
            "int run(int? count, float? ratio)",
            "        let b = count == ratio;\n        b = count != 1.5;\n        return 1;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                AND
                  BINARY_OP [16]
                    BINARY_OP [16]
                      ASSIGN
                        VAR
                          ZVAL "operand#1"
                        VAR
                          ZVAL "count"
                      ZVAL null
                    BINARY_OP [16]
                      ASSIGN
                        VAR
                          ZVAL "operand#2"
                        VAR
                          ZVAL "ratio"
                      ZVAL null
                  OR
                    BINARY_OP [16]
                      VAR
                        ZVAL "operand#1"
                      ZVAL null
                    BINARY_OP [16]
                      CAST [5]
                        VAR
                          ZVAL "operand#1"
                      VAR
                        ZVAL "operand#2"
              ASSIGN
                VAR
                  ZVAL "b"
                UNARY_OP [14]
                  AND
                    BINARY_OP [16]
                      BINARY_OP [16]
                        ASSIGN
                          VAR
                            ZVAL "operand#1"
                          VAR
                            ZVAL "count"
                        ZVAL null
                      BINARY_OP [16]
                        ASSIGN
                          VAR
                            ZVAL "operand#2"
                          ZVAL 1.5
                        ZVAL null
                    OR
                      BINARY_OP [16]
                        VAR
                          ZVAL "operand#1"
                        ZVAL null
                      BINARY_OP [16]
                        CAST [5]
                          VAR
                            ZVAL "operand#1"
                        VAR
                          ZVAL "operand#2"
              RETURN
                ZVAL 1
        "#}
    );
}

/// ```php
/// return (($operand#1 = $a) === null) === (($operand#2 = ((($operand#3 = $b) === null) === (($operand#4 = $c) === null)
///     && ($operand#3 === null || (float) $operand#3 === $operand#4)) ? 1 : 2.5) === null)
///     && ($operand#1 === null || (float) $operand#1 === (float) $operand#2);
/// ```
///
/// An int/float `==` inside another one's operand takes its own `$operand#N`s, so it never overwrites the outer `a`.
#[test]
fn a_nested_nullable_int_and_float_equality_takes_its_own_hidden_variables() {
    assert_eq!(
        body_in("bool run(int? a, int? b, float c)", "        return a == (b == c ? 1 : 2.5);\n", &[]),
        indoc! {r#"
            STMT_LIST
              RETURN
                AND
                  BINARY_OP [16]
                    BINARY_OP [16]
                      ASSIGN
                        VAR
                          ZVAL "operand#1"
                        VAR
                          ZVAL "a"
                      ZVAL null
                    BINARY_OP [16]
                      ASSIGN
                        VAR
                          ZVAL "operand#2"
                        CONDITIONAL [1]
                          AND
                            BINARY_OP [16]
                              BINARY_OP [16]
                                ASSIGN
                                  VAR
                                    ZVAL "operand#3"
                                  VAR
                                    ZVAL "b"
                                ZVAL null
                              BINARY_OP [16]
                                ASSIGN
                                  VAR
                                    ZVAL "operand#4"
                                  VAR
                                    ZVAL "c"
                                ZVAL null
                            OR
                              BINARY_OP [16]
                                VAR
                                  ZVAL "operand#3"
                                ZVAL null
                              BINARY_OP [16]
                                CAST [5]
                                  VAR
                                    ZVAL "operand#3"
                                VAR
                                  ZVAL "operand#4"
                          ZVAL 1
                          ZVAL 2.5
                      ZVAL null
                  OR
                    BINARY_OP [16]
                      VAR
                        ZVAL "operand#1"
                      ZVAL null
                    BINARY_OP [16]
                      CAST [5]
                        VAR
                          ZVAL "operand#1"
                      CAST [5]
                        VAR
                          ZVAL "operand#2"
        "#}
    );
}

/// ```php
/// $b = \strcmp($text, "9") < 0; $b = \strcmp($text, $other) >= 0; $b = $total < 9;
/// ```
///
/// PHP's `<` compares two numeric strings as numbers, so `"10" < "9"` is false. PHP# orders two strings by their
/// bytes, which is the sign of `\strcmp`. Numbers keep PHP's `<`.
#[test]
fn string_ordering_is_strcmp_compared_with_zero() {
    assert_eq!(
        body_in(
            "int run(string text, string other, int total)",
            "        let b = text < \"9\";\n        b = text >= other;\n        b = total < 9;\n        return 1;\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "b"
                BINARY_OP [20]
                  CALL
                    ZVAL "strcmp"
                    ARG_LIST
                      VAR
                        ZVAL "text"
                      ZVAL "9"
                  ZVAL 0
              ASSIGN
                VAR
                  ZVAL "b"
                GREATER_EQUAL
                  CALL
                    ZVAL "strcmp"
                    ARG_LIST
                      VAR
                        ZVAL "text"
                      VAR
                        ZVAL "other"
                  ZVAL 0
              ASSIGN
                VAR
                  ZVAL "b"
                BINARY_OP [20]
                  VAR
                    ZVAL "total"
                  ZVAL 9
              RETURN
                ZVAL 1
        "#}
    );
}

/// ```php
/// return match (true) {
///     (${'match#1'} = $this->label()) === "01" => 1,
///     \strcmp(${'match#1'}, "m") < 0 => 2,
///     default => 3,
/// };
/// ```
///
/// A comparison pattern on a string compares as `==` and `<` do outside a pattern. The second arm reads the hidden
/// variable, a node no source writes.
#[test]
fn a_string_comparison_pattern_compares_strictly_and_orders_by_strcmp() {
    assert_eq!(
        child_body(
            RUN,
            "        return match (this.label()) {\n            == \"01\" => 1,\n            < \"m\" => 2,\n            default => 3,\n        };\n",
            "<?php namespace App\\Tenant; class Base { public function label(): string { return ''; } }",
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                MATCH
                  ZVAL true
                  MATCH_ARM_LIST
                    MATCH_ARM
                      EXPR_LIST
                        BINARY_OP [16]
                          ASSIGN
                            VAR
                              ZVAL "match#1"
                            METHOD_CALL
                              VAR
                                ZVAL "this"
                              ZVAL "label"
                              ARG_LIST
                          ZVAL "01"
                      ZVAL 1
                    MATCH_ARM
                      EXPR_LIST
                        BINARY_OP [20]
                          CALL
                            ZVAL "strcmp"
                            ARG_LIST
                              VAR
                                ZVAL "match#1"
                              ZVAL "m"
                          ZVAL 0
                      ZVAL 2
                    MATCH_ARM
                      null
                      ZVAL 3
        "#}
    );
}

/// ```php
/// return $a && $a || !$a;
/// ```
///
/// `[14]` is `ZEND_BOOL_NOT`.
#[test]
fn logical_operators_are_and_or_and_bool_not() {
    assert_eq!(
        body_in("bool run(int extra)", "        let a = true;\n        return a && a || !a;\n", &[]),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                ZVAL true
              RETURN
                OR
                  AND
                    VAR
                      ZVAL "a"
                    VAR
                      ZVAL "a"
                  UNARY_OP [14]
                    VAR
                      ZVAL "a"
        "#}
    );
}

/// ```php
/// -$a; +$a; ++$a; --$a; $a++; $a--;
/// ```
#[test]
fn unary_operators_are_the_kinds_php_gives_them() {
    let tree = body(
        "        let a = 1;\n        -a;\n        +a;\n        ++a;\n        --a;\n        a++;\n        a--;\n        return a;\n",
    );
    let operators: Vec<&str> = tree.lines().filter(|line| line.starts_with("  ") && !line.starts_with("   ")).collect();

    assert_eq!(
        operators,
        ["  ASSIGN", "  UNARY_MINUS", "  UNARY_PLUS", "  PRE_INC", "  PRE_DEC", "  POST_INC", "  POST_DEC", "  RETURN"]
    );
}

/// ```php
/// $a -= 1; $a *= 2; $a = \intdiv($a, 3); $a **= 4;
/// ```
///
/// `[2]`, `[3]` and `[12]` are `ZEND_SUB`, `ZEND_MUL` and `ZEND_POW`. `/=` on an int assigns the `\intdiv` quotient.
#[test]
fn compound_assignments_are_assign_ops() {
    let tree = body(
        "        let a = 1;\n        a -= 1;\n        a *= 2;\n        a /= 3;\n        a **= 4;\n        return a;\n",
    );
    let operators: Vec<&str> = tree.lines().filter(|line| line.starts_with("  ") && !line.starts_with("   ")).collect();

    assert_eq!(
        operators,
        ["  ASSIGN", "  ASSIGN_OP [2]", "  ASSIGN_OP [3]", "  ASSIGN", "  ASSIGN_OP [12]", "  RETURN"]
    );
}

/// ```php
/// $b = $extra | $extra; $b = $extra & $extra; $b = $extra ^ $extra; $b = $extra << $extra; $b = $extra >> $extra;
/// $b = ~$extra;
/// ```
///
/// `[9]`, `[10]`, `[11]`, `[6]` and `[7]` are `ZEND_BW_OR`, `ZEND_BW_AND`, `ZEND_BW_XOR`, `ZEND_SL` and `ZEND_SR`, and
/// `[13]` is `ZEND_BW_NOT`, in php-src's `Zend/zend_vm_opcodes.h`. PHP throws `ArithmeticError` for a negative shift
/// count, and `<<` drops the bits it shifts out, as spec section 19 has them.
#[test]
fn bitwise_operators_are_the_binary_and_unary_ops_php_gives_them() {
    let tree = body(
        "        let b = extra | extra;\n        b = extra & extra;\n        b = extra ^ extra;\n        b = extra << extra;\n        b = extra >> extra;\n        b = ~extra;\n        return b;\n",
    );

    assert_eq!(
        assigned_values(&tree),
        ["BINARY_OP [9]", "BINARY_OP [10]", "BINARY_OP [11]", "BINARY_OP [6]", "BINARY_OP [7]", "UNARY_OP [13]"]
    );
}

/// ```php
/// $a |= 1; $a &= 2; $a ^= 4; $a <<= 1; $a >>= 1; $a %= 3;
/// ```
///
/// Each compound form applies the opcode of its operator: `[9]`, `[10]`, `[11]`, `[6]`, `[7]` and `[5]` are
/// `ZEND_BW_OR`, `ZEND_BW_AND`, `ZEND_BW_XOR`, `ZEND_SL`, `ZEND_SR` and `ZEND_MOD`.
#[test]
fn bitwise_and_modulo_compound_assignments_are_assign_ops() {
    let tree = body(
        "        let a = extra;\n        a |= 1;\n        a &= 2;\n        a ^= 4;\n        a <<= 1;\n        a >>= 1;\n        a %= 3;\n        return a;\n",
    );
    let operators: Vec<&str> = tree.lines().filter(|line| line.starts_with("  ") && !line.starts_with("   ")).collect();

    assert_eq!(
        operators,
        [
            "  ASSIGN",
            "  ASSIGN_OP [9]",
            "  ASSIGN_OP [10]",
            "  ASSIGN_OP [11]",
            "  ASSIGN_OP [6]",
            "  ASSIGN_OP [7]",
            "  ASSIGN_OP [5]",
            "  RETURN",
        ]
    );
}

/// ```php
/// return ($extra & 2) !== 0 ? 1 : 0;
/// ```
///
/// `&` binds tighter than `!=` in PHP#, so the flag test compares the `[10]` `ZEND_BW_AND` with 0, where PHP's own
/// grammar would read `$extra & (2 != 0)`. `[17]` is `ZEND_IS_NOT_IDENTICAL`.
#[test]
fn a_flag_test_compares_the_bitwise_and_with_zero() {
    assert_eq!(
        body("        return extra & 2 != 0 ? 1 : 0;\n"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL
                  BINARY_OP [17]
                    BINARY_OP [10]
                      VAR
                        ZVAL "extra"
                      ZVAL 2
                    ZVAL 0
                  ZVAL 1
                  ZVAL 0
        "#}
    );
}

/// ```php
/// return -$a ** $a ** 2;
/// ```
///
/// `[12]` is `ZEND_POW`. `**` groups to the right and binds tighter than unary `-`, as php-src's grammar has it.
#[test]
fn exponentiation_is_a_right_grouped_pow_under_unary_minus() {
    assert_eq!(
        body("        return -extra ** extra ** 2;\n"),
        indoc! {r#"
            STMT_LIST
              RETURN
                UNARY_MINUS
                  BINARY_OP [12]
                    VAR
                      ZVAL "extra"
                    BINARY_OP [12]
                      VAR
                        ZVAL "extra"
                      ZVAL 2
        "#}
    );
}

/// ```php
/// return $extra ?? $this->total() ?? 0;
/// ```
///
/// `??` is right-associative, as php-src's grammar declares it.
#[test]
fn null_coalescing_is_coalesce() {
    assert_eq!(
        child_body(
            "int run(int? extra)",
            "        return extra ?? this.total() ?? 0;\n",
            "<?php namespace App\\Tenant; class Base { public function total(): ?int { return null; } }",
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                COALESCE
                  VAR
                    ZVAL "extra"
                  COALESCE
                    METHOD_CALL
                      VAR
                        ZVAL "this"
                      ZVAL "total"
                      ARG_LIST
                    ZVAL 0
        "#}
    );
}

/// ```php
/// return ($extra > 1 ? true : false) ? $extra : ($extra < 0 ? 0 : 1);
/// ```
///
/// A ternary in parentheses carries `ZEND_PARENTHESIZED_CONDITIONAL`, as php-src's grammar marks `'(' expr ')'`, so
/// the engine accepts it as the condition of another ternary.
#[test]
fn the_ternary_is_a_conditional_marked_when_parenthesized() {
    assert_eq!(
        body("        return (extra > 1 ? true : false) ? extra : (extra < 0 ? 0 : 1);\n"),
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL
                  CONDITIONAL [1]
                    GREATER
                      VAR
                        ZVAL "extra"
                      ZVAL 1
                    ZVAL true
                    ZVAL false
                  VAR
                    ZVAL "extra"
                  CONDITIONAL [1]
                    BINARY_OP [20]
                      VAR
                        ZVAL "extra"
                      ZVAL 0
                    ZVAL 0
                    ZVAL 1
        "#}
    );
}

/// ```php
/// $class = $event;
/// return $class + ${'@this'};
/// ```
///
/// A name written with `@`, spec section 2, runs as the PHP variable of its word, so `@event` is `$event`, as a plain PHP
/// parent names its parameter. `@this` keeps its `@`, a variable name PHP code never writes, since PHP forbids `$this`.
#[test]
fn a_name_written_with_at_runs_as_the_variable_of_its_word() {
    assert_eq!(
        body_in(
            "int run(int @event, int @this)",
            "        const @class = @event;\n        return @class + @this;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "class"
                VAR
                  ZVAL "event"
              RETURN
                BINARY_OP [1]
                  VAR
                    ZVAL "class"
                  VAR
                    ZVAL "@this"
        "#}
    );
}

/// ```php
/// ${'@_GET'} = ${'@GLOBALS'};
/// return $this->run(GLOBALS: ${'@_GET'});
/// ```
///
/// A local or a parameter named as one of PHP's superglobals runs as `@` before its name, which PHP code never writes,
/// so it never reads or replaces PHP's, and a named argument reaches it by that name.
#[test]
fn a_local_named_as_a_superglobal_runs_under_a_hidden_name() {
    assert_eq!(
        body_in(
            "int run(int GLOBALS)",
            "        const _GET = GLOBALS;\n        return this.run(GLOBALS: _GET);\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "@_GET"
                VAR
                  ZVAL "@GLOBALS"
              RETURN
                METHOD_CALL
                  VAR
                    ZVAL "this"
                  ZVAL "run"
                  ARG_LIST
                    NAMED_ARG
                      ZVAL "@GLOBALS"
                      VAR
                        ZVAL "@_GET"
        "#}
    );
}

/// ```php
/// $cents = (int)($extra * 1.5); return (string)(float)$cents;
/// ```
///
/// A cast's attr is the type it converts to, `IS_LONG`, `IS_DOUBLE` or `IS_STRING`, as php-src's grammar builds it.
#[test]
fn casts_between_numbers_are_casts_to_their_types() {
    assert_eq!(
        body_in(
            "string run(int extra)",
            "        const cents = (int)(extra * 1.5);\n        return (string)(float)cents;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "cents"
                CAST [4]
                  BINARY_OP [3]
                    VAR
                      ZVAL "extra"
                    ZVAL 1.5
              RETURN
                CAST [6]
                  CAST [5]
                    VAR
                      ZVAL "cents"
        "#}
    );
}

/// ```php
/// $extra ??= 1; $this->count ??= $extra;
/// ```
#[test]
fn null_coalescing_assignment_is_assign_coalesce() {
    assert_eq!(
        child_body(
            "int run(int? extra)",
            "        extra ??= 1;\n        this.count ??= extra;\n        return extra;\n",
            "<?php namespace App\\Tenant; class Base { public ?int $count = null; }",
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN_COALESCE
                VAR
                  ZVAL "extra"
                ZVAL 1
              ASSIGN_COALESCE
                PROP
                  VAR
                    ZVAL "this"
                  ZVAL "count"
                VAR
                  ZVAL "extra"
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// return $base?->total($extra)?->value->cents;
/// ```
#[test]
fn null_safe_calls_and_reads_are_nullsafe_kinds() {
    assert_eq!(
        child_body(
            "int? run(Base? base, int extra)",
            "        return base?.total(extra)?.value.cents;\n",
            "<?php namespace App\\Tenant; final class Money { public int $cents = 0; } final class Total { public Money $value; } class Base { public function total(int $a): ?Total { return null; } }",
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                PROP
                  NULLSAFE_PROP
                    NULLSAFE_METHOD_CALL
                      VAR
                        ZVAL "base"
                      ZVAL "total"
                      ARG_LIST
                        VAR
                          ZVAL "extra"
                    ZVAL "value"
                  ZVAL "cents"
        "#}
    );
}

/// ```php
/// return \is_int(${'match#1'} = $sizes[0]) && \is_int(${'match#1'} = $counts['a'] ?? null);
/// ```
///
/// Spec section 12: a `List` index a pattern tests is a bare read, which throws on a missing index, and a `Map` index
/// reads a missing key as null, as `??` does.
#[test]
fn a_tested_list_index_is_read_bare_and_a_tested_map_key_quietly() {
    assert_eq!(
        body_in(
            "bool run(List<int?> sizes, Map<string, int> counts)",
            "        return sizes[0] is int && counts[\"a\"] is int;\n",
            &[]
        )
        .lines()
        .skip_while(|line| line.trim() != "RETURN")
        .map(str::trim_start)
        .collect::<Vec<_>>(),
        [
            "RETURN",
            "AND",
            "CALL",
            "ZVAL \"is_int\"",
            "ARG_LIST",
            "ASSIGN",
            "VAR",
            "ZVAL \"match#1\"",
            "DIM",
            "VAR",
            "ZVAL \"sizes\"",
            "ZVAL 0",
            "CALL",
            "ZVAL \"is_int\"",
            "ARG_LIST",
            "ASSIGN",
            "VAR",
            "ZVAL \"match#1\"",
            "COALESCE",
            "DIM",
            "VAR",
            "ZVAL \"counts\"",
            "ZVAL \"a\"",
            "ZVAL null",
        ]
    );
}

/// ```php
/// return $extra[0]?->value ?? $extra[1]?->total() ?? ($named['a'] ?? null)?->value;
/// ```
///
/// `?.` reads a missing key of the `Map` index directly before it as null, as `??` does (spec section 12), so that
/// index is the left side of a `COALESCE`. A `List` index is the bare index itself, which throws on a missing index.
#[test]
fn null_safe_access_reads_a_missing_map_key_as_null_and_a_list_index_bare() {
    assert_eq!(
        body_in(
            "int? run(List<Calc?> extra, Map<string, Calc?> named)",
            "        return extra[0]?.value ?? (extra[1])?.total() ?? named[\"a\"]?.value;\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; final class Calc { public int $value = 0; public function total(): int { return 0; } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "named"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "named"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @7-7
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#1"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#2"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#1"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#2"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "named"
                                  VAR
                                    ZVAL "named"
                    ZVAL "string, Lib.Calc?"
                  VAR
                    ZVAL "named"
              RETURN
                COALESCE
                  NULLSAFE_PROP
                    DIM
                      VAR
                        ZVAL "extra"
                      ZVAL 0
                    ZVAL "value"
                  COALESCE
                    NULLSAFE_METHOD_CALL
                      DIM
                        VAR
                          ZVAL "extra"
                        ZVAL 1
                      ZVAL "total"
                      ARG_LIST
                    NULLSAFE_PROP
                      COALESCE
                        DIM
                          VAR
                            ZVAL "named"
                          ZVAL "a"
                        ZVAL null
                      ZVAL "value"
        "#}
    );
}

/// ```php
/// return ($extra + 1) * 2;
/// ```
#[test]
fn parentheses_only_group() {
    assert_eq!(
        body("        return (extra + 1) * 2;\n"),
        indoc! {r#"
            STMT_LIST
              RETURN
                BINARY_OP [3]
                  BINARY_OP [1]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                  ZVAL 2
        "#}
    );
}

/// ```php
/// {
///     $inner = \Vendor\Pdf\DEFAULT_DPI;
///     $own = LIMIT;
/// }
/// ```
///
/// `Pdf.DEFAULT_DPI` names the library's constant by its full name, `ZEND_NAME_FQ`, which is 0, spec section 23. A
/// bare name is the code's own constant, and `[1]` on its name is `ZEND_NAME_NOT_FQ`: the engine looks it up in the
/// file's namespace.
#[test]
fn a_block_is_a_statement_list_and_a_constant_is_looked_up_by_the_name_it_is_read_by() {
    let limit = ("src/App/Tenant/constants.php", "<?php\n\nnamespace App\\Tenant;\n\nconst LIMIT = 3;\n");
    let pdf = ("src/Vendor/Pdf/constants.php", "<?php namespace Vendor\\Pdf; const DEFAULT_DPI = 300;");

    assert_eq!(
        Lowered::with(
            "namespace App.Tenant;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        {\n            let inner = Pdf.DEFAULT_DPI;\n            let own = LIMIT;\n        }\n        return 1;\n    }\n}\n",
            &[limit, pdf]
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              STMT_LIST
                ASSIGN
                  VAR
                    ZVAL "inner"
                  CONST
                    ZVAL "Vendor\\Pdf\\DEFAULT_DPI"
                ASSIGN
                  VAR
                    ZVAL "own"
                  CONST
                    ZVAL [1] "LIMIT"
              RETURN
                ZVAL 1
        "#}
    );
}

/// ```php
/// if ($extra > 1) {
///     return 1;
/// } else if ($extra < 0) {
///     return 2;
/// } else {
///     return 3;
/// }
/// ```
///
/// php-src reads `else if` as an `else` whose statement is the next `if`. An `else` has a null condition.
#[test]
fn if_else_if_and_else_are_if_lists_of_if_elems() {
    assert_eq!(
        body(
            "        if (extra > 1) {\n            return 1;\n        } else if (extra < 0) {\n            return 2;\n        } else {\n            return 3;\n        }\n"
        ),
        indoc! {r#"
            STMT_LIST
              IF
                IF_ELEM
                  GREATER
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                  STMT_LIST
                    RETURN
                      ZVAL 1
                IF_ELEM
                  null
                  IF
                    IF_ELEM
                      BINARY_OP [20]
                        VAR
                          ZVAL "extra"
                        ZVAL 0
                      STMT_LIST
                        RETURN
                          ZVAL 2
                    IF_ELEM
                      null
                      STMT_LIST
                        RETURN
                          ZVAL 3
        "#}
    );
}

/// ```php
/// while ($extra > 0) {
///     $extra -= 1;
/// }
/// do {
///     $extra += 1;
/// } while ($extra < 3);
/// ```
///
/// `WHILE` takes its condition first, and `DO_WHILE` its body first.
#[test]
fn while_and_do_while_are_their_php_kinds() {
    assert_eq!(
        body(
            "        while (extra > 0) {\n            extra -= 1;\n        }\n        do {\n            extra += 1;\n        } while (extra < 3);\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              WHILE
                GREATER
                  VAR
                    ZVAL "extra"
                  ZVAL 0
                STMT_LIST
                  ASSIGN_OP [2]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
              DO_WHILE
                STMT_LIST
                  ASSIGN_OP [1]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                BINARY_OP [20]
                  VAR
                    ZVAL "extra"
                  ZVAL 3
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// while ($again) {
///     continue;
/// }
/// while (true) {
///     break;
/// }
/// ```
///
/// A `break` or `continue` without a level has a null depth.
#[test]
fn break_and_continue_have_a_null_depth() {
    assert_eq!(
        body_in(
            "int run(bool again)",
            "        while (again) {\n            continue;\n        }\n        while (true) {\n            break;\n        }\n        return 1;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              WHILE
                VAR
                  ZVAL "again"
                STMT_LIST
                  CONTINUE
                    null
              WHILE
                ZVAL true
                STMT_LIST
                  BREAK
                    null
              RETURN
                ZVAL 1
        "#}
    );
}

/// ```php
/// foreach ([1, 2] as $order) {
///     while ($extra > 0) {
///         if ($extra == 1) { continue 2; }
///         if ($extra == 2) { break 2; }
///         if ($extra == 3) { break; }
///         $extra -= 1;
///     }
/// }
/// ```
///
/// Spec section 17: a `break` or `continue` that names a loop leaves as many PHP loops as hold it inside that loop,
/// and that loop, as PHP's level, so naming the innermost loop is a null depth. The name itself lowers to nothing.
#[test]
fn a_named_break_or_continue_has_the_depth_of_the_loop_it_names() {
    assert_eq!(
        body(
            "        orders: for (const order of [1, 2]) {\n            rows: while (extra > 0) {\n                if (extra == 1) { continue orders; }\n                if (extra == 2) { break orders; }\n                if (extra == 3) { break rows; }\n                extra -= 1;\n            }\n        }\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              FOREACH
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL 1
                    null
                  ARRAY_ELEM
                    ZVAL 2
                    null
                VAR
                  ZVAL "order"
                null
                STMT_LIST
                  WHILE
                    GREATER
                      VAR
                        ZVAL "extra"
                      ZVAL 0
                    STMT_LIST
                      IF
                        IF_ELEM
                          BINARY_OP [16]
                            VAR
                              ZVAL "extra"
                            ZVAL 1
                          STMT_LIST
                            CONTINUE
                              ZVAL 2
                      IF
                        IF_ELEM
                          BINARY_OP [16]
                            VAR
                              ZVAL "extra"
                            ZVAL 2
                          STMT_LIST
                            BREAK
                              ZVAL 2
                      IF
                        IF_ELEM
                          BINARY_OP [16]
                            VAR
                              ZVAL "extra"
                            ZVAL 3
                          STMT_LIST
                            BREAK
                              null
                      ASSIGN_OP [2]
                        VAR
                          ZVAL "extra"
                        ZVAL 1
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// for ($step = 0; $step < $extra; $step++, $extra--) {
/// }
/// for (;;) {
///     break;
/// }
/// ```
///
/// Each part of the header is an `EXPR_LIST`, or null when it is empty. A `let` counter is the assignment of its
/// value.
#[test]
fn for_loops_are_for_nodes_with_an_expression_list_per_part() {
    assert_eq!(
        body(
            "        for (let step = 0; step < extra; step++, extra--) {\n        }\n        for (;;) {\n            break;\n        }\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              FOR
                EXPR_LIST
                  ASSIGN
                    VAR
                      ZVAL "step"
                    ZVAL 0
                EXPR_LIST
                  BINARY_OP [20]
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "extra"
                EXPR_LIST
                  POST_INC
                    VAR
                      ZVAL "step"
                  POST_DEC
                    VAR
                      ZVAL "extra"
                STMT_LIST
              FOR
                null
                null
                null
                STMT_LIST
                  BREAK
                    null
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// A typed counter lowers as a `let` counter does: its type only tells the checker the counter's type.
///
/// ```php
/// for ($step = 0; $step < $extra; ) {
/// }
/// ```
#[test]
fn a_typed_for_counter_is_the_assignment_of_its_value() {
    assert_eq!(
        body("        for (int step = 0; step < extra; ) {\n        }\n        return extra;\n"),
        indoc! {r#"
            STMT_LIST
              FOR
                EXPR_LIST
                  ASSIGN
                    VAR
                      ZVAL "step"
                    ZVAL 0
                EXPR_LIST
                  BINARY_OP [20]
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "extra"
                null
                STMT_LIST
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// foreach (<check Map<int|string, int>>(\Lib\Calc::make(2)) as $key#1 => $value#2) {
///     $entry = [$key#1, $value#2];
///     $extra += $entry[1];
/// }
/// foreach (<check Map<int|string, int>>(\Lib\Calc::make(3)) as $key => $value) {
/// }
/// ```
///
/// `FOREACH` takes the collection, the value variable, the key variable or null, and the body. The map a plain PHP
/// docblock claims is checked entry by entry first, and one loop variable over it is each entry.
#[test]
fn for_of_loops_are_foreach_nodes_with_the_value_before_the_key() {
    assert_eq!(
        body_in(
            RUN,
            "        for (const entry of Calc.make(2)) {\n            extra += entry[1];\n        }\n        for (let [key, value] of Calc.make(3)) {\n        }\n        return extra;\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; final class Calc { /** @return array<int|string, int> */ public static function make(int $n): array { return [$n => $n]; } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              FOREACH
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "make"
                    ARG_LIST
                      ZVAL 2
                  ZVAL "Map<int|string, int>"
                  ZVAL "Lib\\Calc::make()"
                VAR
                  ZVAL "value#2"
                VAR
                  ZVAL "key#1"
                STMT_LIST
                  ASSIGN
                    VAR
                      ZVAL "entry"
                    ARRAY [3]
                      ARRAY_ELEM
                        VAR
                          ZVAL "key#1"
                        null
                      ARRAY_ELEM
                        VAR
                          ZVAL "value#2"
                        null
                  STMT_LIST
                    ASSIGN_OP [1]
                      VAR
                        ZVAL "extra"
                      DIM
                        VAR
                          ZVAL "entry"
                        ZVAL 1
              FOREACH
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "make"
                    ARG_LIST
                      ZVAL 3
                  ZVAL "Map<int|string, int>"
                  ZVAL "Lib\\Calc::make()"
                VAR
                  ZVAL "value"
                VAR
                  ZVAL "key"
                STMT_LIST
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// return \Sharp\Internal\containsKey(\is_array($crossing#1 = \Lib\Calc::prices()) ? \Sharp\Map::from($crossing#1)
///     : $crossing#1, 5)
///     && (($nullsafe#1 = \Lib\Calc::maybe()) === null ? null
///         : \Sharp\Internal\containsKey(\is_array($crossing#2 = $nullsafe#1) ? … : $crossing#2, 5)) == true;
/// ```
///
/// Spec section 12: a plain PHP array a `Map` member reads becomes the `\Sharp\Map` first, as it does where a typed
/// local holds it, null-safe or not, so the member runs on the `Map` and a key keeps its type.
#[test]
fn a_plain_php_array_becomes_the_map_a_map_method_reads() {
    assert_eq!(
        body_in(
            "bool run()",
            "        return Calc.prices().has(5) && Calc.maybe()?.has(5) == true;\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib;\nfinal class Calc { /** @return array<array-key, int> */ public static function prices(): array { return []; } /** @return array<array-key, int>|null */ public static function maybe(): ?array { return null; } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                AND
                  CALL
                    ZVAL "Sharp\\Internal\\containsKey"
                    ARG_LIST
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            ASSIGN
                              VAR
                                ZVAL "crossing#1"
                              STATIC_CALL
                                ZVAL "Lib\\Calc"
                                ZVAL "prices"
                                ARG_LIST
                        STATIC_CALL
                          ZVAL "Sharp\\Map"
                          ZVAL "from"
                          ARG_LIST
                            VAR
                              ZVAL "crossing#1"
                        VAR
                          ZVAL "crossing#1"
                      ZVAL 5
                  BINARY_OP [16]
                    CONDITIONAL [1]
                      BINARY_OP [16]
                        ASSIGN
                          VAR
                            ZVAL "nullsafe#1"
                          STATIC_CALL
                            ZVAL "Lib\\Calc"
                            ZVAL "maybe"
                            ARG_LIST
                        ZVAL null
                      ZVAL null
                      CALL
                        ZVAL "Sharp\\Internal\\containsKey"
                        ARG_LIST
                          CONDITIONAL
                            CALL
                              ZVAL "is_array"
                              ARG_LIST
                                ASSIGN
                                  VAR
                                    ZVAL "crossing#2"
                                  VAR
                                    ZVAL "nullsafe#1"
                            STATIC_CALL
                              ZVAL "Sharp\\Map"
                              ZVAL "from"
                              ARG_LIST
                                VAR
                                  ZVAL "crossing#2"
                            VAR
                              ZVAL "crossing#2"
                          ZVAL 5
                    ZVAL true
        "#}
    );
}

/// ```php
/// foreach (\is_array($crossing#1 = \Lib\Calc::prices()) ? new \Sharp\Map(…(string) $key#2…) : $crossing#1
///     as $sku => $count) {}
/// foreach (\Lib\Calc::counts() as $id => $count) {}
/// ```
///
/// Spec section 12: PHP holds an all-digit `string` key as an `int`, so a loop over a plain PHP array keyed by `string`
/// runs over the `\Sharp\Map` that takes each key back as its `string`. One keyed by `int|string` keeps its keys.
#[test]
fn a_loop_over_a_plain_php_array_keyed_by_string_takes_its_keys_back() {
    assert_eq!(
        body_in(
            "void run()",
            "        for (const [sku, count] of Calc.prices()) {\n        }\n        for (const [id, count] of Calc.counts()) {\n        }\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib;\nfinal class Calc { /** @return array<string, int> */ public static function prices(): array { return []; } /** @return array<array-key, int> */ public static function counts(): array { return []; } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              FOREACH
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "crossing#1"
                        VERIFY_TYPE_ARGS
                          STATIC_CALL
                            ZVAL "Lib\\Calc"
                            ZVAL "prices"
                            ARG_LIST
                          ZVAL "Map<string, int>"
                          ZVAL "Lib\\Calc::prices()"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @9-9
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#2"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#3"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#2"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#3"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "crossing#1"
                                  VAR
                                    ZVAL "crossing#1"
                    ZVAL "string, int"
                  VAR
                    ZVAL "crossing#1"
                VAR
                  ZVAL "count"
                VAR
                  ZVAL "sku"
                STMT_LIST
              FOREACH
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "counts"
                  ARG_LIST
                VAR
                  ZVAL "count"
                VAR
                  ZVAL "id"
                STMT_LIST
        "#}
    );
}

/// ```php
/// $names = \VERIFY_TYPE_ARGS(\Lib\Calc::lazy(), 'Iterable<string>', 'Lib\Calc::lazy()');
/// return Report::tally(\VERIFY_TYPE_ARGS(\Lib\Calc::lazy(), …)) + \Lib\Calc::lazy()->count();
/// ```
///
/// Spec section 12: a lazy plain PHP source is checked element by element as it is read. A call that gives an object
/// of a plain PHP class that is a `Traversable`, as a generator or Laravel's `LazyCollection`, is checked in a
/// `VERIFY_TYPE_ARGS` of the place's type where an `Iterable<T>` holds it, a local or a PHP# parameter, which puts a
/// checking `Sequence` in its place. The engine checks the arguments of a call from plain PHP only, so a call from
/// PHP# checks the one it passes. Until then the value keeps its own class, so a call of its own `count` takes no check.
#[test]
fn a_lazy_plain_php_source_is_checked_where_an_iterable_holds_it() {
    assert_eq!(
        body_in(
            "int run()",
            "        Iterable<string> names = Calc.lazy();\n        return Report.tally(Calc.lazy()) + Calc.lazy().count();\n    }\n\n    private static int tally(Iterable<string> names)\n    {\n        return 0;\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib;\n/**\n * @template TKey of array-key\n * @template TValue\n * @implements \\IteratorAggregate<TKey, TValue>\n */\nfinal class Lazy implements \\IteratorAggregate { public function getIterator(): \\Generator { yield 'a'; } public function count(): int { return 1; } }\nfinal class Calc { /** @return Lazy<int, string> */ public static function lazy(): Lazy { return new Lazy(); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "names"
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "lazy"
                    ARG_LIST
                  ZVAL "Iterable<string>"
                  ZVAL "Lib\\Calc::lazy()"
              RETURN
                BINARY_OP [1]
                  STATIC_CALL
                    ZVAL "App\\Tenant\\Report"
                    ZVAL "tally"
                    ARG_LIST
                      VERIFY_TYPE_ARGS
                        STATIC_CALL
                          ZVAL "Lib\\Calc"
                          ZVAL "lazy"
                          ARG_LIST
                        ZVAL "Iterable<string>"
                        ZVAL "Lib\\Calc::lazy()"
                  METHOD_CALL
                    STATIC_CALL
                      ZVAL "Lib\\Calc"
                      ZVAL "lazy"
                      ARG_LIST
                    ZVAL "count"
                    ARG_LIST
        "#}
    );
}

/// ```php
/// $pair = [1, 'a']; [$count, $label] = $pair;
/// ```
///
/// Spec section 30: a tuple is a PHP list while the code runs, so a tuple literal is a list literal, and unpacking one
/// is PHP's list assignment, an `ASSIGN` of an `ARRAY` of `ARRAY_ELEM`s, as php-src's grammar builds `[$a, $b] = $c`.
#[test]
fn an_unpacked_tuple_is_a_list_assignment() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public void run()\n    {\n        [int, string] pair = [1, \"a\"];\n        const [count, label] = pair;\n    }\n}\n",
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "pair"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL 1
                    null
                  ARRAY_ELEM
                    ZVAL "a"
                    null
              ASSIGN
                ARRAY [3]
                  ARRAY_ELEM
                    VAR
                      ZVAL "count"
                    null
                  ARRAY_ELEM
                    VAR
                      ZVAL "label"
                    null
                VAR
                  ZVAL "pair"
        "#}
    );
}

/// ```php
/// foreach ($plans as $key#1 => $value#2) { $entry = [$key#1, $value#2]; }
/// foreach ($rows as [$name, $count]) { }
/// foreach ($plans as $name => $plan) { }
/// ```
///
/// Spec sections 17 and 30: a loop variable is each element, and a `Map`'s element is its entry, so one variable over a
/// `Map` is the tuple of each key and value, which a `Sharp\Map` and a PHP array both give a `foreach` of both. `[a, b]`
/// unpacks each two-element tuple of any other collection, as PHP's `foreach ($rows as [$a, $b])` does, and reads a
/// `Map`'s key and value.
#[test]
fn a_loop_over_a_map_reads_each_entry_and_a_loop_unpacks_each_tuple() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public void run(Map<string, int> plans, List<[string, int]> rows)\n    {\n        for (const entry of plans) {\n        }\n        for (const [name, count] of rows) {\n        }\n        for (const [name, plan] of plans) {\n        }\n    }\n}\n",
    );

    // The class's generated `parse` loops over the fields after them.
    let loops: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_FOREACH)
        .map(|(index, _)| lowered.render(index as u32))
        .take(3)
        .collect();

    assert_eq!(
        loops,
        [
            indoc! {r#"
                FOREACH
                  VAR
                    ZVAL "plans"
                  VAR
                    ZVAL "value#2"
                  VAR
                    ZVAL "key#1"
                  STMT_LIST
                    ASSIGN
                      VAR
                        ZVAL "entry"
                      ARRAY [3]
                        ARRAY_ELEM
                          VAR
                            ZVAL "key#1"
                          null
                        ARRAY_ELEM
                          VAR
                            ZVAL "value#2"
                          null
                    STMT_LIST
            "#},
            indoc! {r#"
                FOREACH
                  VAR
                    ZVAL "rows"
                  ARRAY [3]
                    ARRAY_ELEM
                      VAR
                        ZVAL "name"
                      null
                    ARRAY_ELEM
                      VAR
                        ZVAL "count"
                      null
                  null
                  STMT_LIST
            "#},
            indoc! {r#"
                FOREACH
                  VAR
                    ZVAL "plans"
                  VAR
                    ZVAL "plan"
                  VAR
                    ZVAL "name"
                  STMT_LIST
            "#},
        ]
    );
}

/// ```php
/// $entries = $entries instanceof \Sharp\Map ? \Sharp\Sequence::from($entries) : $entries;
/// yield from \Sharp\Sequence::from($plans);
/// return \Sharp\Sequence::from($plans);
/// $kept = \Sharp\Sequence::from($plans);
/// ```
///
/// Spec section 12: a `Map<TKey, TValue>` is an `Iterable<[TKey, TValue]>` of its entries, so a `Map` that lands in an
/// `Iterable` place, a local, a return or `yield ...`, is the `Sequence` that reads its entries. A parameter takes any
/// caller's `Map` the same way before the body runs.
#[test]
fn a_map_that_lands_in_an_iterable_gives_its_entries() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public int count(Iterable<[string, int]> entries) { return 1; }\n\n    public Iterable<[string, int]> all(Map<string, int> plans) { yield ...plans; }\n\n    public Iterable<[string, int]> some(Map<string, int> plans) { return plans; }\n\n    public void run(Map<string, int> plans)\n    {\n        Iterable<[string, int]> kept = plans;\n    }\n}\n",
    );

    assert_eq!(
        lowered.body_of("count"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "entries"
                CONDITIONAL
                  INSTANCEOF
                    VAR
                      ZVAL "entries"
                    ZVAL "Sharp\\Map"
                  STATIC_CALL
                    ZVAL "Sharp\\Sequence"
                    ZVAL "from"
                    ARG_LIST
                      VAR
                        ZVAL "entries"
                  VAR
                    ZVAL "entries"
              RETURN
                ZVAL 1
        "#}
    );
    // Each body first makes the object of a PHP array plain PHP passes as `plans`, and then a statement takes the
    // entries as its first child: the loop `yield ...` runs as, the `return` and the assignment.
    let entries = concat!(
        "    STATIC_CALL\n",
        "      ZVAL \"Sharp\\\\Sequence\"\n",
        "      ZVAL \"from\"\n",
        "      ARG_LIST\n",
        "        VAR\n",
        "          ZVAL \"plans\"\n",
    );
    for (method, statement) in
        [("all", "  FOREACH\n"), ("some", "  RETURN\n"), ("run", "  ASSIGN\n    VAR\n      ZVAL \"kept\"\n")]
    {
        let body = lowered.body_of(method);

        assert!(body.contains(&format!("{statement}{entries}")), "{method}:\n{body}");
    }
}

/// ```php
/// return $summary[1] . $pair[0];
/// ```
///
/// Spec section 30: a named element of a tuple, which runs as a PHP list, is the index read of its position, and an
/// index read of a tuple is one already.
#[test]
fn a_named_tuple_element_is_an_index_read_of_its_position() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Report\n{\n    public string run([int total, string label] summary, [string, int] pair)\n    {\n        return summary.label + pair[0];\n    }\n}\n",
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                BINARY_OP [8]
                  DIM
                    VAR
                      ZVAL "summary"
                    ZVAL 1
                  DIM
                    VAR
                      ZVAL "pair"
                    ZVAL 0
        "#}
    );
}

/// ```php
/// foreach ($pending as $element#1) { yield $element#1; } yield $latest; yield fn(int $x) => $x; return;
/// ```
///
/// `yield value;` is a `YIELD` of its value and a null key, alone as a statement, as php-src's grammar builds
/// `yield $value;`. `yield ...other;` is a loop that yields each element of `other`, so each takes the generator's
/// next automatic key, where PHP's `yield from` would give the keys of `other`. `yield (int x) => x;` yields a lambda,
/// because `=>` is the lambda arrow in PHP#.
#[test]
fn yield_is_a_yield_statement_and_yield_spread_is_a_loop_that_yields_each_element() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass OrderImport\n{\n    public Iterable<Any> run(List<int> pending, int latest)\n    {\n        yield ...pending;\n        yield latest;\n        yield (int x) => x;\n        return;\n    }\n}\n",
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              FOREACH
                VAR
                  ZVAL "pending"
                VAR
                  ZVAL "element#1"
                null
                STMT_LIST
                  YIELD
                    VAR
                      ZVAL "element#1"
                    null
              YIELD
                VAR
                  ZVAL "latest"
                null
              YIELD
                ARROW_FUNC "" @9-9
                  PARAM_LIST
                    PARAM
                      ZVAL [1] "int"
                      ZVAL "x"
                      null
                      null
                      null
                      null
                  null
                  VAR
                    ZVAL "x"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int(int)>"
                  null
                null
              RETURN
                null
        "#}
    );
}

/// A method that yields is a generator: `[16777217]` is `ZEND_ACC_PUBLIC | ZEND_ACC_GENERATOR`, which php-src's grammar
/// puts on a function whose body holds a `yield`, so the engine compiles it to start with `GENERATOR_CREATE`. A yield
/// nested in a loop or an `if` counts, and a method that returns an `Iterable<T>` without a yield stays `[1]`.
#[test]
fn a_method_that_yields_is_a_generator() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass OrderImport\n{\n    public Iterable<int> lines(List<int> rows)\n    {\n        for (const row of rows) {\n            if (row > 0) {\n                yield row;\n            }\n        }\n    }\n\n    public Iterable<int> all(List<int> rows)\n    {\n        yield ...rows;\n    }\n\n    public Iterable<int> kept(List<int> rows)\n    {\n        return rows;\n    }\n}\n",
    );

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    let methods: Vec<String> = lowered
        .nodes()
        .iter()
        .filter(|node| node.kind == sharp_kind::SHARP_AST_METHOD)
        .map(|node| format!("{} [{}]", lowered.text(node.text), node.attr))
        .collect();
    assert_eq!(methods, ["lines [16777217]", "all [16777217]", "kept [1]", "parse [17]", "tryParse [17]"]);
}

/// A function whose result can hold a `Map` or a `Set`, at any depth, as `Any`, a type parameter or an `Iterable` can,
/// carries `ZEND_SHARP_RESULT_CROSSES`, `1`, as the attr of its result's type, so each of its returns and yields emits
/// the `ZEND_SHARP_RETURN_ARRAY` that gives a plain PHP caller the PHP array, spec section 12, and its PHP type takes
/// `array` beside the class. A lambda carries it by its result as the analysis gives it. A result of any other type, as
/// `List<int>` or a function, carries none, nor does one that holds a `Map` keyed by a type no PHP array holds, as
/// `List<int>`, which plain PHP gets as the object. A `Map` keyed by `int|string` crosses, and throws when it runs if
/// two of its keys are one PHP array key.
#[test]
fn a_function_whose_result_holds_a_map_or_a_set_gives_plain_php_its_array() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Shelf\n{\n    public Map<string, int> sizes() => [:];\n\n    public Set<string> tags() => [];\n\n    public List<Map<string, int>> rows() => [];\n\n    public List<int> counts() => [];\n\n    public Function<Map<string, int>()> sizer() => () => [:];\n\n    public Any? anything() => null;\n\n    public T held<T>(T value) => value;\n\n    public Iterable<Map<string, int>> streamed(List<Map<string, int>> rows) => rows;\n\n    public Map<int|string, int> mixed() => [:];\n\n    public List<Map<List<int>, int>> listed() => [];\n}\n",
    );

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    let results: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(index, node)| {
            node.kind == sharp_kind::SHARP_AST_METHOD && !lowered.generated().contains(&(*index as u32))
        })
        .map(|(index, node)| {
            let mut result = lowered.child(index as u32, 3);
            let mut crosses = false;
            if lowered
                .nodes()
                .get(result as usize)
                .is_some_and(|node| node.kind == sharp_kind::SHARP_AST_SHARP_TYPE_ARGS)
            {
                crosses = lowered.nodes()[result as usize].attr == 1;
                result = lowered.child(result, 0);
            }
            let php_type = lowered.render(result);
            format!(
                "{} {}: {}",
                lowered.text(node.text),
                crosses,
                php_type.lines().map(str::trim).collect::<Vec<_>>().join(" ")
            )
        })
        .collect();
    assert_eq!(
        results,
        [
            "sizes true: TYPE_UNION ZVAL \"Sharp\\\\Map\" TYPE [7]",
            "tags true: TYPE_UNION ZVAL \"Sharp\\\\Set\" TYPE [7]",
            "rows true: TYPE [7]",
            "counts false: TYPE [7]",
            "sizer false: ZVAL \"Closure\"",
            "anything true: null",
            "held true: null",
            "streamed true: ZVAL [1] \"iterable\"",
            "mixed true: TYPE_UNION ZVAL \"Sharp\\\\Map\" TYPE [7]",
            "listed false: TYPE [7]",
        ]
    );
    // The lambda declares no PHP result type, and its result crosses as a method's does.
    assert!(lowered.body_of("sizer").contains("    SHARP_TYPE_ARGS [1]\n"), "{}", lowered.body_of("sizer"));
}

/// ```php
/// $code = $extra > 0 ? $extra : throw new \App\Tenant\Failure(0);
/// throw new \App\Tenant\Failure($code);
/// ```
///
/// `throw` is an expression, and a `throw` statement is that expression alone.
#[test]
fn throw_is_a_throw_expression() {
    assert_eq!(
        body_in(
            RUN,
            "        let code = extra > 0 ? extra : throw new Failure(0);\n        throw new Failure(code);\n",
            &[(
                "src/App/Tenant/Failure.php",
                "<?php namespace App\\Tenant; final class Failure extends \\Exception { public function __construct(int $code) { parent::__construct('', $code); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "code"
                CONDITIONAL
                  GREATER
                    VAR
                      ZVAL "extra"
                    ZVAL 0
                  VAR
                    ZVAL "extra"
                  THROW
                    NEW
                      ZVAL "App\\Tenant\\Failure"
                      ARG_LIST
                        ZVAL 0
              THROW
                NEW
                  ZVAL "App\\Tenant\\Failure"
                  ARG_LIST
                    VAR
                      ZVAL "code"
        "#}
    );
}

/// ```php
/// try {
///     $extra += 1;
/// } catch (\Lib\Calc | \App\Tenant\Missing $failure) {
///     throw $failure;
/// } catch (\App\Tenant\Broken) {
/// } finally {
///     $extra -= 1;
/// }
/// ```
///
/// `TRY` takes the try block, a `CATCH_LIST` and the finally block or null. Each `CATCH` takes a `NAME_LIST` of
/// classes, the variable's name or null, and its block.
#[test]
fn try_is_a_try_node_with_a_catch_list_and_a_finally_block() {
    assert_eq!(
        body_in(
            RUN,
            "        try {\n            extra += 1;\n        } catch (Calc | Missing failure) {\n            throw failure;\n        } catch (Broken) {\n        } finally {\n            extra -= 1;\n        }\n        return extra;\n",
            &[("src/Lib/Calc.php", "<?php namespace Lib; final class Calc extends \\Exception {}"), common::FAILURES]
        ),
        indoc! {r#"
            STMT_LIST
              TRY
                STMT_LIST
                  ASSIGN_OP [1]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                CATCH_LIST
                  CATCH
                    NAME_LIST
                      ZVAL "Lib\\Calc"
                      ZVAL "App\\Tenant\\Missing"
                    ZVAL "failure"
                    STMT_LIST
                      THROW
                        VAR
                          ZVAL "failure"
                  CATCH
                    NAME_LIST
                      ZVAL "App\\Tenant\\Broken"
                    null
                    STMT_LIST
                STMT_LIST
                  ASSIGN_OP [2]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// try {
/// } finally {
/// }
/// ```
#[test]
fn try_without_a_catch_has_an_empty_catch_list() {
    assert_eq!(
        body("        try {\n        } finally {\n        }\n        return extra;\n"),
        indoc! {r#"
            STMT_LIST
              TRY
                STMT_LIST
                CATCH_LIST
                STMT_LIST
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// `App\Failure`, a generic exception class.
const FAILURE: (&str, &str) = (
    "src/App/Failure.sharp",
    "namespace App;\n\nimport RuntimeException;\n\npublic class Failure<TItem> : RuntimeException\n{\n}\n",
);

/// ```php
/// try {
///     $extra += 1;
/// } catch (\Throwable $caught#1) {
///     if (sharp_is_type($caught#1, 'App.Failure<int>')) {
///         $numbers = $caught#1;
///         { $extra = 1; }
///     } elseif (sharp_is_type($caught#1, 'App.Failure<string>') || $caught#1 instanceof \LogicException) {
///         $texts = $caught#1;
///         { throw $texts; }
///     } elseif ($caught#1 instanceof \Exception) {
///         $extra = 0;
///     } else {
///         throw $caught#1;
///     }
/// } finally {
///     $extra -= 1;
/// }
/// ```
///
/// A `try` with a catch clause of a generic class catches every `Throwable` into a hidden variable, then tests each
/// clause in the order the code writes them, with the `SHARP_IS_TYPE` an `is` of a generic class runs. The first that
/// matches gives its variable the value and runs its block. When none matches, the value is thrown again, so a `try`
/// around this one still catches it.
#[test]
fn a_try_with_a_generic_catch_clause_catches_throwable_and_tests_each_clause_in_order() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App;

        import Exception;
        import LogicException;

        public class Report
        {
            public int run(int extra)
            {
                try {
                    extra += 1;
                } catch (Failure<int> numbers) {
                    extra = 1;
                } catch (Failure<string> | LogicException texts) {
                    throw texts;
                } catch (Exception) {
                    extra = 0;
                } finally {
                    extra -= 1;
                }
                return extra;
            }
        }
    "},
        &[FAILURE],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              TRY
                STMT_LIST
                  ASSIGN_OP [1]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                CATCH_LIST
                  CATCH
                    NAME_LIST
                      ZVAL "Throwable"
                    ZVAL "caught#1"
                    STMT_LIST
                      IF
                        IF_ELEM
                          SHARP_IS_TYPE
                            VAR
                              ZVAL "caught#1"
                            ZVAL "App.Failure<int>"
                          STMT_LIST
                            ASSIGN
                              VAR
                                ZVAL "numbers"
                              VAR
                                ZVAL "caught#1"
                            STMT_LIST
                              ASSIGN
                                VAR
                                  ZVAL "extra"
                                ZVAL 1
                        IF_ELEM
                          OR
                            SHARP_IS_TYPE
                              VAR
                                ZVAL "caught#1"
                              ZVAL "App.Failure<string>"
                            INSTANCEOF
                              VAR
                                ZVAL "caught#1"
                              ZVAL "LogicException"
                          STMT_LIST
                            ASSIGN
                              VAR
                                ZVAL "texts"
                              VAR
                                ZVAL "caught#1"
                            STMT_LIST
                              THROW
                                VAR
                                  ZVAL "texts"
                        IF_ELEM
                          INSTANCEOF
                            VAR
                              ZVAL "caught#1"
                            ZVAL "Exception"
                          STMT_LIST
                            ASSIGN
                              VAR
                                ZVAL "extra"
                              ZVAL 0
                        IF_ELEM
                          null
                          STMT_LIST
                            THROW
                              VAR
                                ZVAL "caught#1"
                STMT_LIST
                  ASSIGN_OP [2]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// A `try` without a catch clause of a generic class lowers as it does in a file that has none, beside a `try` that
/// has one: the choice is made for each `try`.
#[test]
fn a_try_without_a_generic_catch_clause_keeps_its_catch_list_beside_one_with_it() {
    let source = |guarded: &str| {
        format!(
            "namespace App;\n\nimport Exception;\nimport RuntimeException;\n\npublic class Report\n{{\n    public int plain(int extra)\n    {{\n        try {{\n            extra += 1;\n        }} catch (RuntimeException failure) {{\n            throw failure;\n        }} catch (Exception) {{\n        }}\n        return extra;\n    }}\n{guarded}}}\n"
        )
    };
    let guarded = "\n    public int guarded(int extra)\n    {\n        try {\n            extra += 1;\n        } catch (Failure<int>) {\n        }\n        return extra;\n    }\n";
    let alone = Lowered::with(&source(""), &[FAILURE]);

    assert_eq!(Lowered::with(&source(guarded), &[FAILURE]).body_of("plain"), alone.body_of("plain"));
    assert!(alone.body_of("plain").contains("CATCH\n        NAME_LIST\n          ZVAL \"RuntimeException\""));
}

/// A catch clause of a type parameter tests the type argument the method runs with, as `is` does, written as `new`
/// writes a method's type argument.
#[test]
fn a_catch_clause_of_a_type_parameter_tests_its_type_argument() {
    let lowered = Lowered::new(indoc! {"
        namespace App;

        import RuntimeException;

        public class Report
        {
            public int run<TError : RuntimeException>(int extra)
            {
                try {
                    extra += 1;
                } catch (TError) {
                    extra = 0;
                }
                return extra;
            }
        }
    "});

    assert!(
        lowered.body_of("run").contains(
            "IF_ELEM\n              SHARP_IS_TYPE\n                VAR\n                  ZVAL \"caught#1\"\n                ZVAL \"#0\"\n"
        ),
        "{}",
        lowered.body_of("run")
    );
}

/// ```php
/// return \measure(\Vendor\Pdf\render(\pad("x", length: $extra)));
/// ```
///
/// Spec section 23 calls a plain PHP function through its namespace: `Pdf.render(…)` after `import Vendor.Pdf;` a
/// function of that namespace, and `Pdf.measure(…)` and `Pdf.pad(…)` the functions the library declares in PHP's root
/// namespace beside its classes, as Laravel declares `abort()`. Each is a call of the function by its full name, with
/// `ZEND_NAME_FQ`, which is 0.
#[test]
fn a_call_through_a_namespace_is_a_call_of_its_plain_php_function() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        return Pdf.measure(Pdf.render(Pdf.pad(\"x\", length: extra)));\n    }\n}\n",
        &[
            (
                "src/Vendor/Pdf/functions.php",
                "<?php namespace Vendor\\Pdf; function render(string $html): string { return $html; }",
            ),
            (
                "src/Vendor/Pdf/helpers.php",
                "<?php function measure(string $text): int { return strlen($text); } function pad(string $text, int $length): string { return str_pad($text, $length); }",
            ),
            ("src/Vendor/Pdf/Document.php", "<?php namespace Vendor\\Pdf; final class Document {}"),
        ],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  ZVAL "measure"
                  ARG_LIST
                    CALL
                      ZVAL "Vendor\\Pdf\\render"
                      ARG_LIST
                        CALL
                          ZVAL "pad"
                          ARG_LIST
                            ZVAL "x"
                            NAMED_ARG
                              ZVAL "length"
                              VAR
                                ZVAL "extra"
        "#}
    );
}

/// ```php
/// $size = \strlen($text);
/// $decoded = \is_string(${'match#1'} = \Vendor\Pdf\decode($text));
/// $called = \call_user_func(\strlen(...), $text);
/// return \is_string(${'match#1'} = @\iconv("UTF-8", "ASCII", $text));
/// ```
///
/// The standard library reads a built-in's failure from its value, so a call of one whose declared return type holds
/// `false` or `null`, as `iconv`'s `string|false` does, runs without PHP's warning for the same failure. A call of a
/// built-in that cannot fail, as `strlen`, of one that runs a function it is given, as `call_user_func`, and of a plain
/// PHP library's own function keep their warnings.
#[test]
fn a_call_of_a_built_in_that_returns_its_failure_runs_without_its_warning() {
    let lowered = Lowered(common::checked(
        "vendor/heyjordanparker/php-sharp-composer/library/Sharp/Report.sharp",
        "namespace Sharp;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public bool run(string text)\n    {\n        int size = global.strlen(text);\n        bool decoded = Pdf.decode(text) is string;\n        Any? called = global.call_user_func(global.strlen, text);\n        return global.iconv(\"UTF-8\", \"ASCII\", text) is string;\n    }\n}\n",
        &[(
            "src/Vendor/Pdf/functions.php",
            "<?php namespace Vendor\\Pdf; function decode(string $text): string|false { return $text; }",
        )],
        lower,
    ));

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "size"
                CALL
                  ZVAL "strlen"
                  ARG_LIST
                    VAR
                      ZVAL "text"
              ASSIGN
                VAR
                  ZVAL "decoded"
                CALL
                  ZVAL "is_string"
                  ARG_LIST
                    ASSIGN
                      VAR
                        ZVAL "match#1"
                      CALL
                        ZVAL "Vendor\\Pdf\\decode"
                        ARG_LIST
                          VAR
                            ZVAL "text"
              ASSIGN
                VAR
                  ZVAL "called"
                CALL
                  ZVAL "call_user_func"
                  ARG_LIST
                    CALL
                      ZVAL "strlen"
                      CALLABLE_CONVERT
                    VAR
                      ZVAL "text"
              RETURN
                CALL
                  ZVAL "is_string"
                  ARG_LIST
                    ASSIGN
                      VAR
                        ZVAL "match#1"
                      SILENCE
                        CALL
                          ZVAL "iconv"
                          ARG_LIST
                            ZVAL "UTF-8"
                            ZVAL "ASCII"
                            VAR
                              ZVAL "text"
        "#}
    );
}

/// ```php
/// return \Vendor\Pdf\DEFAULT_DPI + \PDF_VERSION;
/// ```
///
/// Spec section 23 reads a plain PHP constant through its namespace, as it calls a function: `Pdf.DEFAULT_DPI` after
/// `import Vendor.Pdf;`, and `Pdf.PDF_VERSION`, the one the library declares in PHP's root namespace beside its classes.
/// Each is a read of the constant by its full name, with `ZEND_NAME_FQ`, which is 0.
#[test]
fn a_read_through_a_namespace_is_a_read_of_its_plain_php_constant() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Vendor.Pdf;\n\nclass Report\n{\n    public int run()\n    {\n        return Pdf.DEFAULT_DPI + Pdf.PDF_VERSION;\n    }\n}\n",
        &[
            ("src/Vendor/Pdf/constants.php", "<?php namespace Vendor\\Pdf; const DEFAULT_DPI = 300;"),
            ("src/Vendor/Pdf/version.php", "<?php const PDF_VERSION = 2;"),
            ("src/Vendor/Pdf/Document.php", "<?php namespace Vendor\\Pdf; final class Document {}"),
        ],
    );

    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                BINARY_OP [1]
                  CONST
                    ZVAL "Vendor\\Pdf\\DEFAULT_DPI"
                  CONST
                    ZVAL "PDF_VERSION"
        "#}
    );
}

/// ```php
/// return \run($extra);
/// ```
///
/// Spec section 4 writes every member as `this.m()` or `Class.m()`, so `Jobs.run(extra)` inside `run` calls the plain
/// PHP function `run` a library declares in PHP's root namespace beside `Vendor\Jobs`'s classes, not the method.
#[test]
fn a_namespace_call_named_like_a_method_of_its_class_is_a_call_of_the_plain_php_function() {
    assert_eq!(
        Lowered::with(
            "namespace App.Tenant;\n\nimport Vendor.Jobs;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        return Jobs.run(extra);\n    }\n}\n",
            &[
                ("src/Vendor/Jobs/run.php", "<?php function run(int $extra): int { return $extra; }"),
                ("src/Vendor/Jobs/Queue.php", "<?php namespace Vendor\\Jobs; final class Queue {}"),
            ]
        )
        .body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                CALL
                  ZVAL "run"
                  ARG_LIST
                    VAR
                      ZVAL "extra"
        "#}
    );
}

/// ```php
/// exit($extra);
/// ```
///
/// PHP 8.4 makes `exit` a function, so `global.exit(…)` is a call of the global function `exit`, named with
/// `ZEND_NAME_FQ`, which is 0, as php-src's grammar builds `exit(…)`. Only the standard library calls it, as
/// `Process.exit` does.
#[test]
fn exit_is_a_call_of_the_global_function_exit() {
    let halt = "namespace Sharp;\n\npublic class Halt\n{\n    public void run(int extra)\n    {\n        global.exit(extra);\n    }\n}\n";

    assert_eq!(
        Lowered::named("vendor/heyjordanparker/php-sharp-composer/library/Sharp/Halt.sharp", halt).body(),
        indoc! {r#"
            STMT_LIST
              CALL
                ZVAL "exit"
                ARG_LIST
                  VAR
                    ZVAL "extra"
        "#}
    );
}

/// ```php
/// $label = "Order {$extra}: " . ($extra + 1) . "!"; $alone = "{$extra}"; $plain = "plain A"; return $extra;
/// ```
///
/// php-src's grammar builds an interpolated string as an `ENCAPS_LIST` of its text and its expressions, and a
/// string without one as a `ZVAL`. A template's `${…}` takes any expression, which `ENCAPS_LIST` compiles as PHP's
/// `{$…}` does.
#[test]
fn a_template_is_an_encaps_list_of_its_text_and_interpolations() {
    assert_eq!(
        body(
            "        const label = `Order ${extra}: ${extra + 1}!`;\n        const alone = `${extra}`;\n        const plain = `plain \\x41`;\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "label"
                ENCAPS_LIST
                  ZVAL "Order "
                  VAR
                    ZVAL "extra"
                  ZVAL ": "
                  BINARY_OP [1]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                  ZVAL "!"
              ASSIGN
                VAR
                  ZVAL "alone"
                ENCAPS_LIST
                  VAR
                    ZVAL "extra"
              ASSIGN
                VAR
                  ZVAL "plain"
                ZVAL "plain A"
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// Spec section 12: plain PHP's `array<int, T>` arrives as a `List<T>`, renumbered where PHP# reads it with
/// `\array_values`, a `List` of `Map`s too. A `Map` place keeps its keys and makes the `Map` of them, an argument of
/// plain PHP takes the array as plain PHP gave it, and a value plain PHP declares a list is one already.
#[test]
fn a_plain_php_int_keyed_array_is_renumbered_where_it_arrives() {
    let ids = (
        "src/App/Tenant/Ids.php",
        "<?php namespace App\\Tenant; final class Ids { /** @return array<int, int> */ public static function all(): array { return [5 => 1]; } /** @return list<int> */ public static function listed(): array { return [1]; } /** @return array<int, array<string, int>> */ public static function rows(): array { return []; } public static function sum(array $values): int { return array_sum($values); } }",
    );
    let lowered = |statements: &str| body_in(RUN, statements, &[ids]);

    assert!(lowered("        List<int> all = Ids.all();\n        return all[0];\n").contains("ZVAL \"array_values\""));
    assert!(
        lowered("        List<Map<string, int>> rows = Ids.rows();\n        return rows.count();\n")
            .contains("ZVAL \"array_values\"")
    );
    assert!(
        !lowered("        Map<int, int> byId = Ids.all();\n        return byId.count();\n")
            .contains("ZVAL \"array_values\"")
    );
    assert!(!lowered("        return Ids.sum(Ids.all());\n").contains("ZVAL \"array_values\""));
    assert!(
        !lowered("        List<int> listed = Ids.listed();\n        return listed[0];\n")
            .contains("ZVAL \"array_values\"")
    );
}

/// ```php
/// [$users->names = \is_array($renumbered#1 = $users->names) ? \array_values($renumbered#1) : $renumbered#1,
///     \Sharp\Internal\add($users->names, 'cy')][1];
/// [$receiver#1 = \App\Tenant\Users::make(), $receiver#1->names = …, \Sharp\Internal\add($receiver#1->names, 'x')][2];
/// $users->names = ['p', 'q'];
/// ```
///
/// Spec section 12: a plain PHP property PHP# reads as a `List` is a `List` everywhere, writes included. A change in
/// place sets the renumbered list back first and then changes the property, through a method that changes the list, an
/// index and `++`, whose object runs once. A write of the whole property sets it, and a method that reads the list
/// reads it renumbered.
#[test]
fn a_write_through_a_plain_php_property_read_as_a_list_changes_it_renumbered() {
    let users = (
        "src/App/Tenant/Users.php",
        "<?php namespace App\\Tenant; class Users { /** @var array<int, string> */ public array $names = []; /** @var array<int, int> */ public array $scores = []; /** @var array<int, string> */ public static array $tags = []; /** @var array<int, string>|null */ public ?array $aliases = null; public static function make(): Users { return new Users(); } }",
    );
    let lowered = |statements: &str| body_in("int run(Users users)", statements, &[users]);

    assert_eq!(
        lowered("        users.names.add(\"cy\");\n        return 1;\n"),
        indoc! {r#"
            STMT_LIST
              DIM
                ARRAY [3]
                  ARRAY_ELEM
                    ASSIGN
                      PROP
                        VAR
                          ZVAL "users"
                        ZVAL "names"
                      CONDITIONAL
                        CALL
                          ZVAL "is_array"
                          ARG_LIST
                            ASSIGN
                              VAR
                                ZVAL "renumbered#1"
                              PROP
                                VAR
                                  ZVAL "users"
                                ZVAL "names"
                        CALL
                          ZVAL "array_values"
                          ARG_LIST
                            VAR
                              ZVAL "renumbered#1"
                        VAR
                          ZVAL "renumbered#1"
                    null
                  ARRAY_ELEM
                    CALL
                      ZVAL "Sharp\\Internal\\add"
                      ARG_LIST
                        PROP
                          VAR
                            ZVAL "users"
                          ZVAL "names"
                        ZVAL "cy"
                    null
                ZVAL 1
              RETURN
                ZVAL 1
        "#}
    );
    for (statement, place) in [
        ("users.names.add(\"cy\")", "PROP"),
        ("users.names[0] = \"zed\"", "PROP"),
        ("users.scores[1]++", "PROP"),
        ("users.names.remove(\"ada\")", "PROP"),
        ("Users.tags.add(\"z\")", "STATIC_PROP"),
        ("Users.make().names.add(\"x\")", "PROP"),
        ("users.aliases?.add(\"al\")", "PROP"),
    ] {
        let body = lowered(&format!("        {statement};\n        return 1;\n"));
        assert!(body.starts_with("STMT_LIST\n  DIM\n    ARRAY [3]\n"), "{statement}\n{body}");
        assert!(body.contains(&format!("ASSIGN\n          {place}\n")), "{statement}\n{body}");
        assert!(body.contains("ZVAL \"array_values\""), "{statement}\n{body}");
    }
    assert!(
        lowered("        Users.make().names.add(\"x\");\n        return 1;\n")
            .contains("ASSIGN\n          VAR\n            ZVAL \"receiver#1\"\n          STATIC_CALL\n")
    );
    assert_eq!(
        lowered("        users.names = [\"p\", \"q\"];\n        return 1;\n"),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                PROP
                  VAR
                    ZVAL "users"
                  ZVAL "names"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "p"
                    null
                  ARRAY_ELEM
                    ZVAL "q"
                    null
              RETURN
                ZVAL 1
        "#}
    );
    assert!(
        lowered("        string? first = users.names.getOrNull(0);\n        return 1;\n")
            .contains("CALL\n      ZVAL \"Sharp\\\\Internal\\\\get\"\n      ARG_LIST\n        CONDITIONAL\n")
    );
}

/// Spec section 18 shows an object in a template by what its `toString()` returns, so the part calls it, which an enum
/// case needs, since PHP gives an enum no string conversion.
#[test]
fn an_object_in_a_template_shows_what_its_to_string_returns() {
    assert_eq!(
        body_in(
            "string run(Sku sku)",
            "        return `Sku: ${sku}`;\n",
            &[(
                "src/App/Tenant/Sku.sharp",
                "namespace App.Tenant;\n\nclass Sku\n{\n    public string toString() => \"A-12\";\n}\n"
            )]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                ENCAPS_LIST
                  ZVAL "Sku: "
                  METHOD_CALL
                    VAR
                      ZVAL "sku"
                    ZVAL "toString"
                    ARG_LIST
        "#}
    );
}

/// ```php
/// public function __toString(): string { return $this->toString(); }
/// ```
///
/// Spec section 18: plain PHP converts an object of a class that declares `toString()` to the text it returns, so the
/// class gets PHP's `__toString()`, which calls it.
#[test]
fn a_class_that_declares_to_string_gets_php_s_string_conversion() {
    let conversion = |lines: &str| {
        format!(
            "METHOD [1] \"__toString\" @{lines}\n  PARAM_LIST\n  null\n  STMT_LIST\n    RETURN\n      METHOD_CALL\n        VAR\n          ZVAL \"this\"\n        ZVAL \"toString\"\n        ARG_LIST\n  ZVAL [1] \"string\"\n  null\n"
        )
    };
    assert_eq!(
        Lowered::new("namespace App.Tenant;\n\nclass Sku\n{\n    public string toString() => \"A-12\";\n}\n")
            .declared("__toString"),
        conversion("5-6")
    );

    // A class, or an event, that takes `toString()` from an interface's default body gets it too, from its body's start,
    // and the trait of the body declares none.
    let named = (
        "src/App/Tenant/Named.sharp",
        "namespace App.Tenant;\n\npublic interface Named\n{\n    string toString() => \"named\";\n}\n",
    );
    assert_eq!(
        Lowered::with("namespace App.Tenant;\n\nclass Widget : Named\n{\n}\n", &[named]).declared("__toString"),
        conversion("4-5")
    );
    assert_eq!(
        Lowered::with("namespace App.Tenant;\n\npublic event Shipped(int order) : Named;\n", &[named])
            .declared("__toString"),
        conversion("3-3")
    );
    let interface = Lowered::named("src/App/Tenant/Named.sharp", named.1);
    assert!(!interface.tree().contains("__toString"), "{}", interface.tree());
}

/// ```php
/// return "Paid: {["false", "true"][$paid]} of {$extra} for {$name} {["false", "true"][true]}";
/// ```
///
/// Spec section 18 shows a `bool` in a template as `true` or `false`, where PHP's string conversion gives `1` or
/// nothing, so a `bool` part reads its text from `["false", "true"]`, where PHP reads `false` as the index 0 and
/// `true` as the index 1. The optimizer keeps the read as one `FETCH_DIM_R` of a constant array, where
/// `$paid ? "true" : "false"` takes four instructions. An `int` and a `string` part lower as before.
#[test]
fn a_bool_in_a_template_is_its_text_read_by_the_bool() {
    assert_eq!(
        body_in(
            "string run(bool paid, int extra, string name)",
            "        return `Paid: ${paid} of ${extra} for ${name} ${true}`;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                ENCAPS_LIST
                  ZVAL "Paid: "
                  DIM
                    ARRAY [3]
                      ARRAY_ELEM
                        ZVAL "false"
                        null
                      ARRAY_ELEM
                        ZVAL "true"
                        null
                    VAR
                      ZVAL "paid"
                  ZVAL " of "
                  VAR
                    ZVAL "extra"
                  ZVAL " for "
                  VAR
                    ZVAL "name"
                  ZVAL " "
                  DIM
                    ARRAY [3]
                      ARRAY_ELEM
                        ZVAL "false"
                        null
                      ARRAY_ELEM
                        ZVAL "true"
                        null
                    ZVAL true
        "#}
    );
}

/// ```php
/// $twice = fn (int $a) => $a * $extra; $half = fn ($b) => \intdiv($b, 2); return $twice($half(4));
/// ```
///
/// A lambda that writes none of the locals it captures is PHP's `fn`, which captures by value what its body reads.
/// php-src's grammar gives an arrow function no name, no `use` list and its expression as its body. A call of a local
/// calls the closure the local holds.
#[test]
fn a_lambda_that_writes_no_capture_is_an_arrow_function() {
    assert_eq!(
        body_in(
            RUN,
            "        const twice = (int a) => a * extra;\n        Function<int(int)> half = b => b / 2;\n        return twice(half(4));\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "twice"
                ARROW_FUNC "" @9-9
                  PARAM_LIST
                    PARAM
                      ZVAL [1] "int"
                      ZVAL "a"
                      null
                      null
                      null
                      null
                  null
                  BINARY_OP [3]
                    VAR
                      ZVAL "a"
                    VAR
                      ZVAL "extra"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int(int)>"
                  null
              ASSIGN
                VAR
                  ZVAL "half"
                ARROW_FUNC "" @10-10
                  PARAM_LIST
                    PARAM
                      null
                      ZVAL "b"
                      null
                      null
                      null
                      null
                  null
                  CALL
                    ZVAL "intdiv"
                    ARG_LIST
                      VAR
                        ZVAL "b"
                      ZVAL 2
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int(int)>"
                  null
              RETURN
                CALL
                  VAR
                    ZVAL "twice"
                  ARG_LIST
                    CALL
                      VAR
                        ZVAL "half"
                      ARG_LIST
                        ZVAL 4
        "#}
    );
}

/// ```php
/// $count = 0;
/// $add = function (int $step) use (&$count, $extra) {
///     $count += $step + $extra;
/// };
/// $bump = function () use (&$count) { return $count += 1; };
/// $add(1);
/// return $count;
/// ```
///
/// Spec section 3: a lambda captures the variable itself. A lambda with a block body, or one that writes a local it
/// captures, is PHP's `function` with a `use` list in first-use order, which captures a local that code writes by
/// reference, `ZEND_BIND_REF`, which is 1, and any other by value. An expression body is the `return` of it.
#[test]
fn a_lambda_with_a_block_or_a_written_capture_is_a_closure_with_a_use_list() {
    assert_eq!(
        body(
            "        let count = 0;\n        const add = (int step) => {\n            count += step + extra;\n        };\n        const bump = () => count += 1;\n        add(1);\n        return count;\n"
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "count"
                ZVAL 0
              ASSIGN
                VAR
                  ZVAL "add"
                CLOSURE "" @10-12
                  PARAM_LIST
                    PARAM
                      ZVAL [1] "int"
                      ZVAL "step"
                      null
                      null
                      null
                      null
                  CLOSURE_USES
                    ZVAL [1] "count"
                    ZVAL "extra"
                  STMT_LIST
                    ASSIGN_OP [1]
                      VAR
                        ZVAL "count"
                      BINARY_OP [1]
                        VAR
                          ZVAL "step"
                        VAR
                          ZVAL "extra"
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<void(int)>"
                  null
              ASSIGN
                VAR
                  ZVAL "bump"
                CLOSURE "" @13-13
                  PARAM_LIST
                  CLOSURE_USES
                    ZVAL [1] "count"
                  STMT_LIST
                    RETURN
                      ASSIGN_OP [1]
                        VAR
                          ZVAL "count"
                        ZVAL 1
                  SHARP_TYPE_ARGS
                    null
                    ZVAL "Function<int()>"
                  null
              CALL
                VAR
                  ZVAL "add"
                ARG_LIST
                  ZVAL 1
              RETURN
                VAR
                  ZVAL "count"
        "#}
    );
}

/// ```php
/// foreach ($values as $value#1) { { unset($value); $value = $value#1; } $value += 1; $read = function () use (&$value) { return $value; }; }
/// ```
///
/// Spec sections 3 and 14.2: each loop pass has its own loop variable, and a lambda captures the variable itself. PHP's
/// `foreach` reuses one variable, so a loop variable a lambda captures by reference takes each element through a
/// hidden variable, and is unset before it is assigned, as a captured `let` in a loop body is.
#[test]
fn a_for_of_variable_a_lambda_captures_by_reference_is_fresh_in_each_pass() {
    assert_eq!(
        body_in(
            "void run(List<int> values)",
            "        for (let value of values) {\n            value += 1;\n            const read = () => value;\n        }\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              FOREACH
                VAR
                  ZVAL "values"
                VAR
                  ZVAL "value#1"
                null
                STMT_LIST
                  STMT_LIST
                    STMT_LIST
                      UNSET
                        VAR
                          ZVAL "value"
                    ASSIGN
                      VAR
                        ZVAL "value"
                      VAR
                        ZVAL "value#1"
                  STMT_LIST
                    ASSIGN_OP [1]
                      VAR
                        ZVAL "value"
                      ZVAL 1
                    ASSIGN
                      VAR
                        ZVAL "read"
                      CLOSURE "" @11-11
                        PARAM_LIST
                        CLOSURE_USES
                          ZVAL [1] "value"
                        STMT_LIST
                          RETURN
                            VAR
                              ZVAL "value"
                        SHARP_TYPE_ARGS
                          null
                          ZVAL "Function<int()>"
                        null
        "#}
    );
}

/// ```php
/// for ($step = 0; $step < $extra; $step++) {
///     do { if ($step == 1) { continue; } if ($step == 5) { break 2; } $show = function () use (&$step) { return $step; }; } while (false);
///     $step#1 = $step; unset($step); $step = $step#1;
/// }
/// ```
///
/// Spec sections 3 and 14.2: each pass of `for (let step = …; …; step++)` has its own `step`, which starts as the last
/// pass left it, as JavaScript copies a `let` counter. PHP's increments take expressions and `unset` is a statement, so
/// the body runs inside `do { … } while (false)` and the counter moves into a fresh variable after it: a `continue`
/// leaves the `do` and reaches the move, and a `break` leaves both.
#[test]
fn a_for_counter_a_lambda_captures_by_reference_is_fresh_in_each_pass() {
    assert_eq!(
        body_in(
            "void run(int extra)",
            "        for (let step = 0; step < extra; step++) {\n            if (step == 1) { continue; }\n            if (step == 5) { break; }\n            const show = () => step;\n        }\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              FOR
                EXPR_LIST
                  ASSIGN
                    VAR
                      ZVAL "step"
                    ZVAL 0
                EXPR_LIST
                  BINARY_OP [20]
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "extra"
                EXPR_LIST
                  POST_INC
                    VAR
                      ZVAL "step"
                STMT_LIST
                  DO_WHILE
                    STMT_LIST
                      IF
                        IF_ELEM
                          BINARY_OP [16]
                            VAR
                              ZVAL "step"
                            ZVAL 1
                          STMT_LIST
                            CONTINUE
                              null
                      IF
                        IF_ELEM
                          BINARY_OP [16]
                            VAR
                              ZVAL "step"
                            ZVAL 5
                          STMT_LIST
                            BREAK
                              ZVAL 2
                      ASSIGN
                        VAR
                          ZVAL "show"
                        CLOSURE "" @12-12
                          PARAM_LIST
                          CLOSURE_USES
                            ZVAL [1] "step"
                          STMT_LIST
                            RETURN
                              VAR
                                ZVAL "step"
                          SHARP_TYPE_ARGS
                            null
                            ZVAL "Function<int()>"
                          null
                    ZVAL false
                  ASSIGN
                    VAR
                      ZVAL "step#1"
                    VAR
                      ZVAL "step"
                  STMT_LIST
                    UNSET
                      VAR
                        ZVAL "step"
                  ASSIGN
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "step#1"
        "#}
    );
}

/// ```php
/// for ($step = 0; $step < $extra; $step++) {
///     do { while ($extra > 2) { if ($step == 1) { continue 2; } if ($step == 3) { break 3; } $extra -= 1; } $show = function () use (&$step) { return $step; }; } while (false);
///     $step#1 = $step; unset($step); $step = $step#1;
/// }
/// ```
///
/// A `for` whose counter moves into a fresh variable runs its body in a second PHP loop, so `continue steps;` from a
/// loop inside it leaves that loop and continues the `do`, which reaches the move, and `break steps;` leaves all three.
#[test]
fn a_named_jump_to_a_for_with_a_fresh_counter_reaches_the_counter_move() {
    assert_eq!(
        body_in(
            "void run(int extra)",
            "        steps: for (let step = 0; step < extra; step++) {\n            while (extra > 2) {\n                if (step == 1) { continue steps; }\n                if (step == 3) { break steps; }\n                extra -= 1;\n            }\n            const show = () => step;\n        }\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              FOR
                EXPR_LIST
                  ASSIGN
                    VAR
                      ZVAL "step"
                    ZVAL 0
                EXPR_LIST
                  BINARY_OP [20]
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "extra"
                EXPR_LIST
                  POST_INC
                    VAR
                      ZVAL "step"
                STMT_LIST
                  DO_WHILE
                    STMT_LIST
                      WHILE
                        GREATER
                          VAR
                            ZVAL "extra"
                          ZVAL 2
                        STMT_LIST
                          IF
                            IF_ELEM
                              BINARY_OP [16]
                                VAR
                                  ZVAL "step"
                                ZVAL 1
                              STMT_LIST
                                CONTINUE
                                  ZVAL 2
                          IF
                            IF_ELEM
                              BINARY_OP [16]
                                VAR
                                  ZVAL "step"
                                ZVAL 3
                              STMT_LIST
                                BREAK
                                  ZVAL 3
                          ASSIGN_OP [2]
                            VAR
                              ZVAL "extra"
                            ZVAL 1
                      ASSIGN
                        VAR
                          ZVAL "show"
                        CLOSURE "" @15-15
                          PARAM_LIST
                          CLOSURE_USES
                            ZVAL [1] "step"
                          STMT_LIST
                            RETURN
                              VAR
                                ZVAL "step"
                          SHARP_TYPE_ARGS
                            null
                            ZVAL "Function<int()>"
                          null
                    ZVAL false
                  ASSIGN
                    VAR
                      ZVAL "step#1"
                    VAR
                      ZVAL "step"
                  STMT_LIST
                    UNSET
                      VAR
                        ZVAL "step"
                  ASSIGN
                    VAR
                      ZVAL "step"
                    VAR
                      ZVAL "step#1"
        "#}
    );
}

/// ```php
/// while ($extra > 0) {
///     $extra -= 1;
///     { unset($step); }
///     for ($step = 0; $step < $extra; $step++) {
///         do { if ($step == 1) { continue; } if ($step == 3) { break 2; } $show = function () use (&$step) { return $step; }; } while (false);
///         $step#1 = $step; unset($step); $step = $step#1;
///     }
/// }
/// ```
///
/// A `for` inside a loop gives its captured counter a fresh variable on each pass of the outer loop too, since a
/// `break` leaves the inner loop before the counter moves, and a lambda of that pass keeps it. A header takes only
/// expressions, so the `unset` runs as a statement before the `for`.
#[test]
fn a_for_counter_a_lambda_captures_inside_a_loop_is_unset_before_the_for() {
    assert_eq!(
        body_in(
            "void run(int extra)",
            "        while (extra > 0) {\n            extra -= 1;\n            for (let step = 0; step < extra; step++) {\n                if (step == 1) { continue; }\n                if (step == 3) { break; }\n                const show = () => step;\n            }\n        }\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              WHILE
                GREATER
                  VAR
                    ZVAL "extra"
                  ZVAL 0
                STMT_LIST
                  ASSIGN_OP [2]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
                  STMT_LIST
                    STMT_LIST
                      UNSET
                        VAR
                          ZVAL "step"
                    FOR
                      EXPR_LIST
                        ASSIGN
                          VAR
                            ZVAL "step"
                          ZVAL 0
                      EXPR_LIST
                        BINARY_OP [20]
                          VAR
                            ZVAL "step"
                          VAR
                            ZVAL "extra"
                      EXPR_LIST
                        POST_INC
                          VAR
                            ZVAL "step"
                      STMT_LIST
                        DO_WHILE
                          STMT_LIST
                            IF
                              IF_ELEM
                                BINARY_OP [16]
                                  VAR
                                    ZVAL "step"
                                  ZVAL 1
                                STMT_LIST
                                  CONTINUE
                                    null
                            IF
                              IF_ELEM
                                BINARY_OP [16]
                                  VAR
                                    ZVAL "step"
                                  ZVAL 3
                                STMT_LIST
                                  BREAK
                                    ZVAL 2
                            ASSIGN
                              VAR
                                ZVAL "show"
                              CLOSURE "" @14-14
                                PARAM_LIST
                                CLOSURE_USES
                                  ZVAL [1] "step"
                                STMT_LIST
                                  RETURN
                                    VAR
                                      ZVAL "step"
                                SHARP_TYPE_ARGS
                                  null
                                  ZVAL "Function<int()>"
                                null
                          ZVAL false
                        ASSIGN
                          VAR
                            ZVAL "step#1"
                          VAR
                            ZVAL "step"
                        STMT_LIST
                          UNSET
                            VAR
                              ZVAL "step"
                        ASSIGN
                          VAR
                            ZVAL "step"
                          VAR
                            ZVAL "step#1"
        "#}
    );
}

/// ```php
/// while ($extra > 0) {
///     { unset($seen); $seen = $extra; }
///     $mark = function () use (&$seen) { $seen += 1; };
///     $mark();
///     $extra -= 1;
/// }
/// return $extra;
/// ```
///
/// Spec section 3 gives each loop pass its own `let`. PHP reuses one variable across passes, so a `let` declared in a
/// loop body that a lambda captures by reference is unset before its assignment, and the lambda of each pass keeps
/// its own. php-src's grammar builds `unset($seen);` as a statement list of one `UNSET`.
#[test]
fn a_let_in_a_loop_captured_by_reference_is_unset_before_its_assignment() {
    assert_eq!(
        body(
            "        while (extra > 0) {\n            let seen = extra;\n            const mark = () => {\n                seen += 1;\n            };\n            mark();\n            extra -= 1;\n        }\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              WHILE
                GREATER
                  VAR
                    ZVAL "extra"
                  ZVAL 0
                STMT_LIST
                  STMT_LIST
                    STMT_LIST
                      UNSET
                        VAR
                          ZVAL "seen"
                    ASSIGN
                      VAR
                        ZVAL "seen"
                      VAR
                        ZVAL "extra"
                  ASSIGN
                    VAR
                      ZVAL "mark"
                    CLOSURE "" @11-13
                      PARAM_LIST
                      CLOSURE_USES
                        ZVAL [1] "seen"
                      STMT_LIST
                        ASSIGN_OP [1]
                          VAR
                            ZVAL "seen"
                          ZVAL 1
                      SHARP_TYPE_ARGS
                        null
                        ZVAL "Function<void()>"
                      null
                  CALL
                    VAR
                      ZVAL "mark"
                    ARG_LIST
                  ASSIGN_OP [2]
                    VAR
                      ZVAL "extra"
                    ZVAL 1
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// A `let` the lambda declares in its own body lives in each call's own frame, so it is never unset, even when the
/// lambda sits in a loop.
#[test]
fn a_let_declared_inside_a_lambda_in_a_loop_is_not_unset() {
    let tree = body(
        "        while (extra > 0) {\n            const step = () => {\n                let inner = 1;\n                const again = () => {\n                    inner += 1;\n                };\n                again();\n            };\n            step();\n            extra -= 1;\n        }\n        return extra;\n",
    );

    assert!(!tree.contains("UNSET"), "{tree}");
}

/// php-src takes a list's line from its first child, and each piece of text's from where it starts.
#[test]
fn a_template_over_several_lines_keeps_the_line_of_each_part() {
    let lowered = Lowered::new(&method_with("string run(int extra)", "        return `total:\n${extra} more`;\n"));
    let list = lowered.nodes().iter().position(|node| node.kind == sharp_kind::SHARP_AST_ENCAPS_LIST).expect("a list");
    let lines: Vec<u32> =
        (0..3).map(|index| lowered.nodes()[lowered.child(list as u32, index) as usize].line).collect();

    assert_eq!(lowered.nodes()[list].line, 9);
    assert_eq!(lines, [9, 10, 10]);
}

/// ```php
/// #[\Lib\Entity(label: "Orders", order: 2 * 3), \App\Tenant\Searchable]
/// #[\Lib\Entity(null)]
/// class Report
/// {
///     #[\Lib\Field] private int $count = 0;
///
///     public function __construct(#[\Lib\Field(-1.5)] public readonly int $total)
///     {
///     }
///
///     #[\Lib\Entity(true, \Lib\TOP)]
///     public function run(#[\Lib\Field] int $extra): void
///     {
///     }
/// }
/// ```
///
/// Each `#[...]` is an `ATTRIBUTE_GROUP`, and a declaration's groups are one `ATTRIBUTE_LIST` in the child
/// `zend_ast_with_attributes` gives it: the 4th of a class, the 5th of a method, the 3rd of a property group and the
/// 4th of a parameter.
#[test]
fn attributes_are_attribute_lists_of_attribute_groups_on_their_declarations() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib;\nimport Lib.Field;\nimport Lib.Entity;\n\n[Entity(label: \"Orders\", order: 2 * 3), Searchable]\n[Entity(null)]\nclass Report\n{\n    [Field] private int count = 0;\n\n    public Report([Field(-1.5)] public int total { get; })\n    {\n    }\n\n    [Entity(true, Lib.TOP)]\n    public void run([Field] int extra)\n    {\n    }\n}\n",
        &[
            common::FIELD,
            common::ENTITY,
            common::SEARCHABLE,
            ("src/Lib/constants.php", "<?php namespace Lib; const TOP = 9;"),
        ],
    );

    assert_eq!(
        lowered.render(lowered.child(lowered.root(), 2)),
        indoc! {r#"
            CLASS "Report" @9-21
              null
              null
              STMT_LIST
                PROP_GROUP [32772]
                  ZVAL [1] "int"
                  PROP_DECL
                    PROP_ELEM
                      ZVAL "count"
                      ZVAL 0
                      null
                      null
                  ATTRIBUTE_LIST
                    ATTRIBUTE_GROUP
                      ATTRIBUTE
                        ZVAL "Lib\\Field"
                        null
                METHOD [1] "__construct" @13-15
                  PARAM_LIST
                    PARAM [129]
                      ZVAL [1] "int"
                      ZVAL "total"
                      null
                      ATTRIBUTE_LIST
                        ATTRIBUTE_GROUP
                          ATTRIBUTE
                            ZVAL "Lib\\Field"
                            ARG_LIST
                              UNARY_MINUS
                                ZVAL 1.5
                      null
                      null
                  null
                  STMT_LIST
                  null
                  null
                METHOD [1] "run" @18-20
                  PARAM_LIST
                    PARAM
                      ZVAL [1] "int"
                      ZVAL "extra"
                      null
                      ATTRIBUTE_LIST
                        ATTRIBUTE_GROUP
                          ATTRIBUTE
                            ZVAL "Lib\\Field"
                            null
                      null
                      null
                  null
                  STMT_LIST
                  SHARP_TYPE_ARGS
                    ZVAL [1] "void"
                    ZVAL "Function<void(int)>"
                  ATTRIBUTE_LIST
                    ATTRIBUTE_GROUP
                      ATTRIBUTE
                        ZVAL "Lib\\Entity"
                        ARG_LIST
                          ZVAL true
                          CONST
                            ZVAL "Lib\\TOP"
              ATTRIBUTE_LIST
                ATTRIBUTE_GROUP
                  ATTRIBUTE
                    ZVAL "Lib\\Entity"
                    ARG_LIST
                      NAMED_ARG
                        ZVAL "label"
                        ZVAL "Orders"
                      NAMED_ARG
                        ZVAL "order"
                        BINARY_OP [3]
                          ZVAL 2
                          ZVAL 3
                  ATTRIBUTE
                    ZVAL "App\\Tenant\\Searchable"
                    null
                ATTRIBUTE_GROUP
                  ATTRIBUTE
                    ZVAL "Lib\\Entity"
                    ARG_LIST
                      ZVAL null
              null
        "#}
    );
}

/// ```php
/// interface Labeled {
///     #[\Lib\Field('shown in lists')] public function label(): string;
///     #[\Lib\Entity('shown in headings')] public function title(): string;
/// }
/// trait Labeled\Defaults { #[\Lib\Entity('shown in headings')] public function title(): string { … } }
/// ```
///
/// ```php
/// #[\Lib\Field('sized')] interface Sized { #[\Lib\Field('size')] public int $size { get; } }
/// #[\Lib\Field('paid')] final class Paid { … }
/// final class Limits {
///     #[\Lib\Field('max')] public const int MAX = 3;
///     … #[\Lib\Field('twice')] static fn (int $n): int => $n * 2 …
/// }
/// ```
///
/// Spec section 1: an attribute on an interface, an interface property, an event, a constant or a lambda is where
/// php-src's grammar holds it: the 4th child of a class, the 3rd of a property group, the 2nd of a constant group and
/// the 5th of a closure.
#[test]
fn attributes_on_an_interface_its_property_an_event_a_constant_and_a_lambda_lower_where_php_holds_them() {
    let files = lowered_each(
        &[
            (
                "src/App/Sized.sharp",
                "namespace App;\n\nimport Lib.Field;\n\n[Field(\"sized\")]\npublic interface Sized\n{\n    [Field(\"size\")]\n    int size { get; }\n}\n",
            ),
            (
                "src/App/Paid.sharp",
                "namespace App;\n\nimport Lib.Field;\n\n[Field(\"paid\")]\npublic event Paid(int orderId);\n",
            ),
            (
                "src/App/Limits.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic class Limits\n{\n    [Field(\"max\")]\n    public const int MAX = 3;\n\n    public Function<int(int)> twice() => [Field(\"twice\")] (int n) => n * 2;\n}\n",
            ),
        ],
        &[common::FIELD],
    );
    let attribute = |text: &str| {
        format!(
            "ATTRIBUTE_LIST\n  ATTRIBUTE_GROUP\n    ATTRIBUTE\n      ZVAL \"Lib\\\\Field\"\n      ARG_LIST\n        ZVAL {text:?}\n"
        )
    };
    let class_attributes = |name: &str| {
        let (lowered, class) = class_in(&files, name);

        lowered.render(lowered.child(class, 3))
    };
    let (limits, _) = class_in(&files, "Limits");
    let closure = limits
        .nodes()
        .iter()
        .position(|node| node.kind == sharp_kind::SHARP_AST_CLOSURE || node.kind == sharp_kind::SHARP_AST_ARROW_FUNC)
        .expect("Limits declares a lambda") as u32;

    assert_eq!(class_attributes("Sized"), attribute("sized"));
    assert_eq!(member_in(&files, "Sized", &[0, 2]), attribute("size"));
    assert_eq!(class_attributes("Paid"), attribute("paid"));
    assert_eq!(member_in(&files, "Limits", &[0, 1]), attribute("max"));
    assert_eq!(limits.render(limits.child(closure, 4)), attribute("twice"));
}

/// ```php
/// #[\Lib\Field([new \Lib\Throttle(perMinute: 60, window: new \App\Window(5))])]
/// ```
///
/// Spec section 1: an attribute argument may `new` an object from constants, which lowers to the `NEW` php-src's
/// grammar builds in a constant expression, so PHP creates the object each time it reads the attribute.
#[test]
fn a_new_in_an_attribute_argument_lowers_to_the_new_php_takes_there() {
    let throttle = (
        "src/Lib/Throttle.php",
        "<?php namespace Lib; final class Throttle { public function __construct(public int $perMinute, public ?object $window = null) {} }",
    );
    let files = lowered_each(
        &[
            (
                "src/App/Window.sharp",
                "namespace App;\n\npublic class Window\n{\n    public Window(public int seconds { get; }) { }\n}\n",
            ),
            (
                "src/App/Orders.sharp",
                "namespace App;\n\nimport Lib.Field;\nimport Lib.Throttle;\n\n[Field([new Throttle(perMinute: 60, window: new Window(5))])]\npublic class Orders\n{\n}\n",
            ),
        ],
        &[common::FIELD, throttle],
    );
    let (lowered, class) = class_in(&files, "Orders");

    assert_eq!(
        lowered.render(lowered.child(class, 3)),
        indoc! {r#"
            ATTRIBUTE_LIST
              ATTRIBUTE_GROUP
                ATTRIBUTE
                  ZVAL "Lib\\Field"
                  ARG_LIST
                    ARRAY [3]
                      ARRAY_ELEM
                        NEW
                          ZVAL "Lib\\Throttle"
                          ARG_LIST
                            NAMED_ARG
                              ZVAL "perMinute"
                              ZVAL 60
                            NAMED_ARG
                              ZVAL "window"
                              NEW
                                ZVAL "App\\Window"
                                ARG_LIST
                                  ZVAL 5
                        null
        "#}
    );
}

/// ```php
/// public int $count = 0 { #[\Lib\Field("get")] get => $this->count; #[\Lib\Field("set")] set(#[\Lib\Field("value")] int $value) { $this->count = $value; } }
/// ```
///
/// Spec section 1: an accessor's attributes go on its hook, and a `param:` one on the value `set` takes, which the hook
/// then declares. An auto accessor with attributes is the hook over the storage. A static property's accessor carries
/// them on its hidden method, and a promoted parameter's `param:` ones stay on the parameter, beside the property
/// that takes its `property:` ones.
#[test]
fn an_accessor_carries_its_attributes_on_its_hook_and_a_target_picks_the_part() {
    let files = lowered_each(
        &[
            (
                "src/App/Report.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic class Report\n{\n    public int count { [Field(\"get\")] get; [param: Field(\"value\")] [Field(\"set\")] set; } = 0;\n\n    public static int total { [Field(\"read\")] get => 1; }\n\n    public Report([param: Field(\"in\")] [property: Field(\"kept\")] public int id { get; }) { }\n}\n",
            ),
            (
                "src/App/Sized.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic interface Sized\n{\n    int size { [Field(\"measured\")] get; [param: Field(\"new size\")] set; }\n}\n",
            ),
        ],
        &[common::FIELD],
    );

    let attribute = |text: &str| {
        format!(
            "ATTRIBUTE_LIST\n  ATTRIBUTE_GROUP\n    ATTRIBUTE\n      ZVAL \"Lib\\\\Field\"\n      ARG_LIST\n        ZVAL {text:?}\n"
        )
    };
    let member = |path: &[u32]| member_in(&files, "Report", path);
    let hooks = [0, 1, 0, 3];

    assert_eq!(
        member(&[hooks.as_slice(), &[0, 2]].concat()),
        "PROPERTY_HOOK_SHORT_BODY\n  PROP\n    VAR\n      ZVAL \"this\"\n    ZVAL \"count\"\n"
    );
    assert_eq!(member(&[hooks.as_slice(), &[0, 4]].concat()), attribute("get"));
    assert_eq!(member(&[hooks.as_slice(), &[1, 4]].concat()), attribute("set"));
    assert_eq!(member(&[hooks.as_slice(), &[1, 0, 0, 0]].concat()), "ZVAL [1] \"int\"\n");
    assert_eq!(member(&[hooks.as_slice(), &[1, 0, 0, 3]].concat()), attribute("value"));
    assert_eq!(member(&[1, 4]), attribute("read"));
    assert_eq!(member(&[2, 2]), attribute("kept"));
    assert_eq!(member(&[3, 0, 0, 3]), attribute("in"));
    assert_eq!(member_in(&files, "Sized", &[0, 1, 0, 3, 0, 4]), attribute("measured"));
    assert_eq!(member_in(&files, "Sized", &[0, 1, 0, 3, 1, 0, 0, 3]), attribute("new size"));
}

/// Spec section 1: every accessor form takes attributes. A static auto-property's accessors with attributes run as its
/// hidden methods over the storage, and a get-only auto-property's `get;` with attributes is a hook, so the property is
/// `protected(set)`, as `readonly` takes no hooks. An event's and a data case's parameters declare properties, so a
/// targeted list declares each property beside its parameter, which the constructor sets.
#[test]
fn every_accessor_form_takes_attributes_and_an_event_parameter_targets_its_part() {
    let files = lowered_each(
        &[
            (
                "src/App/Counter.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic class Counter\n{\n    public static int counter { [Field(\"counted\")] get; set; } = 0;\n\n    public string code { [Field(\"coded\")] get; }\n\n    public Counter()\n    {\n        this.code = \"c\";\n    }\n}\n",
            ),
            (
                "src/App/Settled.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic event Settled([param: Field(\"order\")] int orderId, [property: Field(\"amount\")] int amount);\n",
            ),
            (
                "src/App/Payment.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic enum Payment\n{\n    case Paid([param: Field(\"given\")] string id);\n    case Open;\n}\n",
            ),
            (
                "src/App/Tagged.sharp",
                "namespace App;\n\nimport Lib.Field;\n\npublic event Tagged([param: Field(\"tags\")] Set<string> tags);\n",
            ),
        ],
        &[common::FIELD],
    );

    let attribute = |text: &str| {
        format!(
            "ATTRIBUTE_LIST\n  ATTRIBUTE_GROUP\n    ATTRIBUTE\n      ZVAL \"Lib\\\\Field\"\n      ARG_LIST\n        ZVAL {text:?}\n"
        )
    };
    let counter = |path: &[u32]| member_in(&files, "Counter", path);
    let settled = |path: &[u32]| member_in(&files, "Settled", path);
    let set_by_constructor = |name: &str| {
        format!("ASSIGN\n  PROP\n    VAR\n      ZVAL \"this\"\n    ZVAL {name:?}\n  VAR\n    ZVAL {name:?}\n")
    };

    assert_eq!(counter(&[1, 4]), attribute("counted"));
    assert!(counter(&[0]).starts_with("PROP_GROUP [20]\n"), "the storage is a private static");
    assert!(counter(&[3]).starts_with("PROP_GROUP [2049]\n"), "a public protected(set) property, not readonly");
    assert_eq!(counter(&[3, 1, 0, 3, 0, 4]), attribute("coded"));
    assert_eq!(settled(&[0, 2]), "null\n");
    assert_eq!(settled(&[1, 2]), attribute("amount"));
    assert_eq!(settled(&[2, 0, 0, 3]), attribute("order"));
    assert_eq!(settled(&[2, 0, 1, 3]), "null\n");
    assert_eq!(settled(&[2, 2, 0]), set_by_constructor("orderId"));
    assert_eq!(settled(&[2, 2, 1]), set_by_constructor("amount"));
    let paid = |path: &[u32]| member_in(&files, "Payment\\Paid", path);
    assert_eq!(paid(&[0, 2]), "null\n");
    assert_eq!(paid(&[1, 0, 0, 3]), attribute("given"));
    assert_eq!(paid(&[1, 2, 0]), set_by_constructor("id"));
    let tagged = |path: &[u32]| member_in(&files, "Tagged", path);
    assert_eq!(tagged(&[1, 0, 0, 3]), attribute("tags"));
    assert_eq!(
        tagged(&[1, 2, 0]),
        "ASSIGN\n  VAR\n    ZVAL \"tags\"\n  CONDITIONAL\n    CALL\n      ZVAL \"is_array\"\n      ARG_LIST\n        VAR\n          ZVAL \"tags\"\n    SHARP_TYPE_ARGS\n      NEW\n        ZVAL \"Sharp\\\\Set\"\n        ARG_LIST\n          VAR\n            ZVAL \"tags\"\n      ZVAL \"string\"\n    VAR\n      ZVAL \"tags\"\n"
    );
    assert_eq!(tagged(&[1, 2, 1]), set_by_constructor("tags"));
}

/// Spec section 1: an interface method carries its attributes as a class method does, and so does the trait method
/// that runs its default body.
#[test]
fn an_interface_method_carries_its_attributes() {
    let files = lowered_each(
        &[(
            "src/App/Labeled.sharp",
            "namespace App;\n\nimport Lib.Field;\nimport Lib.Entity;\n\npublic interface Labeled\n{\n    [Field(\"shown in lists\")]\n    string label();\n\n    [Entity(\"shown in headings\")]\n    string title() => \"Untitled\";\n}\n",
        )],
        &[common::FIELD, common::ENTITY],
    );
    let member = |name: &str, path: &[u32]| member_in(&files, name, path);

    assert_eq!(
        [member("Labeled", &[0, 4]), member("Labeled", &[1, 4]), member("Labeled\\Defaults", &[0, 4])].concat(),
        indoc! {r#"
            ATTRIBUTE_LIST
              ATTRIBUTE_GROUP
                ATTRIBUTE
                  ZVAL "Lib\\Field"
                  ARG_LIST
                    ZVAL "shown in lists"
            ATTRIBUTE_LIST
              ATTRIBUTE_GROUP
                ATTRIBUTE
                  ZVAL "Lib\\Entity"
                  ARG_LIST
                    ZVAL "shown in headings"
            ATTRIBUTE_LIST
              ATTRIBUTE_GROUP
                ATTRIBUTE
                  ZVAL "Lib\\Entity"
                  ARG_LIST
                    ZVAL "shown in headings"
        "#}
    );
}

/// ```php
/// public \Sharp\Map $stock;    #[\Sharp\Crossing(['map', 'string', null])]
/// public \Sharp\Map $names;    #[\Sharp\Crossing(['map', null, null])]
/// public \Sharp\Map $counts;   #[\Sharp\Crossing(['map', 'App\Tenant\Status', null])]
/// public ?\Sharp\Map $spare;   #[\Sharp\Crossing(['map', 'string', null])]
/// public static \Sharp\Set $tags;   #[\Sharp\Crossing(['set', null])]
/// public \Sharp\Map $shelves;  #[\Sharp\Crossing(['map', 'string', ['list', ['set', null]]])]
/// public int $count;           no attribute
/// ```
///
/// A property PHP# declares a `Map` or a `Set` carries `#[\Sharp\Crossing]`, the plan the engine crosses a PHP array
/// plain PHP writes there by: an `int` key back as a `string` for a key type of `string`, a backing value back as its
/// case, and each `Map` or `Set` it holds, at any depth, crossed too.
#[test]
fn a_map_or_set_property_carries_the_plan_a_php_array_crosses_by() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nclass Ledger\n{\n    public Map<string, int> stock { get; set; } = [:];\n    public Map<int, string> names { get; set; } = [:];\n    public Map<Status, int> counts { get; set; } = [:];\n    public Map<string, int>? spare { get; set; } = null;\n    public static Set<string> tags { get; set; } = [];\n    public Map<string, List<Set<int>>> shelves { get; set; } = [:];\n    public int count { get; set; } = 0;\n}\n",
        &[(
            "src/App/Tenant/Status.sharp",
            "namespace App.Tenant;\n\nenum Status : string\n{\n    case Open = \"open\";\n}\n",
        )],
    );
    // The attribute list of `#[\Sharp\Crossing(plan)]`, with the plan's rendering indented under its `ARG_LIST`.
    let crossing = |plan: &str| {
        let mut attribute = String::from(
            "ATTRIBUTE_LIST\n  ATTRIBUTE_GROUP\n    ATTRIBUTE\n      ZVAL \"Sharp\\\\Crossing\"\n      ARG_LIST\n",
        );
        for line in plan.lines() {
            attribute.push_str("        ");
            attribute.push_str(line);
            attribute.push('\n');
        }

        attribute
    };
    let map_by_string = indoc! {r#"
        ARRAY [3]
          ARRAY_ELEM
            ZVAL "map"
            null
          ARRAY_ELEM
            ZVAL "string"
            null
          ARRAY_ELEM
            ZVAL null
            null
    "#};
    let attributes: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_PROP_GROUP)
        .map(|(index, _)| lowered.render(lowered.child(index as u32, 2)))
        .collect();

    assert_eq!(lowered.diagnostics(), Vec::<String>::new(), "the source lowers");
    assert_eq!(
        attributes,
        [
            crossing(map_by_string),
            crossing(indoc! {r#"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "map"
                    null
                  ARRAY_ELEM
                    ZVAL null
                    null
                  ARRAY_ELEM
                    ZVAL null
                    null
            "#}),
            crossing(indoc! {r#"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "map"
                    null
                  ARRAY_ELEM
                    ZVAL "App\\Tenant\\Status"
                    null
                  ARRAY_ELEM
                    ZVAL null
                    null
            "#}),
            crossing(map_by_string),
            crossing(indoc! {r#"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "set"
                    null
                  ARRAY_ELEM
                    ZVAL null
                    null
            "#}),
            crossing(indoc! {r#"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "map"
                    null
                  ARRAY_ELEM
                    ZVAL "string"
                    null
                  ARRAY_ELEM
                    ARRAY [3]
                      ARRAY_ELEM
                        ZVAL "list"
                        null
                      ARRAY_ELEM
                        ARRAY [3]
                          ARRAY_ELEM
                            ZVAL "set"
                            null
                          ARRAY_ELEM
                            ZVAL null
                            null
                        null
                    null
            "#}),
            "null\n".to_string(),
        ]
    );
}

/// ```php
/// ```php
/// public \Sharp\Map $mixed;   #[\Sharp\Crossing(['map', null, null])]
/// public \Sharp\Map $listed;  #[\Sharp\Crossing(['map', null, null], false)]
/// public mixed $loose;        #[\Sharp\Crossing(null)]
/// public iterable $shelved;   #[\Sharp\Crossing(null)]
/// public mixed $held;         #[\Sharp\Crossing(null)]
/// public \Sharp\Map $anyValues;  #[\Sharp\Crossing(['map', 'string', false])]
/// ```
///
/// Plain PHP reads a property whose type can hold a `Map` or a `Set` with each one as its PHP array, spec section 12, so
/// an `Any?`, an `Iterable` or a type parameter carries `#[\Sharp\Crossing]` with no plan, since nothing it holds
/// crosses back. A `Map` keyed by `int|string` reads as its PHP array too, which throws when it runs if two of its keys
/// are one PHP array key. A `Map` keyed by a type no PHP array holds, as `List<int>`, crosses in by its plan, and its
/// `false` keeps it the object plain PHP reads. A plan's part that may hold a `Map` no plan rebuilds, as the values of a
/// `Map<string, Any>` may, is false, so the engine keeps the object a plain PHP reference to the property holds.
#[test]
fn a_property_that_can_hold_a_map_carries_whether_plain_php_reads_its_array() {
    let lowered = Lowered::new(
        "namespace App.Tenant;\n\nclass Ledger<T>\n{\n    public Map<int|string, int> mixed { get; set; } = [:];\n    public Map<List<int>, int> listed { get; set; } = [:];\n    public Any? loose { get; set; } = null;\n    public Iterable<Map<string, int>> shelved { get; set; } = [[\"s\": 1]];\n    public T? held { get; set; } = null;\n    public Map<string, Any> anyValues { get; set; } = [:];\n}\n",
    );
    let attributes: Vec<String> = lowered
        .nodes()
        .iter()
        .enumerate()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_PROP_GROUP)
        .map(|(index, _)| lowered.render(lowered.child(index as u32, 2)))
        .collect();

    // The attribute list of `#[\Sharp\Crossing(arguments)]`, with the arguments' rendering indented under its `ARG_LIST`.
    let crossing = |arguments: &str| {
        let mut attribute = String::from(
            "ATTRIBUTE_LIST\n  ATTRIBUTE_GROUP\n    ATTRIBUTE\n      ZVAL \"Sharp\\\\Crossing\"\n      ARG_LIST\n",
        );
        for line in arguments.lines() {
            attribute.push_str("        ");
            attribute.push_str(line);
            attribute.push('\n');
        }

        attribute
    };
    let unplanned = crossing("ZVAL null\n");
    let keyed = indoc! {r#"
        ARRAY [3]
          ARRAY_ELEM
            ZVAL "map"
            null
          ARRAY_ELEM
            ZVAL null
            null
          ARRAY_ELEM
            ZVAL null
            null
    "#};

    assert_eq!(lowered.diagnostics(), Vec::<String>::new(), "the source lowers");
    assert_eq!(
        attributes,
        [
            crossing(keyed),
            crossing(&format!("{keyed}ZVAL false\n")),
            unplanned.clone(),
            unplanned.clone(),
            unplanned,
            crossing(indoc! {r#"
                ARRAY [3]
                  ARRAY_ELEM
                    ZVAL "map"
                    null
                  ARRAY_ELEM
                    ZVAL "string"
                    null
                  ARRAY_ELEM
                    ZVAL false
                    null
            "#}),
        ]
    );
}

/// `Lib\Calc`, a plain PHP class whose methods take and give PHP arrays and closures that take them.
const ARRAYS: (&str, &str) = (
    "src/Lib/Calc.php",
    "<?php namespace Lib; final class Calc {
        public static function total(?array $items): int { return 0; }
        public static function sum(array ...$items): int { return 0; }
        /** @param array<int, string> $items */
        public static function sort(array &$items): void {}
        /** @param-out array<int, string> $value */
        public static function fill(&$value): void {}
        /** @param-out int $value */
        public static function bump(&$value): void {}
        /** @return array<int, string> */
        public static function names(): array { return []; }
        /** @return \\Closure(array $items, array ...$rest): int */
        public static function counter(): \\Closure { return fn (array $items, array ...$rest): int => 0; }
        public static function plain(): \\Closure { return fn () => 0; }
    }",
);

/// The statements of `run` at `positions` in `code`, lowered beside `ARRAYS` and the `library` files.
fn statements_at(code: &str, library: &[(&str, &str)], positions: std::ops::Range<u32>) -> Vec<String> {
    let files: Vec<(&str, &str)> = std::iter::once(ARRAYS).chain(library.iter().copied()).collect();
    let lowered = Lowered::with(code, &files);
    let body = lowered.child(lowered.method_named("run"), 2);

    positions.map(|position| lowered.render(lowered.child(body, position))).collect()
}

/// ```php
/// \Lib\Calc::sum(\Sharp\Internal\arrayOf($stock), extra: \Sharp\Internal\arrayOf($stock));
/// ```
///
/// Spec section 16: a named argument that matches no other parameter of a plain PHP method fills its `...` parameter,
/// so a `Map` goes in under its name as its PHP array, as it goes in by position.
#[test]
fn a_map_named_into_a_plain_php_variadic_goes_in_as_its_php_array() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<string, int> stock = this.stock();\n        return Calc.sum(stock, extra: stock);\n    }\n\n    private Map<string, int> stock() => [:];\n}\n";

    assert_eq!(
        statements_at(code, &[], 1..2),
        [indoc! {r#"
            RETURN
              STATIC_CALL
                ZVAL "Lib\\Calc"
                ZVAL "sum"
                ARG_LIST
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
                  NAMED_ARG
                    ZVAL "extra"
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "stock"
        "#}]
    );
}

/// ```php
/// $typed = $gadget->label(...);
/// $held = $gadget->format;
/// ```
///
/// A plain PHP class's method is the value of a read of its name, where the class also declares a property of that
/// name, when the code takes the read as a function the property's type does not fit, spec section 14.3. The engine
/// would read the property, so the read is PHP's first-class callable. A property whose type fits keeps the read.
#[test]
fn a_plain_php_method_of_a_property_s_name_read_as_a_function_is_a_first_class_callable() {
    let gadget = (
        "src/Lib/Gadget.php",
        "<?php\n\nnamespace Lib;\n\nfinal class Gadget\n{\n    public string $label = 'gadget';\n\n    /** @var Closure(string): string */\n    public \\Closure $format;\n\n    public function label(string $prefix): string\n    {\n        return $prefix . $this->label;\n    }\n\n    public function format(string $text): string\n    {\n        return $text;\n    }\n}\n",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Gadget;\nextern Gadget.label;\n\nclass Report\n{\n    public string run(Gadget gadget)\n    {\n        Function<string(string)> typed = gadget.label;\n        Function<string(string)> held = gadget.format;\n        return typed(\"a\") + held(\"b\");\n    }\n}\n";

    assert_eq!(
        statements_at(code, &[gadget], 0..2),
        [
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "typed"
                  METHOD_CALL
                    VAR
                      ZVAL "gadget"
                    ZVAL "label"
                    CALLABLE_CONVERT
            "#},
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "held"
                  PROP
                    VAR
                      ZVAL "gadget"
                    ZVAL "format"
            "#},
        ]
    );
}

/// ```php
/// $owner = $this->owner;
/// $relation = $this->owner(...);
/// ```
///
/// A PHP# class whose plain PHP parent defines `__get`, as a PHP# Eloquent model is, has the properties `__get` reads,
/// spec section 14.3, so a read of its own method's name reads the property, and takes the method where the code takes
/// a function.
#[test]
fn a_read_of_a_sharp_class_whose_plain_php_parent_defines_get_reads_the_property() {
    let model = (
        "src/Lib/Model.php",
        "<?php\n\nnamespace Lib;\n\nabstract class Model\n{\n    public function __get(string $name): mixed\n    {\n        return $name;\n    }\n\n    public static function measure(string $text): int\n    {\n        return strlen($text);\n    }\n}\n",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Model;\n\nclass Row : Model\n{\n    public Row() : super() { }\n\n    public string owner() => \"relation\";\n\n    public int run()\n    {\n        const owner = this.owner;\n        Function<string()> relation = this.owner;\n        return Model.measure(relation()) + (owner is string ? 1 : 0);\n    }\n}\n";
    let lowered = Lowered::with(code, &[model]);
    let run = member_in(std::slice::from_ref(&lowered), "Row", &[2, 2]);

    assert_eq!(
        run,
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "owner"
                PROP
                  VAR
                    ZVAL "this"
                  ZVAL "owner"
              ASSIGN
                VAR
                  ZVAL "relation"
                METHOD_CALL
                  VAR
                    ZVAL "this"
                  ZVAL "owner"
                  CALLABLE_CONVERT
              RETURN
                BINARY_OP [1]
                  STATIC_CALL
                    ZVAL "Lib\\Model"
                    ZVAL "measure"
                    ARG_LIST
                      CALL
                        VAR
                          ZVAL "relation"
                        ARG_LIST
                  CONDITIONAL [1]
                    CALL
                      ZVAL "is_string"
                      ARG_LIST
                        VAR
                          ZVAL "owner"
                    ZVAL 1
                    ZVAL 0
        "#}
    );
}

/// ```php
/// $contact = $row->contact;
/// $owner = $row->owner;
/// $relation = $row->owner(...);
/// $called = $row->owner();
/// ```
///
/// A plain PHP class that defines `__get` has the properties it reads, spec section 14.3, so a read of a name it also
/// has a method of reads the property, typed by an `@property-read` line or not. The method is the value where the code
/// takes a function, and a call calls it.
#[test]
fn a_read_of_a_plain_php_class_with_get_reads_the_property_and_takes_the_method_as_a_function() {
    let row = (
        "src/Lib/Row.php",
        "<?php\n\nnamespace Lib;\n\n/** @property-read Contact $contact */\nclass Row\n{\n    public function contact(): Contact\n    {\n        return new Contact();\n    }\n\n    public function owner(): Contact\n    {\n        return new Contact();\n    }\n\n    public function __get(string $name): mixed\n    {\n        return new Contact();\n    }\n}\n",
    );
    let contact = ("src/Lib/Contact.php", "<?php\n\nnamespace Lib;\n\nfinal class Contact\n{\n}\n");
    let code = "namespace App.Tenant;\n\nimport Lib.Contact;\nimport Lib.Row;\nextern Row.owner;\n\nclass Report\n{\n    public int run(Row row)\n    {\n        const contact = row.contact;\n        const owner = row.owner;\n        Function<Contact()> relation = row.owner;\n        const called = row.owner();\n        return [contact, relation(), called].count() + (owner is Contact ? 1 : 0);\n    }\n}\n";

    assert_eq!(
        statements_at(code, &[row, contact], 0..4),
        [
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "contact"
                  PROP
                    VAR
                      ZVAL "row"
                    ZVAL "contact"
            "#},
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "owner"
                  PROP
                    VAR
                      ZVAL "row"
                    ZVAL "owner"
            "#},
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "relation"
                  METHOD_CALL
                    VAR
                      ZVAL "row"
                    ZVAL "owner"
                    CALLABLE_CONVERT
            "#},
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "called"
                  METHOD_CALL
                    VAR
                      ZVAL "row"
                    ZVAL "owner"
                    ARG_LIST
            "#},
        ]
    );
}

/// ```php
/// return \Lib\Calc::total(\Sharp\Internal\arrayOf($stock));
/// return \Lib\Calc::sum(...\Sharp\Internal\arrayOf([$stock]));
/// ```
///
/// A `Map` keyed by a backed enum goes into a plain PHP parameter that takes `array` through
/// `\Sharp\Internal\arrayOf`, which keys it by each case's backing value, spec section 12, as the keys a PHP array
/// holds, and so does each `Map` a spread passes.
#[test]
fn a_map_keyed_by_a_backed_enum_goes_into_a_plain_php_array_with_backing_values_as_keys() {
    let level = ("src/Lib/Level.php", "<?php namespace Lib; enum Level: string { case Low = 'low'; }");
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\nimport Lib.Level;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<Level, int> stock = this.stock();\n        return Calc.total(stock);\n    }\n\n    private Map<Level, int> stock() => [Level.Low: 1];\n}\n";

    assert_eq!(
        statements_at(code, &[level], 1..2),
        [indoc! {r#"
            RETURN
              STATIC_CALL
                ZVAL "Lib\\Calc"
                ZVAL "total"
                ARG_LIST
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
        "#}]
    );
    assert_eq!(
        statements_at(&code.replace("Calc.total(stock)", "Calc.sum(...[stock])"), &[level], 1..2),
        [indoc! {r#"
            RETURN
              STATIC_CALL
                ZVAL "Lib\\Calc"
                ZVAL "sum"
                ARG_LIST
                  UNPACK
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        ARRAY [3]
                          ARRAY_ELEM
                            VAR
                              ZVAL "stock"
                            null
        "#}]
    );
}

/// ```php
/// \Lib\Calc::total(\Sharp\Internal\arrayOf($stock));
/// \Lib\Calc::total(\Sharp\Internal\arrayOf($tags));
/// \Lib\Calc::total(\Sharp\Internal\arrayOf($spare));
/// \Lib\Calc::sum(...\Sharp\Internal\arrayOf($shelves));
/// \Vendor\Csv\join(",", \Sharp\Internal\arrayOf($tags));
/// return \Lib\Calc::total(items: \Sharp\Internal\arrayOf($stock));
/// ```
///
/// A `Map` or a `Set` goes into a plain PHP parameter that takes `array` as its PHP array, spec section 12, and a `Set`
/// as the list of its elements, whether a method or a function called through its namespace takes it, as
/// `\Sharp\Internal\arrayOf` gives them. A value that is null goes in as it is, and each `Map` of a spread `List` goes
/// in as its PHP array.
#[test]
fn a_map_or_set_goes_into_a_plain_php_array_parameter_as_its_php_array() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\nimport Vendor.Csv;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<string, int> stock = this.stock();\n        Set<string> tags = this.tags();\n        Map<string, int>? spare = this.spare();\n        List<Map<string, int>> shelves = this.shelves();\n        Calc.total(stock);\n        Calc.total(tags);\n        Calc.total(spare);\n        Calc.sum(...shelves);\n        Csv.join(\",\", tags);\n        return Calc.total(items: stock);\n    }\n\n    private Map<string, int> stock() => [:];\n\n    private Set<string> tags() => [];\n\n    private Map<string, int>? spare() => null;\n\n    private List<Map<string, int>> shelves() => [];\n}\n";
    let csv = (
        "src/Vendor/Csv/functions.php",
        "<?php namespace Vendor\\Csv; function join(string $glue, array $parts): string { return implode($glue, $parts); }",
    );

    assert_eq!(
        statements_at(code, &[csv], 4..10),
        [
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "total"
                  ARG_LIST
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "stock"
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "total"
                  ARG_LIST
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "tags"
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "total"
                  ARG_LIST
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "spare"
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "sum"
                  ARG_LIST
                    UNPACK
                      CALL
                        ZVAL "Sharp\\Internal\\arrayOf"
                        ARG_LIST
                          VAR
                            ZVAL "shelves"
            "#},
            indoc! {r#"
                CALL
                  ZVAL "Vendor\\Csv\\join"
                  ARG_LIST
                    ZVAL ","
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "tags"
            "#},
            indoc! {r#"
                RETURN
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "total"
                    ARG_LIST
                      NAMED_ARG
                        ZVAL "items"
                        CALL
                          ZVAL "Sharp\\Internal\\arrayOf"
                          ARG_LIST
                            VAR
                              ZVAL "stock"
            "#},
        ]
    );
}

/// ```php
/// $context->payload = \Sharp\Internal\arrayOf($stock);
/// \Lib\Context::$registry = \Sharp\Internal\arrayOf($stock);
/// $context->payloads['first'] = \Sharp\Internal\arrayOf($stock);
/// $context->counted = $stock;
/// $this->own = $stock;
/// ```
///
/// A `Map` written into a property plain PHP declares, or an element of one, goes in as the PHP array a parameter of
/// the property's type takes, spec section 12: as its PHP array where the type takes an array, and as itself where it
/// takes only objects, as `\Countable` does. A property PHP# declares keeps the `Map`.
#[test]
fn a_map_written_into_plain_php_storage_goes_in_as_a_parameter_of_the_property_s_type_takes_it() {
    let context = (
        "src/Lib/Context.php",
        "<?php namespace Lib; class Context { public array $payload = []; public static array $registry = []; public array $payloads = []; public ?\\Countable $counted = null; }",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Context;\n\nclass Report\n{\n    public Map<string, int> own { get; set; } = [:];\n\n    public void run(Context context)\n    {\n        Map<string, int> stock = this.stock();\n        context.payload = stock;\n        Context.registry = stock;\n        context.payloads[\"first\"] = stock;\n        context.counted = stock;\n        this.own = stock;\n    }\n\n    private Map<string, int> stock() => [:];\n}\n";

    assert_eq!(
        statements_at(code, &[context], 1..6),
        [
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "context"
                    ZVAL "payload"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  STATIC_PROP
                    ZVAL "Lib\\Context"
                    ZVAL "registry"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  DIM
                    PROP
                      VAR
                        ZVAL "context"
                      ZVAL "payloads"
                    ZVAL "first"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "context"
                    ZVAL "counted"
                  VAR
                    ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "own"
                  VAR
                    ZVAL "stock"
            "#},
        ]
    );
}

/// ```php
/// $this->payload = \Sharp\Internal\arrayOf($stock);
/// \App\Tenant\Job::$registry = \Sharp\Internal\arrayOf($stock);
/// $this->rows[0]['shelf'] = \Sharp\Internal\arrayOf($stock);
/// [$context->kept = \is_array($renumbered#1 = $context->kept) ? \array_values($renumbered#1) : $renumbered#1,
///     $context->kept[0]['shelf'] = \Sharp\Internal\arrayOf($stock)][1];
/// $this->payload += \Sharp\Internal\arrayOf($stock);
/// $attributes->meta = \Sharp\Internal\arrayOf($stock);
/// ```
///
/// A property a plain PHP parent declares takes a `Map` as a property its class declares does, and so does an
/// element of an element of a list it declares, which is PHP's own write, after the list is renumbered where the
/// checker reads plain PHP's `array<int, …>` as a `List`. A compound assignment takes it the same way, and so does a
/// name the class declares no property for, which its `__set` takes as its `mixed` value parameter does.
#[test]
fn a_map_written_into_a_plain_php_parent_s_or_set_s_storage_goes_in_as_its_type_takes_it() {
    let library = (
        "src/Lib/BaseJob.php",
        "<?php namespace Lib; abstract class BaseJob { public array $payload = []; public static array $registry = []; /** @var list<array<string, mixed>> */ public array $rows = []; }
        final class Context { /** @var array<int, array<string, mixed>> */ public array $kept = []; }
        final class Attributes { public function __set(string $name, mixed $value): void {} }",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Attributes;\nimport Lib.BaseJob;\nimport Lib.Context;\n\nclass Job : BaseJob\n{\n    public void run(Context context, Attributes attributes)\n    {\n        Map<string, int> stock = this.stock();\n        this.payload = stock;\n        Job.registry = stock;\n        this.rows[0][\"shelf\"] = stock;\n        context.kept[0][\"shelf\"] = stock;\n        this.payload += stock;\n        attributes.meta = stock;\n    }\n\n    private Map<string, int> stock() => [:];\n}\n";

    assert_eq!(
        statements_at(code, &[library], 1..7),
        [
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "payload"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  STATIC_PROP
                    ZVAL "App\\Tenant\\Job"
                    ZVAL "registry"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  DIM
                    DIM
                      PROP
                        VAR
                          ZVAL "this"
                        ZVAL "rows"
                      ZVAL 0
                    ZVAL "shelf"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                DIM
                  ARRAY [3]
                    ARRAY_ELEM
                      ASSIGN
                        PROP
                          VAR
                            ZVAL "context"
                          ZVAL "kept"
                        CONDITIONAL
                          CALL
                            ZVAL "is_array"
                            ARG_LIST
                              ASSIGN
                                VAR
                                  ZVAL "renumbered#1"
                                PROP
                                  VAR
                                    ZVAL "context"
                                  ZVAL "kept"
                          CALL
                            ZVAL "array_values"
                            ARG_LIST
                              VAR
                                ZVAL "renumbered#1"
                          VAR
                            ZVAL "renumbered#1"
                      null
                    ARRAY_ELEM
                      ASSIGN
                        DIM
                          DIM
                            PROP
                              VAR
                                ZVAL "context"
                              ZVAL "kept"
                            ZVAL 0
                          ZVAL "shelf"
                        CALL
                          ZVAL "Sharp\\Internal\\arrayOf"
                          ARG_LIST
                            VAR
                              ZVAL "stock"
                      null
                  ZVAL 1
            "#},
            indoc! {r#"
                ASSIGN_OP [1]
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "payload"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "attributes"
                    ZVAL "meta"
                  CALL
                    ZVAL "Sharp\\Internal\\arrayOf"
                    ARG_LIST
                      VAR
                        ZVAL "stock"
            "#},
        ]
    );
}

/// ```php
/// \Sharp\Internal\add($context->rows, \Sharp\Internal\arrayOf($stock));
/// \Sharp\ListMembers::add($context->rows, value: \Sharp\Internal\arrayOf($stock), /* type args "Any?" */);
/// \Sharp\ListMembers::insert($context->rows, index: 0, value: \Sharp\Internal\arrayOf($stock), /* type args "Any?" */);
/// ```
///
/// A `Map` a `List` member stores in a list plain PHP declares goes in as an element of it takes it, spec section 12,
/// whether the argument is positional, in the member's inline form, or named, in the call of its static method.
#[test]
fn a_map_a_method_stores_in_a_plain_php_collection_goes_in_as_its_element_takes_it() {
    let context = (
        "src/Lib/Context.php",
        "<?php namespace Lib; class Context { /** @var list<mixed> */ public array $rows = []; }",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Context;\n\nclass Report\n{\n    public void run(Context context)\n    {\n        Map<string, int> stock = this.stock();\n        context.rows.add(stock);\n        context.rows.add(value: stock);\n        context.rows.insert(index: 0, value: stock);\n    }\n\n    private Map<string, int> stock() => [:];\n}\n";
    assert_eq!(
        statements_at(code, &[context], 1..4),
        [
            indoc! {r#"
                CALL
                  ZVAL "Sharp\\Internal\\add"
                  ARG_LIST
                    PROP
                      VAR
                        ZVAL "context"
                      ZVAL "rows"
                    CALL
                      ZVAL "Sharp\\Internal\\arrayOf"
                      ARG_LIST
                        VAR
                          ZVAL "stock"
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Sharp\\ListMembers"
                  ZVAL "add"
                  ARG_LIST
                    PROP
                      VAR
                        ZVAL "context"
                      ZVAL "rows"
                    NAMED_ARG
                      ZVAL "value"
                      CALL
                        ZVAL "Sharp\\Internal\\arrayOf"
                        ARG_LIST
                          VAR
                            ZVAL "stock"
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Any?"
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Sharp\\ListMembers"
                  ZVAL "insert"
                  ARG_LIST
                    PROP
                      VAR
                        ZVAL "context"
                      ZVAL "rows"
                    NAMED_ARG
                      ZVAL "index"
                      ZVAL 0
                    NAMED_ARG
                      ZVAL "value"
                      CALL
                        ZVAL "Sharp\\Internal\\arrayOf"
                        ARG_LIST
                          VAR
                            ZVAL "stock"
                    SHARP_TYPE_ARGS
                      null
                      ZVAL "Any?"
            "#},
        ]
    );
}

/// ```php
/// $this->stock = \is_array($crossing = \Lib\Prices::all())
///     ? new \Sharp\Map<string, int>(\array_merge([], ...\array_map(fn ($key, $value) => [(string) $key, $value], \array_keys($crossing), $crossing)))
///     : $crossing;
/// $this->names = \is_array($renumbered = \Lib\Calc::names()) ? \array_values($renumbered) : $renumbered;
/// ```
///
/// Plain PHP's array a PHP# subclass writes into a property its PHP# base declares crosses as the property's declared
/// type says, as it does into a property the class declares itself: into a `Map` as the `Map` of its entries, and into
/// a `List` renumbered.
#[test]
fn plain_php_s_array_written_into_a_php_sharp_base_s_property_crosses_as_its_type_declares() {
    let base = (
        "src/App/Tenant/Shelf.sharp",
        "namespace App.Tenant;\n\npublic abstract class Shelf\n{\n    public Map<string, int> stock { get; set; } = [:];\n\n    public List<string> names { get; set; } = [];\n}\n",
    );
    let prices = (
        "src/Lib/Prices.php",
        "<?php namespace Lib; final class Prices { /** @return array<string, int> */ public static function all(): array { return []; } }",
    );
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\nimport Lib.Prices;\n\nclass Pantry : Shelf\n{\n    public void run()\n    {\n        this.stock = Prices.all();\n        this.names = Calc.names();\n    }\n}\n";

    assert_eq!(
        statements_at(code, &[base, prices], 0..2),
        [
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "stock"
                  CONDITIONAL
                    CALL
                      ZVAL "is_array"
                      ARG_LIST
                        ASSIGN
                          VAR
                            ZVAL "crossing#1"
                          VERIFY_TYPE_ARGS
                            STATIC_CALL
                              ZVAL "Lib\\Prices"
                              ZVAL "all"
                              ARG_LIST
                            ZVAL "Map<string, int>"
                            ZVAL "Lib\\Prices::all()"
                    SHARP_TYPE_ARGS
                      NEW
                        ZVAL "Sharp\\Map"
                        ARG_LIST
                          CALL
                            ZVAL "array_merge"
                            ARG_LIST
                              ARRAY [3]
                              UNPACK
                                CALL
                                  ZVAL "array_map"
                                  ARG_LIST
                                    ARROW_FUNC "" @10-10
                                      PARAM_LIST
                                        PARAM
                                          null
                                          ZVAL "key#2"
                                          null
                                          null
                                          null
                                          null
                                        PARAM
                                          null
                                          ZVAL "value#3"
                                          null
                                          null
                                          null
                                          null
                                      null
                                      ARRAY [3]
                                        ARRAY_ELEM
                                          CAST [6]
                                            VAR
                                              ZVAL "key#2"
                                          null
                                        ARRAY_ELEM
                                          VAR
                                            ZVAL "value#3"
                                          null
                                      null
                                      null
                                    CALL
                                      ZVAL "array_keys"
                                      ARG_LIST
                                        VAR
                                          ZVAL "crossing#1"
                                    VAR
                                      ZVAL "crossing#1"
                      ZVAL "string, int"
                    VAR
                      ZVAL "crossing#1"
            "#},
            indoc! {r#"
                ASSIGN
                  PROP
                    VAR
                      ZVAL "this"
                    ZVAL "names"
                  VERIFY_TYPE_ARGS
                    CONDITIONAL
                      CALL
                        ZVAL "is_array"
                        ARG_LIST
                          ASSIGN
                            VAR
                              ZVAL "renumbered#1"
                            STATIC_CALL
                              ZVAL "Lib\\Calc"
                              ZVAL "names"
                              ARG_LIST
                      CALL
                        ZVAL "array_values"
                        ARG_LIST
                          VAR
                            ZVAL "renumbered#1"
                      VAR
                        ZVAL "renumbered#1"
                    ZVAL "List<string>"
                    ZVAL "Lib\\Calc::names()"
            "#},
        ]
    );
}

/// ```php
/// [$sorted = \Sharp\Internal\arrayOf($sorted), \Lib\Calc::sort($sorted), $sorted = \is_array($sorted) ? \Sharp\Map::from($sorted, 'int, string') : $sorted][1];
/// [$filled = \Sharp\Internal\arrayOf($filled), \Lib\Calc::fill($filled), $filled = \is_array($filled) ? \Sharp\Map::from($filled, 'int, string') : $filled][1];
/// \Lib\Calc::bump($count);
/// ```
///
/// A typed local that holds a `Map` or a `Set` goes into a plain PHP reference parameter and comes back as the object
/// of what plain PHP wrote there: as its PHP array first where the parameter takes an array, as `array` and an
/// untyped one do, and as itself otherwise. A local of any other type goes in as it is.
#[test]
fn a_typed_local_crosses_into_and_back_from_a_plain_php_reference_parameter() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<int, string> sorted = this.names();\n        Map<int, string> filled = this.names();\n        int count = 0;\n        Calc.sort(sorted);\n        Calc.fill(filled);\n        Calc.bump(count);\n        return count;\n    }\n\n    private Map<int, string> names() => [:];\n}\n";

    assert_eq!(
        statements_at(code, &[], 3..6),
        [
            indoc! {r#"
                DIM
                  ARRAY [3]
                    ARRAY_ELEM
                      ASSIGN
                        VAR
                          ZVAL "sorted"
                        CALL
                          ZVAL "Sharp\\Internal\\arrayOf"
                          ARG_LIST
                            VAR
                              ZVAL "sorted"
                      null
                    ARRAY_ELEM
                      STATIC_CALL
                        ZVAL "Lib\\Calc"
                        ZVAL "sort"
                        ARG_LIST
                          VAR
                            ZVAL "sorted"
                      null
                    ARRAY_ELEM
                      ASSIGN
                        VAR
                          ZVAL "sorted"
                        CONDITIONAL
                          CALL
                            ZVAL "is_array"
                            ARG_LIST
                              VAR
                                ZVAL "sorted"
                          STATIC_CALL
                            ZVAL "Sharp\\Map"
                            ZVAL "from"
                            ARG_LIST
                              VAR
                                ZVAL "sorted"
                              ZVAL "int, string"
                          VAR
                            ZVAL "sorted"
                      null
                  ZVAL 1
            "#},
            indoc! {r#"
                DIM
                  ARRAY [3]
                    ARRAY_ELEM
                      ASSIGN
                        VAR
                          ZVAL "filled"
                        CALL
                          ZVAL "Sharp\\Internal\\arrayOf"
                          ARG_LIST
                            VAR
                              ZVAL "filled"
                      null
                    ARRAY_ELEM
                      STATIC_CALL
                        ZVAL "Lib\\Calc"
                        ZVAL "fill"
                        ARG_LIST
                          VAR
                            ZVAL "filled"
                      null
                    ARRAY_ELEM
                      ASSIGN
                        VAR
                          ZVAL "filled"
                        CONDITIONAL
                          CALL
                            ZVAL "is_array"
                            ARG_LIST
                              VAR
                                ZVAL "filled"
                          STATIC_CALL
                            ZVAL "Sharp\\Map"
                            ZVAL "from"
                            ARG_LIST
                              VAR
                                ZVAL "filled"
                              ZVAL "int, string"
                          VAR
                            ZVAL "filled"
                      null
                  ZVAL 1
            "#},
            indoc! {r#"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "bump"
                  ARG_LIST
                    VAR
                      ZVAL "count"
            "#},
        ]
    );
}

/// ```php
/// $count(\Sharp\Internal\arrayOf($names, $count), \Sharp\Internal\arrayOf($names, $count), \Sharp\Internal\arrayOf($names, $count));
/// $count(items: \Sharp\Internal\arrayOf($names, $count));
/// $plain(\Sharp\Internal\arrayOf($names, $plain));
/// $doubler(\Sharp\Internal\arrayOf($names));
/// ```
///
/// A call of a closure a local holds crosses each `Map` by the parameters of the closure's signature, as a call of a
/// plain PHP method does: by position, by name and into its variadic parameter, and a closure whose signature its type
/// doesn't give takes any value. `\Sharp\Internal\arrayOf` reads the closure, and keeps the object for a closure of
/// PHP#, spec section 12. A plain PHP object a local holds crosses each by its `__invoke`.
#[test]
fn a_call_of_a_plain_php_callable_a_local_holds_crosses_each_map_by_its_parameters() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\nimport Lib.Doubler;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<int, string> names = this.names();\n        const count = Calc.counter();\n        const plain = Calc.plain();\n        const doubler = new Doubler();\n        count(names, names, names);\n        count(items: names);\n        plain(names);\n        doubler(names);\n        return 0;\n    }\n\n    private Map<int, string> names() => [:];\n}\n";
    let doubler = (
        "src/Lib/Doubler.php",
        "<?php namespace Lib; final class Doubler { public function __invoke(array $items): int { return 0; } }",
    );
    // The tree of `\Sharp\Internal\arrayOf($names, $local)`, or of `\Sharp\Internal\arrayOf($names)` without a local.
    let crossed = |local: Option<&str>| {
        let receiver = local.map_or(String::new(), |local| format!("    VAR\n      ZVAL \"{local}\"\n"));

        format!("CALL\n  ZVAL \"Sharp\\\\Internal\\\\arrayOf\"\n  ARG_LIST\n    VAR\n      ZVAL \"names\"\n{receiver}")
    };
    let counted = crossed(Some("count"));
    // The tree of `$local(…)` with `arguments`, each a rendered node, below its `ARG_LIST`.
    let called = |local: &str, arguments: &[&str]| {
        let mut call = format!("CALL\n  VAR\n    ZVAL \"{local}\"\n  ARG_LIST\n");
        for argument in arguments {
            call.push_str(&nested(argument, 2));
        }

        call
    };
    let named = format!("NAMED_ARG\n  ZVAL \"items\"\n{}", nested(&counted, 1));

    assert_eq!(
        statements_at(code, &[doubler], 4..8),
        [
            called("count", &[&counted, &counted, &counted]),
            called("count", &[named.as_str()]),
            called("plain", &[&crossed(Some("plain"))]),
            called("doubler", &[&crossed(None)]),
        ]
    );
}

/// ```php
/// ($function#1 = \Lib\Calc::counter())(\Sharp\Internal\arrayOf($names, $function#1));
/// ```
///
/// A call of any other expression that gives a closure holds the closure first, so `\Sharp\Internal\arrayOf` reads it
/// as it reads a closure a local holds, spec section 12.
#[test]
fn a_call_of_a_closure_an_expression_gives_holds_it_for_each_map_it_crosses() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\n\nclass Report\n{\n    public int run(int extra)\n    {\n        Map<int, string> names = this.names();\n        Calc.counter()(names);\n        return 0;\n    }\n\n    private Map<int, string> names() => [:];\n}\n";

    assert_eq!(
        statements_at(code, &[], 1..2),
        [indoc! {r#"
            CALL
              ASSIGN
                VAR
                  ZVAL "function#1"
                STATIC_CALL
                  ZVAL "Lib\\Calc"
                  ZVAL "counter"
                  ARG_LIST
              ARG_LIST
                CALL
                  ZVAL "Sharp\\Internal\\arrayOf"
                  ARG_LIST
                    VAR
                      ZVAL "names"
                    VAR
                      ZVAL "function#1"
        "#}]
    );
}

/// `tree`, a rendered node, as it renders `levels` below its parent.
fn nested(tree: &str, levels: usize) -> String {
    let mut nested = String::new();
    for line in tree.lines() {
        nested.push_str(&"  ".repeat(levels));
        nested.push_str(line);
        nested.push('\n');
    }

    nested
}

/// ```php
/// $levels = \is_array($levels) ? new \Sharp\Map<Lib.Level, int>(\array_merge([], ...\array_map(fn ($key#1, $value#2) => [\Lib\Level::from($key#1), $value#2], \array_keys($levels), $levels))) : $levels;
/// $names = \is_array(${'crossing#1'} = \Lib\Calc::names()) ? \Sharp\Map::from(${'crossing#1'}, 'int, string') : ${'crossing#1'};
/// return \is_array(${'crossing#1'} = \Lib\Calc::names()) ? \Sharp\Map::from(${'crossing#1'}, 'int, string') : ${'crossing#1'};
/// ```
///
/// A value plain PHP gives enters PHP# with each `Map` it holds made the object, spec section 12: a parameter, a typed
/// local and a `return`. A call's result is checked in its `VERIFY_TYPE_ARGS` first, then made the object. A `Map` keyed by an `int`-backed enum takes each backing value back as its case as it is,
/// where a `string`-backed one casts it first, as `a_backed_enum_key_beside_a_map_spread_goes_in_as_its_case` shows.
#[test]
fn a_value_plain_php_gives_enters_php_sharp_as_the_object() {
    let code = "namespace App.Tenant;\n\nimport Lib.Calc;\nimport Lib.Level;\n\nclass Report\n{\n    public Map<int, string> run(Map<Level, int> levels)\n    {\n        Map<int, string> names = Calc.names();\n        return Calc.names();\n    }\n}\n";
    let level = ("src/Lib/Level.php", "<?php namespace Lib; enum Level: int { case Low = 1; }");
    let crossing = indoc! {r#"
        CONDITIONAL
          CALL
            ZVAL "is_array"
            ARG_LIST
              ASSIGN
                VAR
                  ZVAL "crossing#1"
                VERIFY_TYPE_ARGS
                  STATIC_CALL
                    ZVAL "Lib\\Calc"
                    ZVAL "names"
                    ARG_LIST
                  ZVAL "Map<int, string>"
                  ZVAL "Lib\\Calc::names()"
          STATIC_CALL
            ZVAL "Sharp\\Map"
            ZVAL "from"
            ARG_LIST
              VAR
                ZVAL "crossing#1"
              ZVAL "int, string"
          VAR
            ZVAL "crossing#1"
    "#};

    assert_eq!(
        statements_at(code, &[level], 0..3),
        [
            indoc! {r#"
                ASSIGN
                  VAR
                    ZVAL "levels"
                  CONDITIONAL
                    CALL
                      ZVAL "is_array"
                      ARG_LIST
                        VAR
                          ZVAL "levels"
                    SHARP_TYPE_ARGS
                      NEW
                        ZVAL "Sharp\\Map"
                        ARG_LIST
                          CALL
                            ZVAL "array_merge"
                            ARG_LIST
                              ARRAY [3]
                              UNPACK
                                CALL
                                  ZVAL "array_map"
                                  ARG_LIST
                                    ARROW_FUNC "" @8-8
                                      PARAM_LIST
                                        PARAM
                                          null
                                          ZVAL "key#1"
                                          null
                                          null
                                          null
                                          null
                                        PARAM
                                          null
                                          ZVAL "value#2"
                                          null
                                          null
                                          null
                                          null
                                      null
                                      ARRAY [3]
                                        ARRAY_ELEM
                                          STATIC_CALL
                                            ZVAL "Lib\\Level"
                                            ZVAL "from"
                                            ARG_LIST
                                              VAR
                                                ZVAL "key#1"
                                          null
                                        ARRAY_ELEM
                                          VAR
                                            ZVAL "value#2"
                                          null
                                      null
                                      null
                                    CALL
                                      ZVAL "array_keys"
                                      ARG_LIST
                                        VAR
                                          ZVAL "levels"
                                    VAR
                                      ZVAL "levels"
                      ZVAL "Lib.Level, int"
                    VAR
                      ZVAL "levels"
            "#}
            .to_owned(),
            format!("ASSIGN\n  VAR\n    ZVAL \"names\"\n{}", nested(crossing, 1)),
            format!("RETURN\n{}", nested(crossing, 1)),
        ]
    );
}

/// ```php
/// $a = $extra instanceof \Lib\Calc; $b = \is_int($extra); $c = \is_string($extra);
/// $d = (${'match#1'} = $this->total()) instanceof \Lib\Calc;
/// ```
///
/// A class is tested with `instanceof` on its full name, and a built-in type with the global `is_` function the
/// engine compiles to `TYPE_CHECK`. A value that is not a local or a parameter is tested through a variable PHP#
/// cannot name, so the analyzer never narrows a property.
#[test]
fn is_without_a_name_is_instanceof_or_a_type_check() {
    assert_eq!(
        child_body(
            "Calc|int|string run(Calc|int|string extra)",
            "        const a = extra is Calc;\n        const b = extra is int;\n        const c = extra is string;\n        const d = this.total() is Calc;\n        return extra;\n",
            "<?php namespace App\\Tenant { class Base { public function total(): ?object { return null; } } } namespace Lib { final class Calc {} }",
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                INSTANCEOF
                  VAR
                    ZVAL "extra"
                  ZVAL "Lib\\Calc"
              ASSIGN
                VAR
                  ZVAL "b"
                CALL
                  ZVAL "is_int"
                  ARG_LIST
                    VAR
                      ZVAL "extra"
              ASSIGN
                VAR
                  ZVAL "c"
                CALL
                  ZVAL "is_string"
                  ARG_LIST
                    VAR
                      ZVAL "extra"
              ASSIGN
                VAR
                  ZVAL "d"
                INSTANCEOF
                  ASSIGN
                    VAR
                      ZVAL "match#1"
                    METHOD_CALL
                      VAR
                        ZVAL "this"
                      ZVAL "total"
                      ARG_LIST
                  ZVAL "Lib\\Calc"
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// if (($calc = $extra) instanceof \Lib\Calc) { return 1; }
/// if (!\is_int($count = $extra)) { return 0; }
/// return $count;
/// ```
///
/// A pattern's variable is assigned the tested value before the test. The binder lets code read it only where the
/// test holds, so the assignment is never seen where it fails.
#[test]
fn is_with_a_name_assigns_the_name_before_the_test() {
    assert_eq!(
        body_in(
            "int run(Calc|int extra)",
            "        if (extra is Calc calc) {\n            return 1;\n        }\n        if (extra is not int count) {\n            return 0;\n        }\n        return count;\n",
            &[("src/Lib/Calc.php", "<?php namespace Lib; final class Calc {}")]
        ),
        indoc! {r#"
            STMT_LIST
              IF
                IF_ELEM
                  INSTANCEOF
                    ASSIGN
                      VAR
                        ZVAL "calc"
                      VAR
                        ZVAL "extra"
                    ZVAL "Lib\\Calc"
                  STMT_LIST
                    RETURN
                      ZVAL 1
              IF
                IF_ELEM
                  UNARY_OP [14]
                    CALL
                      ZVAL "is_int"
                      ARG_LIST
                        ASSIGN
                          VAR
                            ZVAL "count"
                          VAR
                            ZVAL "extra"
                  STMT_LIST
                    RETURN
                      ZVAL 0
              RETURN
                VAR
                  ZVAL "count"
        "#}
    );
}

/// ```php
/// return \is_string($extra) ? 1 : 0;
/// ```
///
/// A `?` after the type that `is` tests starts a `? :`, as in C#, so it lowers as the same test in parentheses does.
#[test]
fn is_before_a_question_mark_is_the_condition_of_a_conditional() {
    let tree = body_in("int run(int|string extra)", "        return extra is string ? 1 : 0;\n", &[]);

    assert_eq!(tree, body_in("int run(int|string extra)", "        return (extra is string) ? 1 : 0;\n", &[]));
    assert_eq!(
        tree,
        indoc! {r#"
            STMT_LIST
              RETURN
                CONDITIONAL
                  CALL
                    ZVAL "is_string"
                    ARG_LIST
                      VAR
                        ZVAL "extra"
                  ZVAL 1
                  ZVAL 0
        "#}
    );
}

/// ```php
/// $calc = $extra instanceof \Lib\Calc ? $extra : null;
/// $made = (${'as#1'} = \Lib\Calc::make()) instanceof \Lib\Calc ? ${'as#1'} : null;
/// ```
///
/// `as` reads a local or a parameter twice. Any other value is assigned to a variable PHP# cannot name, so it runs
/// once.
#[test]
fn as_is_a_conditional_that_gives_the_value_or_null() {
    assert_eq!(
        body_in(
            "Calc|int run(Calc|int extra)",
            "        const calc = extra as Calc;\n        const made = Calc.make() as Calc;\n        return extra;\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; final class Calc { public static function make(): object { return new self(); } }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "calc"
                CONDITIONAL
                  INSTANCEOF
                    VAR
                      ZVAL "extra"
                    ZVAL "Lib\\Calc"
                  VAR
                    ZVAL "extra"
                  ZVAL null
              ASSIGN
                VAR
                  ZVAL "made"
                CONDITIONAL
                  INSTANCEOF
                    ASSIGN
                      VAR
                        ZVAL "as#1"
                      STATIC_CALL
                        ZVAL "Lib\\Calc"
                        ZVAL "make"
                        ARG_LIST
                    ZVAL "Lib\\Calc"
                  VAR
                    ZVAL "as#1"
                  ZVAL null
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// A `match` without arms has no PHP, so the checker refuses it before the lowering meets it.
#[test]
fn a_match_without_arms_is_refused_before_lowering() {
    let lowered = Lowered::new(&method_with("void run(Any? extra)", "        match (extra) {}\n"));

    assert_eq!(lowered.diagnostics(), ["9:9 compile error: A `match` needs a `default` arm."]);
}

/// Spec section 21: a function type is tested as any type is, by the engine's test of its type text, its effects
/// included, which compares a closure's own function type with it.
#[test]
fn a_test_of_a_function_type_is_the_engine_test_of_its_type_text() {
    assert_eq!(
        body_in("bool run(Any? extra)", "        return extra is Function<int(int) uses Http>;\n", &[]),
        indoc! {r#"
            STMT_LIST
              RETURN
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Function<int(int) uses Sharp.Net.Http>"
        "#}
    );
}

#[test]
fn a_test_of_a_function_type_that_uses_none_is_the_engine_test_of_the_pure_type_text() {
    assert_eq!(
        body_in("bool run(Any? extra)", "        return extra is Function<int(int) uses none>;\n", &[]),
        indoc! {r#"
            STMT_LIST
              RETURN
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Function<int(int)>"
        "#}
    );
}

/// A plain PHP class's objects carry no type arguments while the code runs, so `is` and `as` that give one type
/// arguments are refused before the lowering would test the class alone. The class alone is its `instanceof`.
#[test]
fn is_and_as_that_give_a_plain_php_class_type_arguments_are_refused_before_lowering() {
    let lowered = Lowered::with(
        indoc! {"
        namespace App.Tenant;

        import Lib.Collection;
        import Lib.Order;

        class Report
        {
            public void run(Any extra)
            {
                const tested = extra is Collection<Order>;
                const kept = extra as List<Collection<Order>>;
            }
        }
    "},
        &[(
            "src/Lib/Collection.php",
            "<?php namespace Lib; class Order {} /** @template T */ final class Collection { /** @param list<T> $items */ public function __construct(array $items) {} }",
        )],
    );

    assert_eq!(
        lowered.diagnostics(),
        [
            "10:33 compile error: `Collection<Order>` can't be tested: `Collection` is a plain PHP class, so its objects carry no type arguments while the code runs.",
            "11:36 compile error: `Collection<Order>` can't be tested: `Collection` is a plain PHP class, so its objects carry no type arguments while the code runs.",
        ]
    );
}

/// ```php
/// $present = <is Any>($extra);
/// $either = <is int|string>($extra) ? $extra : null;
/// ```
///
/// `is` and `as` of `Any` and of a union are the engine's test of the type, as a collection's are.
#[test]
fn is_and_as_of_any_or_a_union_are_the_engine_test_of_its_type() {
    assert_eq!(
        body_in(
            "void run(Any? extra)",
            "        const present = extra is Any;\n        const either = extra as int|string;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "present"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Any"
              ASSIGN
                VAR
                  ZVAL "either"
                CONDITIONAL
                  SHARP_IS_TYPE
                    VAR
                      ZVAL "extra"
                    ZVAL "int|string"
                  VAR
                    ZVAL "extra"
                  ZVAL null
        "#}
    );
}

/// ```php
/// $pair = <is [int, string]>($extra) ? $extra : null;
/// $type = <is Class<App.Tenant.Report>>($extra);
/// $object = <is Object|int>($extra);
/// $boxed = <is Class<App.Tenant.Box<int>>>($extra);
/// $box = <is Class<App.Tenant.Box>>($extra);
/// ```
///
/// `is` and `as` of a tuple, of a class value and of `Object` are the engine's test of the type, as a collection's are,
/// which checks a tuple's count and each element and finds the class a class value names. A generic class written
/// without type arguments in `Class<Box>` is the class alone, which takes it with any type arguments.
#[test]
fn is_and_as_of_a_tuple_a_class_value_or_object_are_the_engine_test_of_its_type() {
    assert_eq!(
        body_in(
            "void run(Any? extra)",
            "        const pair = extra as [int, string];\n        const type = extra is Class<Report>;\n        const object = extra is int|Object;\n        const boxed = extra is Class<Box<int>>;\n        const box = extra is Class<Box>;\n",
            &[("src/App/Tenant/Box.sharp", "namespace App.Tenant;\n\npublic class Box<TItem>\n{\n}\n")]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "pair"
                CONDITIONAL
                  SHARP_IS_TYPE
                    VAR
                      ZVAL "extra"
                    ZVAL "[int, string]"
                  VAR
                    ZVAL "extra"
                  ZVAL null
              ASSIGN
                VAR
                  ZVAL "type"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Class<App.Tenant.Report>"
              ASSIGN
                VAR
                  ZVAL "object"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Object|int"
              ASSIGN
                VAR
                  ZVAL "boxed"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Class<App.Tenant.Box<int>>"
              ASSIGN
                VAR
                  ZVAL "box"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Class<App.Tenant.Box>"
        "#}
    );
}

/// ```php
/// $numbers = <is List<int>>($extra);
/// $kept = \is_array($crossing#1 = <is Map<string, int>>($extra) ? $extra : null) ? new \Sharp\Map<string, int>(…) : $crossing#1;
/// $tags = <is Set<string>>($extra);
/// ```
///
/// `is` and `as` of a `List`, a `Map` or a `Set` are the engine's test of the type, as a generic class's are, which
/// walks every element. The test passes a PHP array whose elements fit, so the local `as` gives it to becomes the `Map`
/// first, as a typed local does.
#[test]
fn is_and_as_of_a_collection_are_the_engine_test_of_its_type() {
    assert_eq!(
        body_in(
            "void run(Any? extra)",
            "        const numbers = extra is List<int>;\n        const kept = extra as Map<string, int>;\n        const tags = extra is Set<string>;\n",
            &[],
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "numbers"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "List<int>"
              ASSIGN
                VAR
                  ZVAL "kept"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "crossing#1"
                        CONDITIONAL
                          SHARP_IS_TYPE
                            VAR
                              ZVAL "extra"
                            ZVAL "Map<string, int>"
                          VAR
                            ZVAL "extra"
                          ZVAL null
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @10-10
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#2"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#3"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#2"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#3"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "crossing#1"
                                  VAR
                                    ZVAL "crossing#1"
                    ZVAL "string, int"
                  VAR
                    ZVAL "crossing#1"
              ASSIGN
                VAR
                  ZVAL "tags"
                SHARP_IS_TYPE
                  VAR
                    ZVAL "extra"
                  ZVAL "Set<string>"
        "#}
    );
}

/// ```php
/// if (\is_int($count = $counts[$key] ?? null)) { return $count; }
/// $price = \is_int(${'as#1'} = $counts[$key] ?? null) ? ${'as#1'} : null;
/// ```
///
/// An index a pattern tests reads a missing key as null, as `??` does, so the index is the left side of a
/// `COALESCE`, and a missing key reaches the test as null instead of a warning.
#[test]
fn an_index_a_pattern_tests_coalesces_a_missing_key_to_null() {
    assert_eq!(
        body_in(
            "int? run(Map<string, int> counts, string key)",
            "        if (counts[key] is int count) {\n            return count;\n        }\n        const price = counts[key] as int;\n        return price;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "counts"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "counts"
                  SHARP_TYPE_ARGS
                    NEW
                      ZVAL "Sharp\\Map"
                      ARG_LIST
                        CALL
                          ZVAL "array_merge"
                          ARG_LIST
                            ARRAY [3]
                            UNPACK
                              CALL
                                ZVAL "array_map"
                                ARG_LIST
                                  ARROW_FUNC "" @7-7
                                    PARAM_LIST
                                      PARAM
                                        null
                                        ZVAL "key#1"
                                        null
                                        null
                                        null
                                        null
                                      PARAM
                                        null
                                        ZVAL "value#2"
                                        null
                                        null
                                        null
                                        null
                                    null
                                    ARRAY [3]
                                      ARRAY_ELEM
                                        CAST [6]
                                          VAR
                                            ZVAL "key#1"
                                        null
                                      ARRAY_ELEM
                                        VAR
                                          ZVAL "value#2"
                                        null
                                    null
                                    null
                                  CALL
                                    ZVAL "array_keys"
                                    ARG_LIST
                                      VAR
                                        ZVAL "counts"
                                  VAR
                                    ZVAL "counts"
                    ZVAL "string, int"
                  VAR
                    ZVAL "counts"
              IF
                IF_ELEM
                  CALL
                    ZVAL "is_int"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "count"
                        COALESCE
                          DIM
                            VAR
                              ZVAL "counts"
                            VAR
                              ZVAL "key"
                          ZVAL null
                  STMT_LIST
                    RETURN
                      VAR
                        ZVAL "count"
              ASSIGN
                VAR
                  ZVAL "price"
                CONDITIONAL
                  CALL
                    ZVAL "is_int"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "as#1"
                        COALESCE
                          DIM
                            VAR
                              ZVAL "counts"
                            VAR
                              ZVAL "key"
                          ZVAL null
                  VAR
                    ZVAL "as#1"
                  ZVAL null
              RETURN
                VAR
                  ZVAL "price"
        "#}
    );
}

/// ```php
/// $a = \is_int($extra) && $extra === 200;
/// $b = \is_int($extra) && ($extra >= 1 && $extra < 10 || !($extra === -1));
/// $c = \is_object($extra) && (${'match#1'} = $extra->count) > 0 && \is_string($label = $extra->name);
/// ```
///
/// A value is compared with `===`, a comparison keeps its operator, and `and`, `or` and `not` are `&&`, `||` and
/// `!`. A properties pattern tests that the value is an object, then reads each property once. A value pattern
/// compares a `Calc`, which declares no `operator ==`, and a comparison orders one, which declares no `operator <=>`,
/// only once `int` has ruled it out: a value pattern's `==` is the code's own, so `extra is 200` is refused as
/// `extra == 200` is.
#[test]
fn values_comparisons_and_properties_are_the_php_comparisons_they_name() {
    let calc = (
        "src/Lib/Calc.php",
        "<?php namespace Lib; final class Calc { public int $count = 0; public ?string $name = null; }",
    );
    assert_eq!(
        body_in(
            "Calc|int run(Calc|int extra)",
            "        const a = extra is int and 200;\n        const b = extra is int and (>= 1 and < 10 or (not -1));\n        const c = extra is { count: > 0, name: string label };\n        return extra;\n",
            &[calc]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                AND
                  CALL
                    ZVAL "is_int"
                    ARG_LIST
                      VAR
                        ZVAL "extra"
                  BINARY_OP [16]
                    VAR
                      ZVAL "extra"
                    ZVAL 200
              ASSIGN
                VAR
                  ZVAL "b"
                AND
                  CALL
                    ZVAL "is_int"
                    ARG_LIST
                      VAR
                        ZVAL "extra"
                  OR
                    AND
                      GREATER_EQUAL
                        VAR
                          ZVAL "extra"
                        ZVAL 1
                      BINARY_OP [20]
                        VAR
                          ZVAL "extra"
                        ZVAL 10
                    UNARY_OP [14]
                      BINARY_OP [16]
                        VAR
                          ZVAL "extra"
                        UNARY_MINUS
                          ZVAL 1
              ASSIGN
                VAR
                  ZVAL "c"
                AND
                  AND
                    CALL
                      ZVAL "is_object"
                      ARG_LIST
                        VAR
                          ZVAL "extra"
                    GREATER
                      ASSIGN
                        VAR
                          ZVAL "match#1"
                        PROP
                          VAR
                            ZVAL "extra"
                          ZVAL "count"
                      ZVAL 0
                  CALL
                    ZVAL "is_string"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "label"
                        PROP
                          VAR
                            ZVAL "extra"
                          ZVAL "name"
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
    assert_eq!(
        Lowered::with(&method_with("bool run(Calc|int extra)", "        return extra is 200;\n"), &[calc])
            .diagnostics(),
        ["9:16 compile error: `==` cannot compare `int|Calc` with `int`: `Calc` declares no `operator ==`."]
    );
}

/// ```php
/// $a = ($big = $extra) instanceof \Lib\Calc && (${'match#1'} = $big->count) > 1000;
/// $b = (${'match#1'} = $this->calc()) instanceof \Lib\Calc && (${'match#2'} = ${'match#1'}->count) > 0;
/// ```
///
/// Spec section 21: a type pattern with properties tests the type, then each property on the value the name holds, or
/// on the subject's hidden variable when it has no name. Each property is read once, as in a properties pattern.
/// `a ?? return`, `a ?? continue` and `a ?? break` lower to a RETURN, CONTINUE or BREAK node in the place of the right side
/// of `??`, which the engine compiles in the middle of the expression. PHP has no spelling for it.
#[test]
fn a_leave_after_null_coalesce_is_its_statement_inside_the_expression() {
    assert_eq!(
        body_in(
            "int run(Map<int, int> values)",
            "        const a = values[0] ?? return -1;\n        for (int i = 0; i < 2; i++) {\n            const b = values[i] ?? continue;\n            const c = values[i + 1] ?? break;\n        }\n        return a;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "values"
                CONDITIONAL
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "values"
                  STATIC_CALL
                    ZVAL "Sharp\\Map"
                    ZVAL "from"
                    ARG_LIST
                      VAR
                        ZVAL "values"
                      ZVAL "int, int"
                  VAR
                    ZVAL "values"
              ASSIGN
                VAR
                  ZVAL "a"
                COALESCE
                  DIM
                    VAR
                      ZVAL "values"
                    ZVAL 0
                  RETURN
                    UNARY_MINUS
                      ZVAL 1
              FOR
                EXPR_LIST
                  ASSIGN
                    VAR
                      ZVAL "i"
                    ZVAL 0
                EXPR_LIST
                  BINARY_OP [20]
                    VAR
                      ZVAL "i"
                    ZVAL 2
                EXPR_LIST
                  POST_INC
                    VAR
                      ZVAL "i"
                STMT_LIST
                  ASSIGN
                    VAR
                      ZVAL "b"
                    COALESCE
                      DIM
                        VAR
                          ZVAL "values"
                        VAR
                          ZVAL "i"
                      CONTINUE
                        null
                  ASSIGN
                    VAR
                      ZVAL "c"
                    COALESCE
                      DIM
                        VAR
                          ZVAL "values"
                        BINARY_OP [1]
                          VAR
                            ZVAL "i"
                          ZVAL 1
                      BREAK
                        null
              RETURN
                VAR
                  ZVAL "a"
            "#}
    );
}

/// ```php
/// $a = \is_array($values) && \count($values) === 0;
/// $b = \is_array($values) && \count($values) >= 1 && \is_int($first = $values[0])
///     && ($rest = \array_slice($values, 1)) is List<int>;
/// ```
///
/// The rest is tested as a typed element is, by the engine's test of its type, so `...List<Circle> rest` holds only
/// circles.
#[test]
fn a_list_pattern_tests_the_count_then_each_element_then_takes_the_rest() {
    assert_eq!(
        body_in(
            "int run(List<int> values)",
            "        const a = values is [];\n        const b = values is [int first, ...List<int> rest];\n        return 0;\n",
            &[]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                AND
                  CALL
                    ZVAL "is_array"
                    ARG_LIST
                      VAR
                        ZVAL "values"
                  BINARY_OP [16]
                    CALL
                      ZVAL "count"
                      ARG_LIST
                        VAR
                          ZVAL "values"
                    ZVAL 0
              ASSIGN
                VAR
                  ZVAL "b"
                AND
                  AND
                    AND
                      CALL
                        ZVAL "is_array"
                        ARG_LIST
                          VAR
                            ZVAL "values"
                      GREATER_EQUAL
                        CALL
                          ZVAL "count"
                          ARG_LIST
                            VAR
                              ZVAL "values"
                        ZVAL 1
                    CALL
                      ZVAL "is_int"
                      ARG_LIST
                        ASSIGN
                          VAR
                            ZVAL "first"
                          DIM
                            VAR
                              ZVAL "values"
                            ZVAL 0
                  SHARP_IS_TYPE
                    ASSIGN
                      VAR
                        ZVAL "rest"
                      CALL
                        ZVAL "array_slice"
                        ARG_LIST
                          VAR
                            ZVAL "values"
                          ZVAL 1
                    ZVAL "List<int>"
              RETURN
                ZVAL 0
            "#}
    );
}

/// ```php
/// return match (true) {
///     \is_array($values) && \count($values) === 0 => 0,
///     \is_array($values) && \count($values) >= 1 && \is_int($first = $values[0]) => $first,
/// };
///
/// $total = 0;
/// if (\is_array($values) && \count($values) === 0) { $total = 1; }
/// else if (\is_array($values) && \count($values) >= 1 && \is_int($first = $values[0])) { $total = $first; }
/// return $total;
/// ```
///
/// A `match` on a List whose arms handle every length has no `default`, and its PHP has none, as an expression or as
/// a statement with block arms.
#[test]
fn a_match_on_a_list_whose_arms_handle_every_length_lowers_with_no_default() {
    let lowered = Lowered::with(
        &method_with(
            "int run(List<int> values)",
            "        return match (values) {\n            [] => 0,\n            [int first, ...] => first,\n        };\n",
        ),
        &[],
    );

    assert_eq!(lowered.diagnostics(), Vec::<String>::new());
    assert_eq!(
        lowered.body(),
        indoc! {r#"
            STMT_LIST
              RETURN
                MATCH
                  ZVAL true
                  MATCH_ARM_LIST
                    MATCH_ARM
                      EXPR_LIST
                        AND
                          CALL
                            ZVAL "is_array"
                            ARG_LIST
                              VAR
                                ZVAL "values"
                          BINARY_OP [16]
                            CALL
                              ZVAL "count"
                              ARG_LIST
                                VAR
                                  ZVAL "values"
                            ZVAL 0
                      ZVAL 0
                    MATCH_ARM
                      EXPR_LIST
                        AND
                          AND
                            CALL
                              ZVAL "is_array"
                              ARG_LIST
                                VAR
                                  ZVAL "values"
                            GREATER_EQUAL
                              CALL
                                ZVAL "count"
                                ARG_LIST
                                  VAR
                                    ZVAL "values"
                              ZVAL 1
                          CALL
                            ZVAL "is_int"
                            ARG_LIST
                              ASSIGN
                                VAR
                                  ZVAL "first"
                                DIM
                                  VAR
                                    ZVAL "values"
                                  ZVAL 0
                      VAR
                        ZVAL "first"
            "#}
    );

    let statement = Lowered::with(
        &method_with(
            "int run(List<int> values)",
            "        let total = 0;\n        match (values) {\n            [] => { total = 1; },\n            [int first, ...] => { total = first; },\n        }\n        return total;\n",
        ),
        &[],
    );

    assert_eq!(statement.diagnostics(), Vec::<String>::new());
    assert_eq!(
        statement.body(),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "total"
                ZVAL 0
              IF
                IF_ELEM
                  AND
                    CALL
                      ZVAL "is_array"
                      ARG_LIST
                        VAR
                          ZVAL "values"
                    BINARY_OP [16]
                      CALL
                        ZVAL "count"
                        ARG_LIST
                          VAR
                            ZVAL "values"
                      ZVAL 0
                  STMT_LIST
                    ASSIGN
                      VAR
                        ZVAL "total"
                      ZVAL 1
                IF_ELEM
                  null
                  IF
                    IF_ELEM
                      AND
                        AND
                          CALL
                            ZVAL "is_array"
                            ARG_LIST
                              VAR
                                ZVAL "values"
                          GREATER_EQUAL
                            CALL
                              ZVAL "count"
                              ARG_LIST
                                VAR
                                  ZVAL "values"
                            ZVAL 1
                        CALL
                          ZVAL "is_int"
                          ARG_LIST
                            ASSIGN
                              VAR
                                ZVAL "first"
                              DIM
                                VAR
                                  ZVAL "values"
                                ZVAL 0
                      STMT_LIST
                        ASSIGN
                          VAR
                            ZVAL "total"
                          VAR
                            ZVAL "first"
              RETURN
                VAR
                  ZVAL "total"
            "#}
    );
}

/// ```php
/// $a = $value is List<Any?> && \count($value) === 1 && \is_int($one = $value[0]);
/// ```
///
/// A value that may be a list or anything else is tested with the engine's test of `List<Any?>` first, where a `List`
/// needs only `\is_array`.
#[test]
fn a_list_pattern_on_any_value_tests_it_is_a_list_first() {
    assert_eq!(
        body_in("int run(Any value)", "        const a = value is [int one];\n        return 0;\n", &[]),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                AND
                  AND
                    SHARP_IS_TYPE
                      VAR
                        ZVAL "value"
                      ZVAL "List<Any?>"
                    BINARY_OP [16]
                      CALL
                        ZVAL "count"
                        ARG_LIST
                          VAR
                            ZVAL "value"
                      ZVAL 1
                  CALL
                    ZVAL "is_int"
                    ARG_LIST
                      ASSIGN
                        VAR
                          ZVAL "one"
                        DIM
                          VAR
                            ZVAL "value"
                          ZVAL 0
              RETURN
                ZVAL 0
            "#}
    );
}

#[test]
fn a_type_with_properties_tests_the_type_then_each_property() {
    assert_eq!(
        body_in(
            "Calc|int run(Calc|int extra)",
            "        const a = extra is Calc { count: > 1000 } big;\n        const b = this.calc() is Calc { count: > 0 };\n        return extra;\n    }\n\n    public Calc calc()\n    {\n        return new Calc();\n",
            &[(
                "src/Lib/Calc.php",
                "<?php namespace Lib; final class Calc { public int $count = 0; public ?string $name = null; }",
            )]
        ),
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "a"
                AND
                  INSTANCEOF
                    ASSIGN
                      VAR
                        ZVAL "big"
                      VAR
                        ZVAL "extra"
                    ZVAL "Lib\\Calc"
                  GREATER
                    ASSIGN
                      VAR
                        ZVAL "match#1"
                      PROP
                        VAR
                          ZVAL "big"
                        ZVAL "count"
                    ZVAL 1000
              ASSIGN
                VAR
                  ZVAL "b"
                AND
                  INSTANCEOF
                    ASSIGN
                      VAR
                        ZVAL "match#1"
                      METHOD_CALL
                        VAR
                          ZVAL "this"
                        ZVAL "calc"
                        ARG_LIST
                    ZVAL "Lib\\Calc"
                  GREATER
                    ASSIGN
                      VAR
                        ZVAL "match#2"
                      PROP
                        VAR
                          ZVAL "match#1"
                        ZVAL "count"
                    ZVAL 0
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// ```php
/// return match (true) {
///     (${'match#1'} = $this->total()) === 0 => 1,
///     \is_int($n = ${'match#1'}) && $n > 9 => $n,
///     default => 2,
/// };
/// ```
///
/// A `match` that gives a value is PHP's `match (true)` with one condition per arm: its pattern's test, `&&` its
/// `when` condition. The first test assigns the hidden variable.
#[test]
fn a_match_that_gives_a_value_is_a_match_of_true() {
    assert_eq!(
        child_body(
            RUN,
            "        return match (this.total()) {\n            0 => 1,\n            int n when n > 9 => n,\n            default => 2,\n        };\n",
            "<?php namespace App\\Tenant; class Base { public function total(): int { return 0; } }",
        ),
        indoc! {r#"
            STMT_LIST
              RETURN
                MATCH
                  ZVAL true
                  MATCH_ARM_LIST
                    MATCH_ARM
                      EXPR_LIST
                        BINARY_OP [16]
                          ASSIGN
                            VAR
                              ZVAL "match#1"
                            METHOD_CALL
                              VAR
                                ZVAL "this"
                              ZVAL "total"
                              ARG_LIST
                          ZVAL 0
                      ZVAL 1
                    MATCH_ARM
                      EXPR_LIST
                        AND
                          CALL
                            ZVAL "is_int"
                            ARG_LIST
                              ASSIGN
                                VAR
                                  ZVAL "n"
                                VAR
                                  ZVAL "match#1"
                          GREATER
                            VAR
                              ZVAL "n"
                            ZVAL 9
                      VAR
                        ZVAL "n"
                    MATCH_ARM
                      null
                      ZVAL 2
        "#}
    );
}

/// ```php
/// if ($extra === 0) {
///     return 1;
/// } else if (\is_int($n = $extra) && $n > 9) $this->run($n); else {
/// }
/// ```
///
/// A `match` that starts a statement is `if`, `else if` per arm, and `else` for `default`. An arm that is an
/// expression is its expression statement.
#[test]
fn a_match_that_starts_a_statement_is_an_if_list() {
    assert_eq!(
        body(
            "        match (extra) {\n            0 => {\n                return 1;\n            },\n            int n when n > 9 => this.run(n),\n            default => {},\n        }\n        return extra;\n"
        ),
        indoc! {r#"
            STMT_LIST
              IF
                IF_ELEM
                  BINARY_OP [16]
                    VAR
                      ZVAL "extra"
                    ZVAL 0
                  STMT_LIST
                    RETURN
                      ZVAL 1
                IF_ELEM
                  null
                  IF
                    IF_ELEM
                      AND
                        CALL
                          ZVAL "is_int"
                          ARG_LIST
                            ASSIGN
                              VAR
                                ZVAL "n"
                              VAR
                                ZVAL "extra"
                        GREATER
                          VAR
                            ZVAL "n"
                          ZVAL 9
                      METHOD_CALL
                        VAR
                          ZVAL "this"
                        ZVAL "run"
                        ARG_LIST
                          VAR
                            ZVAL "n"
                    IF_ELEM
                      null
                      STMT_LIST
              RETURN
                VAR
                  ZVAL "extra"
        "#}
    );
}

/// php-src gives the jump after a branch the line of its `IF_ELEM`, so each arm's `if` is on its pattern's line, as
/// its PHP twin's is, and coverage never counts the line of the arm before it.
#[test]
fn each_arm_of_a_match_that_starts_a_statement_is_on_its_pattern_line() {
    let lowered = Lowered::new(&method(
        "        match (extra) {\n            0 => {},\n            1 => {},\n            default => {},\n        }\n        return extra;\n",
    ));
    let mut lines: Vec<u32> = lowered
        .written()
        .into_iter()
        .filter(|(_, node)| node.kind == sharp_kind::SHARP_AST_IF_ELEM)
        .map(|(_, node)| node.line)
        .collect();
    lines.sort_unstable();

    assert_eq!(lines, [10, 11, 11, 12]);
}

/// ```php
/// $forced = $extra > 9;
/// return match (true) {
///     $extra === 0 && $forced => 1,
///     default => 2,
/// };
/// ```
///
/// A `when` condition that ends in a bare name is the arm's `&&` operand, as `forced == true` is.
#[test]
fn a_when_condition_that_is_a_bare_name_is_the_arms_and_operand() {
    let guarded = |condition: &str| {
        body(&format!(
            "        const forced = extra > 9;\n        return match (extra) {{\n            0 when {condition} => 1,\n            default => 2,\n        }};\n"
        ))
    };
    let bare = guarded("forced");

    assert_eq!(
        bare,
        indoc! {r#"
            STMT_LIST
              ASSIGN
                VAR
                  ZVAL "forced"
                GREATER
                  VAR
                    ZVAL "extra"
                  ZVAL 9
              RETURN
                MATCH
                  ZVAL true
                  MATCH_ARM_LIST
                    MATCH_ARM
                      EXPR_LIST
                        AND
                          BINARY_OP [16]
                            VAR
                              ZVAL "extra"
                            ZVAL 0
                          VAR
                            ZVAL "forced"
                      ZVAL 1
                    MATCH_ARM
                      null
                      ZVAL 2
        "#}
    );
    assert_eq!(
        guarded("forced == true"),
        bare.replace(
            "              VAR\n                ZVAL \"forced\"\n          ZVAL 1\n",
            "              BINARY_OP [16]\n                VAR\n                  ZVAL \"forced\"\n                ZVAL true\n          ZVAL 1\n",
        )
    );
}

/// ```php
/// <?php declare(strict_types=1); namespace App\Tenant;
///
///
///
/// #[\Lib\Label("Order status")]
/// enum Status: string
/// {
///     case Active = "active";
///     #[\Lib\Label("Gone")]
///     case Archived = "archived";
///
///     public function title(): string
///     {
///         return $this->value;
///     }
///
///     public static function parse(string $value): \App\Tenant\Status
///     {
///         $all = \App\Tenant\Status::cases();
///         return \App\Tenant\Status::tryFrom($value) ?? \App\Tenant\Status::from("active");
///     }
/// }
/// ```
///
/// An enum is a `CLASS` with `[268435488]`, `ZEND_ACC_ENUM | ZEND_ACC_FINAL`, and its backing type as its 5th child. A
/// case is an `ENUM_CASE` of its name, its value, a null doc comment and its attributes, on the line of its name.
#[test]
fn a_backed_enum_is_a_final_enum_class_with_its_backing_type_cases_and_methods() {
    let lowered = Lowered::with(
        "namespace App.Tenant;\n\nimport Lib.Label;\n\n[Label(\"Order status\")]\nenum Status : string\n{\n    case Active = \"active\";\n    [Label(\"Gone\")]\n    case Archived = \"archived\";\n\n    public string title()\n    {\n        return this.value;\n    }\n\n    public static Status parse(string value)\n    {\n        const all = Status.cases();\n        return Status.tryFrom(value) ?? Status.from(\"active\");\n    }\n}\n",
        &[(
            "src/Lib/Label.php",
            "<?php namespace Lib; #[\\Attribute(\\Attribute::TARGET_ALL)] final class Label { public function __construct(string $text) {} }",
        )],
    );
    let case_lines: Vec<u32> = lowered
        .nodes()
        .iter()
        .filter(|node| node.kind == sharp_kind::SHARP_AST_ENUM_CASE)
        .map(|node| node.line)
        .collect();

    assert_eq!(case_lines, [8, 10]);
    assert_eq!(
        lowered.tree(),
        indoc! {r#"
            STMT_LIST
              DECLARE
                CONST_DECL
                  CONST_ELEM
                    ZVAL "strict_types"
                    ZVAL 1
                    null
                null
              NAMESPACE
                ZVAL "App\\Tenant"
                null
              CLASS [268435488] "Status" @6-22
                null
                null
                STMT_LIST
                  ENUM_CASE
                    ZVAL "Active"
                    ZVAL "active"
                    null
                    null
                  ENUM_CASE
                    ZVAL "Archived"
                    ZVAL "archived"
                    null
                    ATTRIBUTE_LIST
                      ATTRIBUTE_GROUP
                        ATTRIBUTE
                          ZVAL "Lib\\Label"
                          ARG_LIST
                            ZVAL "Gone"
                  METHOD [1] "title" @12-15
                    PARAM_LIST
                    null
                    STMT_LIST
                      RETURN
                        PROP
                          VAR
                            ZVAL "this"
                          ZVAL "value"
                    SHARP_TYPE_ARGS
                      ZVAL [1] "string"
                      ZVAL "Function<string()>"
                    null
                  METHOD [17] "parse" @17-21
                    PARAM_LIST
                      PARAM
                        ZVAL [1] "string"
                        ZVAL "value"
                        null
                        null
                        null
                        null
                    null
                    STMT_LIST
                      ASSIGN
                        VAR
                          ZVAL "all"
                        STATIC_CALL
                          ZVAL "App\\Tenant\\Status"
                          ZVAL "cases"
                          ARG_LIST
                      RETURN
                        COALESCE
                          STATIC_CALL
                            ZVAL "App\\Tenant\\Status"
                            ZVAL "tryFrom"
                            ARG_LIST
                              VAR
                                ZVAL "value"
                          STATIC_CALL
                            ZVAL "App\\Tenant\\Status"
                            ZVAL "from"
                            ARG_LIST
                              ZVAL "active"
                    SHARP_TYPE_ARGS
                      ZVAL "App\\Tenant\\Status"
                      ZVAL "Function<App.Tenant.Status(string)>"
                    null
                ATTRIBUTE_LIST
                  ATTRIBUTE_GROUP
                    ATTRIBUTE
                      ZVAL "Lib\\Label"
                      ARG_LIST
                        ZVAL "Order status"
                ZVAL [1] "string"
        "#}
    );
}

